#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_MUX_AIN0_SINGLE 0x8000
#define ADS1115_CONFIG_PGA_4_096V 0x4000
#define ADS1115_CONFIG_DR_128SPS 0x2000
#define ADS1115_CONFIG_MODE_SINGLE 0x0001
#define ADS1115_CONFIG_OS_NONE 0x0000
#define ADS1115_CONFIG_OS_MID_SUPPLY 0x0100
#define ADS1115_CONFIG_OS_MID_SUPPLY 0x0100
#define SENSITIVITY 40.0
#define ZERO_CURRENT_OFFSET 0.0
#define SAMPLE_INTERVAL_US 500000
#define LOG_INTERVAL_US 500000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_ads1115(int handle) {
    uint16_t config = ADS1115_CONFIG_MUX_AIN0_SINGLE |
                      ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_OS_NONE |
                      ADS1115_CONFIG_OS_MID_SUPPLY;
    if (i2cWriteWordData(handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }
    return 0;
}

static int read_ads1115(int handle, int16_t *raw_out) {
    uint8_t config = ADS1115_CONFIG_MUX_AIN0_SINGLE |
                      ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_OS_NONE |
                      ADS1115_CONFIG_OS_MID_SUPPLY;
    if (i2cWriteWordData(handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }
    uint8_t reg = ADS1115_REG_CONVERSION;
    uint8_t data[2];
    if (i2cReadI2CBlockData(handle, reg, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115\n");
        return -1;
    }
    *raw_out = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static double calculate_current(int16_t raw_out) {
    double voltage = (double)raw_out / 32768.0;
    double current = (voltage - ZERO_CURRENT_OFFSET) / SENSITIVITY;
    return current;
}

static void log_current(double current) {
    printf("Current: %.4f A\n", current);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_ads1115(i2c_handle) < 0) {
        fprintf(stderr, "ADS1115 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        int16_t raw_out;
        if (read_ads1115(i2c_handle, &raw_out) < 0) {
            fprintf(stderr, "Sensor read error, retrying next cycle\n");
            gpioDelay(LOG_INTERVAL_US);
            continue;
        }

        double current = calculate_current(raw_out);
        log_current(current);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

