#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define FLAME_SENSOR_PIN  4
#define BUZZER_PIN        27
#define I2C_BUS           1
#define ADS1115_ADDR      0x48
#define ADS1115_REG_CONV  0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS  0x8000  /* single-shot, AIN0 single-ended, ±4.096V, 128 SPS */
#define ADS1115_CONFIG_GAIN_4_096V 0x4000
#define ADS1115_CONFIG_MODE_SINGLE_SHOT 0x8000
#define ADS1115_CONFIG_DR_128SPS 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x2000
#define ADS1115_CONFIG_MODE_SINGLE_SHOT_128SPS 0x8000
#define ADS1115_CONFIG_PGA_4_096V_128SPS 0xC000
#define DEBOUNCE_MS 50
#define BUZZER_DURATION_MS 2000
#define TEMP_THRESHOLD_C 60.0f
#define LOG_FILE_NAME "fire_log.txt"

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static int g_i2c_handle = -1;

/* ---- Function prototypes ---- */
static int  init_gpio(void);
static int  init_i2c(void);
static int  init_ads1115(void);
static int  read_ads1115(float *temperature);
static void flame_event_callback(int gpio, int level, uint32_t tick, void *userdata);
static void log_event(float temperature);
static void buzzer_on(void);
static void buzzer_off(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- ISR ---- */
static void flame_event_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    if (level == 0) {
        /* Falling edge: flame detected */
        if (g_running) {
            g_running = 0;
            gpioWrite(BUZZER_PIN, 1);
            gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, NULL, NULL);
        }
    }
}

/* ---- Logging ---- */
static void log_event(float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[64];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

