#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define ADC_VREF 3.3
#define ADC_MAX 1023.0
#define ADC_SENSITIVITY 0.1
#define DEFAULT_CURRENT_THRESHOLD 5.0
#define DEFAULT_SENSITIVITY 100.0
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "current_log.txt"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 18

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_adc(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x80 | (channel & 0x07)) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_current(int adc_value) {
    return (float)adc_value * ADC_SENSITIVITY;
}

static int configure_sensor(float sensitivity) {
    if (sensitivity < 0.0 || sensitivity > ADC_MAX) {
        fprintf(stderr, "Invalid sensitivity %.2f, using default %.2f\n", sensitivity, DEFAULT_SENSITIVITY);
        sensitivity = DEFAULT_SENSITIVITY;
    }
    printf("Sensor sensitivity set to %.2f mV/A\n", sensitivity);
    return 0;
}

static int configure_fan(float threshold) {
    if (threshold < 0.0 || threshold > ADC_MAX) {
        fprintf(stderr, "Invalid threshold %.2f, using default %.2f\n", threshold, DEFAULT_CURRENT_THRESHOLD);
        threshold = DEFAULT_CURRENT_THRESHOLD;
    }
    printf("Fan threshold set to %.2f A\n", threshold);
    return 0;
}

static int log_data(float current_mA, int fan_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Current: %.2f A, Fan: %s\n", timestamp, current_mA, fan_state ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
        fan_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:t:h")) != -1) {
        switch (opt) {
            case 's':
                if (strcmp(optarg, "100") == 0) {
                    DEFAULT_SENSITIVITY = 100.0;
                    printf("Using default sensitivity: %.2f mV/A\n", DEFAULT_SENSITIVITY);
                } else {
                    fprintf(stderr, "Invalid sensitivity: %s\n", optarg);
                }
                break;
            case 't':
                if (strcmp(optarg, "5.0") == 0) {
                    DEFAULT_CURRENT_THRESHOLD = 5.0;
                    printf("Using default current threshold: %.2f A\n", DEFAULT_CURRENT_THRESHOLD);
                } else {
                    fprintf(stderr, "Invalid threshold: %s\n", optarg);
                }
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                fprintf(stderr, "  -s  Sensitivity in mV/A (default %.2f)\n", DEFAULT_SENSITIVITY);
                fprintf(stderr, "  -t  Current threshold in A (default %.2f)\n", DEFAULT_CURRENT_THRESHOLD);
                return EXIT_SUCCESS;
        }
    }

    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (configure_sensor(DEFAULT_SENSITIVITY) != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        return EXIT_FAILURE;
    }
    if (configure_fan(DEFAULT_CURRENT_THRESHOLD) != 0) {
        fprintf(stderr, "Fan configuration failed\n");
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fan_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!fan_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(fan_line, "mlx91219-fan", 0) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX91219 current monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = 0;
        if (spi_read_adc(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "SPI read error, skipping sample\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float current_mA = adc_to_current(adc_value);
        int fan_state = (current_mA > DEFAULT_CURRENT_THRESHOLD) ? 1 : 0;

        if (log_data(current_mA, fan_state) != 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }

        if (gpiod_line_set_value(fan_line, fan_state) != 0) {
            fprintf(stderr, "Failed to set fan GPIO: %s\n", strerror(errno));
        }

        printf("Current: %.2f A, Fan: %s\n", current_mA, fan_state ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

