#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define CO_SENSOR_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_co_sensor(int i2c_handle, int *co_value);
double convert_co_to_ppm(int co_value);
void log_co_data(double ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Read raw 16-bit ADC value from the CO sensor
int read_co_sensor(int i2c_handle, int *co_value) {
    char buffer[2];
    int result;

    // Send the start bit (0x01)
    result = i2cWriteByte(i2c_handle, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error writing start bit to I2C device: %d\n", result);
        return -1;
    }

    // Wait for the sensor to be ready (typically ~100ms)
    gpioDelay(100000); // 100ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *co_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Convert raw ADC value to CO concentration in PPM
double convert_co_to_ppm(int co_value) {
    // Logical curve parameters (example values)
    double slope = 0.01;
    double intercept = 0.0;
    double max_ppm = 1000.0;
    double min_ppm = 0.0;

    if (co_value < min_ppm) {
        return 0.0;
    }
    if (co_value > max_ppm) {
        return max_ppm;
    }

    double log_co = log10(co_value + intercept);
    double ppm = slope * log_co;
    if (ppm < 0.0) {
        ppm = 0.0;
    }
    if (ppm > max_ppm) {
        ppm = max_ppm;
    }
    return ppm;
}

// Log CO data to a file
void log_co_data(double ppm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, CO: %.2f PPM\n", timestamp, ppm);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int co_value;
        if (read_co_sensor(i2c_handle, &co_value) == 0) {
            double ppm = convert_co_to_ppm(co_value);
            log_co_data(ppm);
            printf("CO: %.2f PPM\n", ppm);
        } else {
            fprintf(stderr, "Error reading CO sensor. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    // Cleanup
    cleanup();
    printf("CO sensor monitoring stopped.\n");
    return 0;
}

