#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define CO_ADC_REG 0x00
#define NO2_ADC_REG 0x01
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static FILE *alert_file = NULL;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sensor_data(int handle, int *co_adc, int *no2_adc) {
    char buf[4];
    int result = i2cReadI2CBlockData(handle, CO_ADC_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    *co_adc = (buf[0] << 8) | buf[1];
    *no2_adc = (buf[2] << 8) | buf[3];
    return 0;
}

float calculate_co_ppm(int co_adc, int no2_adc) {
    return (float)co_adc / 32768.0f * 100.0f;
}

void log_data(float co_ppm, float no2_ppm) {
    time_t now = time(NULL);
