#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SENSOR_1_ADDR 0x48
#define SENSOR_2_ADDR 0x49
#define SENSOR_1_REG 0x00
#define SENSOR_2_REG 0x00
#define SENSOR_1_SENSITIVITY -38.0f
#define REFERENCE_PRESSURE 20.0e-6f
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "audio_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_raw(int handle, int reg, int16_t *raw) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float convert_to_db(int16_t raw) {
    return (float)raw / SENSOR_1_SENSITIVITY - REFERENCE_PRESSURE;
}

static int log_data(float avg_db) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_db);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, SENSOR_1_ADDR, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, SENSOR_2_ADDR, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Acoustic leak detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw1 = 0, raw2 = 0;
        int16_t err1 = 0, err2 = 0;

        if (read_raw(i2c_handle_1, SENSOR_1_REG, &raw1) < 0) {
            err1 = -999.0f;
        }
        if (read_raw(i2c_handle_2, SENSOR_2_REG, &raw2) < 0) {
            err2 = -999.0f;
        }

        float avg = (float)err1 + (float)err2;
        if (avg < 0.0f) {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        } else {
            if (log_data(convert_to_db(raw1)) < 0 ||
                log_data(convert_to_db(raw2)) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    gpioTerminate();
    return 0;
}

