    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    motor_line = gpiod_chip_get_line(chip, MOTOR_GPIO);
    if (!motor_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", MOTOR_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(motor_line, "motor-control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", MOTOR_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(log_file, "Timestamp,Current_Amperes\n");
    fflush(log_file);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = spi_read_adc(SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error, retrying...\n");
            usleep(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        if (log_data(current) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        if (current > OVERCURRENT_THRESHOLD) {
            printf("Current exceeds threshold: %.3f A\n", current);
            motor_shutdown();
            motor_enable();
            usleep(1000000);
            motor_disable();
            usleep(1000000);
        }

        usleep(SAMPLE_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    motor_disable();
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

