#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define PRESSURE_SCALE 500.0f   /* kPa per raw */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: set flag, then let main loop   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a CSV row to the log file.                                    */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_row(FILE *fp, const char *timestamp, float pressure)
{
    if (fprintf(fp, "%s,%.2f\n", timestamp, pressure) < 0) {
        perror("fprintf to log file");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian pressure value from the MLX90817.        */
/* Returns 0 on success, -1 on I2C read failure.                      */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, float *pressure)
{
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr,
                "I2C read failed at register 0x%02X (rc=%d)\n",
                PRESSURE_REG, rc);
        return -1;
    }

    /* MLX90817 pressure register is 16-bit big-endian */
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure = (float)raw / 65535.0f * PRESSURE_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — release I2C handle and close log file.                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file once at startup --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen log file");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log_fp, "timestamp,pressure_kPa\n");
    fflush(g_log_fp);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90817 pressure logger started. Logging to %s every 1 s.\n",
           LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        float pressure;
        int rc;

        rc = read_pressure(g_i2c_handle, &pressure);
        if (rc == 0) {
            char ts[32];
            time_t now = time(NULL);
            struct tm tm_info;
            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
            } else {
                strncpy(ts, "1970-01-01T00:00:00", sizeof(ts) - 1);
                ts[sizeof(ts) - 1] = '\0';
            }
            if (log_row(g_log_fp, ts, pressure) != 0) {
                fprintf(stderr, "Failed to write row to log file.\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_US / 1000000 && g_running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

