    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90817 pressure logger started. Logging to %s every 1 s.\n",
           LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        float pressure;
        int rc;

        rc = read_pressure(g_i2c_handle, &pressure);
        if (rc == 0) {
            char ts[32];
            time_t now = time(NULL);
            struct tm tm_info;
            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
            } else {
                strncpy(ts, "1970-01-01T00:00:00", sizeof(ts) - 1);
                ts[sizeof(ts) - 1] = '\0';
            }
            if (log_row(g_log_fp, ts, pressure) != 0) {
                fprintf(stderr, "Failed to write row to log file.\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_US / 1000000 && g_running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

