#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define WARNING_LED_PIN 17
#define PRESSURE_THRESHOLD 105.0
#define ADC_MAX_VALUE 65535.0
#define ADC_SCALE (ADC_MAX_VALUE / (2.0 / 3.0))
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 400.0
#define TEMP_MIN 0.0
#define TEMP_MAX 100.0
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_ads1115(float *pressure, float *temperature) {
    char buffer[2];
    int16_t raw_pressure, raw_temperature;

    for (int attempt = 1; attempt <= 3; attempt++) {
        if (i2cWriteDevice(i2c_handle, buffer, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", attempt, i2c_handle);
            if (attempt < 3) {
                gpioDelay(10000);
            }
            continue;
        }

        int16_t result = i2cReadDevice(i2c_handle, buffer, 2);
        if (result != 2) {
            fprintf(stderr, "I2C read failed (attempt %d): got %d, expected 2\n", attempt, result);
            if (attempt < 3) {
                gpioDelay(10000);
            }
            continue;
        }

        raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
        raw_temperature = (int16_t)((buffer[1] << 8) | buffer[0]);

        if (raw_pressure < 0 || raw_pressure > 32767) {
            fprintf(stderr, "ADC raw value out of range: %d\n", raw_pressure);
            if (attempt < 3) {
                gpioDelay(10000);
            }
            continue;
        }

        *pressure = (float)raw_pressure / ADC_SCALE;
        *temperature = (float)raw_temperature / 128.0;

        return 0;
    }

    fprintf(stderr, "Failed to read sensor after 3 attempts\n");
    return -1;
}

static float convert_pressure(float raw_pressure) {
    return PRESSURE_MIN + (PRESSURE_MAX - PRESSURE_MIN) * (raw_pressure / ADC_MAX_VALUE);
}

static float convert_temperature(float raw_temperature) {
    return TEMP_MIN + (TEMP_MAX - TEMP_MIN) * (raw_temperature / ADC_MAX_VALUE);
}

static void display_data(float pressure, float temperature) {
    printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
    fflush(stdout);
}

static void control_warning_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(WARNING_LED_PIN, 1);
    } else {
        gpioWrite(WARNING_LED_PIN, 0);
    }
}

int main(void) {
    float pressure, temperature;

    signal(SIGINT, signal_handler);

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioSetMode(WARNING_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", WARNING_LED_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(WARNING_LED_PIN, 0);

    while (!terminate) {
        if (read_ads1115(&pressure, &temperature) == 0) {
            display_data(pressure, temperature);
            control_warning_led(pressure);
        } else {
            fprintf(stderr, "Sensor read failed, retrying in 1 second...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

