#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define VCC 3.3
#define ADC_MAX 1023
#define SENSOR_ZERO_CURRENT 0.0
#define SENSOR_SENSITIVITY 0.066
#define OVERCURRENT_THRESHOLD 10.0
#define GPIO_SHUTDOWN 27
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_US 100000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) return -1;

    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / (float)ADC_MAX) * VCC;
}

static float voltage_to_current(float voltage) {
    return (voltage - SENSOR_ZERO_CURRENT) / SENSOR_SENSITIVITY;
}

static void log_current(float current) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file) {
        fprintf(log_file, "%s, %.2f A\n", timestamp, current);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

static void shutdown_motor(void) {
    gpioWrite(GPIO_SHUTDOWN, 1);
    printf("Motor shutdown triggered\n");
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying in 100ms\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        if (current > OVERCURRENT_THRESHOLD) {
            shutdown_motor();
            log_current(current);
            fprintf(stderr, "Current %.2f A exceeds threshold, shutting down\n", current);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Program terminated gracefully\n");
    return 0;
}

