#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ALARM_GPIO 4
#define VREF 3.3
#define VTHRESHOLD 2.5
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float voltage_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0f) * VREF;
}

static void control_alarm(int gpio_pin, int voltage_exceeded) {
    if (gpioWrite(gpio_pin, voltage_exceeded ? 1 : 0) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", gpio_pin);
    }
}

static void log_reading(FILE *fp, int adc_value, float voltage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,Voltage: %.2f V\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, voltage);
    fflush(fp);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, retrying in 1 s...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = voltage_to_voltage(adc_value);
        printf("ADC: %4d, Voltage: %.2f V\n", adc_value, voltage);

        if (voltage > VTHRESHOLD) {
            control_alarm(ALARM_GPIO, 1);
        } else {
            control_alarm(ALARM_GPIO, 0);
        }

        log_reading(log_file, adc_value, voltage);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("CO sensor monitoring stopped.\n");
    return 0;
}

