#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define LOG_FILE "mcp3008_log.txt"
#define ALARM_THRESHOLD 1000.0
#define ADC_MAX 1023
#define ADC_SCALE (ADC_MAX * 1000.0) / (ALARM_THRESHOLD - 0.0)

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_ppm(int adc_value) {
    return (float)adc_value / (float)ADC_MAX * ALARM_THRESHOLD;
}

static void log_data(float ppm) {
    time_t now = time(NULL);
    struct tm *t = localtime_r(&now, NULL);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, Methane: %.2f PPM\n", ts, ppm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open\n");
    }
}

static void check_alarm(float ppm) {
    if (ppm > ALARM_THRESHOLD) {
        printf("ALARM: Methane concentration exceeds threshold!\n");
        fflush(stdout);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MCP3008 methane monitor started. Logging to '%s' every 1 s.\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "Error: SPI read failed, retrying...\n");
            time_sleep(1.0);
            continue;
        }

        float ppm = adc_to_ppm(adc);
        log_data(ppm);
        check_alarm(ppm);

        time_sleep(1.0);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

