#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define MCP3208_CS 8
#define MCP3208_ADDR 0x80
#define MCP3208_REG_CONFIG 0x00
#define MCP3208_REG_DATA 0x01

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    float humidity;
    float temperature;
} SensorData;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3208(int handle, int reg, int *value) {
    char tx[2] = {0x80 | (reg << 1), 0x00};
    char rx[2] = {0};
    if (spiXfer(handle, tx, rx, 2) != 2) return -1;
    *value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

static int read_mcp3208_config(int handle) {
    char tx[2] = {0x80 | (0x80 << 1), 0x00};
    char rx[2] = {0};
    if (spiXfer(handle, tx, rx, 2) != 2) return -1;
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int read_mcp3208_data(int handle, int reg, int *value) {
    char tx[2] = {0x80 | (reg << 1), 0x00};
    char rx[2] = {0};
    if (spiXfer(handle, tx, rx, 2) != 2) return -1;
    *value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

static float calculate_relative_humidity(int value) {
    float voltage = (float)value / 1023.0 * 5.0;
    float humidity = 0.824 + 0.0315 * voltage;
    return humidity;
}

static float calculate_temperature(int value) {
    float voltage = (float)value / 1023.0 * 5.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

static int log_data(FILE *fp, float humidity, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(fp);
    return 0;
}

static int send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command), "echo 'Subject: HIH-4602-A Alert\n\nHumidity: %.2f%%' | ssmtp user@example.com", humidity);
    int ret = system(command);
    if (ret == -1) {
        fprintf(stderr, "Failed to execute ssmtp command\n");
        return -1;
    }
    if (ret != 0) {
        fprintf(stderr, "ssmtp command failed with exit code %d\n", ret);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int mcp_config = read_mcp3208_config(spi_handle);
    if (mcp_config < 0) {
        fprintf(stderr, "Failed to read MCP3208 config\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (mcp_config & 0x03) {
        fprintf(stderr, "MCP3208 not found or not responding\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    int mcp_cs = MCP3208_CS;
    if (mcp_cs == 8) mcp_cs = 0;
    if (mcp_cs == 9) mcp_cs = 1;

    int mcp_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (mcp_handle < 0) {
        fprintf(stderr, "SPI open failed for MCP3208\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int humidity = 0;
        int temperature = 0;
        int mcp_value = 0;

        if (read_mcp3208_data(mcp_handle, MCP3208_REG_DATA, &mcp_value) != 0) {
            fprintf(stderr, "Failed to read MCP3208 data\n");
            log_data(log_file, 0.0, 0.0);
            sleep(1);
            continue;
        }

        if (read_mcp3208_config(spi_handle) != 0) {
            fprintf(stderr, "Failed to read MCP3208 config\n");
            log_data(log_file, 0.0, 0.0);
            sleep(1);
            continue;
        }

        if (mcp_value & 0x03) {
            fprintf(stderr, "MCP3208 not responding\n");
            log_data(log_file, 0.0, 0.0);
            sleep(1);
            continue;
        }

        float humidity_raw = calculate_relative_humidity(mcp_value);
        float temperature_raw = calculate_temperature(mcp_value);

        if (humidity_raw < 0.0) {
            fprintf(stderr, "Failed to calculate humidity\n");
            log_data(log_file, 0.0, 0.0);
            sleep(1);
            continue;
        }

        if (temperature_raw < 0.0) {
            fprintf(stderr, "Failed to calculate temperature\n");
            log_data(log_file, 0.0, 0.0);
            sleep(1);
            continue;
        }

        humidity = humidity_raw;
        temperature = temperature_raw;

        if (humidity > HUMIDITY_THRESHOLD) {
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Failed to send email alert\n");
            }
        }

        log_data(log_file, humidity, temperature);
        sleep(1);
    }

    fprintf(stderr, "Shutting down gracefully...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

