#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 1023.0
#define ADXL335_SENSITIVITY 300.0
#define ADXL335_ZERO_G_POINT 1.65
#define IMPACT_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"
#define SAMPLE_INTERVAL_US 100000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_adxl335(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0, 0, 0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > ADC_RESOLUTION) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static float calculate_acceleration(int adc_value) {
    float voltage = (float)adc_value / ADC_RESOLUTION * ADXL335_SENSITIVITY;
    float g_x = (voltage - ADXL335_ZERO_G_POINT) / ADXL335_SENSITIVITY;
    float g_y = (voltage - ADXL335_ZERO_G_POINT) / ADXL335_SENSITIVITY;
    float g_z = (voltage - ADXL335_ZERO_G_POINT) / ADXL335_SENSITIVITY;
    return sqrtf(g_x * g_x + g_y * g_y + g_z * g_z);
}

static void log_impact(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_x = read_adxl335(ADC_CHANNEL);
        int adc_y = read_adxl335(ADC_CHANNEL);
        int adc_z = read_adxl335(ADC_CHANNEL);

        if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float x = calculate_acceleration(adc_x);
        float y = calculate_acceleration(adc_y);
        float z = calculate_acceleration(adc_z);

        log_impact(x, y, z);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Impact detection stopped.\n");
    return 0;
}

