/*
 * Si1172-A30-GMR Optical Heart Rate Sensor Reader for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   Si1172 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Si1172 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Si1172 VDD -> 3.3 V
 *   Si1172 GND -> GND
 *
 * Build: gcc -o si1172_reader si1172_reader.c -lpigpio -lrt
 * Run:   sudo ./si1172_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1172_ADDR    0x49
#define LOG_FILE       "biometric_log.csv"
#define SAMPLE_PERIOD  1
#define FIFO_SIZE      4

/* Si1172 register addresses */
#define REG_COMMAND     0xC0
#define REG_FIFO_DATA   0xC1
#define REG_FIFO_DATA_0 0xC1
#define REG_FIFO_DATA_1 0xC2
#define REG_FIFO_DATA_2 0xC3
#define REG_FIFO_DATA_3 0xC4

/* Si1172 command register values */
#define CMD_MEASURE     0x01
#define CMD_RESET       0x00

/* Si1172 command codes */
#define CMD_RESET_EXPECTED 0x01

/* Si1172 data register addresses */
#define REG_HR_DATA_0    0x00
#define REG_HR_DATA_1    0x01
#define REG_HR_DATA_2    0x02
#define REG_HR_DATA_3    0x03
#define REG_SPO2_DATA_0  0x04
#define REG_SPO2_DATA_1  0x05
#define REG_SPO2_DATA_2  0x06
#define REG_SPO2_DATA_3  0x07

/* Si1172 data register values */
#define DATA_HR_OK       0x00
#define DATA_HR_ERR      0x01
#define DATA_SPO2_OK     0x00
#define DATA_SPO2_ERR    0x01

/* Error flags */
#define ERROR_OK 0
#define ERROR_READ_FIFO_DATA 1
#define ERROR_NO_SENSOR 2

typedef struct {
    int i2c_handle;
    FILE *log_file;
    volatile sig_atomic_t running;
} AppState;

static AppState app_state = {0};

static void signal_handler(int sig) {
    (void)sig;
    app_state.running = 0;
}

/*
 * Write a single byte to a Si1172 register.
 * Returns 0 on success, -1 on failure.
 */
static int si1172_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a Si1172 register.
 * Returns 0 on success, -1 on failure.
 */
static int si1172_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice (reg select) failed for reg 0x%02X\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: i2cReadDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

/*
 * Trigger a measurement and read the raw photoplethysmography data.
 * Returns 0 on success, -1 on failure.
 */
static int si1172_read_raw_data(int handle, uint8_t *raw_data) {
    /* Trigger a measurement */
    if (si1172_write_reg(handle, REG_COMMAND, CMD_MEASURE) != 0) {
        return -1;
    }

    /* Wait for measurement to complete (~1.5ms typical) */
