 * Read a single photoplethysmography sample.
 * Returns 0 on success, -1 on failure.
 */
static int si1172_read_sample(int handle, uint8_t *sample) {
    if (si1172_read_reg(handle, REG_HR_DATA_0, sample) != 0) {
        return -1;
    }
    return 0;
}

