        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/*
 * Cleanup resources.
 */
static void cleanup(void) {
    if (app_state.log_file != NULL) {
        fclose(app_state.log_file);
        app_state.log_file = NULL;
    }
    if (app_state.i2c_handle >= 0) {
