    }

    /* Open the log file */
    app_state.log_file = fopen(LOG_FILE, "a");
    if (app_state.log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write the CSV header if the file is empty */
    fseek(app_state.log_file, 0, SEEK_END);
    if (ftell(app_state.log_file) == 0) {
        fprintf(app_state.log_file, "timestamp,hr_bpm,spo2_percent,error_flag\n");
