#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_MICS 2
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNELS 8
#define ADC_RESOLUTION 1023.0
#define SAMPLE_RATE 44100
#define SAMPLE_SIZE (SAMPLE_RATE * NUM_MICS)
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int spi_speed = SPI_SPEED;
static int spi_channel = SPI_CHANNEL;
static int gain = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_gain(int *audio_data) {
    if (audio_data == NULL) {
        fprintf(stderr, "Error: Audio data pointer is NULL\n");
        return 0.0f;
    }

    float sum = 0.0f;
    for (int i = 0; i < SAMPLE_SIZE; i++) {
        sum += audio_data[i];
    }
    return sum / SAMPLE_SIZE;
}

static int play_audio(float *audio_data) {
    if (audio_data == NULL) {
        fprintf(stderr, "Error: Audio data pointer is NULL\n");
        return -1;
    }

    int channels = NUM_MICS;
    int samples = SAMPLE_SIZE;
    int channels_per_sample = channels * 2;
    int total_samples = samples * channels;

    int *buffer = malloc(total_samples * sizeof(int));
    if (buffer == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return -1;
    }

    for (int i = 0; i < samples; i++) {
        for (int j = 0; j < channels; j++) {
            int adc_value = read_mcp3008(j);
            if (adc_value < 0) {
                fprintf(stderr, "Error: ADC read failed at channel %d\n", j);
                free(buffer);
                return -1;
            }
            buffer[i * channels_per_sample + j] = (int)adc_value;
        }
    }

    int *output_buffer = malloc(total_samples * sizeof(int));
    if (output_buffer == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(buffer);
        return -1;
    }

    for (int i = 0; i < samples; i++) {
        for (int j = 0; j < channels; j++) {
            int adc_value = read_mcp3008(j);
            if (adc_value < 0) {
                fprintf(stderr, "Error: ADC read failed at channel %d\n", j);
                free(output_buffer);
                free(buffer);
                return -1;
            }
            output_buffer[i * channels_per_sample + j] = (int)adc_value;
        }
    }

    int *input_buffer = malloc(total_samples * sizeof(int));
    if (input_buffer == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(output_buffer);
        free(buffer);
        return -1;
    }

    for (int i = 0; i < samples; i++) {
        for (int j = 0; j < channels; j++) {
            int adc_value = read_mcp3008(j);
            if (adc_value < 0) {
                fprintf(stderr, "Error: ADC read failed at channel %d\n", j);
                free(input_buffer);
                free(output_buffer);
                return -1;
            }
            input_buffer[i * channels_per_sample + j] = (int)adc_value;
        }
    }

    for (int i = 0; i < total_samples; i++) {
        int index = i * channels_per_sample;
        int value = input_buffer[index];
        output_buffer[index] = value;
    }

    free(input_buffer);
    free(output_buffer);
    free(buffer);
    return 0;
}

static void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <gain_factor>\n", argv[0]);
        return 1;
    }

    float *audio_data = malloc(NUM_MICS * sizeof(float));
    if (audio_data == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_MICS; i++) {
        audio_data[i] = 0.0f;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        free(audio_data);
        return 1;
    }

    spi_handle = spiOpen(spi_channel, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d)\n", spi_channel, SPI_SPEED);
        gpioTerminate();
        free(audio_data);
        return 1;
    }

    int *gain_buffer = malloc(NUM_MICS * sizeof(int));
    if (gain_buffer == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        free(audio_data);
        return 1;
    }

    for (int i = 0; i < NUM_MICS; i++) {
        gain_buffer[i] = 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        if (play_audio(audio_data) == 0) {
            for (int i = 0; i < NUM_MICS; i++) {
                gain_buffer[i] = calculate_gain(audio_data);
            }
            for (int i = 0; i < NUM_MICS; i++) {
                if (gain_buffer[i] > 0) {
                    printf("MCP23S2: %d, gain: %.2f\n", i, gain_buffer[i]);
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to play audio\n");
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

