#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define BUZZER_GPIO 18
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define ADC_MAX 1023.0
#define ADC_MIN 0.0
#define ADC_VOLTAGE_OFFSET 0.0
#define ADC_VOLTAGE_SCALE (ADC_MAX - ADC_MIN)
#define TEMP_OFFSET 25.0
#define TEMP_SCALE 0.001
#define FLAME_THRESHOLD 1.0
#define RETRY_MAX 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    unsigned int bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    return fd;
}

static int spi_read_mcp3008(int fd, int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((channel & 0x07) << 4 | 0x80),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_voltage(int adc_value) {
    return (adc_value / ADC_MAX) * ADC_VOLTAGE_SCALE + ADC_VOLTAGE_OFFSET;
}

static float voltage_to_temperature(float voltage) {
    return (voltage - TEMP_OFFSET) * TEMP_SCALE;
}

static float voltage_to_compensated_voltage(float voltage) {
    return voltage + (voltage - FLAME_THRESHOLD) * TEMP_SCALE;
}

