    struct tm *timeinfo;
    char filename[64];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "ambient_temp.txt", timeinfo);

    if (access(filename, F_OK) == 0) {
        FILE *fp = fopen(filename, "r");
        if (fp) {
