    } else {
        fprintf(stderr, "Log file not open\n");
    }
    return 0;
}

static void control_buzzer(int state) {
    if (gpiod_line_set_value(buzzer_line, state) < 0) {
        perror("Failed to set buzzer GPIO");
    }
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

