                    fprintf(stderr, "SPI read failed, retrying...\n");
                }
            }
            usleep(100000);
        }

        if (!success) {
            fprintf(stderr, "SPI read failed after %d retries, skipping iteration\n", RETRY_MAX);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = adc_to_voltage(raw_adc);
        float compensated_voltage = voltage_to_compensated_voltage(voltage);
        float temperature = voltage_to_temperature(voltage);
        int flame_detected = (compensated_voltage > FLAME_THRESHOLD);

        if (log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected) != 0) {
            fprintf(stderr, "Logging failed, skipping iteration\n");
        }

        control_buzzer(flame_detected);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

