#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_GPIO 17
#define WATER_THRESHOLD_HIGH 75.0
#define WATER_THRESHOLD_LOW 70.0
#define ADC_CHANNEL 0
#define LOG_FILE "water_levels.json"
#define SAMPLE_INTERVAL_US 5000000
#define SPI_RETRIES 3
#define SPI_RETRY_DELAY_US 100000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n",
                attempt + 1, SPI_RETRIES, ret);
        if (attempt < SPI_RETRIES - 1) {
            gpioDelay(SPI_RETRY_DELAY_US);
        }
    }
    return -1;
}

static int log_water_level(float water_level) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Failed to get current time\n");
        return -1;
    }

    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "Failed to convert time\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tstruct) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "[%s]\n", timestamp) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void control_led(float water_level) {
    if (water_level > WATER_THRESHOLD_HIGH) {
        gpioWrite(LED_GPIO, 1);
    } else if (water_level < WATER_THRESHOLD_LOW) {
        gpioWrite(LED_GPIO, 0);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        cleanup();
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping this sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float water_level = (float)adc_value / 1023.0f * 100.0f;
        if (log_water_level(water_level) != 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }

        control_led(water_level);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

