        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        cleanup();
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping this sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float water_level = (float)adc_value / 1023.0f * 100.0f;
        if (log_water_level(water_level) != 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }

        control_led(water_level);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

