#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define MIN_RAW_VALUE 300
#define MAX_RAW_VALUE 700
#define MIN_MOISTURE_PERCENTAGE 30
#define MAX_MOISTURE_PERCENTAGE 100
#define LOG_INTERVAL_SEC 60
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_CONFIG_FILE "email_config.txt"
#define LOG_FILE "plant_data.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < MIN_RAW_VALUE) adc_value = MIN_RAW_VALUE;
    if (adc_value > MAX_RAW_VALUE) adc_value = MAX_RAW_VALUE;
    return ((float)adc_value - MIN_RAW_VALUE) / (MAX_RAW_VALUE - MIN_RAW_VALUE) * 100.0f;
}

static int log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error: Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f, %s\n", timestamp, moisture_percentage, EMAIL_RECIPIENT);
    fclose(fp);
    return 0;
}

static int send_email_alert(float moisture_percentage) {
    FILE *fp = fopen(EMAIL_CONFIG_FILE, "r");
    if (!fp) {
        perror("Error: Failed to open email config file");
        return -1;
    }

    char config_line[256];
    if (fgets(config_line, sizeof(config_line), fp) == NULL) {
        fprintf(stderr, "Error: Failed to read email config file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char command[256];
    snprintf(command, sizeof(command), "echo \"%s\" | msmtp -s \"%s\" --to \"%s\"", config_line, EMAIL_RECIPIENT, EMAIL_RECIPIENT);

    int status = system(command);
    if (status == -1) {
        perror("Error: Failed to execute msmtp");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel>\n", argv[0]);
        return 1;
    }

    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);

    if (spi_channel < 0 || spi_channel > 7) {
        fprintf(stderr, "Error: Invalid SPI channel %d\n", spi_channel);
        return 1;
    }

    if (adc_channel < 0 || adc_channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", adc_channel);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(spi_channel, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring plant moisture via MCP3008 ADC on SPI channel %d, ADC channel %d\n", spi_channel, adc_channel);
    printf("Logging to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, LOG_INTERVAL_SEC);

    while (running) {
        int adc_value = read_mcp3008(adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(LOG_INTERVAL_SEC);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value);
        printf("Moisture: %.2f%%\n", moisture_percentage);

        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        if (moisture_percentage < MIN_MOISTURE_PERCENTAGE) {
            printf("Alert: Moisture below threshold (%.2f%%)\n", moisture_percentage);
            if (send_email_alert(moisture_percentage) != 0) {
                fprintf(stderr, "Error: Failed to send email alert\n");
            }
        }

        sleep(LOG_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

