/* ------------------------------------------------------------------ */
static int calculate_moisture_percentage(int adc_value)
{
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value %d out of range (0–1023)\n", adc_value);
