#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define ADC_MIN 0
#define ADC_VREF 3.3
#define PRESSURE_MIN 0.5
#define PRESSURE_MAX 4.5
#define SAMPLE_INTERVAL_US 1000000
#define SAMPLE_DELAY_US (SAMPLE_INTERVAL_US / 1000)
#define SENSOR_THRESHOLD_V 0.0
#define SENSOR_THRESHOLD_P 0.5
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

float adc_to_voltage(int adc_value) {
    return ((float)adc_value / ADC_MAX) * ADC_VREF;
}

float voltage_to_pressure(float voltage) {
    if (voltage < PRESSURE_MIN) return PRESSURE_MIN;
    if (voltage > PRESSURE_MAX) return PRESSURE_MAX;
    return (voltage - PRESSURE_MIN) / (PRESSURE_MAX - PRESSURE_MIN) * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;
}

void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    printf("[%s] Pressure: %.2f kPa\n", timestamp, pressure);
    fflush(stdout);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float pressure = voltage_to_pressure(voltage);

        if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
            fprintf(stderr, "Warning: Pressure out of range: %.2f kPa\n", pressure);
        } else {
            log_data(pressure);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

