#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define ADC_CHANNEL 0
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define SAMPLE_INTERVAL_SEC 5
#define SAMPLE_US (1000000 / SAMPLE_INTERVAL_SEC)

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *en_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
    };

    if (gpiod_line_set_value(en_line, 0) < 0) {
        perror("Failed to set CS low");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(en_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(en_line, 1) < 0) {
        perror("Failed to set CS high");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_soil_moisture(void) {
    int adc_value = spi_read_channel(ADC_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1;
    }

    if (adc_value == 0) {
        fprintf(stderr, "Warning: ADC value stuck at 0 (wiring fault?)\n");
        return -1;
    }
    if (adc_value == 1023) {
        fprintf(stderr, "Warning: ADC value stuck at 1023 (wiring fault?)\n");
        return -1;
    }

    float moisture = ((float)adc_value / 1023.0f) * 100.0f;
    if (moisture < 0.0f) moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;

    return (int)moisture;
}

static void log_data(int moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Moisture: %d%%\n", timestamp, moisture_percentage);
    fflush(stdout);
}

static void cleanup(void) {
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (en_line) {
        gpiod_line_set_value(en_line, 1);
        gpiod_line_release(en_line);
        en_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    en_line = gpiod_chip_get_line(chip, 17);
    if (!cs_line || !en_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(en_line, "mcp3008_en", 1) < 0) {
        perror("Failed to request EN line as output");
        cleanup();
        return 1;
    }

    printf("Soil Moisture Sensor Monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_percentage = read_soil_moisture();
        if (moisture_percentage < 0) {
            fprintf(stderr, "Error reading soil moisture, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        log_data(moisture_percentage);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

