    return ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_moisture_percentage(float moisture) {
    if (moisture < 0.0f) moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;
    printf("Moisture: %.2f%%\n", moisture);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    printf("Soil Moisture Monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture = calculate_moisture_percentage(adc_value);
        log_moisture_percentage(moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Warning: Moisture below threshold (%f%%). Retrying in %d seconds.\n", moisture, SAMPLE_INTERVAL);
        }

        sleep(SAMPLE_INTERVAL);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    printf("Soil Moisture Monitoring stopped.\n");
    return 0;
}

