#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 300
#define MOISTURE_HIGH 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 5000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int spi_ready = 0;
static int buffer_index = 0;
static int buffer_count = 0;

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} log_entry_t;

static log_entry_t log_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_count_full = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void log_data(int moisture_level, int pump_state) {
    log_entry_t entry = {.timestamp = time(NULL), .moisture_level = moisture_level, .pump_state = pump_state};
    memcpy(&log_buffer[buffer_head], &entry, sizeof(log_entry_t));
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count_full) {
        buffer_count_full--;
    } else {
        buffer_count++;
    }
}

static void control_pump(int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1);
    } else if (moisture_level > MOISTURE_HIGH) {
        gpioWrite(PUMP_GPIO, 0);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int pump_state = gpioRead(PUMP_GPIO);
        if (pump_state < 0) {
            fprintf(stderr, "Error: Failed to read pump GPIO\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        control_pump(moisture_level);
        log_data(moisture_level, pump_state);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

