/* MAX30102 I2C address */
#define MAX30102_ADDR 0x57

/* MAX30102 registers */
#define MAX30102_PART_ID_REG 0xFF
#define MAX30102_MODE_CONFIG_REG 0x06
#define MAX30102_LED1_PA_REG 0x09
#define MAX30102_LED2_PA_REG 0x0A
#define MAX30102_FIFO_DATA_REG 0x07
#define MAX30102_FIFO_DATA_LEN 6

/* Expected Part ID */
#define MAX30102_PART_ID_EXPECTED 0x15

/* SpO2/HR configuration */
#define MAX30102_SPO2_CONFIG 0x27
#define MAX30102_LED_PULSES_PER_SAMPLE 0x27

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to a register */
static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
    }
    return rc;
