#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define LOG_FILE "soil_moisture_log.csv"
#define SAMPLE_INTERVAL_SEC 5
#define NUM_MCP3008 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, unsigned char *tx, unsigned char *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        return -1;
    }
    return 0;
}

static int read_mcp3008(int fd, int channel, int *value) {
    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0};
    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
        return -1;
    }
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_data(const char *filename, int sensor1, int sensor2, int sensor3) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                sensor1, sensor2, sensor3);
    } else {
        fprintf(fp, "Timestamp error\n");
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs0 = NULL, *cs1 = NULL, *cs2 = NULL;
    int ret = 1;

    for (int i = 0; i < NUM_MCP3008; i++) {
        spi_fd = open(SPI_DEVICE, O_RDWR);
        if (spi_fd < 0) {
            fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
            goto cleanup;
        }
        unsigned char mode = SPI_MODE;
        unsigned char bits = SPI_BITS;
        unsigned char speed = SPI_SPEED;
        if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
            ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
            ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
            fprintf(stderr, "Error configuring SPI: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    cs0 = gpiod_chip_get_line(chip, 8);
    cs1 = gpiod_chip_get_line(chip, 7);
    cs2 = gpiod_chip_get_line(chip, 25);
    if (!cs0 || !cs1 || !cs2) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs0, "mcp3008_cs0", 1) < 0 ||
        gpiod_line_request_output(cs1, "mcp3008_cs1", 1) < 0 ||
        gpiod_line_request_output(cs2, "mcp3008_cs2", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Logging soil moisture data to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        int sensor1 = -1, sensor2 = -1, sensor3 = -1;
        for (int i = 0; i < NUM_MCP3008; i++) {
            int val = read_mcp3008(spi_fd, i, &sensor1);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                continue;
            }
            sensor1 = val;
            val = read_mcp3008(spi_fd, i + NUM_MCP3008, &sensor2);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i + NUM_MCP3008);
                continue;
            }
            sensor2 = val;
            val = read_mcp3008(spi_fd, i + 2 * NUM_MCP3008, &sensor3);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i + 2 * NUM_MCP3008);
                continue;
            }
            sensor3 = val;
            if (log_data(LOG_FILE, sensor1, sensor2, sensor3) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    ret = 0;

cleanup:
    if (cs0) gpiod_line_release(cs0);
    if (cs1) gpiod_line_release(cs1);
    if (cs2) gpiod_line_release(cs2);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    return ret;
}

