code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define MOISTURE_THRESHOLD 30
#define MOISTURE_DARK 200
#define MOISTURE_WET 800
#define MOISTURE_MAX 100
#define MOISTURE_MIN 0
#define LOG_FILE "irrigation.log"
#define SLEEP_INTERVAL 60
#define RETRY_COUNT 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n",
                attempt + 1, RETRY_COUNT, ret);
        if (attempt < RETRY_COUNT - 1) {
            gpioDelay(10000);
        }
    }
    return -1;
}

static int map_moisture(int adc_value) {
    if (adc_value < MOISTURE_MIN) return MOISTURE_MIN;
    if (adc_value > MOISTURE_MAX) return MOISTURE_MAX;
    return (int)(((float)adc_value - MOISTURE_DARK) /
                 (MOISTURE_WET - MOISTURE_DARK) * (MOISTURE_MAX - MOISTURE_MIN) + MOISTURE_MIN);
}

static int activate_pump(int duration_seconds) {
    if (gpioWrite(PUMP_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to activate pump GPIO\n");
        return -1;
    }
    printf("Pump activated for %d seconds\n", duration_seconds);
    return 0;
}

static int deactivate_pump(void) {
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to deactivate pump GPIO\n");
        return -1;
    }
    printf("Pump deactivated\n");
    return 0;
}

static int log_irrigation(int moisture_percentage, int pump_active) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Moisture: %d%% - Pump: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            moisture_percentage, pump_active ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    int threshold = MOISTURE_DARK;
    int duration_seconds = 10;
    int sleep_interval = SLEEP_INTERVAL;

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold < 0 || threshold > 100) {
            fprintf(stderr, "Invalid threshold value: %d\n", threshold);
            return 1;
        }
    }
    if (argc > 2) {
        duration_seconds = atoi(argv[2]);
        if (duration_seconds < 1 || duration_seconds > 300) {
            fprintf(stderr, "Invalid duration value: %d\n", duration_seconds);
            return 1;
        }
    }
    if (argc > 3) {
        sleep_interval = atoi(argv[3]);
        if (sleep_interval < 1 || sleep_interval > 300) {
            fprintf(stderr, "Invalid sleep interval value: %d\n", sleep_interval);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Irrigation system started. Threshold: %d%% (0-100), Duration: %d s, Sleep: %d s\n",
           threshold, duration_seconds, sleep_interval);

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", RETRY_COUNT);
            gpioDelay(100000);
            continue;
        }

        int moisture_percentage = map_moisture(adc_value);
        int pump_active = (moisture_percentage < threshold) ? 1 : 0;

        if (pump_active) {
            if (activate_pump(duration_seconds) != 0) {
                fprintf(stderr, "Failed to activate pump\n");
            }
        }

        if (log_irrigation(moisture_percentage, pump_active) != 0) {
            fprintf(stderr, "Failed to log irrigation\n");
        }

        if (pump_active) {
            sleep_interval = duration_seconds;
        } else {
            sleep_interval = SLEEP_INTERVAL;
        }

        printf("Moisture: %d%% - Pump: %s\n", moisture_percentage, pump_active ? "ON" : "OFF");
        fflush(stdout);

        if (running) {
            gpioDelay(sleep_interval * 1000000);
        }
    }

    printf("\nShutting down...\n");
    deactivate_pump();
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
