    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float sound_level = (float)adc_value / 1023.0f;
        float peak_value = calculate_ema(sound_level);

        if (peak_value > 0.0f) {
            log_peak(peak_value);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

