#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define AIN0_CHANNEL   0
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    uint8_t control = 0x00;
    uint8_t sample;
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * PCF8591: single-ended channel 0 (AIN0) in single-shot mode.
     * Control byte: 0x00 (bit 0 = 1 = single-shot, bit 1 = 0 = disabled).
     */
    control = 0x00;
    if (i2c_write_reg8(fd, 0x00, control) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Monitoring AIN0 on PCF8591 at 0x%02X on %s every %d ms. Press Ctrl-C to exit.\n",
           PCF8591_ADDR, I2C_BUS, SAMPLE_MS);

    while (g_running) {
        if (i2c_read_reg8(fd, 0x00, &sample) < 0) {
            fprintf(stderr, "I2C read failed; continuing.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        /*
         * PCF8591 returns the result of the previous conversion.
         * We discard the first byte (control) and read again to get the
         * current sample.
         */
        if (i2c_read_reg8(fd, 0x00, &sample) < 0) {
            fprintf(stderr, "I2C read failed; continuing.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        printf("AIN0: %d\n", sample);
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nExiting cleanly.\n");
    if (fd >= 0)
        close(fd);
    return EXIT_SUCCESS;
}

