#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define GPIO_SHUTDOWN  27
#define BUFFER_SIZE    10
#define THRESHOLD      500.0
#define VCC            3.3
#define SENSITIVITY    1.4e-3
#define ZERO_FIELD     2.5
#define SAMPLE_HZ      1
#define ADC_MAX        32767.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d addr 0x%02X: %d",
               I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GPIO_SHUTDOWN);
        return -1;
    }
    if (gpioWrite(GPIO_SHUTDOWN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO %d LOW", GPIO_SHUTDOWN);
        return -1;
    }
    return 0;
}

static int read_adc(int16_t *raw) {
    char buf[2];
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        syslog(LOG_ERR, "I2C write failed on handle %d", i2c_handle);
        return -1;
    }
