#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE_RANGE 1023

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int set_pwm_duty_cycle(int pwm_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_DUTY_CYCLE_RANGE) {
        fprintf(stderr, "Error: Duty cycle %d out of range [0, %d]\n", duty_cycle, PWM_DUTY_CYCLE_RANGE);
        return -1;
    }

    if (gpioPWM(pwm_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pwm_pin);
        return -1;
    }
    return 0;
