    unsigned char config[3];
    config[0] = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_COMP_NONE;
    config[1] = 0;
    config[2] = 0;
    if (i2cWriteI2CBlockData(handle, ADS1115_REG_CONFIG, config, 3) < 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }
    return 0;
}

int read_ads1115(int handle, int16_t *raw_value) {
    unsigned char reg = ADS1115_REG_CONVERSION;
    unsigned char data[2];
    int result;

    result = i2cWriteI2CBlockData(handle, reg, data, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing conversion register\n");
        return -1;
    }

    // Wait for conversion (128 SPS, ~8 ms)
    gpioDelay(10000);

    // Read 2 bytes
    result = i2cReadI2CBlockData(handle, reg, data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading conversion data\n");
        return -1;
    }

    *raw_value = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

float calculate_magnetic_field(int16_t raw_value) {
    // Convert raw value to voltage (0.001 V/Gauss)
    float voltage = (float)raw_value / 32768.0f;
    // Convert voltage to Gauss (0.001 V/Gauss = 1 Gauss)
    return voltage * 1000.0f;
}

