        exit(EXIT_FAILURE);
    }

    if (configure_ads1115(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int16_t raw_value;
        float magnetic_field;

        if (read_ads1115(i2c_handle, &raw_value) != 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        magnetic_field = calculate_magnetic_field(raw_value);

        if (magnetic_field > threshold) {
            blink_led(led_gpio, BLINK_DURATION_MS);
            gpioDelay(SAMPLE_INTERVAL_MS * 1000);
            if (running) {
                blink_led(led_gpio, BLINK_DURATION_MS);
                gpioDelay(SAMPLE_INTERVAL_MS * 1000);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

