#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <paho/mqtt/mqtt.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000  /* 1 MHz */
#define SPI_FLAGS        0        /* Mode 0, active-low CE */
#define PUMP_GPIO        17
#define MOISTURE_THRESHOLD 30.0f
#define MOISTURE_HYSTERESIS 35.0f
#define SPI_TIMEOUT_US   10000    /* 10 ms */
#define POLL_INTERVAL_S  60
#define MQTT_BROKER       "localhost"
#define MQTT_TOPIC        "soil_moisture"
#define MQTT_CLIENT_ID   "rpi4-pump-control"
#define MQTT_USERNAME    "username"
#define MQTT_PASSWORD    "password"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_mqtt_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel %d", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * Byte 0: 0x01  (start bit)
     * Byte 1: (0x08 | channel) << 4  (single-ended + channel)
     * Byte 2: 0x00  (clock out remaining bits)
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        syslog(LOG_ERR, "SPI transfer failed (returned %d)", ret);
        return -1;
    }

    /* 10-bit result: bits 9-2 in rx[1] (low 2 bits), bits 1-0 in rx[2] (upper 8 bits) */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture(int adc_value) {
    /* HL-69: 0-1023 ADC -> 0-1023 V */
    return (float)adc_value / 1023.0f * 100.0f;
}

static int control_pump(int pump_on) {
    if (gpioWrite(PUMP_GPIO, pump_on ? 1 : 0) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d", PUMP_GPIO);
        return -1;
    }
    return 0;
}

static int publish_mqtt(const char *topic, const char *payload) {
    int rc = mqtt_publish(g_mqtt_handle, topic, payload, 0);
    if (rc != 0) {
        syslog(LOG_ERR, "MQTT publish failed: %d", rc);
        return -1;
    }
    return 0;
}

static int connect_mqtt(void) {
    int rc = mqtt_connect(g_mqtt_handle, MQTT_BROKER, MQTT_CLIENT_ID, MQTT_USERNAME, MQTT_PASSWORD);
    if (rc != 0) {
        syslog(LOG_ERR, "MQTT connect failed: %d", rc);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up...");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_mqtt_handle >= 0) {
        mqtt_disconnect(g_mqtt_handle);
        g_mqtt_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("pump_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", PUMP_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed (channel %d, speed %d)", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_connect(g_mqtt_handle, MQTT_BROKER, MQTT_CLIENT_ID, MQTT_USERNAME, MQTT_PASSWORD) != 0) {
        syslog(LOG_ERR, "MQTT connect failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (connect_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT connect failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Starting pump control...");

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "ADC read error");
            sleep(POLL_INTERVAL_S);
            continue;
        }

        float moisture = calculate_moisture(adc_value);

        if (moisture < MOISTURE_THRESHOLD && moisture > MOISTURE_HYSTERESIS) {
            if (control_pump(1) != 0) {
                syslog(LOG_ERR, "Failed to activate pump");
            }
        } else if (moisture > MOISTURE_THRESHOLD && moisture < MOISTURE_HYSTERESIS) {
            if (control_pump(0) != 0) {
                syslog(LOG_ERR, "Failed to deactivate pump");
            }
        }

        char payload[64];
        snprintf(payload, sizeof(payload), "Moisture: %.2f%%", moisture);
        if (publish_mqtt(MQTT_TOPIC, payload) != 0) {
            syslog(LOG_ERR, "MQTT publish failed");
        }

        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

