#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define THRESHOLD 500
#define PWM_FREQ 100
#define PWM_RANGE 255
#define SAMPLE_DELAY_US 10000
#define LOG_FILE "vibration_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

void set_motor_duty(int motor_pin, int duty) {
    if (duty < 0 || duty > PWM_RANGE) {
        fprintf(stderr, "Invalid PWM duty %d\n", duty);
        return;
    }
    if (gpioPWM(motor_pin, duty) != 0) {
        fprintf(stderr, "Failed to set PWM on pin %d\n", motor_pin);
    }
}

void log_event(int motor_pin, int duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Motor %d: %d\n", timestamp, motor_pin, duty);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQ);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQ);
    gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE);
    spi_handle = spiOpen(0, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping iteration\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }
        int duty = (adc_value * PWM_RANGE) / ADC_MAX;
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        set_motor_duty(MOTOR1_PIN, duty);
        set_motor_duty(MOTOR2_PIN, duty);
        log_event(MOTOR1_PIN, duty);
        log_event(MOTOR2_PIN, duty);
        gpioDelay(SAMPLE_DELAY_US);
    }
    set_motor_duty(MOTOR1_PIN, 0);
    set_motor_duty(MOTOR2_PIN, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Vibration monitoring stopped.\n");
    return 0;
}

