#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HRES_MODE 2
#define BH1750_CONT_HRES_DELAY_MS 180
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_max9814(int fd, int channel, int *value) {
    uint8_t cmd = (channel == 0) ? 0x01 : 0x02;
    uint8_t buf[3];
    if (write(fd, &cmd, 1) != 1) return -1;
    if (read(fd, buf, 3) != 3) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_bh1750(int fd, int *lux) {
    uint8_t cmd = BH1750_CONT_HRES_MODE | BH1750_CONT_HRES_DELAY_MS;
    uint8_t buf[2];
    if (write(fd, &cmd, 1) != 1) return -1;
    usleep(BH1750_CONT_HRES_DELAY_MS * 1000);
    if (read(fd, buf, 2) != 2) return -1;
    *lux = (buf[0] << 8) | buf[1];
    return 0;
}

static int log_data(FILE *fp, int sound_level, int light_level, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d\n", ts, sound_level, light_level, error_code);
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open I2C bus"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) { perror("ioctl I2C_SLAVE"); close(i2c_fd); return 1; }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) { perror("open SPI device"); close(i2c_fd); close(spi_fd); return 1; }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 || ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI mode/bits"); close(i2c_fd); close(spi_fd); return 1;
    }
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI speed"); close(i2c_fd); close(spi_fd); return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) { perror("fopen log file"); close(i2c_fd); close(spi_fd); return 1; }

    while (running) {
        int sound_level = 0, light_level = 0;
        int error_code = 0;

        if (read_max9814(i2c_fd, 0, &sound_level) < 0) {
            fprintf(stderr, "Max9814 read error\n");
            error_code = 1;
        } else if (read_bh1750(spi_fd, &light_level) < 0) {
            fprintf(stderr, "BH1750 read error\n");
            error_code = 1;
        } else {
            if (error_code) {
                fprintf(stderr, "Error: %d\n", error_code);
            }
            if (log_data(log_file, sound_level, light_level, error_code) < 0) {
                fprintf(stderr, "Logging failed\n");
            }
        }

        if (running) sleep(SAMPLE_INTERVAL_SEC);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

