#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) return -1;
    char tx[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_value(int adc_value) {
    if (adc_value < 0) return 0;
    if (adc_value > 1023) return 1023;
    return (adc_value * 100) / 1023;
}

static int set_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(VALVE_GPIO, duty_cycle) != 0) return -1;
    return 0;
}

static void log_data(int raw1, int raw2, int avg, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Raw1: %d, Raw2: %d, Avg: %d, Valve: %d\n",
            ts, raw1, raw2, avg, valve_position);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);
    gpioPWM(VALVE_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Log open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int raw1, raw2, avg;
    int valve_position;
    int error_count = 0;

    while (running) {
        raw1 = read_adc(0);
        raw2 = read_adc(1);
        avg = map_value(raw1 + raw2);
        valve_position = (avg * 100) / 1023;

        if (valve_position < 0) {
            error_count++;
            if (error_count >= 3) {
                fprintf(stderr, "Too many sensor errors, aborting\n");
                break;
            }
            gpioDelay(1000000);
            continue;
        }

        if (valve_position > PWM_RANGE) {
            valve_position = PWM_RANGE;
        }

        if (set_pwm(valve_position) != 0) {
            fprintf(stderr, "PWM set failed\n");
        }

        log_data(raw1, raw2, avg, valve_position);

        if (running) {
            gpioDelay(SAMPLE_INTERVAL * 1000000);
        }
    }

    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioPWM(VALVE_GPIO, 0);
    gpioTerminate();
    return 0;
}

