#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/pwm.h>
#include <linux/pwm-gpio.h>
#include <linux/spi/spidev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define PWM_CH 0
#define PWM_FREQ_HZ 200
#define PWM_DUTY_MAX 1000
#define SAMPLE_INTERVAL_US 100000
#define SAMPLE_DELAY_US 1000
#define SPI_DEVICE "/dev/spidev0.0"
#define CONFIG_FILE "theremin_config.txt"
#define MAX_SENSOR_READ_ERRORS 10

static volatile sig_atomic_t running = 1;
static FILE *config_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trig_line = NULL;
static struct gpiod_line *echo_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int trig_pin, int echo_pin) {
    if (trig_pin < 0 || echo_pin < 0) return -1;

    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100000000; // 100ms

    if (gpiod_line_set_value(trig_line, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig_line, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1;

    int level = gpiod_line_get_value(echo_line);
    if (level < 0) return -1;

    if (level == 0) return -1; // timeout

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (end.tv_sec > start.tv_sec + 1) return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    long duration = end.tv_sec - start.tv_sec;
    long diff_ns = end.tv_nsec - start.tv_nsec;
    if (diff_ns > 1000000000) return -1; // > 1s timeout

    return (int)(duration * 1000000 / 1000000.0);
}

static int read_adc(int adc_pin) {
    if (adc_pin < 0) return -1;

    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 1,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    struct gpiod_line *adc_line = gpiod_chip_get_line(chip, adc_pin);
    if (!adc_line) return -1;

    if (gpiod_line_request_output(adc_line, "adc", 0) < 0) return -1;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;

    if (gpiod_line_release(adc_line) < 0) return -1;

