#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000000
#define SAMPLE_INTERVAL_US 5000000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, speed %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        fprintf(stderr, "Error: SPI transfer failed (attempt %d/%d, ret=%d)\n",
                attempt, MAX_RETRIES, ret);
        if (attempt < MAX_RETRIES) {
            usleep(RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "Error: SPI transfer failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static int calculate_aqi(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range (0-1023)\n");
        return -1;
    }
    float voltage = (float)adc_value / 1023.0f * 3.3f;
    float aqi = (voltage - 0.5f) * 100.0f;
    if (aqi < 0.0f) aqi = 0.0f;
    if (aqi > 1000.0f) aqi = 1000.0f;
    return (int)aqi;
}

static void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }
}

static void log_data(int aqi) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int aqi = -1;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                aqi = calculate_aqi(adc_value);
                break;
            }
            usleep(RETRY_DELAY_US);
        }

        if (adc_value >= 0) {
            control_fan(aqi);
            log_data(aqi);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

