    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, ADC: %d, PPM: %.2f\n", timestamp, adc_to_ppm(adc_to_ppm(ppm)), ppm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        fprintf(stderr, "Error getting GPIO8 line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(line, "alcohol_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO8 as input: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = spi_read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            usleep(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        float ppm = adc_to_ppm(adc_value);
        if (ppm < 0) {
            fprintf(stderr, "ADC conversion error, retrying...\n");
            usleep(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        char log_message[128];
        snprintf(log_message, sizeof(log_message), "ADC: %d, PPM: %.2f", adc_value, ppm);
        if (log_reading(ppm) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        printf("%s\n", log_message);

        if (classify_reading(ppm) != NULL) {
            printf("Alcohol level: %s\n", classify_reading(ppm));
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

