#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define CS_PIN 8
#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_DELAY_US 10000
#define CALIBRATION_DELAY_S 5
#define CALIBRATION_THRESHOLD_PERCENT 10.0
#define CALIBRATION_SAMPLES 100

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calibrate_sound_level(void) {
    float sum = 0.0;
    int count = 0;

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Failed to read ADC on channel 0\n");
            return -1.0;
        }
        sum += sample;
        count++;
        gpioDelay(100000);
    }

    if (count == 0) {
        fprintf(stderr, "Calibration failed: no samples\n");
        return -1.0;
    }

    return (sum / count) * 100.0;
}

static int set_led_state(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "Failed to write LED pin\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    set_led_state(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    float ambient_level = calibrate_sound_level();
    if (ambient_level < 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Sound level calibration complete. Ambient: %.2f dB\n", ambient_level);

    while (running) {
        float sound_level = calibrate_sound_level();
        if (sound_level < 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            cleanup();
            return 1;
        }

        printf("Sound level: %.2f dB\n", sound_level);

        if (sound_level > ambient_level + CALIBRATION_THRESHOLD_PERCENT) {
            if (set_led_state(1) != 0) {
                fprintf(stderr, "Failed to turn LED on\n");
            } else {
                gpioDelay(SAMPLE_DELAY_US);
                if (set_led_state(0) != 0) {
                    fprintf(stderr, "Failed to turn LED off\n");
                }
            }
        }

        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

