#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3 // V
#define MIN_V 0.5 // 0 SLPM
#define MAX_V 4.5 // 200 SLPM
#define MIN_AIRFLOW 0.0
#define MAX_AIRFLOW 200.0
#define SAMPLE_INTERVAL_US 100000 // 100 ms

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(float voltage);
void log_data(float airflow);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel (3 bits)
    // Byte 2: Don't care (0x00)
    unsigned char tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx_buf[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to convert voltage to airflow in SLPM
float voltage_to_airflow(float voltage) {
    if (voltage < MIN_V) {
        return MIN_AIRFLOW;
    }
    if (voltage > MAX_V) {
        return MAX_AIRFLOW;
    }
    return (voltage - MIN_V) / (MAX_V - MIN_V) * (MAX_AIRFLOW - MIN_AIRFLOW) + MIN_AIRFLOW;
}

// Function to log data to file
void log_data(float airflow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Airflow: %.2f SLPM\n", timestamp, airflow);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0, active low CE
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = (float)adc_value * VREF / 1023.0;
        float airflow = voltage_to_airflow(voltage);

        log_data(airflow);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    fprintf(stderr, "Airflow monitoring stopped.\n");
    return 0;
}

