#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define SAMPLE_PERIOD_NS 1000000000L  /* 1 ms */
#define LOG_FILE        "audio_log.txt"
#define CS_GPIO_LINE    8
#define CS_GPIO_CHIP    "gpiochip0"
#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023
#define ADC_RESOLUTION  1023.0f
#define ADC_SAMPLE_DELAY_NS (SAMPLE_PERIOD_NS / 1000)

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ns(unsigned long ns)
{
    struct timespec ts = {
        .tv_sec  = ns / 1000000000L,
        .tv_nsec = (long)(ns % 1000000000L)
    };
    nanosleep(&ts, NULL);
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: rx[1] bits 1..0 are the 10-bit result, rx[2] is all 0.
 */
static int mcp3008_read(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_reading(FILE *fp, int adc_value)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(ts_str + strlen(ts_str), sizeof(ts_str) - strlen(ts_str),
             ".%09ld", ts.tv_nsec);

    if (fprintf(fp, "%s|%d\n", ts_str, adc_value) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int spi_fd = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open GPIO chip and request CS line as output */
    chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CS_GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                CS_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "admp401_cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                CS_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Main sampling loop */
    while (g_running) {
        int adc_value = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; continuing\n");
            sleep_ns(ADC_SAMPLE_DELAY_NS);
            continue;
        }

        if (log_reading(log_fp, adc_value) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        sleep_ns(ADC_SAMPLE_DELAY_NS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fp) {
        fclose(log_fp);
    }
    return ret;
}

