#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define VREF 3.3
#define ADC_MAX 1023
#define LOG_FILE "gas_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define ADC_READ_DELAY_MS 100

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / (float)ADC_MAX) * VREF;
}

static float voltage_to_ppm(float voltage) {
    return voltage * 1000.0f;
}

static int log_data(float voltage, float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f, %.2f\n", timestamp, voltage, ppm);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Gas leak detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, retrying in %d ms...\n", ADC_READ_DELAY_MS);
            gpioDelay(ADC_READ_DELAY_MS * 1000);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float ppm = voltage_to_ppm(voltage);

        if (log_data(voltage, ppm) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        printf("Voltage: %.2f V, PPM: %.2f\n", voltage, ppm);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    cleanup();
    printf("Gas leak detection stopped.\n");
    return 0;
}

