#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR_LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(struct gpiod_line *line, const char *label) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", label, strerror(errno));
        return -1;
    }
    return value;
}

static double calculate_magnetic_field(int sensor_value) {
    double voltage = (double)sensor_value / 2.0;
    double field = (voltage - 1.65) / 0.025;
    return field;
}

static int log_data(const char *sensor_name, double magnetic_field) {
    FILE *fp = fopen(SENSOR_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", SENSOR_LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s,%.2f\n", sensor_name, magnetic_field);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", SENSOR_LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get lines for the three sensors */
    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    line3 = gpiod_chip_get_line(chip, SENSOR3_PIN);
    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request lines as inputs */
    if (gpiod_line_request_input(line1, "drv5055-sensor1") < 0) {
        fprintf(stderr, "Error requesting GPIO %d as input: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(line2, "drv5055-sensor2") < 0) {
        fprintf(stderr, "Error requesting GPIO %d as input: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(line3, "drv5055-sensor3") < 0) {
        fprintf(stderr, "Error requesting GPIO %d as input: %s\n", SENSOR3_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Magnetic field sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(line1, "Sensor1");
        int sensor2_value = read_sensor(line2, "Sensor2");
        int sensor3_value = read_sensor(line3, "Sensor3");

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
        } else {
            double magnetic_field1 = calculate_magnetic_field(sensor1_value);
            double magnetic_field2 = calculate_magnetic_field(sensor2_value);
            double magnetic_field3 = calculate_magnetic_field(sensor3_value);

            if (log_data("Sensor1", magnetic_field1) < 0 ||
                log_data("Sensor2", magnetic_field2) < 0 ||
                log_data("Sensor3", magnetic_field3) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

