#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60
#define MAX_RECONNECT_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int mqtt_client = -1;
static int mqtt_connected = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
}

static void cleanup(void) {
    if (mqtt_client) {
        mosquitto_loop_stop(mqtt_client);
        mosquitto_loop_start(mqtt_client, 0);
        mosquitto_destroy(mqtt_client);
        mqtt_client = -1;
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
    }
}

static void on_connect(void *userdata, int result, const struct mosquitto *m, void *client) {
    (void)userdata;
    (void)client;
    if (result == 0) {
        printf("Connected to MQTT broker\n");
        mqtt_connected = 1;
    } else {
        log_error("MQTT connect failed");
    }
}

static void on_disconnect(void *userdata, int code, const struct mosquitto *m, void *client) {
    (void)userdata;
    (void)m;
    (void)client;
    if (code == 0) {
        printf("Disconnected from MQTT broker\n");
        mqtt_connected = 0;
    } else {
        log_error("MQTT disconnect failed");
    }
}

static void on_message(void *userdata, const struct mosquitto *m, void *client, const struct mosquitto_message *message) {
    (void)userdata;
    (void)m;
    (void)client;
    (void)message;
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        int payload_len = message->payloadlen;
        int led_state = -1;
        if (strcmp(payload, "{\"led_state\":true}") == 0) {
            led_state = 1;
        } else if (strcmp(payload, "{\"led_state\":false}") == 0) {
            led_state = 0;
        } else {
            log_error("Invalid JSON payload");
            return;
        }
        if (led_state >= 0) {
            if (gpioWrite(GPIO_PIN, led_state) != 0) {
                log_error("Failed to write GPIO");
            }
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        cleanup();
        return 1;
    }
    gpioWrite(GPIO_PIN, 0);

    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, 1, NULL);
    if (!mqtt_client) {
        log_error("mosquitto_new failed");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mqtt_client, on_connect);
    mosquitto_disconnect_callback_set(mqtt_client, on_disconnect);
    mosquitto_message_callback_set(mqtt_client, on_message);

    if (mosquitto_connect(mqtt_client, MQTT_BROKER, MQTT_PORT, 60) != 0) {
        log_error("mosquitto_connect failed");
        cleanup();
        return 1;
    }

    while (running) {
        if (mqtt_connected) {
            if (mosquitto_loop_start(mqtt_client) != 0) {
                log_error("mosquitto_loop_start failed");
                break;
            }
        } else {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

