#define SAMPLE_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *alarm_line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the sound sensor line */
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("gpiod_chip_get_line(sound)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the sound sensor line as input */
    ret = gpiod_line_request_input(sound_line, "sound-sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input(sound)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the alarm LED line */
    alarm_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_line) {
        perror("gpiod_chip_get_line(alarm)");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the alarm LED line as output, initially low */
    ret = gpiod_line_request_output(alarm_line, "alarm-led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(alarm)");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            perror("gpiod_line_get_value(sound)");
            break;
        }

        if (sound_level == 0) {
            printf("Sound detected! Alarm LED ON\n");
            ret = gpiod_line_set_value(alarm_line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value(alarm ON)");
                break;
            }
            usleep(1000000); /* 1 s blink */
            ret = gpiod_line_set_value(alarm_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value(alarm OFF)");
                break;
            }
        }

        usleep(SAMPLE_DELAY_MS * 1000); /* 100 ms */
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    gpiod_line_set_value(alarm_line, 0);
    gpiod_line_release(sound_line);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

