#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "temp_log.dat"
#define BUFFER_SIZE 120.0f
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer temperature_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float convert_to_celsius(int adc_value) {
    return (adc_value / 1023.0f) * 100.0f;
}

static void add_to_buffer(float temperature) {
    temperature_buffer.buffer[temperature_buffer.head] = temperature;
    temperature_buffer.head = (temperature_buffer.head + 1) % BUFFER_SIZE;
    if (temperature_buffer.count < BUFFER_SIZE) {
        temperature_buffer.count++;
    }
}

static void log_temperature(float temperature) {
    add_to_buffer(temperature);
    printf("Temperature: %.2f °C\n", temperature);
}

static void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            log_error("Failed to read temperature from MCP3008");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float temperature = convert_to_celsius(adc_value);
        log_temperature(temperature);

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    printf("Temperature logging stopped.\n");
    return 0;
}

