#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        return -1;
    }
    return val;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux) {
    uint8_t reg = BH1750_ADDR;
    if (i2c_write_byte(fd, reg, 0x00) < 0) {
        return -1;
    }
    usleep(10000);
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        return -1;
    }
    int raw = (data[0] << 8) | data[1];
    *lux = (float)raw / 65536.0f;
    return 0;
}

static int read_mcp3008(int fd, int channel, int *raw) {
    uint8_t reg = 0x00;
    if (i2c_write_byte(fd, reg, channel) < 0) {
        return -1;
    }
    uint8_t buf[3];
    if (read(fd, buf, 3) != 3) {
        return -1;
    }
    *raw = (buf[0] << 8) | buf[1];
    return 0;
}

static int log_data(const char *filename, float light, int sound) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Light: %.2f, Sound: %d\n", timestamp, light, sound);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        return 1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(1 << bits)) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float light = 0.0f;
        int sound = 0;
        int ok = 0;
        int rc = read_bh1750(i2c_fd, &light);
        if (rc == 0) {
            ok = 1;
        } else {
            fprintf(stderr, "Error reading BH1750\n");
        }
        rc = read_mcp3008(spi_fd, MCP3008_CHANNEL, &sound);
        if (rc == 0) {
            ok = 1;
        } else {
            fprintf(stderr, "Error reading MCP3008\n");
        }
        if (ok) {
            if (log_data(LOG_FILE, light, sound) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    close(i2c_fd);
    close(spi_fd);
    printf("Exiting gracefully.\n");
    return 0;
}

