                moisture_percentages[0],
                moisture_percentages[1],
                moisture_percentages[2],
                moisture_percentages[3],
                moisture_percentages[4],
                moisture_percentages[5],
                moisture_percentages[6],
                moisture_percentages[7]) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

