/*
 * Light Sequencer using libgpiod on Raspberry Pi 3 Model B+
 *
 * Activates and deactivates four Songle SRD-05VDC-SL relays on BCM GPIO 17, 22, 23,
 * 24 in sequence.  Each relay is initially inactive (LOW).
 *
 * Build:  gcc -O2 -Wall -o light_seq light_seq.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_PIN_1 17
#define RELAY_PIN_2 22
#define RELAY_PIN_3 23
#define RELAY_PIN_4 24

static const unsigned int relay_pins[NUM_RELAYS] = {
    RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void cleanup(struct gpiod_line *relay_lines[NUM_RELAYS])
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
        }
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay_lines[NUM_RELAYS];
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines for the four relay pins */
    relay_lines = (struct gpiod_line *)calloc(NUM_RELAYS, sizeof(struct gpiod_line *));
    if (!relay_lines) {
        perror("calloc(relay_lines)");
        cleanup(relay_lines);
        return EXIT_FAILURE;
    }

    /* Request each relay line as output, initially LOW (inactive) */
    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup(relay_lines);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_output(relay_lines[i], "light-seq", 0);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup(relay_lines);
            return EXIT_FAILURE;
        }
    }

    printf("Light sequencer started.  Press Ctrl+C to exit.\n");

    while (program_running) {
        for (int i = 0; i < NUM_RELAYS && program_running; i++) {
            if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set relay %u HIGH: %s\n",
                        relay_pins[i], strerror(errno));
                cleanup(relay_lines);
                return EXIT_FAILURE;
            }
            printf("Relay %u HIGH\n", relay_pins[i]);
            sleep(1);

            if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set relay %u LOW: %s\n",
                        relay_pins[i], strerror(errno));
                cleanup(relay_lines);
                return EXIT_FAILURE;
            }
            printf("Relay %u LOW\n", relay_pins[i]);
            sleep(1);
        }

        if (program_running) {
            for (int i = 0; i < NUM_RELAYS && program_running; i++) {
                if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
                    fprintf(stderr, "Failed to set relay %u HIGH: %s\n",
                            relay_pins[i], strerror(errno));
                    cleanup(relay_lines);
                    return EXIT_FAILURE;
                }
                printf("Relay %u HIGH\n", relay_pins[i]);
                sleep(1);

                if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
                    fprintf(stderr, "Failed to set relay %u LOW: %s\n",
                            relay_pins[i], strerror(errno));
                    cleanup(relay_lines);
                    return EXIT_FAILURE;
                }
                printf("Relay %u LOW\n", relay_pins[i]);
                sleep(1);
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup(relay_lines);
    return EXIT_SUCCESS;
}

