    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sound level: %d\n", timestamp, sound_level) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file\n");
        return -1;
    }

    return 0;
}

static void control_led(int sound_level) {
    if (sound_level > SOUND_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        gpioDelay(DEBOUNCE_MS * 1000);
        gpioWrite(LED_GPIO, 0);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
