        if (log_event(sound_level) != 0) {
            gpioDelay(10000);
            continue;
        }

        control_led(sound_level);
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (spiClose(spi_handle) != 0) {
        fprintf(stderr, "SPI close failed\n");
    }
    gpioTerminate();
    return 0;
}

