static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_message(const char *message)
{
    if (!log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s: %s\n", ts, message);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* MCP3008 read                                                       */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        log_message("Invalid MCP3008 channel");
        return -1;
    }

    /*
     * MCP3008 single-ended read (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining data)
     * Result: 10-bit value in rx[1] and rx[2].
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (bytes != 3) {
        log_message("SPI transfer failed");
        return -1;
