#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define MIC_PIN        26
#define LED_PIN        16
#define THRESHOLD      0.7f   /* V */
#define DEBOUNCE_US    50000  /* 50 ms */
#define LED_ON_US      500000 /* 500 ms */
#define ADC_MAX        1023
#define ADC_V_MAX      3.3f
#define ADC_V_MIN      0.0f
#define ADC_V_THRESH   (ADC_V_MAX * THRESHOLD)

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Read a 10-bit ADC value from the MAX9814.
 * Returns 0 on success, -1 on error.
 */
static int read_adc(int pin)
{
    int raw = 0;
    int i;

    for (i = 0; i < 10; i++) {
        /*
         * pigpio bit-bang ADC read:
         *   tx[0] = 0x80  (start bit)
         *   tx[1] = (1 << 7) | (1 << 6) | (1 << 5) | (1 << 4) | (1 << 3) | (1 << 2) | (1 << 1) | 0x00
         *   tx[2] = 0x00  (end bit)
         *
         * The 10-bit result is in the lower 8 bits of tx[2].
         */
        if (gpioWrite(pin, 1) < 0) {
            fprintf(stderr, "ADC write failed on pin %d\n", pin);
            return -1;
        }
        gpioDelay(1);
        if (gpioWrite(pin, 0) < 0) {
            fprintf(stderr, "ADC write failed on pin %d\n", pin);
            return -1;
        }
        gpioDelay(1);

        raw <<= 1;
        raw |= (gpioRead(pin) == 1) ? 1 : 0;
    }

    return raw;
}

static void control_led(int on)
{
    if (gpioWrite(LED_PIN, on ? 1 : 0) < 0) {
        fprintf(stderr, "Failed to set LED state on pin %d\n", LED_PIN);
    }
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }
    char buf[64];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }
    printf("[%s] Clap detected\n", buf);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set MIC_PIN %d as input\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED_PIN %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize LED_PIN %d to LOW\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");

    while (running) {
        int adc = read_adc(MIC_PIN);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; retrying in 1 s\n");
            gpioDelay(1000000);
            continue;
        }

        if (adc > ADC_V_THRESH) {
            printf("Threshold exceeded: ADC=%d\n", adc);
            control_led(1);
            print_timestamp();
            gpioDelay(DEBOUNCE_US);
            control_led(0);
            print_timestamp();
            gpioDelay(LED_ON_US);
            control_led(0);
            print_timestamp();
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    control_led(0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

