#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 200.0
#define VOLTAGE_LOW 0.0
#define VOLTAGE_HIGH 3.3
#define VOLTAGE_LOW_THRESHOLD 0.0
#define VOLTAGE_HIGH_THRESHOLD 3.3
#define SENSOR_A 26.0
#define SENSOR_B -6.0
#define SENSOR_A_V 0.0
#define SENSOR_B_V 3.3
#define SENSOR_A_A_V 26.0
#define SENSOR_B_A_V -6.0

static volatile sig_atomic_t running = 1;
static int log_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int gpio_export(int gpio) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("open export");
        return -1;
    }
    if (write(fd, &gpio, 1) != 1) {
        perror("write export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_unexport(int gpio) {
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("open unexport");
        return -1;
    }
    if (write(fd, &gpio, 1) != 1) {
        perror("write unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_set_direction(int gpio, const char *direction) {
    int fd = open("/sys/class/gpio/gpiochip0/gpiochip0/gpio17/direction", O_WRONLY);
    if (fd < 0) {
        perror("open direction");
        return -1;
    }
    if (write(fd, direction, 1) != 1) {
        perror("write direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_set_value(int gpio, int value) {
    int fd = open("/sys/class/gpio/gpiochip0/gpio17/value", O_WRONLY);
    if (fd < 0) {
        perror("open value");
        return -1;
    }
    if (write(fd, &value, 1) != 1) {
        perror("write value");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_read(int gpio) {
    int fd = open("/sys/class/gpio/gpiochip0/gpio17/value", O_RDONLY);
    if (fd < 0) {
        perror("open read");
        return -1;
    }
    int val = read(fd, &val, 1);
    close(fd);
    return val;
}

float read_distance(int gpio) {
    if (gpio_read(gpio) < 0) {
        return -1.0;
    }
    float voltage = (float)gpio_read(gpio) / VOLTAGE_HIGH_THRESHOLD;
    if (voltage < VOLTAGE_LOW_THRESHOLD) {
        return -1.0;
    }
    float distance = (voltage - SENSOR_A_A_V) / SENSOR_A_A_V;
    if (distance < 0.0) {
        return -1.0;
    }
    return distance;
}

void log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fd, "%s, Distance: %.2f mm\n", timestamp, distance);
    fflush(log_fd);
