#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pump_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_soil_moisture(void) {
    int adc_value = spi_read_adc(0);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    if (adc_value < 300) {
        fprintf(stderr, "Moisture level too low (ADC=%d)\n", adc_value);
        return -1;
    }

    return adc_value;
}

static void log_data(int moisture_percentage, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_fp, "%s, Moisture: %d%% (ADC: %d), Pump: %s\n",
            timestamp, moisture_percentage, adc_value, pump_state ? "ON" : "OFF");
    fflush(log_fp);
}

static void control_pump(int state) {
    if (gpiod_line_set_value(pump_line, state) < 0) {
        perror("Failed to set pump GPIO");
    }
}

static void cleanup(void) {
    if (pump_line) {
        gpiod_line_set_value(pump_line, 0);
        gpiod_line_release(pump_line);
        pump_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        cleanup();
        return 1;
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_GPIO);
    if (!pump_line) {
        perror("Failed to get pump GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(pump_line, "pump_control", 0) < 0) {
        perror("Failed to request pump GPIO as output");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_percentage = read_soil_moisture();
        if (moisture_percentage < 0) {
            fprintf(stderr, "Failed to read soil moisture\n");
        } else {
            log_data(moisture_percentage, gpiod_line_get_value(pump_line));
            control_pump(moisture_percentage < MOISTURE_THRESHOLD ? 1 : 0);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

