#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define ADC_CHANNEL     0
#define ADC_RESOLUTION  1023
#define VREF            3.3
#define DRV5055_VCC     1650.0
#define DRV5055_SENSITIVITY_MV_PER_MT 100.0
#define SAMPLE_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_line = NULL;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    if (spi_transfer(tx, rx, 3) < 0) {
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_magnetic_field(int adc_value) {
    float vout_mv = (float)adc_value * VREF / ADC_RESOLUTION;
    float b_mt = (vout_mv - DRV5055_VCC) / DRV5055_SENSITIVITY_MV_PER_MT;
    return b_mt;
}

static int log_data(float magnetic_field) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(g_log_fp, "%s,%.2f\n", timestamp, magnetic_field);
    fflush(g_log_fp);
    return 0;
}

static void cleanup(void) {
    if (g_cs_line) {
        gpiod_line_set_value(g_cs_line, 1);
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    g_cs_line = gpiod_chip_get_line(g_chip, 8);
    if (!g_cs_line) {
        fprintf(stderr, "Failed to get GPIO 8: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(g_cs_line, "mcp3008_cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO 8 as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting magnetic field measurement. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
