/*
 * Raspberry Pi Zero W - MLX91211 analog current sensor via MCP3008 SPI ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 5V (pin 1)
 *   MCP3008 VREF -> Pi 5V (pin 1)
 *   MCP3008 AGND -> Pi GND
 *   MCP3008 AGND -> Pi GND
 *   MCP3008 DGND -> Pi GND
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI)
 *   MCP3008 CS   -> Pi GPIO8  (CE0)
 *   MCP3008 CH0  -> MLX91211 analog output
 *
 * Build: gcc -Wall -o current_mlx91211 current_mlx91211.c -lpigpio -lrt
 * Run:   sudo ./current_mlx91211
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL        0          /* CE0 on GPIO8 */
#define SPI_BAUD           1000000    /* 1 MHz */
#define SPI_FLAGS          0          /* mode 0, active-low CE */
#define ADC_CHANNEL        0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE      1023       /* 10-bit ADC */
#define VREF               5.0        /* MCP3008 VREF */
#define VDD                5.0        /* MLX91211 VDD */
#define MLX91211_VDD       2.5        /* MLX91211 VDD at zero current */
#define MLX91211_VDD_FULL  5.0        /* MLX91211 VDD at full-scale +50A */
#define MLX91211_VDD_FULL_V 0.0        /* MLX91211 VDD at full-scale +50A */
#define MLX91211_VDD_FULL_I 0.0        /* MLX91211 VDD at full-scale +50A */
#define CURRENT_THRESHOLD  5.0        /* Voltage threshold for current */
#define LOG_FILE           "current_log.txt"
#define SAMPLE_INTERVAL_US 100000     /* 100 ms */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_terminate = 0;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel);
static float voltage_to_current(float voltage);
static float voltage_to_current_ratio(float voltage);
static void log_current(float current);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* --- Install SIGINT handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d).\n", spi_handle);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (!g_terminate) {
        int raw = read_mcp3008(ADC_CHANNEL);
        if (raw < 0) {
            fprintf(stderr, "Warning: SPI read error on channel %d.\n", ADC_CHANNEL);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /*
         * MCP3008 single-ended read: 3-byte transfer
         *   tx[0] = 0x01                       (start bit)
         *   tx[1] = (channel << 4) | 0x80     (single-ended + channel)
         *   tx[2] = 0x00                       (clock out low bits)
         * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
         */
        uint16_t code = ((uint16_t)raw & 0x03) << 8;
        code |= (uint16_t)((uint8_t)raw >> 2);

        float voltage = (code * VREF) / (float)ADC_MAX_VALUE;
        float current = voltage_to_current(voltage);

        if (current < CURRENT_THRESHOLD) {
            fprintf(stderr, "Warning: current %.2f A below threshold %.2f A.\n",
                    current, CURRENT_THRESHOLD);
        }

        log_current(current);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- Cleanup --- */
    cleanup();
    printf("Current monitoring stopped.\n");
    return EXIT_SUCCESS;
}

/* ----------------------------- SPI read ----------------------------------- */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (channel << 4) | 0x80     (single-ended + channel)
     *   tx[2] = 0x00                       (clock out low bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((channel << 4) | 0x80), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed (returned %d).\n", ret);
        return -1;
    }

    /*
     * 10-bit result: rx[1] contains the lower 2 bits, rx[2] contains the
     * upper 8 bits.  rx[1] is the MSB, rx[2] is the LSB.
     */
    int code = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return code;
}

/* ----------------------------- Voltage to current conversion ----------- */
static float voltage_to_current(float voltage)
{
    if (voltage < 0.0f) return 0.0f;
    if (voltage > VDD)   return 0.0f;

    float ratio = (voltage - MLX91211_VDD_FULL_V) /
                  (MLX91211_VDD_FULL_V - MLX91211_VDD_FULL_I);
    return (ratio * MLX91211_VDD_FULL_I) + MLX91211_VDD_FULL_V;
}

/* ----------------------------- Current ratio to current ---------------- */
static float voltage_to_current_ratio(float voltage)
{
    if (voltage < 0.0f) return 0.0f;
    if (voltage > VDD)   return 0.0f;

    float ratio = (voltage - MLX91211_VDD_FULL_V) /
                  (MLX91211_VDD_FULL_V - MLX91211_VDD_FULL_I);
    return ratio * MLX91211_VDD_FULL_I;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_current(float current)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s, %.2f A\n", ts, current);
    fflush(g_log_fp);
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

