    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line (SENSOR1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line (SENSOR2)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w-db01-sensor1") < 0) {
        perror("gpiod_line_request_input (SENSOR1)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-db01-sensor2") < 0) {
        perror("gpiod_line_request_input (SENSOR2)");
        goto cleanup;
    }

    printf("Monitoring B5W-DB01 sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR1_PIN, SENSOR2_PIN);
    fflush(stdout);

    while (running) {
        int val1 = read_sensor(line1, "Sensor1");
        int val2 = read_sensor(line2, "Sensor2");

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            goto cleanup;
        }

        int obj1 = val1 ? 0 : 1;
        int obj2 = val2 ? 0 : 1;

        log_sensor_state(obj1, obj2);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

