#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_MS 50
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_FILENAME "security_cam_image.jpg"
#define LOG_FILE "/home/pi/security_cam/security_cam.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_message(const char *message) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        syslog(LOG_ERR, "localtime_r failed");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        syslog(LOG_ERR, "strftime failed");
        return -1;
    }

    if (syslog(LOG_INFO, "%s: %s", timestamp, message) == -1) {
        syslog(LOG_ERR, "syslog failed");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    int status;
    char command[256];

    snprintf(command, sizeof(command),
             "libcamera-still -o %s --width %d --height %d --format jpeg",
             filename, IMAGE_WIDTH, IMAGE_HEIGHT);

    status = system(command);
    if (status == -1) {
        syslog(LOG_ERR, "system() failed for libcamera-still");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        syslog(LOG_ERR, "libcamera-still failed (status=%d)", status);
        return -1;
    }
    return 0;
}

int main(void) {
    int pir_state = 0;
    int last_state = 0;
    int image_captured = 0;

    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started. PIR=GPIO%d, Image=1280x720", PIR_GPIO);

    while (running) {
        int pir_value = gpioRead(PIR_GPIO);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read GPIO%d", PIR_GPIO);
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_value != last_state) {
            last_state = pir_value;
            syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);

            if (capture_image(IMAGE_FILENAME) != 0) {
                syslog(LOG_ERR, "Failed to capture image");
            } else {
                image_captured = 1;
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down camera");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

