    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        return -1;
    }

    *frame_size = buf.bytesused;
    *frame_ptr = mmap(NULL, *frame_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*frame_ptr == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, unsigned char *frame_ptr, size_t frame_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        return -1;
    }

    memcpy(frame_ptr, buf.m.data, buf.bytesused);
    return 0;
}

static int capture_frame_async(int fd, unsigned char *frame_ptr, size_t frame_size, int *frame_number) {
    fd_set readfds;
    struct timeval timeout;
    int ret;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = SELECT_TIMEOUT_MS / 1000;
    timeout.tv_usec = (SELECT_TIMEOUT_MS % 1000) * 1000;

    ret = select(fd + 1, &readfds, NULL, NULL, &timeout);
    if (ret < 0) {
        if (errno == EINTR) {
            return 0;
        }
        fprintf(stderr, "select failed: %s\n", strerror(errno));
        return -1;
    }

    if (ret == 0) {
        return 0;
    }

    if (FD_ISSET(fd, &readfds)) {
        if (capture_frame(fd, frame_ptr, frame_size) == 0) {
            *frame_number = *frame_number + 1;
            return 0;
        }
    }

    return -1;
}

static void cleanup(void) {
    if (g_running) {
        printf("Cleaning up...\n");
        for (int i = 0; i < 10; i++) {
            if (g_running) {
                break;
            }
            sleep(1);
        }
        close(g_video_fd);
        g_video_fd = -1;
        g_running = 0;
    }
}

int main(void) {
    int fd = -1;
    unsigned char *frame_ptr = NULL;
    size_t frame_size = 0;
    int frame_number = 0;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_video_fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK);
    if (g_video_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", VIDEO_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(g_video_fd, VIDIOC_CROPCAPS, &crop_cap) < 0) {
        fprintf(stderr, "VIDIOC_CROPCAPS failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (crop_cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        if (ioctl(g_video_fd, VIDIOC_STREAMON, NULL) < 0) {
            fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
    }

    if (mmap_frame(g_video_fd, &frame_ptr, &frame_size) < 0) {
        cleanup();
        return 1;
    }

    fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", VIDEO_DEVICE, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (fmt.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Unsupported pixel format: %d\n", fmt.pixelformat);
        cleanup();
        return 1;
    }

    if (fmt.width != 640 || fmt.height != 480 || fmt.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Resolution mismatch: %dx%d, %d\n", fmt.width, fmt.height, fmt.pixelformat);
        cleanup();
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (buf.bytesused < (size_t)fmt.width * fmt.height * 3) {
        fprintf(stderr, "Buffer size too small: %d\n", buf.bytesused);
        cleanup();
        return 1;
    }

    if (buf.memory != V4L2_MEMORY_MMAP) {
        fprintf(stderr, "Memory type mismatch: %d\n", buf.memory);
        cleanup();
        return 1;
    }

    if (mmap_frame(fd, &frame_ptr, &frame_size) < 0) {
        cleanup();
        return 1;
    }

    printf("Capturing MJPEG video from %s...\n", VIDEO_DEVICE);

    while (g_running) {
        if (capture_frame_async(fd, frame_ptr, frame_size, &frame_number) < 0) {
            break;
        }
        log_timestamp(stdout, frame_number);
    }

    cleanup();
    return 0;
}

