#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define BUTTON_PUSHES 6
#define PAN_UP_PIN 6
#define PAN_DOWN_PIN 7
#define TILT_LEFT_PIN 8
#define TILT_RIGHT_PIN 9

#define PWM_PERIOD_US 20000
#define PWM_DUTY_MIN 50
#define PWM_DUTY_MAX 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_init(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    struct gpiod_line *pan_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    struct gpiod_line *tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    struct gpiod_line *button_up_line = gpiod_chip_get_line(chip, PAN_UP_PIN);
    struct gpiod_line *button_down_line = gpiod_chip_get_line(chip, PAN_DOWN_PIN);
    struct gpiod_line *button_left_line = gpiod_chip_get_line(chip, TILT_LEFT_PIN);
    struct gpiod_line *button_right_line = gpiod_chip_get_line(chip, TILT_RIGHT_PIN);

    if (!pan_line || !tilt_line || !button_up_line || !button_down_line || !button_left_line || !button_right_line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    if (gpiod_line_request_output(pan_line, "pan-tilt", 0) < 0) {
        perror("gpiod_line_request_output pan");
        return -1;
    }
    if (gpiod_line_request_output(tilt_line, "pan-tilt", 0) < 0) {
        perror("gpiod_line_request_output tilt");
        return -1;
    }
    if (gpiod_line_request_input(button_up_line, "pan-tilt") < 0) {
        perror("gpiod_line_request_input button up");
        return -1;
    }
    if (gpiod_line_request_input(button_down_line, "pan-tilt") < 0) {
        perror("gpiod_line_request_input button down");
        return -1;
    }
    if (gpiod_line_request_input(button_left_line, "pan-tilt") < 0) {
        perror("gpiod_line_request_input button left");
        return -1;
    }
    if (gpiod_line_request_input(button_right_line, "pan-tilt") < 0) {
        perror("gpiod_line_request_input button right");
        return -1;
    }

    return 0;
}

static void gpio_cleanup(void) {
    if (pan_line) gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (button_up_line) gpiod_line_release(button_up_line);
    if (button_down_line) gpiod_line_release(button_down_line);
    if (button_left_line) gpiod_line_release(button_left_line);
    if (button_right_line) gpiod_line_release(button_right_line);
    if (chip) gpiod_chip_close(chip);
}

static void pan_servo_set(int val) {
    if (gpiod_line_set_value(pan_line, val) < 0) {
        perror("gpiod_line_set_value pan");
    }
}

static void tilt_servo_set(int val) {
    if (gpiod_line_set_value(tilt_line, val) < 0) {
        perror("gpiod_line_set_value tilt");
    }
}

static void pan_servo_move(int val) {
    if (val < 0) val = 0;
    if (val > 100) val = 100;
    pan_servo_set(val);
}

static void tilt_servo_move(int val) {
    if (val < 0) val = 0;
    if (val > 100) val = 100;
    tilt_servo_set(val);
}

static void pan_servo_mid(void) {
    pan_servo_move(75);
}

static void tilt_servo_mid(void) {
    tilt_servo_move(75);
}

static void pan_servo_up(void) {
    pan_servo_move(100);
}

static void tilt_servo_up(void) {
    tilt_servo_move(100);
}

static void pan_servo_down(void) {
    pan_servo_move(25);
}

static void tilt_servo_down(void) {
    tilt_servo_move(25);
}

static void pan_servo_clamp(int val) {
    if (val < 25) val = 25;
    if (val > 100) val = 100;
}

static void tilt_servo_clamp(int val) {
    if (val < 25) val = 25;
    if (val > 100) val = 100;
}

