static int fd = -1;

static int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

static int ioctl_query_capabilities(int fd) {
    if (ioctl(fd, VIDIOC_QUERYCAP, &(struct v4l2_capability){0}) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ioctl_query_frame_size(int fd, int *width, int *height) {
    struct v4l2_queryctrl query = {0};
    query.id = V4L2_QUERYCTRL_ID_FRAME_WIDTH;
    query.value = 0;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &query) < 0) {
        fprintf(stderr, "Error querying frame width: %s\n", strerror(errno));
        return -1;
    }
    *width = query.value;
    return 0;
}

static int ioctl_query_frame_rate(int fd, int *fps) {
    struct v4l2_queryctrl query = {0};
    query.id = V4L2_QUERYCTRL_ID_FRAME_RATE;
    query.value = 0;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &query) < 0) {
        fprintf(stderr, "Error querying frame rate: %s\n", strerror(errno));
        return -1;
    }
    *fps = query.value;
    return 0;
}

static int ioctl_query_frame_interval(int fd, int *interval) {
    struct v4l2_queryctrl query = {0};
    query.id = V4L2_QUERYCTRL_ID_FRAME_INTERVAL;
    query.value = 0;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &query) < 0) {
        fprintf(stderr, "Error querying frame interval: %s\n", strerror(errno));
        return -1;
    }
    *interval = query.value;
    return 0;
}

static int ioctl_query_autofocus(int fd, int *autofocus) {
    struct v4l2_queryctrl query = {0};
    query.id = V4L2_QUERYCTRL_ID_AUTO_FOCUS;
    query.value = 0;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &query) < 0) {
        fprintf(stderr, "Error querying autofocus: %s\n", strerror(errno));
        return -1;
    }
    *autofocus = query.value;
    return 0;
}

static int open_device_with_autofocus(const char *device_name) {
    fd = open_device(device_name);
    if (fd < 0) {
        return -1;
    }
    if (ioctl_query_capabilities(fd) < 0) {
        close(fd);
        return -1;
    }
    if (ioctl_query_frame_size(fd, &width, &height) < 0) {
        close(fd);
