    if (ioctl_query_frame_rate(fd, &fps) < 0) {
        close(fd);
        return -1;
    }
    if (ioctl_query_frame_interval(fd, &interval) < 0) {
        close(fd);
        return -1;
    }
    if (ioctl_query_autofocus(fd, &autofocus) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

