#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_PIN 6
#define DOWN_PIN 7
#define LEFT_PIN 8
#define RIGHT_PIN 9

#define CENTER_POSITION 1500
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define LOOP_DELAY_US 50000
#define BUTTON_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set PAN_SERVO_PIN %d as output.\n", PAN_SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TILT_SERVO_PIN %d as output.\n", TILT_SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UP_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set UP_PIN %d as input.\n", UP_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(DOWN_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set DOWN_PIN %d as input.\n", DOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set LEFT_PIN %d as input.\n", LEFT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set RIGHT_PIN %d as input.\n", RIGHT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on UP_PIN %d.\n", UP_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(DOWN_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on DOWN_PIN %d.\n", DOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LEFT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on LEFT_PIN %d.\n", LEFT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RIGHT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on RIGHT_PIN %d.\n", RIGHT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioServo(PAN_SERVO_PIN, CENTER_POSITION) != 0) {
        fprintf(stderr, "Error: failed to set PAN_SERVO_PIN %d to center position.\n", PAN_SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioServo(TILT_SERVO_PIN, CENTER_POSITION) != 0) {
        fprintf(stderr, "Error: failed to set TILT_SERVO_PIN %d to center position.\n", TILT_SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt system started. Servos at center position.\n");
    printf("UP: GPIO%d, DOWN: GPIO%d, LEFT: GPIO%d, RIGHT: GPIO%d\n",
           UP_PIN, DOWN_PIN, LEFT_PIN, RIGHT_PIN);
    printf("Press UP/DOWN/LEFT/RIGHT buttons to control movement.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int up_pressed = gpioRead(UP_PIN);
        int down_pressed = gpioRead(DOWN_PIN);
        int left_pressed = gpioRead(LEFT_PIN);
        int right_pressed = gpioRead(RIGHT_PIN);

        if (up_pressed == 1) {
            if (gpioServo(PAN_SERVO_PIN, CENTER_POSITION + 10) != 0) {
                fprintf(stderr, "Error: failed to increment PAN_SERVO_PIN %d.\n", PAN_SERVO_PIN);
                break;
            }
            gpioDelay(BUTTON_DELAY_US);
            if (gpioServo(PAN_SERVO_PIN, CENTER_POSITION) != 0) {
                fprintf(stderr, "Error: failed to decrement PAN_SERVO_PIN %d.\n", PAN_SERVO_PIN);
                break;
            }
        } else if (down_pressed == 1) {
            if (gpioServo(PAN_SERVO_PIN, CENTER_POSITION - 10) != 0) {
                fprintf(stderr, "Error: failed to decrement PAN_SERVO_PIN %d.\n", PAN_SERVO_PIN);
                break;
            }
            gpioDelay(BUTTON_DELAY_US);
            if (gpioServo(PAN_SERVO_PIN, CENTER_POSITION) != 0) {
                fprintf(stderr, "Error: failed to increment PAN_SERVO_PIN %d.\n", PAN_SERVO_PIN);
                break;
            }
        } else if (left_pressed == 1) {
            if (gpioServo(TILT_SERVO_PIN, CENTER_POSITION + 10) != 0) {
                fprintf(stderr, "Error: failed to increment TILT_SERVO_PIN %d.\n", TILT_SERVO_PIN);
                break;
            }
            gpioDelay(BUTTON_DELAY_US);
            if (gpioServo(TILT_SERVO_PIN, CENTER_POSITION) != 0) {
                fprintf(stderr, "Error: failed to decrement TILT_SERVO_PIN %d.\n", TILT_SERVO_PIN);
                break;
            }
        } else if (right_pressed == 1) {
            if (gpioServo(TILT_SERVO_PIN, CENTER_POSITION - 10) != 0) {
                fprintf(stderr, "Error: failed to decrement TILT_SERVO_PIN %d.\n", TILT_SERVO_PIN);
                break;
            }
            gpioDelay(BUTTON_DELAY_US);
            if (gpioServo(TILT_SERVO_PIN, CENTER_POSITION) != 0) {
                fprintf(stderr, "Error: failed to increment TILT_SERVO_PIN %d.\n", TILT_SERVO_PIN);
                break;
            }
        } else {
            gpioDelay(BUTTON_DELAY_US);
        }
    }

    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

