    signal(SIGTERM, signal_handler);

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set PAN_SERVO_PIN %d as output.\n", PAN_SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TILT_SERVO_PIN %d as output.\n", TILT_SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UP_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set UP_PIN %d as input.\n", UP_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(DOWN_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set DOWN_PIN %d as input.\n", DOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set LEFT_PIN %d as input.\n", LEFT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set RIGHT_PIN %d as input.\n", RIGHT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on UP_PIN %d.\n", UP_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(DOWN_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on DOWN_PIN %d.\n", DOWN_PIN);
        cleanup();
