        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioServo(TILT_SERVO_PIN, CENTER_POSITION) != 0) {
        fprintf(stderr, "Error: failed to set TILT_SERVO_PIN %d to center position.\n", TILT_SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

