    printf("Press UP/DOWN/LEFT/RIGHT buttons to control movement.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int up_pressed = gpioRead(UP_PIN);
        int down_pressed = gpioRead(DOWN_PIN);
        int left_pressed = gpioRead(LEFT_PIN);
        int right_pressed = gpioRead(RIGHT_PIN);

        if (up_pressed == 1) {
            if (gpioServo(PAN_SERVO_PIN, CENTER_POSITION + 10) != 0) {
                fprintf(stderr, "Error: failed to increment PAN_SERVO_PIN %d.\n", PAN_SERVO_PIN);
                break;
            }
            gpioDelay(BUTTON_DELAY_US);
            if (gpioServo(PAN_SERVO_PIN, CENTER_POSITION) != 0) {
                fprintf(stderr, "Error: failed to decrement PAN_SERVO_PIN %d.\n", PAN_SERVO_PIN);
                break;
            }
        } else if (down_pressed == 1) {
            if (gpioServo(PAN_SERVO_PIN, CENTER_POSITION - 10) != 0) {
                fprintf(stderr, "Error: failed to decrement PAN_SERVO_PIN %d.\n", PAN_SERVO_PIN);
                break;
            }
            gpioDelay(BUTTON_DELAY_US);
            if (gpioServo(PAN_SERVO_PIN, CENTER_POSITION) != 0) {
                fprintf(stderr, "Error: failed to increment PAN_SERVO_PIN %d.\n", PAN_SERVO_PIN);
                break;
            }
