                fprintf(stderr, "Error: failed to decrement TILT_SERVO_PIN %d.\n", TILT_SERVO_PIN);
                break;
            }
        } else if (right_pressed == 1) {
            if (gpioServo(TILT_SERVO_PIN, CENTER_POSITION - 10) != 0) {
                fprintf(stderr, "Error: failed to decrement TILT_SERVO_PIN %d.\n", TILT_SERVO_PIN);
                break;
            }
            gpioDelay(BUTTON_DELAY_US);
            if (gpioServo(TILT_SERVO_PIN, CENTER_POSITION) != 0) {
                fprintf(stderr, "Error: failed to increment TILT_SERVO_PIN %d.\n", TILT_SERVO_PIN);
                break;
            }
        } else {
            gpioDelay(BUTTON_DELAY_US);
        }
    }

    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

