#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 17
#define IMAGES_DIR "/home/pi/images"
#define DEBOUNCE_MS 50
#define CAPTURE_TIMEOUT_MS 2000
#define LOG_FILE "/home/pi/motion_capture.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
    return 0;
}

static int capture_image(const char *filename) {
    int ret = system("libcamera-still -o " + filename + " --width 640 --height 480 -q 85 --timeout 2000 --nopreview");
    if (ret == -1) {
        fprintf(stderr, "libcamera-still failed: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(ret) && WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "libcamera-still exited with status %d\n", WEXITSTATUS(ret));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line_event event;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir-motion") < 0) {
        fprintf(stderr, "Failed to request falling-edge events on GPIO %d: %s\n", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", PIR_PIN);

    while (running) {
        if (gpiod_line_event_wait(pir_line, &(struct timespec){.tv_sec = 1, .tv_nsec = 0}) < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }

        if (gpiod_line_event_read(pir_line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            char filename[64];
            time_t t = time(NULL);
            struct tm tm;
            if (localtime_r(&t, &tm)) {
                strftime(filename, sizeof(filename), IMAGES_DIR "/motion_%04d%02d%02d_%02d%02d%02d.jpg", &tm);
            } else {
                snprintf(filename, sizeof(filename), IMAGES_DIR "/motion_%04d%02d%02d_%02d%02d%02d.jpg",
                         tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                         tm.tm_hour, tm.tm_min, tm.tm_sec);
            }

            if (capture_image(filename) == 0) {
                log_event("Motion detected, capturing image.");
            } else {
                log_event("Failed to capture image.");
            }
        }
    }

    printf("\nExiting gracefully.\n");
    ret = 0;

cleanup:
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

