#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_STRIDE (FRAME_WIDTH * 2)
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_STRIDE (CROP_HEIGHT * 2)
#define BUFFER_COUNT 1
#define BUF_SIZE (FRAME_STRIDE * BUFFER_COUNT)

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int v4l2_ioctl(int fd, int ioctl_code, ...) {
    va_list ap;
    va_start(ap, ioctl_code);
    int ret = ioctl(fd, ioctl_code, ap);
    va_end(ap);
    return ret;
}

static int v4l2_query_cap(int fd, struct v4l2_capability *cap) {
    if (v4l2_ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (cap->driver_data == NULL) {
        fprintf(stderr, "VIDIOC_QUERYCAP: driver_data is NULL\n");
        return -1;
    }
    if (strcmp(cap->driver_data, "v4l2-camera") != 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP: driver_data mismatch\n");
        return -1;
    }
    return 0;
}

static int v4l2_open(const char *device, struct v4l2_capability *cap) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open");
        return -1;
    }
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return -1;
    }
    return fd;
}

static int v4l2_query_format(int fd, struct v4l2_format *fmt) {
    if (v4l2_ioctl(fd, VIDIOC_QUERY_FORMAT, fmt) < 0) {
        perror("VIDIOC_QUERY_FORMAT");
        return -1;
    }
    if (fmt->type != V4L2_BUF_TYPE_VIDEO_CAPTURE) {
        fprintf(stderr, "VIDIOC_QUERY_FORMAT: type mismatch\n");
        return -1;
    }
    if (fmt->fmt.pix.width != FRAME_WIDTH ||
        fmt->fmt.pix.height != FRAME_HEIGHT ||
        fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "VIDIOC_QUERY_FORMAT: width=%d, height=%d, fmt=%d\n",
                fmt->fmt.pix.width, fmt->fmt.pix.height, fmt->fmt.pix.pixelformat);
        return -1;
    }
    return 0;
}

static int v4l2_set_format(int fd, struct v4l2_format *fmt) {
    if (v4l2_ioctl(fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    return 0;
}

static int v4l2_query_buffers(int fd, struct v4l2_buffer *bufs, int *num_bufs) {
    if (v4l2_ioctl(fd, VIDIOC_QUERY_BUFFERS, bufs) < 0) {
        perror("VIDIOC_QUERY_BUFFERS");
        return -1;
    }
    *num_bufs = bufs->count;
    return 0;
}

static int v4l2_enqueue_buffer(int fd, struct v4l2_buffer *buf) {
    if (v4l2_ioctl(fd, VIDIOC_QBUF, buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

static int v4l2_dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    if (v4l2_ioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }
    return 0;
}

static int v4l2_map_buffer(int fd, struct v4l2_buffer *buf) {
    struct v4l2_mmap_arg mmap_arg;
    memset(&mmap_arg, 0, sizeof(mmap_arg));
    mmap_arg.flags = 0;
    mmap_arg.offset = 0;
    mmap_arg.size = BUF_SIZE;
    mmap_arg.name = NULL;
    if (v4l2_ioctl(fd, VIDIOC_MMAP_BUF, &mmap_arg) < 0) {
        perror("VIDIOC_MMAP_BUF");
        return -1;
    }
    return 0;
}

static int v4l2_unmap_buffer(int fd, struct v4l2_buffer *buf) {
    if (v4l2_ioctl(fd, VIDIOC_UNMAP_BUF, buf) < 0) {
        perror("VIDIOC_UNMAP_BUF");
        return -1;
    }
    return 0;
}

static int v4l2_query_buffer(int fd, struct v4l2_buffer *buf) {
    if (v4l2_ioctl(fd, VIDIOC_QUERY_BUFFER, buf) < 0) {
        perror("VIDIOC_QUERY_BUFFER");
        return -1;
    }
    return 0;
}

static int v4l2_read_frame(int fd, unsigned char *frame) {
    struct v4l2_buffer buf;
    if (v4l2_map_buffer(fd, &buf) < 0) {
        return -1;
    }
    if (v4l2_read_frame(fd, frame) < 0) {
        v4l2_unmap_buffer(fd, &buf);
        return -1;
    }
    v4l2_unmap_buffer(fd, &buf);
    return 0;
}

static int crop_frame(const unsigned char *src,
