    (void)sig;
    g_running = 0;
}

static int v4l2_ioctl(int fd, int ioctl_code, ...) {
    va_list ap;
    va_start(ap, ioctl_code);
    int ret = ioctl(fd, ioctl_code, ap);
    va_end(ap);
    return ret;
}

static int v4l2_query_cap(int fd, struct v4l2_capability *cap) {
    if (v4l2_ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (cap->driver_data == NULL) {
        fprintf(stderr, "VIDIOC_QUERYCAP: driver_data is NULL\n");
        return -1;
    }
    if (strcmp(cap->driver_data, "v4l2-camera") != 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP: driver_data mismatch\n");
        return -1;
    }
    return 0;
}

static int v4l2_open(const char *device, struct v4l2_capability *cap) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open");
        return -1;
    }
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return -1;
    }
    return fd;
}

static int v4l2_query_format(int fd, struct v4l2_format *fmt) {
    if (v4l2_ioctl(fd, VIDIOC_QUERY_FORMAT, fmt) < 0) {
        perror("VIDIOC_QUERY_FORMAT");
        return -1;
    }
    if (fmt->type != V4L2_BUF_TYPE_VIDEO_CAPTURE) {
        fprintf(stderr, "VIDIOC_QUERY_FORMAT: type mismatch\n");
        return -1;
    }
    if (fmt->fmt.pix.width != FRAME_WIDTH ||
        fmt->fmt.pix.height != FRAME_HEIGHT ||
        fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "VIDIOC_QUERY_FORMAT: width=%d, height=%d, fmt=%d\n",
                fmt->fmt.pix.width, fmt->fmt.pix.height, fmt->fmt.pix.pixelformat);
        return -1;
    }
    return 0;
}

