    if (v4l2_ioctl(fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    return 0;
}

static int v4l2_query_buffers(int fd, struct v4l2_buffer *bufs, int *num_bufs) {
