        return -1;
    }
    return 0;
}

static int v4l2_map_buffer(int fd, struct v4l2_buffer *buf) {
    struct v4l2_mmap_arg mmap_arg;
    memset(&mmap_arg, 0, sizeof(mmap_arg));
    mmap_arg.flags = 0;
    mmap_arg.offset = 0;
    mmap_arg.size = BUF_SIZE;
    mmap_arg.name = NULL;
    if (v4l2_ioctl(fd, VIDIOC_MMAP_BUF, &mmap_arg) < 0) {
        perror("VIDIOC_MMAP_BUF");
        return -1;
    }
    return 0;
}

static int v4l2_unmap_buffer(int fd, struct v4l2_buffer *buf) {
    if (v4l2_ioctl(fd, VIDIOC_UNMAP_BUF, buf) < 0) {
