#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PAN_ANGLE 0
#define MAX_PAN_ANGLE 180
#define MIN_TILT_ANGLE 0
#define MAX_TILT_ANGLE 180
#define MIN_PWM_WIDTH 500
#define MAX_PWM_WIDTH 2500
#define DELAY_MS 100

static volatile int keep_running = 1;

void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int set_servo_angle(int pin, int angle) {
    if (angle < MIN_PAN_ANGLE || angle > MAX_PAN_ANGLE) {
        fprintf(stderr, "Error: Invalid pan angle %d degrees\n", angle);
        return -1;
    }
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = (int)((angle / 180.0) * (MAX_PWM_WIDTH - MIN_PWM_WIDTH) + MIN_PWM_WIDTH);
    if (gpioServo(pin, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo on pin %d to angle %d degrees\n", pin, angle);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set PAN_SERVO_PIN %d as output\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set TILT_SERVO_PIN %d as output\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    int pan_angle = 90;
    int tilt_angle = 90;
    int pan_angle_set = 0;
    int tilt_angle_set = 0;

    while (keep_running) {
        char input;
        printf("Enter arrow keys (up/down/left/right) to adjust pan and tilt: ");
        fflush(stdout);

        if (fgets(&input, sizeof(input), stdin) == NULL) {
            if (feof(stdin)) break;
            fprintf(stderr, "Error: Input from stdin is invalid\n");
            break;
        }

        input = toupper(input);

        if (input == 'U') {
            if (pan_angle_set) {
                pan_angle_set = 0;
                printf("Pan: %d degrees\n", pan_angle);
            } else {
                pan_angle_set = 1;
                printf("Pan: %d degrees\n", pan_angle);
            }
        } else if (input == 'D') {
            if (tilt_angle_set) {
                tilt_angle_set = 0;
                printf("Tilt: %d degrees\n", tilt_angle);
            } else {
                tilt_angle_set = 1;
                printf("Tilt: %d degrees\n", tilt_angle);
            }
        } else if (input == 'L') {
            if (pan_angle_set) {
                pan_angle_set = 0;
                printf("Pan: %d degrees\n", pan_angle);
            } else {
                tilt_angle_set = 1;
                printf("Tilt: %d degrees\n", tilt_angle);
            }
        } else if (input == 'R') {
            if (pan_angle_set) {
                pan_angle_set = 0;
                printf("Pan: %d degrees\n", pan_angle);
            } else {
                tilt_angle_set = 1;
                printf("Tilt: %d degrees\n", tilt_angle);
            }
        } else {
            fprintf(stderr, "Error: Invalid input\n");
            break;
        }

        if (pan_angle_set) {
            if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) {
                fprintf(stderr, "Error: Failed to set pan angle\n");
            }
            pan_angle_set = 0;
        }
        if (tilt_angle_set) {
            if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
                fprintf(stderr, "Error: Failed to set tilt angle\n");
            }
            tilt_angle_set = 0;
        }

        gpioDelay(DELAY_MS * 1000);
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

