#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// GPIO pin for YF-S201 sensor
#define SENSOR_PIN 17

// I2C address for HD44780 LCD
#define LCD_ADDR 0x27

// Calibration factor for YF-S201 (pulses per liter)
#define PULSES_PER_LITER 450.0

// I2C bus on Raspberry Pi 4 Model B
#define I2C_BUS 1

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float calculate_flow_rate(int pulses);
float accumulate_volume(float volume);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(int pulses) {
    return (float)pulses / PULSES_PER_LITER;
}

// Function to accumulate volume in liters
float accumulate_volume(float volume) {
    return volume + (float)pulses / PULSES_PER_LITER;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, LCD_ADDR);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int pulses = gpioRead(SENSOR_PIN);
        if (pulses < 0) {
            fprintf(stderr, "Error: Failed to read sensor pin %d\n", SENSOR_PIN);
            break;
        }

        float flow_rate = calculate_flow_rate(pulses);
        float volume = accumulate_volume(flow_rate);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        printf("[%s] Flow Rate: %.2f liters/minute, Volume: %.2f liters\n", timestamp, flow_rate, volume);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    printf("Water flow monitoring stopped.\n");
    return 0;
}

