#define ADC_MAX       1023
#define ADC_SCALE     1000.0f

#define SAMPLE_MS     500
#define SAMPLE_COUNT  (SAMPLE_MS * 1000)

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d)\n", g_spi_handle);
        return -1;
    }
    return 0;
}

static int i2c_init(void) {
