static float calculate_wind_direction(int pulses) {
    if (pulses <= 0) return 0.0f;
    float angle = ((float)pulses * 360.0f) / (float)SAMPLE_COUNT;
    if (angle < 0.0f) angle += 360.0f;
    return angle;
