    gpioWrite(LCD_RS_PIN, 1);
    gpioWrite(LCD_EN_PIN, 1);
    gpioDelay(2000);
    gpioWrite(LCD_RS_PIN, 0);
    gpioWrite(LCD_EN_PIN, 0);
}

static void lcd_string(const char *s) {
    lcd_clear();
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == ' ') {
            lcd_string("  ");
        } else {
            lcd_string(c);
        }
    }
}

static void lcd_command(uint8_t cmd) {
    gpioWrite(LCD_RS_PIN, 1);
    gpioWrite(LCD_EN_PIN, 1);
    gpioWrite(LCD_D4_PIN, (cmd >> 4) & 0x07);
    gpioWrite(LCD_D5_PIN, (cmd >> 3) & 0x07);
    gpioWrite(LCD_D6_PIN, (cmd >> 2) & 0x07);
    gpioWrite(LCD_D7_PIN, (cmd >> 1) & 0x07);
    gpioWrite(LCD_D7_PIN, (cmd & 0x07));
    gpioDelay(2000);
    gpioWrite(LCD_RS_PIN, 0);
    gpioWrite(LCD_EN_PIN, 0);
}

static void lcd_data(uint8_t data) {
    gpioWrite(LCD_RS_PIN, 1);
    gpioWrite(LCD_EN_PIN, 1);
    gpioWrite(LCD_D4_PIN, (data >> 6) & 0x07);
    gpioWrite(LCD_D5_PIN, (data >> 5) & 0x07);
    gpioWrite(LCD_D6_PIN, (data >> 4) & 0x07);
    gpioWrite(LCD_D7_PIN, (data >> 3) & 0x07);
    gpioWrite(LCD_D7_PIN, (data >> 2) & 0x07);
    gpioWrite(LCD_D7_PIN, (data >> 1) & 0x07);
    gpioWrite(LCD_D7_PIN, data & 0x07);
    gpioDelay(2000);
    gpioWrite(LCD_RS_PIN, 0);
    gpioWrite(LCD_EN_PIN, 0);
}

static void lcd_send_byte(uint8_t data) {
    lcd_command(0x80 | data);
}

static void lcd_send_string(const char *s) {
    lcd_send_byte('@');
    lcd_send_byte(0x40 | (s[0] - ' '));
    lcd_send_byte(0x00);
    for (int i = 1; s[i] != '\0'; i++) {
        lcd_send_byte(s[i]);
    }
}

