        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    if (i2c_init() != 0) {
        spiClose(g_spi_handle);
        gpioTerminate();
        return 1;
    }

    lcd_init();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
