#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <string.h>

#define FLOW_SENSOR_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define PULSES_PER_LITER 7.5f
#define FLOW_RATE_THRESHOLD 1.0f
#define SAMPLE_INTERVAL_SEC 1
#define LCD_WIDTH 16
#define LCD_LINE_LEN 2

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

float calculate_flow_rate(int pulses) {
    if (pulses <= 0) return 0.0f;
    return (float)pulses / PULSES_PER_LITER;
}

int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP);
    return 0;
}

int setup_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

int setup_lcd(void) {
    int handle = lcd_init(LCD_WIDTH, LCD_LINE_LEN);
    if (handle < 0) {
        fprintf(stderr, "LCD initialization failed: %d\n", handle);
        return -1;
    }
    return 0;
}

int display_flow_rate(float flow_rate) {
    char buffer[LCD_WIDTH + LCD_LINE_LEN];
    int len = snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    if (len < 0 || len >= (int)sizeof(buffer)) {
        fprintf(stderr, "Error formatting LCD buffer\n");
        return -1;
    }
    if (lcd_write(handle, buffer) < 0) {
        fprintf(stderr, "Failed to write to LCD\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (setup_gpio() != 0) return 1;
    if (setup_i2c() != 0) return 1;
    if (setup_lcd() != 0) return 1;

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int pulses = gpioRead(FLOW_SENSOR_PIN);
        if (pulses < 0) {
            fprintf(stderr, "Error reading flow sensor\n");
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        float flow_rate = calculate_flow_rate(pulses);
        if (flow_rate < 0.0f) {
            fprintf(stderr, "Invalid flow rate calculation\n");
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        if (flow_rate > FLOW_RATE_THRESHOLD) {
            printf("Flow Rate: %.2f L/min\n", flow_rate);
            if (display_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Failed to display flow rate\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

