#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800
#define FRAME_DELAY_US 800

static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void set_row(int row_pins[], int col_pins[], int row_num) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_pins[i] == row_num) {
            gpiod_line_set_value(col_lines[i], 0);
            gpiod_line_set_value(row_lines[i], 1);
        }
    }
}

static void set_column(int row_pins[], int col_pins[], int col_num) {
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_pins[i] == col_num) {
            gpiod_line_set_value(row_lines[i], 1);
            gpiod_line_set_value(row_pins[i], 0);
        }
    }
}

static void scan_row(int row_pins[], int col_pins[], int row_num) {
    for (int i = 0; i < NUM_ROWS; i++) {
        set_row(row_pins, col_pins, row_num);
        usleep(SCAN_DELAY_US);
        set_column(row_pins, col_pins, row_num);
        usleep(SCAN_DELAY_US);
    }
}

static void scan_frame(int row_pins[], int col_pins[], int frame_num) {
    for (int i = 0; i < NUM_ROWS; i++) {
        set_row(row_pins, col_pins, i);
        usleep(FRAME_DELAY_US);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(row_lines[i], "common-anode", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            cleanup();
            return 1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(col_lines[i], "common-anode", 0) < 0) {
            fprintf(stderr, "Failed to request col line %u as output\n", col_pins[i]);
            cleanup();
            return 1;
        }
    }

    printf("Wave animation started. Press Ctrl+C to exit.\n");

    while (running) {
        scan_frame(row_pins, col_pins, 0);
        scan_frame(row_pins, col_pins, 1);
        scan_frame(row_pins, col_pins, 2);
        scan_frame(row_pins, col_pins, 3);
        scan_frame(row_pins, col_pins, 4);
        scan_frame(row_pins, col_pins, 5);
        scan_frame(row_pins, col_pins, 6);
        scan_frame(row_pins, col_pins, 7);
        scan_frame(row_pins, col_pins, 8);
        scan_frame(row_pins, col_pins, 9);
        usleep(10000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

