#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_MS 150

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile sig_atomic_t running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    running = 0;
}

void cleanup_and_exit_with_error(int signum) {
    (void)signum;
    running = 0;
    if (chip) {
        for (int i = 0; i < NUM_ROWS; i++) {
            if (row_lines[i]) {
                gpiod_line_release(row_lines[i]);
            }
        }
        for (int i = 0; i < NUM_COLS; i++) {
            if (col_lines[i]) {
                gpiod_line_release(col_lines[i]);
            }
        }
        gpiod_chip_close(chip);
    }
    exit(EXIT_FAILURE);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit_with_error;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, i);
        if (!row_lines[i]) {
            perror("Failed to get row line");
            cleanup_and_exit_with_error(0);
        }
        if (gpiod_line_request_output(row_lines[i], "common_anode_matrix", 1) < 0) {
            perror("Failed to request row line as output");
            cleanup_and_exit_with_error(0);
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, i);
        if (!col_lines[i]) {
            perror("Failed to get column line");
            cleanup_and_exit_with_error(0);
        }
