#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "biometric_data.log"
#define SAMPLE_PERIOD  1
#define CMD_ALS_FORCE  0x06
#define CMD_PS1_FORCE  0x07
#define CMD_RESET      0x00
#define CMD_HW_KEY     0x07
#define CMD_CH_LIST    0x4F
#define CMD_PS1_DATA   0x18
#define CMD_ALS_VIS_DATA 0x22

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

static int init_si1145(int handle) {
    uint8_t part_id = 0;
    if (i2c_read_byte(handle, CMD_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != 0x45) {
