#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define POLL_INTERVAL_S 60
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_message(const char *message) {
    if (!log_file) return -1;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_file, "%s: %s\n", ts, message);
    fflush(log_file);
    return 0;
}

static int log_error(const char *message) {
    if (!log_file) return -1;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_file, "%s: ERROR: %s\n", ts, message);
    fflush(log_file);
    return 0;
}

static int measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trigger, 1) < 0) {
        log_error("Failed to set trigger high");
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        log_error("Failed to set trigger low");
        return -1;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (end.tv_sec >= ECHO_TIMEOUT_US) {
            log_error("Echo timeout: sensor absent or stuck high");
            return -1;
        }
    }

    struct timespec pulse_start, pulse_end;
    clock_gettime(CLOCK_MONOTONIC, &pulse_start);

    if (gpiod_line_set_value(trigger, 1) < 0) {
        log_error("Failed to set trigger high");
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        log_error("Failed to set trigger low");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &pulse_end);
    double pulse_duration = (pulse_end.tv_sec - pulse_start.tv_sec) +
                            (pulse_end.tv_nsec - pulse_start.tv_nsec) / 1e9;

    double distance = (pulse_duration * 34300.0) / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        log_error("Distance out of range: %.2f cm", distance);
        return -1;
    }

    return (int)distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("Failed to set signal handlers");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger || !echo) {
        log_error("Failed to get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        log_error("Failed to request trigger line as output");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        log_error("Failed to request echo line as input");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        goto cleanup;
    }

    printf("HC-SR04 watering reminder started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int distance = measure_distance(trigger, echo);
        if (distance < 0) {
            log_error("Measurement failed, skipping cycle");
        } else if (distance < 0.0) {
            log_error("Measurement failed, sensor absent or stuck high");
        } else {
            if (distance < MIN_DISTANCE_CM) {
                printf("Time to water the plant!\n");
                log_message("Time to water the plant!");
            }
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    return ret;
}

