#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define APDS9960_ADDR 0x39
#define APDS9960_ID_REG 0x92
#define APDS9960_ENABLE_REG 0x80
#define APDS9960_ATIME_REG 0x81
#define APDS9960_WTIME_REG 0x83
#define APDS9960_PPULSE_REG 0x8E
#define APDS9960_CONTROL_REG 0xF1
#define APDS9960_CONFIG2_REG 0x90
#define APDS9960_PROXIMITY_REG 0x9C
#define APDS9960_COLOR_REG 0x96

#define PROXIMITY_THRESHOLD 200
#define I2C_BUS 1
#define LOG_FILE "color_proximity_log.csv"
#define READ_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int apds9960_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int apds9960_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error setting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

static int apds9960_read_color(int handle, uint16_t *r, uint16_t *g, uint16_t *b) {
    char reg_buf[2] = { (char)APDS9960_COLOR_REG, (char)APDS9960_COLOR_REG + 1 };
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error setting reg 0x%02X: %s\n", APDS9960_COLOR_REG, strerror(errno));
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading color data: %s\n", strerror(errno));
        return -1;
    }
    *r = (uint16_t)((data[0] << 8) | data[1]);
    *g = (uint16_t)((data[2] << 8) | data[3]);
    *b = (uint16_t)((data[4] << 8) | data[5]);
    return 0;
}

static int apds9960_read_proximity(int handle, uint8_t *prox) {
    char reg_buf[1] = { (char)APDS9960_PROXIMITY_REG };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error setting reg 0x%02X: %s\n", APDS9960_PROXIMITY_REG, strerror(errno));
        return -1;
