        if (vl53l0x_trigger_measurement(i2c_handle) < 0) {
            fprintf(stderr, "Trigger failed; continuing\n");
            gpioDelay(1000000);
            continue;
        }

        uint16_t distance_mm;
        if (vl53l0x_read_distance(i2c_handle, &distance_mm) < 0) {
            fprintf(stderr, "Distance read failed; continuing\n");
