#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define CH101_ADDR 0x45
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 200000  /* 200 ms */
#define MEASUREMENT_DELAY_US 50000   /* 50 ms */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, CH101_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(void) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle is invalid\n");
        return -1;
    }

    /*
     * TDK CH101:
     *   - Start bit: 0x01
     *   - Single-shot mode: 0x00
     *   - Transmit data: 8-bit data register + 8-bit clock
     *   - Data register: 0x00
     *   - Data: 8-bit data register + 8-bit clock
     *
     * The CH101 datasheet provides a detailed timing diagram.
     * We send a single-shot start bit, then read the 8-bit data
     * register + 8-bit clock.
     */
    char tx[2] = {0x01, 0x00};
    char rx[2] = {0};

    if (i2cWriteDevice(i2c_handle, tx, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(i2c_handle, rx, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1;
    }

    return ((rx[0] & 0xFC) << 8) | rx[1];
}

