        fflush(log_file);
    }
    fprintf(stderr, "%s: ERROR: %s\n", timestamp, message);
    return 1;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return value;
}

static void log_reading(int sensor1, int sensor2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1, sensor2);
        fflush(log_file);
    }
    printf("%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1, sensor2);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting mode for GPIO %d\n", SENSOR1_PIN);
        log_error("Error setting mode for GPIO 17");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting mode for GPIO %d\n", SENSOR2_PIN);
        log_error("Error setting mode for GPIO 18");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("TCRT5000 obstacle detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            log_error("Error reading sensor values");
        } else {
            log_reading(sensor1_value, sensor2_value);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

