#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define DISTANCE_THRESHOLD_CM 20.0f
#define LED_GPIO 17
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        return -1;
    }
    gpioWrite(LED_GPIO, 0);
    return 0;
}

static int read_distance(float *distance_out) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    *distance_out = (float)buf[0] | ((float)buf[1] << 8);
    return 0;
}

static void log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02dT%02d:%02d:%02d,%.2f cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fclose(fp);
}

static void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD_CM) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        return 1;
    }

    printf("Distance monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

