#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint16_t *value) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        int result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *value = (uint16_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read failed (reg 0x%02X, ret=%d): %s\n", reg, result, pigpio_error(result));
        retries--;
        gpioDelay(10000);
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X)\n", RETRY_COUNT, reg);
    return -1;
}

static int write_register(int handle, uint8_t reg, uint16_t value) {
    int result = i2cWriteWordData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, value 0x%04X, ret=%d): %s\n", reg, value, result, pigpio_error(result));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient) {
    uint16_t raw;
    if (read_register(handle, PROXIMITY_REG, &raw) != 0) {
        return -1;
    }
    *proximity = raw;
    if (read_register(handle, AMBIENT_REG, &raw) != 0) {
        return -1;
    }
    *ambient = raw;
    return 0;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Proximity: %u, Ambient: %u\n", timestamp, proximity, ambient);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", SI1182_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting Si1182 proximity and ambient sensor logging...\n");

    while (running) {
        uint16_t proximity, ambient;
        if (read_sensor_data(i2c_handle, &proximity, &ambient) == 0) {
            log_data(log_file, proximity, ambient);
            printf("Proximity: %u, Ambient: %u\n", proximity, ambient);
        } else {
            fprintf(stderr, "Failed to read sensor data after retries\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

