#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x50
#define MEASUREMENT_CMD_LEN 4
#define RESPONSE_LEN 15
#define SAMPLE_INTERVAL_MS 100
#define MEASUREMENT_DELAY_MS 10
#define LOG_FILE "intrusion_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    uint8_t buf[MEASUREMENT_CMD_LEN];
    buf[0] = cmd;
    if (write(fd, buf, MEASUREMENT_CMD_LEN) != MEASUREMENT_CMD_LEN) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_response(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance_mm) {
    uint8_t cmd[MEASUREMENT_CMD_LEN];
    uint8_t response[RESPONSE_LEN];
    int ret;

    cmd[0] = SENSOR_ADDR;
    cmd[1] = 0x50;
    cmd[2] = 0x00;
    cmd[3] = 0x01;

    ret = i2c_write_cmd(fd, cmd[0]);
    if (ret != 0) return ret;

    usleep(MEASUREMENT_DELAY_MS * 1000);

    ret = i2c_read_response(fd, response, RESPONSE_LEN);
    if (ret != 0) return ret;

    if (response[0] != SENSOR_ADDR) {
        fprintf(stderr, "Invalid sensor address: 0x%02X (expected 0x%02X)\n",
                response[0], SENSOR_ADDR);
        return -1;
    }

    *distance_mm = (uint16_t)((response[1] << 8) | response[2]);
    return 0;
}

static void log_intrusion(FILE *log, uint16_t distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log, "%s - Intrusion detected: Distance: %u mm\n", timestamp, distance);
    fflush(log);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

