    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance;

        for (int i = 0; i < 10 && running; i++) {
            if (read_distance(i2c_fd, &distance) == 0) {
                log_intrusion(log_file, distance);
                printf("Distance: %u mm\n", distance);
            } else {
                fprintf(stderr, "Sensor read failed at cycle %d\n", i);
            }
            usleep(SAMPLE_INTERVAL_MS * 1000);
        }

        if (!running) break;
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

