#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define VL53L0X_ADDR        0x29
#define VL53L0X_SYSRANGE_START 0x00
#define VL53L0X_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_RESULT_RANGE_STATUS 0x14
#define VL53L0X_SYSTEM_INTERRUPT_CLEAR 0x0B
#define VL53L0X_MODEL_ID 0xC0
#define VL53L0X_MODEL_ID_EXPECTED 0xEE
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg(handle, VL53L0X_MODEL_ID, &model_id) != 0) {
        return -1;
    }
    if (model_id != VL53L0X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L0X_MODEL_ID_EXPECTED);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X)\n", model_id);

    if (i2c_write_reg(handle, VL53L0X_SYSRANGE_START, 0x01) != 0) {
        return -1;
