#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR   0x4C
#define DISTANCE_REG    0x00
#define DISTANCE_FACTOR 0.125f   /* mm per count */
#define LOOP_MS        500
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd bytes: %s\n",
                reg, n, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void)
{
    int fd = -1;
    int retries = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX75030 detected on %s at 0x%02X. Reading every %d ms.\n",
           I2C_BUS, MLX75030_ADDR, LOOP_MS);

    while (g_running) {
        uint16_t dist;
        if (i2c_read_word(fd, DISTANCE_REG, &dist) == 0) {
            printf("Distance: %u mm\n", (unsigned)dist);
            fflush(stdout);
        } else {
            fprintf(stderr, "I2C read failed; retrying next cycle.\n");
        }
        fflush(stdout);
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = LOOP_MS * 1000000}, NULL);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

