#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define OPT3101_ADDR 0x44
#define I2C_BUS 1
#define LOG_INTERVAL_MS 500

// OPT3101 Registers
#define OPT3101_REG_DISTANCE_L 0x00
#define OPT3101_REG_DISTANCE_H 0x01
#define OPT3101_REG_AMBIENT_L 0x02
#define OPT3101_REG_AMBIENT_H 0x03
#define OPT3101_REG_ERROR_FLAG 0x04
#define OPT3101_REG_CONFIG 0x05

// OPT3101 Config: Enable, Auto-increment, Single-shot
#define OPT3101_CONFIG_VAL 0x01

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int read_sensor_data(uint16_t *distance, uint16_t *ambient_light) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, OPT3101_REG_DISTANCE_L, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    *distance = (uint16_t)((buf[1] << 8) | buf[0]);
    *ambient_light = (uint16_t)((buf[2] << 8) | buf[1]);
    return 0;
}

int log_data(uint16_t distance, uint16_t ambient_light, int error_flag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %u, Ambient Light: %u, Error Flag: %d\n",
           timestamp, distance, ambient_light, error_flag);
    fflush(stdout);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        uint16_t distance, ambient_light;
        int error_flag;

        if (read_sensor_data(&distance, &ambient_light) == 0) {
            error_flag = 0;
        } else {
            error_flag = 1;
        }

        log_data(distance, ambient_light, error_flag);

        gpioDelay(LOG_INTERVAL_MS * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

