/*
 * HC-SR04 Ultrasonic Distance Sensor Reader
 * Board: Raspberry Pi 3 Model B+
 * Library: pigpio (not wiringPi)
 *
 * Wiring:
 *   HC-SR04 Trigger  -> GPIO 17 (BCM)
 *   HC-SR04 Echo    -> GPIO 18 (BCM)
 *   HC-SR04 VCC      -> 5V (or 3.3V if powered from Pi)
 *   HC-SR04 GND      -> GND
 *
 * HC-SR04:
 *   - Trigger: 10 us pulse (active-low)
 *   - Echo:  10 us rising edge, then 38 ms falling edge
 *   - Range:  0.0343 cm/us * pulse width (0-38 ms)
 *
 * Note: The HC-SR04 operates at 5V. The Pi GPIO is 3.3V tolerant.
 *       Use a 1 kOhm resistor in series on the echo line for protection.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 200000   /* 200 ms */
#define MAX_RANGE_US     38000    /* 38 ms max range */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timing helpers                                                      */
/* ------------------------------------------------------------------ */
static uint32_t get_tick(void)
{
    return gpioTick();
}

static uint32_t elapsed_us(uint32_t start, uint32_t end)
{
    return (end - start) / 1000; /* microseconds */
}

/* ------------------------------------------------------------------ */
/* HC-SR04 distance computation                                      */
/* ------------------------------------------------------------------ */
static float distance_cm(uint32_t pulse_us)
{
    if (pulse_us <= 0 || pulse_us > MAX_RANGE_US) {
        return -1.0f;
    }

    /* HC-SR04: 10 us trigger, then 38 ms echo.
     * pulse_us * 0.0343 cm/us = distance in cm.
     */
    return (float)pulse_us * 0.0343f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_reading(float distance_cm)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    }

    printf("[%s] Distance: %.2f cm\n", ts, distance_cm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); /* 1 ms settle */

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        /* --- Trigger the sensor --- */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN high.\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN low.\n");
            break;
        }

        /* --- Wait for echo rising edge (10 us) --- */
        uint32_t start = get_tick();
        while (g_running && elapsed_us(start, get_tick()) < ECHO_TIMEOUT_US) {
            gpioDelay(1);
        }

        if (!g_running) {
            break;
        }

        uint32_t end = get_tick();
        if (!g_running) {
            break;
        }

        uint32_t pulse_us = elapsed_us(start, end);

        /* --- Validate pulse width --- */
        if (pulse_us <= 0 || pulse_us > MAX_RANGE_US) {
            fprintf(stderr, "Warning: echo pulse width %u us out of range (0-38 ms).\n",
                    pulse_us);
            continue;
        }

        /* --- Compute distance --- */
        float distance_cm = distance_cm(pulse_us);

        if (distance_cm < 0.0f) {
            fprintf(stderr, "Warning: invalid pulse width %u us.\n",
                    pulse_us);
            continue;
        }

        /* --- Log the reading --- */
        log_reading(distance_cm);

        /* --- Wait for 1 s (interruptible by signals) --- */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* --- Cleanup --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

