    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    return 0;
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
}

static void detect_intrusion(float distance) {
    if (!running) return;

    if (distance < RANGE_THRESHOLD) {
        printf("Intrusion detected at %.2f meters\n", distance);
        gpioWrite(LED_GPIO, 1);
        gpioDelay(ALERT_DURATION_SEC * 1000000);
        gpioWrite(LED_GPIO, 0);
    }
}

static int read_frame(int fd, RangeData *frame) {
    char buffer[BUFFER_SIZE];
    int bytes_read = 0;

    while (bytes_read < BUFFER_SIZE) {
        int n = read(fd, buffer + bytes_read, BUFFER_SIZE - bytes_read);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read: EOF\n");
            return -1;
        }
        bytes_read += n;
    }

    if (bytes_read < BUFFER_SIZE) {
        fprintf(stderr, "Short read: %d bytes\n", bytes_read);
        return -1;
    }

    uint8_t magic[8] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (memcmp(magic, buffer, 8) != 0) {
        fprintf(stderr, "Invalid magic word\n");
        return -1;
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer[i] & 0x80) {
            uint16_t raw_range = (buffer[i] << 8) | buffer[i + 1];
            if (raw_range & 0x8000) {
                raw_range |= 0xFFFF0000;
            }
            frame->range = (float)raw_range / RANGE_RESOLUTION;
            frame->valid = 1;
            return 0;
        }
    }

    fprintf(stderr, "No range data found in frame\n");
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        cleanup();
        return 1;
    }

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        RangeData frame;
        if (read_frame(uart_fd, &frame) == 0) {
            detect_intrusion(frame.range);
            log_intrusion(frame.range);
        } else {
            fprintf(stderr, "Failed to read frame\n");
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

