#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define DISTANCE_REG 0x31
#define ALERT_PIN 17
#define DISTANCE_THRESHOLD 10.0f
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(void) {
    int high = i2cReadByteData(i2c_handle, DISTANCE_REG);
    if (high < 0) {
        fprintf(stderr, "Error reading distance register 0x%02X: %d\n",
                DISTANCE_REG, high);
        return -1;
    }
    int low = i2cReadByteData(i2c_handle, DISTANCE_REG + 1);
    if (low < 0) {
        fprintf(stderr, "Error reading distance register 0x%02X+1: %d\n",
                DISTANCE_REG, low);
        return -1;
    }
    return (high << 8) | low;
}

static void log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        return;
    }
    fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    fclose(fp);
}

static void check_alert(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(ALERT_PIN, 1);
        printf("Alert: Distance below threshold (%.2f cm)\n", distance);
    } else {
        gpioWrite(ALERT_PIN, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0);

    printf("Distance logging started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "I2C read error, retrying in 100 ms...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float distance_cm = (float)distance / 10.0f;
        log_distance(distance_cm);
        check_alert(distance_cm);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(ALERT_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

