#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define LED_PIN 18
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write failed (reg 0x%02X, rc=%d): attempt %d\n", reg, rc, attempt + 1);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc == 0) *value = (uint8_t)rc;
        else {
            fprintf(stderr, "I2C read failed (reg 0x%02X, rc=%d): attempt %d\n", reg, rc, attempt + 1);
        }
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int read_distance(int handle, float *distance) {
    uint8_t raw[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_byte(handle, 0x00, 0x00) < 0) { gpioDelay(RETRY_DELAY_US); continue; }
        if (i2c_read_byte(handle, 0x00, raw) < 0) { gpioDelay(RETRY_DELAY_US); continue; }
        *distance = (float)((raw[0] << 8) | raw[1]) / 10.0f;
        return 0;
    }
    return -1;
}

static void blink_led(int pin, int frequency) {
    gpioWrite(pin, 1);
    gpioDelay(frequency * 1000000);
    gpioWrite(pin, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
