#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "proximity_log.txt"
#define POLL_DELAY_US 10000  /* 10 ms */
#define DEBOUNCE_DELAY_US 50000 /* 50 ms */
#define POLL_INTERVAL_US 100000 /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(int sensor_id, const char *event_type) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor %d - %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor GPIO pins as inputs */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure both sensors start in the idle state */
    if (gpioRead(SENSOR_1_GPIO) != 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioRead(SENSOR_2_GPIO) != 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TCRT5000 obstacle avoidance sensor monitoring started.\n");
    printf("Sensor 1: GPIO %d, Sensor 2: GPIO %d\n", SENSOR_1_GPIO, SENSOR_2_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int sensor_1_state = gpioRead(SENSOR_1_GPIO);
        int sensor_2_state = gpioRead(SENSOR_2_GPIO);

        if (sensor_1_state < 0 || sensor_2_state < 0) {
            fprintf(stderr, "Error reading sensor GPIO %d or %d\n", SENSOR_1_GPIO, SENSOR_2_GPIO);
            break;
        }

        /* Detect transitions (HIGH -> LOW or LOW -> HIGH) */
        int detected = (sensor_1_state == 0 && sensor_2_state == 1) ||
                       (sensor_1_state == 1 && sensor_2_state == 0);

        if (log_event(1, (detected) ? "DETECTED" : "CLEARED") != 0) {
            fprintf(stderr, "Failed to log event\n");
            break;
        }

        gpioDelay(POLL_DEBOUNCE_DELAY_US);
    }

    /* Cleanup */
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

