#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49
#define MEAS_TRIGGER   0x04
#define MEAS_STATUS    0x06
#define DIST_HIGH      0x08
#define DIST_LOW       0x09
#define LOG_FILE       "distance_log.csv"
#define SAMPLE_MS      500
#define I2C_TIMEOUT_MS 50

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_low, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg_low + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_distance(int fd, uint16_t *distance_mm)
{
    if (i2c_write_reg8(fd, MEAS_TRIGGER, 0x01) < 0) return -1;
    struct timespec ts = { 0, I2C_TIMEOUT_MS * 1000000L };
    while (clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &ts, NULL) < 0) {
        if (g_running) {
            fprintf(stderr, "I2C timeout waiting for measurement\n");
            return -1;
        }
        if (errno == EINTR) continue;
        return -1;
    }

    uint8_t status;
    if (i2c_read_reg8(fd, MEAS_STATUS, &status) < 0) return -1;
    if (!(status & 0x01)) {
        fprintf(stderr, "Distance measurement not ready (status=0x%02X)\n", status);
        return -1;
    }

    uint16_t dist;
    if (i2c_read_reg16(fd, DIST_HIGH, &dist) < 0) return -1;
    *distance_mm = dist;
    return 0;
}

static int log_distance(uint16_t distance_mm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, distance_mm);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", CH101_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("CH101 distance logger started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_MS);

    while (g_running) {
        uint16_t distance_mm;
        if (read_distance(fd, &distance_mm) < 0) {
            fprintf(stderr, "Sensor read failed; skipping sample\n");
        } else {
            if (log_distance(distance_mm) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    close(fd);
    return 0;
}

