    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", CH101_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("CH101 distance logger started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_MS);

    while (g_running) {
        uint16_t distance_mm;
        if (read_distance(fd, &distance_mm) < 0) {
            fprintf(stderr, "Sensor read failed; skipping sample\n");
        } else {
            if (log_distance(distance_mm) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    close(fd);
    return 0;
}

