#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define VL53L4CX_I2C_ADDR 0x29
#define VL53L4CX_REG_SOFT_RESET 0x7FFF
#define VL53L4CX_REG_RANGE_START 0x0009
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0046
#define VL53L4CX_REG_DISTANCE_HIGH 0x0096
#define VL53L4CX_REG_DISTANCE_LOW 0x0097

#define I2C_BUS 1
#define POLL_INTERVAL_US 500000
#define RESET_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l4cx_write_reg(int handle, uint16_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%04X to register 0x%04X: %d\n", value, reg, rc);
    }
    return rc;
}

static int vl53l4cx_init(int handle) {
    /* Soft reset: write 0x00 to register 0x7FFF */
    if (vl53l4cx_write_reg(handle, VL53L4CX_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(RESET_DELAY_US);

    /* Begin ranging: write 0x00 to register 0x0009 */
    if (vl53l4cx_write_reg(handle, VL53L4CX_REG_RANGE_START, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

static int vl53l4cx_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    int rc = i2cReadByteData(handle, VL53L4CX_REG_INTERRUPT_STATUS);
    if (rc < 0) {
        fprintf(stderr, "Error reading interrupt status: %d\n", rc);
        return -1;
    }
    if (rc == 0) {
        return -1; /* no data available */
    }

    /* Read 16-bit distance (high byte first) */
    uint8_t high_byte = i2cReadByteData(handle, VL53L4CX_REG_DISTANCE_HIGH);
    if (high_byte < 0) {
        fprintf(stderr, "Error reading distance high byte: %d\n", rc);
        return -1;
    }
    *distance_mm = (uint16_t)((high_byte & 0xFF) << 8);

    /* Read low byte */
    uint8_t low_byte = i2cReadByteData(handle, VL53L4CX_REG_DISTANCE_LOW);
    if (low_byte < 0) {
        fprintf(stderr, "Error reading distance low byte: %d\n", rc);
        return -1;
    }
    *distance_mm |= (uint16_t)(low_byte & 0xFF);

    /* Clear interrupt bit */
    if (vl53l4cx_write_reg(handle, VL53L4CX_REG_INTERRUPT_STATUS, 0x00) < 0) {
        fprintf(stderr, "Error clearing interrupt status\n");
        return -1;
    }

    return 0;
}

static void log_distance(uint16_t distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance_mm);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, VL53L4CX_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l4cx_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("VL53L4CX initialized. Starting polling...\n");

    while (running) {
        uint16_t distance_mm;
        if (vl53l4cx_read_distance(i2c_handle, &distance_mm) == 0) {
            log_distance(distance_mm);
        } else {
            fprintf(stderr, "Skipping this cycle due to I2C error\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

