/*
 * VL53L1X Continuous Ranging Trigger with Buzzer Alarm
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO 2 (I2C1 SDA)
 *   VL53L1X SCL -> GPIO 3 (I2C1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Buzzer + -> GPIO 22 (active buzzer)
 *   Buzzer - -> GND
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_buzzer vl53l1x_buzzer.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X constants ---- */
#define VL53L1X_ADDR             0x29
#define VL53L1X_REG_SOFT_RESET   0x0001
#define VL53L1X_REG_I2C_SLAVE_DEV 0x0001
#define VL53L1X_REG_SYSTEM_MODE  0x0007
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0097
#define VL53L1X_REG_RESULT_RANGE_START_BIT 0x0098
#define VL53L1X_REG_RESULT_RANGE_FINAL_STATUS 0x0099
#define VL53L1X_REG_RESULT_RANGE_FINAL_CROSSTALK_CORRECTED_MM 0x0096

#define I2C_BUS 1
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD_MM 100
#define POLL_DELAY_US 500000   /* 500 ms */
#define MAX_RETRIES 3

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register with a single byte write.                    */
/* Returns 0 on success, -1 on error.                                    */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg16(int handle, uint8_t reg, uint16_t val)
{
    if (i2cWriteByteData(handle, reg, (val >> 8) & 0xFF, val & 0xFF) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%04X) failed\n",
                reg, val);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register with a single byte read.                       */
/* Returns 0 on success, -1 on error.                                    */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, v);
        return -1;
    }
    *out = (uint16_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a continuous ranging measurement.                            */
/* Returns 0 on success, -1 on error.                                    */
/* ------------------------------------------------------------------ */
static int vl53l1x_trigger_range(int handle)
{
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE,
                            0x0007) < 0)
        return -1;

    /* Wait for the first measurement to complete (~1.5 ms at 100 kHz). */
    gpioDelay(2000);

    /* Trigger a continuous ranging measurement. */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_RESULT_RANGE_START_BIT,
                            0x00) < 0)
        return -1;

    /* Wait for the first measurement to complete (~1.5 ms at 100 kHz). */
    gpioDelay(2000);

    /* Read the final distance. */
    uint16_t dist;
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM,
                           &dist) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the distance in mm.                                             */
/* Returns 0 on success, -1 on error.                                    */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, int *out)
{
    uint16_t status;
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* Range not ready yet. */
        return 0;
    }

    uint16_t dist;
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_FINAL_STATUS, &dist) < 0)
        return -1;

    if ((dist & 0x01) == 0) {
        /* Range not ready yet. */
        return 0;
    }

    *out = (int)dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Apply the continuous ranging configuration once at startup.       */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset the sensor. */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Set continuous ranging mode. */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE,
                            0x0007) < 0)
        return -1;

    /* Start a single measurement. */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_RESULT_RANGE_START_BIT,
                            0x00) < 0)
        return -1;

    /* Wait for the first measurement to complete. */
    gpioDelay(2000);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Apply the continuous ranging configuration again if re-initialized. */
/* ------------------------------------------------------------------ */
static int vl53l1x_reinit(int handle)
{
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE,
                            0x0007) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources.                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Buzzer GPIO init ---- */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", BUZZER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Initial configuration ---- */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Re-initialization on re-entry ---- */
    if (g_i2c_handle < 0) {
        if (vl53l1x_reinit(g_i2c_handle) < 0) {
            fprintf(stderr, "[FATAL] Re-initialisation failed\n");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("VL53L1X continuous ranging started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int distance;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "[WARN] I2C read error; retrying in 500 ms\n");
            gpioDelay(500000);
            continue;
        }

        printf("Distance: %d mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_MM) {
            printf("[ALERT] Distance below threshold (%d mm). Buzzer ON.\n",
                   distance);
            gpioWrite(BUZZER_GPIO, 1);
        } else {
            printf("[OK] Distance: %d mm\n", distance);
            gpioWrite(BUZZER_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

