    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* Range not ready yet. */
        return 0;
    }

    uint16_t dist;
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_FINAL_STATUS, &dist) < 0)
        return -1;

    if ((dist & 0x01) == 0) {
        /* Range not ready yet. */
        return 0;
    }

    *out = (int)dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Apply the continuous ranging configuration once at startup.       */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset the sensor. */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Set continuous ranging mode. */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE,
                            0x0007) < 0)
        return -1;

    /* Start a single measurement. */
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_RESULT_RANGE_START_BIT,
                            0x00) < 0)
        return -1;

    /* Wait for the first measurement to complete. */
    gpioDelay(2000);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Apply the continuous ranging configuration again if re-initialized. */
/* ------------------------------------------------------------------ */
static int vl53l1x_reinit(int handle)
{
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE,
                            0x0007) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources.                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Buzzer GPIO init ---- */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", BUZZER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Initial configuration ---- */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Re-initialization on re-entry ---- */
    if (g_i2c_handle < 0) {
        if (vl53l1x_reinit(g_i2c_handle) < 0) {
            fprintf(stderr, "[FATAL] Re-initialisation failed\n");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("VL53L1X continuous ranging started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int distance;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "[WARN] I2C read error; retrying in 500 ms\n");
            gpioDelay(500000);
            continue;
        }

        printf("Distance: %d mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_MM) {
            printf("[ALERT] Distance below threshold (%d mm). Buzzer ON.\n",
                   distance);
            gpioWrite(BUZZER_GPIO, 1);
        } else {
            printf("[OK] Distance: %d mm\n", distance);
            gpioWrite(BUZZER_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

