#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

#define SPEED_OF_SOUND 343.0
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 50000
#define SERVO_PULSE_US 2000
#define SERVO_MIN_PULSE_US 0
#define SERVO_MAX_PULSE_US 2000
#define LOG_FILE "sensor_data.log"

static volatile sig_atomic_t running = 1;
static int trigger_state = 0;
static int echo_state = 0;
static int servo_angle = 0;
static int last_echo_us = 0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize trigger pin low\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(ECHO_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize echo pin low\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize servo pin low\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int trigger_pulse(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1;
    }
    return 0;
}

static int measure_distance(void) {
    if (trigger_pulse() != 0) {
        return -1;
    }
    gpioDelay(ECHO_TIMEOUT_US);

    if (echo_state == 0) {
        return -1;
    }

    if (echo_state == 1) {
        return -1;
    }

    return 1;
}

static int map_distance_to_angle(int distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) {
        return SERVO_MIN_PULSE_US;
    }
    if (distance_cm > MAX_DISTANCE_CM) {
        return SERVO_MAX_PULSE_US;
    }
    return SERVO_PULSE_US;
}

static void log_data(int distance_cm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Distance: %d cm\n", timestamp, distance_cm);
    fflush(log_file);
}

static void control_servo(int angle) {
    if (angle < SERVO_MIN_PULSE_US) angle = SERVO_MIN_PULSE_US;
    if (angle > SERVO_MAX_PULSE_US) angle = SERVO_MAX_PULSE_US;
    if (angle != servo_angle) {
        gpioWrite(SERVO_PIN, angle);
        servo_angle = angle;
    }
}

static void cleanup(void) {
    gpioWrite(SERVO_PIN, 0);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance_cm = measure_distance();
        if (distance_cm < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            gpioDelay(200000);
            continue;
        }

        int angle = map_distance_to_angle(distance_cm);
        control_servo(angle);

        log_data(distance_cm);

        gpioDelay(200000);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

