#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/msg.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define VL53L1X_ADDR 0x29
#define I2C_BUS "/dev/i2c-1"
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 50000
#define MAX_DISTANCE_MM 65535

#define REG_MODEL_ID 0x010F
#define REG_SOFT_RESET 0x0000
#define REG_RANGE_CONFIG 0x0080
#define REG_RANGE_STATUS 0x0089
#define REG_RANGE_DATA 0x0096

#define EXPECTED_MODEL_ID 0xEA

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int msg_fd = -1;
static int msg_qid = -1;
static int msg_q_len = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    char buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read word from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_vl53l1x(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_reg(fd, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X)\n", model_id);

    if (i2c_write_reg(fd, REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg(fd, REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(fd, REG_RANGE_CONFIG, 0x0A) != 0) return -1;
    if (i2c_write_reg(fd, REG_RANGE_CONFIG, 0x0C) != 0) return -1;
    if (i2c_write_reg(fd, REG_RANGE_CONFIG, 0x0E) != 0) return -1;
    if (i2c_write_reg(fd, REG_RANGE_CONFIG, 0x0F) != 0) return -1;

    if (i2c_write_reg(fd, REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int read_distance(int fd, uint16_t *distance) {
    uint8_t status = 0;
    if (i2c_read_reg(fd, REG_RANGE_STATUS, &status) != 0) return -1;
    if (!(status & 0x01)) {
        fprintf(stderr, "Range not ready\n");
        return -1;
    }

    uint16_t data = 0;
    if (i2c_read_word(fd, REG_RANGE_DATA, &data) != 0) return -1;

    if (data & 0x8000) {
        data |= 0xFFFF;
    }
    *distance = data;
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
        i2c_fd = -1;
    }
    if (msg_fd >= 0) {
        msg_write(msg_fd, "cleanup", 0);
        close(msg_fd);
        msg_fd = -1;
    }
    if (msg_qid >= 0) {
        msg_write(msg_fd, "cleanup", 0);
        close(msg_fd);
        msg_fd = -1;
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
    }
}

static void msg_write(int fd, const char *message, int len) {
    struct msg_qentry *entry = (struct msg_qentry *)malloc(sizeof(struct msg_qentry));
    if (!entry) {
        fprintf(stderr, "Failed to allocate message queue entry\n");
        return;
    }
    entry->len = len;
    entry->buf = malloc(len + 1);
    if (!entry->buf) {
        fprintf(stderr, "Failed to allocate message queue buffer\n");
        free(entry);
        return;
    }
    memcpy(entry->buf, message, len);
    entry->buf[len] = '\0';

    if (write(fd, entry, sizeof(struct msg_qentry)) != sizeof(struct msg_qentry)) {
        fprintf(stderr, "Failed to write message to message queue: %s\n", strerror(errno));
        free(entry->buf);
        free(entry);
        return;
    }
    free(entry->buf);
    free(entry);
}

static void msg_read(int fd, char *message, int len) {
    struct msg_qentry *entry = (struct msg_qentry *)malloc(sizeof(struct msg_qentry));
    if (!entry) {
        fprintf(stderr, "Failed to allocate message queue entry\n");
        return;
    }
    entry->len = len;
    entry->buf = malloc(len + 1);
    if (!entry->buf) {
        fprintf(stderr, "Failed to allocate message queue buffer\n");
        free(entry);
        return;
    }
    memcpy(entry->buf, message, len);
    entry->buf[len] = '\0';

    if (read(fd, entry->buf, entry->len) != entry->len) {
        fprintf(stderr, "Failed to read message from message queue: %s\n", strerror(errno));
        free(entry->buf);
        free(entry);
        return;
    }
    free(entry->buf);
    free(entry);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L1X_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_fd) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    msg_fd = msg_write(msg_fd, "init_msg", 0);
    if (msg_fd < 0) {
        fprintf(stderr, "Failed to write init message\n");
        cleanup();
        return 1;
    }

    struct msg_qentry *q_entry = (struct msg_qentry *)malloc(sizeof(struct msg_qentry));
    if (!q_entry) {
        fprintf(stderr, "Failed to allocate message queue entry\n");
        cleanup();
        return 1;
    }
    memset(q_entry, 0, sizeof(struct msg_qentry));
    q_entry->len = 0;
    q_entry->buf = NULL;

    struct msg_qid = msg_write(msg_fd, "msg_qid", 0);
    if (msg_fd < 0) {
        fprintf(stderr, "Failed to write msg_qid message\n");
        cleanup();
        return 1;
    }

    struct msg_qentry *q_entry_buf = (struct msg_qentry *)malloc(sizeof(struct msg_qentry));
    if (!q_entry_buf) {
        fprintf(stderr, "Failed to allocate message queue buffer\n");
        cleanup();
        return 1;
    }
    memset(q_entry_buf, 0, sizeof(struct msg_qentry));
    q_entry_buf->len = 0;
