static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    char buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read word from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_vl53l1x(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_reg(fd, REG_MODEL_ID, &model_id) != 0) {
