#define MAX_DISTANCE 400.0
#define MIN_BUZZER_DURATION_US 10000
#define MAX_BUZZER_DURATION_US 2000000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function for echo pin %d.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        uint32_t start_tick = tick;
        uint32_t end_tick = 0;
        while (gpioRead(ECHO_PIN) == 1) {
            if (gpioTick() - start_tick > 1000) {
                fprintf(stderr, "Error: echo pulse timeout (no echo).\n");
                return;
            }
        }
        uint32_t pulse_width = gpioTick() - start_tick;
        float distance = (float)pulse_width * SPEED_OF_SOUND / 2.0;
        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);
    }
}

static int read_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set trigger HIGH.\n");
        return -1;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger LOW.\n");
        return -1;
    }

    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > 1000) {
            fprintf(stderr, "Error: echo timeout.\n");
            return -1;
        }
    }
    uint32_t end_tick = gpioTick();
    uint32_t pulse_width = end_tick - start_tick;

    if (pulse_width <= 0) {
        fprintf(stderr, "Error: invalid pulse width (timeout).\n");
        return -1;
    }

    float distance = (float)pulse_width * SPEED_OF_SOUND / 2.0;
    return (int)distance;
}

static void buzzer_control(int duration_us) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set buzzer HIGH.\n");
        return;
    }
    gpioDelay(duration_us);
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set buzzer LOW.\n");
    }
}

