 *   GND -> GND  (Pin 9)
 *
 * Speed of sound: 0.0343 cm/us (343 m/s)
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SPEED_OF_SOUND   0.0343f   /* cm/us */
#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse */
#define ECHO_TIMEOUT_US  60000       /* 60 ms timeout for no object */
#define MEASURE_INTERVAL_US 200000    /* 200 ms between measurements */
#define LOG_FILE         "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log_file, "%s: %s\n", ts, msg);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* ECHO alert callback                                                 */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    if (level != 1)
        return;

    uint32_t pulse_us = tick - last_trigger_tick;
    if (pulse_us < 0 || pulse_us > TRIGGER_PULSE_US)
        return;

    last_trigger_tick = tick;

    /*
     * HC-SR04 echo pulse is 5 V at the output.
     * pigpio tick wraps every ~72 minutes (32-bit).
     * We subtract the last trigger tick to get the pulse duration
     * in microseconds.
     */
    float duration_us = (float)pulse_us - (float)last_trigger_tick;
    float distance_cm = duration_us * SPEED_OF_SOUND / 2.0f;

    char msg[128];
    snprintf(msg, sizeof(msg),
             "Distance: %.2f cm (pulse=%u us, %s)",
             distance_cm, pulse_us,
             (pulse_us < 100) ? "NO_OBJECT" :
             (pulse_us > 30000) ? "TIMEOUT" :
             "VALID");

    log_message(msg);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error: cannot open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register alert callback on ECHO pin --- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d.\n",
                ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: failed to install signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    /* --- Main measurement loop --- */
    while (g_running) {
        /* Trigger a 10 us pulse */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        /* Wait for echo to go high (rising edge) */
        uint32_t start_tick = gpioTick();
        while (gpioRead(ECHO_PIN) == 0) {
            if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
                log_message("ECHO timeout: no object detected after %d us.",
                            ECHO_TIMEOUT_US);
                gpioDelay(MEASURE_INTERVAL_US);
                continue;
            }
            gpioDelay(10);
        }

        uint32_t end_tick = gpioTick();
        uint32_t pulse_us = end_tick - start_tick;

        /* Validate pulse width */
        if (pulse_us < TRIGGER_PULSE_US || pulse_us > TRIGGER_PULSE_US) {
            log_message("Warning: pulse width %u us out of range (expected %u-%.0f us).",
                        pulse_us, TRIGGER_PULSE_US, TRIGGER_PULSE_US);
        }

        /* Distance = (pulse_us * speed_of_sound) / 2 */
        float distance = (float)pulse_us * SPEED_OF_SOUND / 2.0f;

        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Distance: %.2f cm (pulse=%u us, %s)",
                 distance, pulse_us,
                 (pulse_us < 100) ? "NO_OBJECT" :
                 (pulse_us > 30000) ? "TIMEOUT" :
                 "VALID");

        log_message(msg);

        /* Sleep 200 ms between measurements */
        gpioDelay(MEASURE_INTERVAL_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

