#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US 500000
#define LOG_FILE "gate_events.log"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_init(int handle) {
    /* Soft reset */
    if (i2cWriteByteData(handle, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Configure timing budget: 200 mm / 20 ms = 10 mm/ms */
    if (i2cWriteByteData(handle, 0x0C, 0x0C) < 0) {
        fprintf(stderr, "Error: VL53L1X timing budget write failed\n");
        return -1;
    }

    /* Start ranging */
    if (i2cWriteByteData(handle, 0x0E, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    char buf[2];
    int result;

    /* Read 16-bit distance register (0x00) */
    result = i2cReadI2CBlockData(handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: VL53L1X distance read failed (got %d bytes)\n", result);
        return -1;
    }

    *distance_mm = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 1);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance_mm;
        if (vl53l1x_read_distance(i2c_handle, &distance_mm) == 0) {
            int open_state = (distance_mm >= DISTANCE_THRESHOLD_MM) ? 1 : 0;
            gpioWrite(GPIO_OPEN, open_state);
            log_event(open_state ? "OPEN" : "CLOSE");
        } else {
            fprintf(stderr, "Error: Sensor read failed, retrying...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 1);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

