#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_GPIO 17
#define MOTOR_BACK 17
#define MOTOR_FORWARD 18
#define DISTANCE_THRESHOLD_MM 100
#define MAX_DISTANCE_MM 300
#define I2C_RETRY_DELAY_US 1000
#define I2C_RETRY_MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write_reg(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error: I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *value) {
    char reg_buf[2] = {(reg >> 8) & 0xFF, reg & 0xFF};
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write (reg select) for reg 0x%04X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
