#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TRIGGER_PULSE_US 10
#define LOG_FILE    "distance_log.txt"
#define SAMPLE_PERIOD_US 1000000  /* 1 second */
#define ECHO_MIN_US   58        /* 1 cm */
#define ECHO_MAX_US   25        /* 4 m */
#define ECHO_MIN_PULSE_US 58
#define ECHO_MAX_PULSE_US 25

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* ISR callback: pulse width on EITHER_EDGE (rising or falling)        */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        if (g_log_fp) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            fprintf(g_log_fp, "%s.%06ld - Echo started\n", ts, (long)tick);
            fflush(g_log_fp);
        }
    } else if (level == 0) {
        /* Falling edge: end of echo pulse */
        if (g_log_fp) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            fprintf(g_log_fp, "%s.%06ld - Echo ended\n", ts, (long)tick);
            fflash(g_log_fp);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                 */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable ISR */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);  /* 1 ms settle */

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register ISR --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers.\n");
    }

    /* --- Main measurement loop --- */
    while (g_running) {
        /* Trigger a 10 us pulse */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        /* Wait for echo to be ready (rising edge) */
        int timeout = 0;
        while (gpioRead(ECHO_PIN) == 0 && timeout < SAMPLE_PERIOD_US) {
            gpioDelay(1);
            timeout++;
        }
        if (timeout >= SAMPLE_PERIOD_US) {
            fprintf(stderr, "Warning: echo not ready within %d us.\n", SAMPLE_PERIOD_US);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Read pulse width */
        uint32_t pulse_us = gpioTick();
        int pulse_width = pulse_us - timeout;

        /* Validate pulse width */
        if (pulse_width <= 0 || pulse_width > SAMPLE_PERIOD_US) {
            fprintf(stderr, "Warning: invalid pulse width %u us.\n", pulse_width);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Distance calculation */
        float distance = (float)pulse_us * 343.0f / (2.0f * 1e6);

        /* Append to log file */
        if (fprintf(g_log_fp, "%f m\n", distance) < 0) {
            fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        }
        fflush(g_log_fp);

        /* Tick-wraparound check */
        if (pulse_width > ECHO_MIN_PULSE_US && pulse_width < ECHO_MAX_PULSE_US) {
            /* 1 cm to 4 m */
            if (distance < 1.0f || distance > 4.0f) {
                fprintf(stderr, "Warning: distance %.2f m out of range (1 cm - 4 m).\n", distance);
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Clean shutdown --- */
    cleanup();
    return EXIT_SUCCESS;
}

