#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <string.h>

#define VL53L1X_ADDR          0x29
#define VL53L1X_REG_DIST_LOW  0x0014
#define VL53L1X_REG_DIST_HIGH 0x0015
#define VL53L1X_REG_STATUS    0x0016
#define VL53L1X_REG_CONFIG    0x0018
#define VL53L1X_REG_START     0x0020

#define I2C_BUS              1
#define TRIGGER_GPIO         27
#define LOOP_DELAY_US        100000
#define READ_INTERVAL_US     100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int vl53l1x_write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)value;
    buf[2] = 0x00;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        syslog(LOG_ERR, "I2C write failed to register 0x%04X", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *value)
{
    char reg_buf[2] = { (char)reg, 0x00 };
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        syslog(LOG_ERR, "I2C write (reg select 0x%04X) failed", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        syslog(LOG_ERR, "I2C read failed from register 0x%04X", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle)
{
    if (vl53l1x_write_reg(handle, VL53L1X_REG_CONFIG, 0x01) != 0) {
        syslog(LOG_ERR, "Failed to start VL53L1X");
        return -1;
    }
    if (vl53l1x_write_reg(handle, VL53L1X_REG_START, 0x01) != 0) {
        syslog(LOG_ERR, "Failed to start VL53L1X");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status;
    uint8_t low, high;

    if (vl53l1x_read_reg(handle, VL53L1X_REG_STATUS, &status) != 0)
        return -1;

    if (status & 0x01) {
        syslog(LOG_ERR, "VL53L1X: Status bit set (0x%02X)", status);
        return -1;
    }

    if (vl53l1x_read_reg(handle, VL53L1X_REG_DIST_LOW, &low) != 0)
        return -1;

    if (vl53l1x_read_reg(handle, VL53L1X_REG_DIST_HIGH, &high) != 0)
        return -1;

    *distance_mm = (uint16_t)((high << 8) | low);
    return 0;
}

static int vl53l1x_read_status(int handle, uint8_t *status)
{
    uint8_t buf[1];
    if (vl53l1x_read_reg(handle, VL53L1X_REG_STATUS, buf) != 0)
        return -1;
    *status = buf[0];
    return 0;
}

static void log_message(const char *message)
{
    syslog(LOG_INFO, "%s", message);
}

static void log_error(const char *message)
{
    syslog(LOG_ERR, "%s", message);
}

int main(void)
{
    int ret;

    openlog("vl53l1x_logger", LOG_PID | LOG_CONS, LOG_USER);

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at 0x%02X", VL53L1X_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO27 as output");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_GPIO, 1);
    gpioDelay(100000);
    gpioWrite(TRIGGER_GPIO, 0);

    while (g_running) {
        uint16_t distance;
        uint8_t status;

        if (vl53l1x_read_distance(g_i2c_handle, &distance) != 0) {
            log_error("Failed to read distance");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        uint8_t status_buf[1];
        if (vl53l1x_read_status(g_i2c_handle, status_buf) != 0) {
            log_error("Failed to read status");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        log_message("Distance: %u mm, Status: 0x%02X", distance, status_buf[0]);

        gpioDelay(READ_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully...");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

