#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* VL53L1X I2C address (SA0 tied to GND) */
#define VL53L1X_ADDR 0x29

/* VL53L1X register addresses */
#define VL53L1X_REG_MODEL_ID       0x010F
#define VL53L1X_REG_RANGE_START    0x0015
#define VL53L1X_REG_RANGE_STATUS   0x0016
#define VL53L1X_REG_RESULT_RANGE_MSB 0x0089
#define VL53L1X_REG_RESULT_RANGE_LSB 0x008A

/* GPIO pin for the gate actuator */
#define GATE_PIN 24

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Distance threshold in mm */
#define DISTANCE_THRESHOLD 20.0

/* Log file */
#define LOG_FILE "gate_log.txt"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X initialization                                              */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    /* Read model ID from register 0x010F */
    if (i2c_read_word(handle, VL53L1X_REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    /* Set ranging mode to short (0x00) */
    if (i2c_write_byte(handle, VL53L1X_REG_RANGE_START, 0x00) < 0) {
        fprintf(stderr, "Failed to set ranging mode\n");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_byte(handle, VL53L1X_REG_RANGE_START, 0x01) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t lo, hi;

    if (i2c_read_word(handle, VL53L1X_REG_RESULT_RANGE_MSB, &lo) < 0)
        return -1;
    if (i2c_read_word(handle, VL53L1X_REG_RESULT_RANGE_LSB, &hi) < 0)
        return -1;

    *distance_mm = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int gate_state, float distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Gate: %s, Distance: %.2f mm\n",
            ts, gate_state ? "OPEN" : "CLOSED", distance_mm);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VL53L1X_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure gate pin */
    if (gpioSetMode(GATE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GATE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_PIN, 0);

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance_mm;

        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) < 0) {
            fprintf(stderr, "Sensor read error; retrying in 100 ms\n");
            gpioDelay(100000);
            continue;
        }

        float distance_cm = (float)distance_mm / 10.0f;

        if (distance_cm < DISTANCE_THRESHOLD) {
            printf("Distance: %.2f mm (threshold: %.2f mm)\n",
                   distance_cm, DISTANCE_THRESHOLD);
            if (gpioWrite(GATE_PIN, 1) < 0) {
                fprintf(stderr, "Failed to open gate\n");
            }
        } else {
            printf("Distance: %.2f mm (threshold: %.2f mm)\n",
                   distance_cm, DISTANCE_THRESHOLD);
            if (gpioWrite(GATE_PIN, 0) < 0) {
                fprintf(stderr, "Failed to close gate\n");
            }
        }

        log_data(g_log_file, gpioGetState(GATE_PIN), distance_cm);

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

