#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_ANGLE_MIN 0
#define SERVO_ANGLE_MAX 180
#define SERVO_PULSE_WIDTH_STEP (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)
#define SERVO_TIMEOUT_US 30000
#define SAMPLE_PERIOD_US 100000
#define TRIGGER_DELAY_US 10
#define ECHO_TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_echo(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(TRIGGER_DELAY_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    return 0;
}

static int read_echo_pulse(void) {
    uint32_t start_tick, end_tick, timeout;
    int pulse_width;

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) return -1;
    }
    timeout = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) return -1;
    }
    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    return pulse_width;
}

static float distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    float angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * SERVO_ANGLE_MAX;
    if (angle < SERVO_ANGLE_MIN) angle = SERVO_ANGLE_MIN;
    if (angle > SERVO_ANGLE_MAX) angle = SERVO_ANGLE_MAX;
    return angle;
}

static int map_angle_to_pulse(int angle) {
    if (angle < SERVO_ANGLE_MIN) angle = SERVO_ANGLE_MIN;
    if (angle > SERVO_ANGLE_MAX) angle = SERVO_ANGLE_MAX;
    return (int)((angle - SERVO_ANGLE_MIN) / (SERVO_ANGLE_MAX - SERVO_ANGLE_MIN) * SERVO_PULSE_WIDTH_STEP);
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_ANGLE_MIN) angle = SERVO_ANGLE_MIN;
    if (angle > SERVO_ANGLE_MAX) angle = SERVO_ANGLE_MAX;
    int pulse_width = map_angle_to_pulse(angle);
    if (gpioServo(SERVO_PIN, pulse_width) < 0) return -1;
    return 0;
}

static void log_data(float distance, int angle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, angle, angle);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

