            tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, angle, angle);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

