#include <stdbool.h>

#define VL53L1X_ADDR 0x29
#define LED_PIN 17
#define BUFFER_SIZE 10
#define READ_DELAY_US 50000
#define MAX_DISTANCE_MM 200

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_init(void) {
    /* Default configuration: 1ms conversion time, 1Hz rate, no auto-ranging */
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write default config\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_set_config(void) {
    /* Enable signal rate check */
    if (i2cWriteByteData(i2c_handle, 0x01, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set config\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_set_xtc_comp(void) {
    /* Enable cross-talk compensation */
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set xtc comp\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_start_ranging(void) {
    /* Start ranging */
    if (i2cWriteByteData(i2c_handle, 0x03, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(float *distance_mm) {
    char buf[2];
    int result;

    /* Read 2 bytes of distance data */
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed (got %d bytes)\n", result);
        return -1;
    }

    /* VL53L1X returns distance in millimeters, MSB first */
    *distance_mm = (float)buf[1] << 8 | (float)buf[0];
    return 0;
}

static void buffer_add(CircularBuffer *buf, float value) {
    buf->buffer[buf->head] = value;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) {
        buf->count++;
    }
}

static void buffer_print(const CircularBuffer *buf) {
    int i;
    for (i = 0; i < buf->count; i++) {
        printf("%.2f mm\n", buf->buffer[i]);
    }
}

static void led_set(int state) {
    gpioWrite(LED_PIN, state);
}

static void cleanup(void) {
    led_set(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    CircularBuffer distance_buffer;
    float distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    if (vl53l1x_set_config() != 0) {
        fprintf(stderr, "Error: VL53L1X configuration failed\n");
        cleanup();
        return 1;
    }

    if (vl53l1x_set_xtc_comp() != 0) {
        fprintf(stderr, "Error: VL53L1X xtc comp failed\n");
        cleanup();
        return 1;
    }

    if (vl53l1x_start_ranging() != 0) {
        fprintf(stderr, "Error: VL53L1X ranging start failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    led_set(0);

    signal(SIGINT, signal_handler);

    while (running) {
        if (vl53l1x_read_distance(&distance) == 0) {
            buffer_add(&distance_buffer, distance);
            buffer_print(&distance_buffer);
            if (distance < MAX_DISTANCE_MM) {
                led_set(1);
            } else {
                led_set(0);
            }
        } else {
            fprintf(stderr, "Warning: I2C read error, continuing\n");
        }
        gpioDelay(READ_DELAY_US);
    }

    cleanup();
    return 0;
}

