    int log_file_fd;
} Config;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI1102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", SI1102_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(GPIO_INTERRUPT, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_INTERRUPT);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_INTERRUPT, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", GPIO_INTERRUPT);
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_proximity(int handle, int *proximity) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, 0x08, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }
    *proximity = (buf[1] << 8) | buf[0];
    return 0;
}

static void log_proximity(int proximity, int threshold, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Proximity: %d, Threshold: %d, Status: %s\n",
            timestamp, proximity, threshold, status);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
    fflush(stderr);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)tick;
    (void)user_data;
    if (level == 1) {
        int proximity = 0;
        if (read_proximity(i2c_handle, &proximity) == 0) {
            if (proximity > 0 && proximity > threshold) {
                log_proximity(proximity, DEFAULT_THRESHOLD, "ALERT");
            } else if (proximity < threshold) {
                log_proximity(proximity, DEFAULT_THRESHOLD, "SAFE");
            }
        }
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    Config config = {
        .i2c_address = SI1102_ADDR,
        .threshold = DEFAULT_THRESHOLD,
        .interrupt_pin = GPIO_INTERRUPT,
        .log_file_fd = -1
    };

    if (argc > 1) {
        config.i2c_address = strtol(argv[1], NULL, 0);
    }
    if (argc > 2) {
        config.threshold = strtol(argv[2], NULL, 0);
    }
    if (argc > 3) {
        config.log_file_fd = open(argv[3], O_RDWR | O_CREAT | O_APPEND, 0644);
        if (config.log_file_fd < 0) {
            fprintf(stderr, "Error opening log file '%s': %s\n", argv[3], strerror(errno));
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_log() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(config.interrupt_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", config.interrupt_pin);
        cleanup();
        return 1;
    }

    if (gpioSetPullUpDown(config.interrupt_pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", config.interrupt_pin);
        cleanup();
        return 1;
    }

    if (gpioSetAlertFuncEx(config.interrupt_pin, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for GPIO %d\n", config.interrupt_pin);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

