#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPEAKER_PIN 18
#define TRIGGER_PIN 23
#define ECHO_PIN 24

#define FREQUENCY_MIN 200
#define FREQUENCY_MAX 2000
#define FREQUENCY_STEP (FREQUENCY_MAX - FREQUENCY_MIN) / (200 - FREQUENCY_MIN)
#define PWM_FREQUENCY FREQUENCY_MIN
#define PWM_DUTY_CYCLE 0.5
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 200000
#define SAMPLE_PERIOD_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set speaker pin %d as output.\n", SPEAKER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int trigger_pulse(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set trigger high.\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger low.\n");
        return -1;
    }
    return 0;
}

static int measure_distance(void) {
    if (trigger_pulse() != 0) {
        return -1;
    }

    gpioDelay(ECHO_TIMEOUT_US);

    if (gpioRead(ECHO_PIN) == 0) {
        return -1;
    }

    return 0;
}

static int map_distance_to_frequency(int distance) {
    if (distance < 2) {
        return FREQUENCY_MIN;
    }
    if (distance > 200) {
        return FREQUENCY_MAX;
    }
    return (int)((distance - 2) * FREQUENCY_STEP + FREQUENCY_MIN);
}

static void set_frequency(int frequency) {
    if (frequency < FREQUENCY_MIN) {
        frequency = FREQUENCY_MIN;
    }
    if (frequency > FREQUENCY_MAX) {
        frequency = FREQUENCY_MAX;
    }
    if (gpioPWM(SPEAKER_PIN, frequency) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on pin %d.\n", SPEAKER_PIN);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: distance measurement failed.\n");
            set_frequency(0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int frequency = map_distance_to_frequency(distance);
        if (frequency < 0) {
            fprintf(stderr, "Error: distance out of range.\n");
            set_frequency(0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        set_frequency(frequency);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioPWM(SPEAKER_PIN, 0);
    gpioTerminate();
    printf("Theremin stopped.\n");
    return EXIT_SUCCESS;
}

