#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_FREQ    2000
#define MIN_FREQ    200
#define MAX_FREQ    2000
#define MIN_DIST    5
#define MAX_DIST    50
#define ECHO_TIMEOUT_US 100000  /* 100 ms timeout */
#define LOOP_DELAY_US  10000   /* 10 ms between readings */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns the pulse width in microseconds, or -1 on timeout.
 */
static int measure_echo_pulse(void) {
    uint32_t start_tick, end_tick;
    int pulse_us;

    /* Ensure trigger is low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    gpioDelay(2);

    /* Send 10 us high pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }

    /* Wait for echo to go high */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    pulse_us = end_tick - start_tick;
    return pulse_us;
}

/*
 * Calculate the PWM frequency based on the distance.
 * Returns the PWM frequency in Hz, or -1 on error.
 */
static int calculate_frequency(int distance) {
    if (distance < MIN_DIST) distance = MIN_DIST;
    if (distance > MAX_DIST) distance = MAX_DIST;

    float ratio = (float)(MAX_FREQ - MIN_FREQ) /
                  (float)(MAX_DIST - MIN_DIST);
    float freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * ratio;

    if (freq < MIN_FREQ) freq = MIN_FREQ;
    if (freq > MAX_FREQ) freq = MAX_FREQ;

    return (int)freq;
}

int main(void) {
    int distance;
    int frequency;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, initial low */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure echo pin as input with pull-down */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on echo pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Measure echo pulse width */
        distance = measure_echo_pulse();
        if (distance < 0) {
            fprintf(stderr, "Error: echo measurement failed\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Calculate frequency */
        frequency = calculate_frequency(distance);

        /* Print distance and frequency */
        printf("Distance: %d cm, Frequency: %d Hz\n", distance, frequency);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

