#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 29.1
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 50000
#define POLL_INTERVAL_US 500000

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

int measure_distance(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick, end_tick;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin low during trigger\n");
            return -1;
        }
        gpioDelay(1);
    }

    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin high during echo\n");
            return -1;
        }
        gpioDelay(1);
    }

    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (float)pulse_width / 2.0 / SPEED_OF_SOUND;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance);
        return -1;
    }

