            fprintf(stderr, "Error: Echo pin high during echo\n");
            return -1;
        }
        gpioDelay(1);
    }

    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (float)pulse_width / 2.0 / SPEED_OF_SOUND;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
