#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define SAMPLE_DELAY_US 100000

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    if (gpioWrite(SPI_CS_PIN, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    gpioDelay(100000);
    if (gpioWrite(SPI_CS_PIN, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance_mm) {
    char tx_buf[2] = {0x01, 0x00};
    char rx_buf[2] = {0x0C, 0x0D};
    int ret;

    ret = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(ret));
        return -1;
    }

    *distance_mm = ((uint16_t)(rx_buf[0] & 0xFF) << 8) | (uint16_t)(rx_buf[1] & 0xFF);
    return 0;
}

static int log_distance(uint16_t distance_mm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %u mm\n", timestamp, distance_mm);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() < 0) {
        gpioTerminate();
        return 1;
    }

    if (init_sensor() < 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Obstacle avoidance started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance_mm;
        if (read_distance(&distance_mm) == 0) {
            if (log_distance(distance_mm) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance, continuing...\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    printf("Obstacle avoidance stopped.\n");
    return 0;
}

