#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1120_ADDR          0x60
#define SI1120_REG_PART_ID   0x00
#define SI1120_REG_ALS_LOW   0x22
#define SI1120_REG_ALS_HIGH  0x23
#define SI1120_REG_PS1_LOW   0x18
#define SI1120_REG_PS1_HIGH  0x19
#define SI1120_REG_RESET     0x30
#define SI1120_PART_ID       0x41
#define I2C_BUS              1
#define SAMPLE_INTERVAL_US   500000
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1120_init(int handle) {
    if (i2c_write_reg(handle, SI1120_REG_RESET, 0x01) < 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms reset delay */
    uint8_t part_id = 0;
    if (i2c_read_reg(handle, SI1120_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read Si1120 part ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected Si1120 part ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID);
        return -1;
    }
    return 0;
}

static int read_als_prox(int handle, uint16_t *als, uint16_t *prox) {
    uint8_t low_l, low_h, high_l, high_h;
    if (i2c_read_reg(handle, SI1120_REG_ALS_LOW, &low_l) < 0) return -1;
    if (i2c_read_reg(handle, SI1120_REG_ALS_HIGH, &high_h) < 0) return -1;
    if (i2c_read_reg(handle, SI1120_REG_PS1_LOW, &low_l) < 0) return -1;
    if (i2c_read_reg(handle, SI1120_REG_PS1_HIGH, &high_h) < 0) return -1;
    *als = (uint16_t)((high_h << 8) | low_l);
    *prox = (uint16_t)((high_h << 8) | low_l);
    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t prox) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, ALS=0x%04X, Prox=0x%04X\n", ts, als, prox);
    fflush(fp);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (si1120_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Si1120 initialisation failed\n");
        cleanup();
        return 1;
    }

    g_log_file = fopen("si1120_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Si1120 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als = 0, prox = 0;
        if (read_als_prox(g_i2c_handle, &als, &prox) == 0) {
            log_data(g_log_file, als, prox);
            printf("ALS=0x%04X, Prox=0x%04X\n", als, prox);
        } else {
            fprintf(stderr, "Failed to read sensor data after retries\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

