#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

/* Si1145 I2C address */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define SI1145_REG_HW_KEY   0x07
#define SI1145_REG_MEAS_RATE 0x06
#define SI1145_REG_INT_CFG  0x1A
#define SI1145_REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define SI1145_REG_PS_ADC_COUNTER 0x24
#define SI1145_REG_PS_LED21 0x0B
#define SI1145_REG_PS_LED3 0x0F
#define SI1145_REG_PS_ADC_GAIN 0x03
#define SI1145_REG_PS_FORCE 0x03
#define SI1145_REG_COMMAND 0x80
#define SI1145_REG_PS1_DATA0 0x16
#define SI1145_REG_PS1_DATA1 0x17

/* Commands */
#define SI1145_CMD_PS_FORCE 0x03

/* Expected values for clear register */
#define SI1145_EXPECTED_PS1_DATA0 0x00
#define SI1145_EXPECTED_PS1_DATA1 0x00

/* Expected values for clear register */
#define SI1145_EXPECTED_PS_LED21 0x00
#define SI1145_EXPECTED_PS_LED3 0x00

/* Expected values for clear register */
#define SI1145_EXPECTED_PS_ADC_GAIN 0x00

/* Expected values for clear register */
#define SI1145_EXPECTED_COMMAND 0x00

/* Retry count */
#define MAX_RETRIES 3

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Log file */
#define LOG_FILE "proximity_log.txt"

/* Global state */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to a Si1145 register                                    */
/* Returns 0 on success, -1 on failure                                */
/* ------------------------------------------------------------------ */
static int si1145_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a byte from a Si1145 register                                  */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int si1145_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1145 sensor                                          */
/* Returns 0 on success, -1 on failure                                  */
/* ------------------------------------------------------------------ */
static int si1145_init(void)
{
    /* Clear any previous state */
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_EXPECTED_COMMAND) < 0)
        return -1;

    /* Clear any previous state */
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_EXPECTED_COMMAND) < 0)
        return -1;

    /* Set measurement rate to 2 ms (0x02) */
    if (si1145_write_reg(SI1145_REG_MEAS_RATE, 0x02) < 0)
        return -1;

    /* Disable interrupts (0x00) */
    if (si1145_write_reg(SI1145_REG_INT_CFG, 0x00) < 0)
        return -1;

    /* Set ALS_VIS_IR_ADC_COUNTER to 16-bit (0x0B) */
    if (si1145_write_reg(SI1145_REG_ALS_VIS_IR_ADC_COUNTER, 0x0B) < 0)
        return -1;

    /* Set PS_ADC_COUNTER to 16-bit (0x0D) */
    if (si1145_write_reg(SI1145_REG_PS_ADC_COUNTER, 0x0D) < 0)
        return -1;

    /* Set PS_LED21 to 180 mA (0x0F) */
    if (si1145_write_reg(SI1145_REG_PS_LED21, 0x0F) < 0)
        return -1;

    /* Set PS_LED3 to 180 mA (0x03) */
    if (si1145_write_reg(SI1145_REG_PS_LED3, 0x03) < 0)
        return -1;

    /* Set PS_ADC_GAIN to 7.7x (0x03) */
    if (si1145_write_reg(SI1145_REG_PS_ADC_GAIN, 0x03) < 0)
        return -1;

    /* Set PS_FORCE to force PS1 (0x03) */
    if (si1145_write_reg(SI1145_REG_PS_FORCE, 0x03) < 0)
        return -1;

    /* Set measurement rate to 2 ms (0x02) */
    if (si1145_write_reg(SI1145_REG_MEAS_RATE, 0x02) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read proximity data from the Si1145 sensor                            */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int si1145_read_proximity(uint16_t *proximity)
{
    uint8_t low, high;

    if (si1145_read_reg(SI1145_REG_PS1_DATA0, &low) < 0)
        return -1;
    if (si1145_read_reg(SI1145_REG_PS1_DATA1, &high) < 0)
        return -1;

    *proximity = (uint16_t)((high << 8) | low);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                         */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int log_proximity(uint16_t proximity)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %u\n", timestamp, proximity) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1145 sensor */
    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write a timestamp to the log file */
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        cleanup();
        return EXIT_FAILURE;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    /* Write the timestamp to the log file */
    if (fprintf(log_file, "%s, ERROR\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    /* Main loop */
    while (program_running) {
        uint16_t proximity;

        if (si1145_read_proximity(&proximity) < 0) {
            fprintf(stderr, "Error reading proximity data\n");
            /* Retry on failure */
            for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
                if (program_running) {
                    gpioDelay(100000); /* 100 ms */
                }
                if (si1145_read_proximity(&proximity) < 0) {
                    fprintf(stderr, "Retry %d/%d\n", attempt, MAX_RETRIES);
                    gpioDelay(100000); /* 100 ms */
                } else {
                    break;
                }
            }
            continue;
        }

        if (log_proximity(proximity) < 0) {
            fprintf(stderr, "Error logging proximity data\n");
        }

        gpioDelay(2000000); /* 2 ms */
    }

    /* Cleanup */
    cleanup();
    return EXIT_SUCCESS;
}

