#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define MAX_DISTANCE_CM 200.0
#define MIN_DISTANCE_CM 110.0
#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define SERVO_PULSE_STEP_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to trigger sensor\n");
        return -1;
    }
    gpioDelay(2);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to reset trigger\n");
        return -1;
    }

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > 100) {
            fprintf(stderr, "Error: echo timeout (sensor not responding)\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    if (gpioRead(ECHO_PIN) == 1) {
        start_tick = gpioTick();
    }

    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > 100) {
            fprintf(stderr, "Error: echo timeout (sensor not responding)\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    if (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
    }

    uint32_t pulse_duration = end_tick - start_tick;
    if (pulse_duration == 0) {
        fprintf(stderr, "Error: echo timeout (sensor not responding)\n");
        return -1.0;
    }

    float distance = (float)pulse_duration * 0.034 / 2.0;
    return distance;
}

static void set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    int pulse_us = (int)((float)angle * SERVO_PULSE_STEP_US / SERVO_MAX_ANGLE);
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Error: failed to set servo pulse\n");
    }
}

static void rotate_servo(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    set_servo_angle(angle);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Parking Assist System\n");
    printf("Trigger: GPIO%d, Echo: GPIO%d, Servo: GPIO%d\n", TRIGGER_PIN, ECHO_PIN, SERVO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Error: distance measurement failed\n");
            break;
        }

        int angle = (int)(distance * 100.0 / MAX_DISTANCE_CM);
        if (angle < 0) angle = 0;
        if (angle > 180) angle = 180;

        printf("Distance: %.2f cm, Servo Angle: %d degrees\n", distance, angle);
        rotate_servo(angle);
        gpioDelay(100000);
    }

    set_servo_angle(SERVO_MIN_ANGLE);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

