#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define GATE_THRESHOLD_CLOSED 200
#define GATE_THRESHOLD_OPEN 250
#define SERVO_OPEN_US 2000
#define SERVO_CLOSED_US 1000
#define POLL_INTERVAL_US 100000
#define LOG_FILE "gate_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2cReadByteData(handle, 0x010F) < 0) {
        fprintf(stderr, "Error: Failed to read model ID from VL53L1X.\n");
        return -1;
    }
    model_id = (uint8_t)model_id;
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    if (i2cWriteByteData(handle, 0x0081, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set timing budget.\n");
        return -1;
    }

    if (i2cWriteByteData(handle, 0x0081, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, 0x0088, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }
    *distance_mm = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static void control_gate(int state) {
    if (gpioServo(SERVO_PIN, state ? SERVO_OPEN_US : SERVO_CLOSED_US) < 0) {
        fprintf(stderr, "Error: Failed to set servo position.\n");
    }
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X.\n", VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioServo(SERVO_PIN, SERVO_CLOSED_US);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Error: Failed to read distance data.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (distance == 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (distance > GATE_THRESHOLD_CLOSED && distance < GATE_THRESHOLD_OPEN) {
            control_gate(1);
            log_event("Object detected at 200 mm");
        } else if (distance > GATE_THRESHOLD_OPEN && distance < GATE_THRESHOLD_CLOSED) {
            control_gate(0);
            log_event("Object detected at 250 mm");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_gate(0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

