    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Error: Failed to read distance data.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (distance == 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (distance > GATE_THRESHOLD_CLOSED && distance < GATE_THRESHOLD_OPEN) {
            control_gate(1);
            log_event("Object detected at 200 mm");
        } else if (distance > GATE_THRESHOLD_OPEN && distance < GATE_THRESHOLD_CLOSED) {
            control_gate(0);
            log_event("Object detected at 250 mm");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_gate(0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

