#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 343.0
#define MIN_DISTANCE 20.0
#define MAX_DISTANCE 200.0
#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define TRIGGER_PULSE_US 10
#define TIMEOUT_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioServo(SERVO_PIN, SERVO_MIN_PULSE_US) != 0) {
        fprintf(stderr, "Error: failed to initialise servo on GPIO %d\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN low\n");
        return -1;
    }
    return 0;
}

static int read_echo_pulse(void) {
    uint32_t start_tick, end_tick;
    uint32_t pulse_us;

    if (gpioRead(ECHO_PIN) != 0) {
        fprintf(stderr, "Error: failed to read ECHO_PIN\n");
        return -1;
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    pulse_us = end_tick - start_tick;
    return pulse_us;
}

static float calculate_distance(int pulse_us) {
    if (pulse_us <= 0) {
        return -1.0;
    }
    return (float)pulse_us * SPEED_OF_SOUND / 2000000.0;
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_us = SERVO_MIN_PULSE_US + (int)((float)angle * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) / 180.0);
    gpioServo(SERVO_PIN, pulse_us);
}

static void print_distance_angle(float distance, int angle) {
    if (distance < 0.0) {
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
    } else {
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Parking Assist System\n");
    printf("Trigger: GPIO%d, Echo: GPIO%d, Servo: GPIO%d\n", TRIGGER_PIN, ECHO_PIN, SERVO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor() != 0) {
            gpioServo(SERVO_PIN, 0);
            gpioTerminate();
            return 1;
        }

        int pulse_us = read_echo_pulse();
        if (pulse_us < 0) {
            gpioServo(SERVO_PIN, 0);
            gpioTerminate();
            return 1;
        }

        float distance = calculate_distance(pulse_us);
        int angle = (int)((distance / MIN_DISTANCE) * 180.0);
        if (angle < 0) angle = 0;
        if (angle > 180) angle = 180;

        set_servo_angle(angle);
        print_distance_angle(distance, angle);

        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

