#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define I2C_BUS 1
#define CONVERSION_DELAY_MS 10

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int init_si7005(void) {
    if (i2c_write_reg(CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure Si7005\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms conversion delay */
    return 0;
}

static int read_si7005(float *temperature, float *humidity) {
    uint8_t raw_temp, raw_hum;

    if (i2c_read_reg(TEMP_REG, &raw_temp) < 0) return -1;
    if (i2c_read_reg(HUMID_REG, &raw_hum) < 0) return -1;

    int16_t raw_temp_16 = (int16_t)((raw_temp & 0x0F) | ((raw_temp >> 4) & 0xF0));
    int16_t raw_hum_16 = (int16_t)((raw_hum & 0x0F) | ((raw_hum >> 4) & 0xF0));

    *temperature = (175.72f * raw_temp_16) / 65536.0f - 46.85f;
    *humidity = (125.0f * raw_hum_16) / 65536.0f - 6.0f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI7005_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si7005() < 0) {
        fprintf(stderr, "Si7005 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        float temperature, humidity;
        if (read_si7005(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(2);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

