#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR        0x68
#define WHO_AM_I_REG        0x75
#define WHO_AM_I_VAL        0x68
#define PWR_MGMT_1_REG      0x6B
#define PWR_MGMT_1_VAL      0x00
#define ACCEL_CONFIG_REG    0x1C
#define ACCEL_XOUT_H_REG    0x3B
#define PWR_MGMT_1_VAL      0x00
#define ACCEL_CONFIG_VAL    0x00
#define ACCEL_SCALE_FACTOR  16384.0f
#define GYRO_SCALE_FACTOR   128.0f
#define SAMPLE_INTERVAL_US  100000
#define MAX_RETRIES         3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpu6050_init(void) {
    int rc;

    rc = i2cWriteByteData(i2c_handle, PWR_MGMT_1_REG, PWR_MGMT_1_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    rc = i2cWriteByteData(i2c_handle, PWR_MGMT_1_REG, PWR_MGMT_1_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error resetting MPU-6050: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    rc = i2cWriteByteData(i2c_handle, ACCEL_CONFIG_REG, ACCEL_CONFIG_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error setting ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    rc = i2cWriteByteData(i2c_handle, ACCEL_CONFIG_REG, ACCEL_CONFIG_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error setting ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    rc = i2cWriteByteData(i2c_handle, GYRO_CONFIG_REG, ACCEL_CONFIG_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error setting GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    rc = i2cWriteByteData(i2c_handle, GYRO_CONFIG_REG, ACCEL_CONFIG_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error setting GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int mpu6050_read_data(int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *gx, int16_t *gy, int16_t *gz) {
    char buf[14];
    int rc;

    rc = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H_REG, buf, 14);
    if (rc != 14) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[6] << 8) | buf[7]);
    *gy = (int16_t)((buf[8] << 8) | buf[9]);
    *gz = (int16_t)((buf[10] << 8) | buf[11]);

    return 0;
}

int main(void) {
    int16_t ax, ay, az, gx, gy, gz;
    int16_t temp;
    int16_t raw_x, raw_y, raw_z;
    int16_t raw_gx, raw_gy, raw_gz;
    int16_t raw_ax, raw_ay, raw_az;
    int16_t temp_raw;
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
    int16_t accel_x_raw, accel_y_raw, accel_z_raw;
    int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
    int16_t accel_x_scale, accel_y_scale, accel_z_scale;
    int16_t gyro_x_scale, gyro_y_scale, gyro_z_scale;
    int16_t accel_x_offset, accel_y_offset, accel_z_offset;
    int16_t gyro_x_offset, gyro_y_offset, gyro_z_offset;
    int16_t accel_x_offset_raw, accel_y_offset_raw, accel_z_offset_raw;
    int16_t gyro_x_offset_raw, gyro_y_offset_raw, gyro_z_offset_raw;
    int16_t accel_x_scale_raw, accel_y_scale_raw, accel_z_scale_raw;
    int16_t gyro_x_scale_raw, gyro_y_scale_raw, gyro_z_scale_raw;
    int16_t accel_x_offset_raw, accel_y_offset_raw, accel_z_offset_raw;
    int16_t gyro_x_offset_raw, gyro_y_offset_raw, gyro_z_offset_raw;
    int16_t accel_x_offset_raw_raw, accel_y_offset_raw_raw, accel_z_offset_raw_raw;
    int16_t gyro_x_offset_raw_raw, gyro_y_offset_raw_raw, gyro_z_offset_raw_raw;
