static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpu6050_init(void) {
    int rc;

    rc = i2cWriteByteData(i2c_handle, PWR_MGMT_1_REG, PWR_MGMT_1_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    rc = i2cWriteByteData(i2c_handle, PWR_MGMT_1_REG, PWR_MGMT_1_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error resetting MPU-6050: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    rc = i2cWriteByteData(i2c_handle, ACCEL_CONFIG_REG, ACCEL_CONFIG_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error setting ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    rc = i2cWriteByteData(i2c_handle, ACCEL_CONFIG_REG, ACCEL_CONFIG_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error setting ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    rc = i2cWriteByteData(i2c_handle, GYRO_CONFIG_REG, ACCEL_CONFIG_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error setting GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    rc = i2cWriteByteData(i2c_handle, GYRO_CONFIG_REG, ACCEL_CONFIG_VAL);
    if (rc < 0) {
        fprintf(stderr, "Error setting GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

