#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SHT40_ADDR          0x44
#define I2C_BUS             1
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define MEASURE_DELAY_US     10000
#define LOG_INTERVAL_S       5
#define MAX_RETRIES          3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by the SHT40: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sht40_read(float *temperature, float *humidity)
{
    uint8_t cmd[2] = { (uint8_t)(MEASURE_HIGH_REPEATABILITY >> 8),
                       (uint8_t)(MEASURE_HIGH_REPEATABILITY & 0xFF) };
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x%02X)\n", MEASURE_HIGH_REPEATABILITY);
        return -1;
    }

    /* Wait for measurement to complete (datasheet: ~10 ms for high-repeatability) */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed (expected 6 bytes)\n");
        return -1;
    }

    /* Validate CRC for temperature */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for humidity */
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_t = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_h = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *humidity   = -6.0f + 125.0f * (float)raw_h / 65535.0f;

    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

static void log_data(float temperature, float humidity)
{
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SHT40_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT40 temperature/humidity logging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (sht40_read(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Warning: SHT40 read failed; re-opening I2C bus.\n");
            if (i2cClose(g_i2c_handle) != 0) {
                fprintf(stderr, "Error: i2cClose failed: %d\n", errno);
            }
            g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Error: i2cOpen failed after re-open: %d\n", errno);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < LOG_INTERVAL_S * 10 && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

