#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP810_ADDR 0x25
#define I2C_BUS 1
#define LOG_FILE "pressure_log.csv"
#define POLL_INTERVAL_US 1000000
#define CMD_CONT_MEAS 0x36
#define CMD_MEAS_WAIT_US 1000
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sensor_data(uint8_t *data) {
    if (i2cWriteByte(i2c_handle, CMD_CONT_MEAS) < 0) {
        fprintf(stderr, "Error: Failed to send continuous measurement command\n");
        return -1;
    }
    gpioDelay(CMD_MEAS_WAIT_US);

    char buf[9];
    if (i2cReadDevice(i2c_handle, buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from sensor\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Differential pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Error: Scale factor CRC mismatch\n");
        return -1;
    }

    uint16_t raw_dp = (buf[0] << 8) | buf[1];
    uint16_t raw_temp = (buf[3] << 8) | buf[4];
    uint16_t scale_dp = (buf[6] << 8) | buf[7];

    return (int)raw_dp | (int)raw_temp | (int)scale_dp;
}

static void log_data(FILE *fp, int16_t dp, int16_t temp) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2fPa,%.2fC\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            (float)dp / 100.0f, (float)temp / 100.0f);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X (handle=%d)\n",
                SDP810_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error: Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(fp, "Timestamp,Differential Pressure (Pa),Temperature (C)\n");
    fflush(fp);

    while (running) {
        uint8_t data[9];
        int16_t dp, temp;

        if (read_sensor_data(data) == 0) {
            dp = (int16_t)data[0] | (int16_t)data[1] << 8;
            temp = (int16_t)data[3] | (int16_t)data[4] << 8;
            log_data(fp, dp, temp);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

