#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x44
#define MEASURE_CMD    0xFD
#define MEASURE_DELAY_MS 10
#define LOG_INTERVAL_S 5
#define LOG_FILE       "sht40_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    uint8_t buf[2] = { cmd, 0x00 };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int sht40_init(int fd) {
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        return -1;
    }
    usleep(MEASURE_DELAY_MS * 1000);
    return 0;
}

static int sht40_read(int fd, float *temp, float *rh) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0) {
        return -1;
    }

    /* SHT40: 6 bytes, 2 MSB, 4 LSB, CRC */
    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    int16_t raw_t = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_h = (int16_t)((buf[3] << 8) | buf[4]);

    *temp = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *rh   = 100.0f * (float)raw_h / 65535.0f;
    return 0;
}

static void log_data(float temp, float rh) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(g_log_fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            ts, temp, rh);
    fflush(g_log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SHT40_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (sht40_init(g_i2c_fd) < 0) {
        fprintf(stderr, "SHT40 initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Smart greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, LOG_INTERVAL_S);

    while (g_running) {
        float temp, rh;
        if (sht40_read(g_i2c_fd, &temp, &rh) == 0) {
            log_data(temp, rh);
        } else {
            fprintf(stderr, "Sensor read failed; retrying next cycle\n");
        }
        sleep(LOG_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

