#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define MEASURE_CMD_MSB 0x21
#define MEASURE_CMD_LSB 0x96
#define MEASURE_DELAY_US 1000
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", SDP31_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sdp31(float *pressure, float *temperature) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d/%d): %d\n", retries + 1, MAX_RETRIES, i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(MEASURE_DELAY_US);

        int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (bytes_read != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d): read %d bytes\n", retries + 1, MAX_RETRIES, bytes_read);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_pressure = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t raw_temperature = ((uint16_t)buf[3] << 8) | buf[4];

        *pressure = (float)raw_pressure / 60.0f;
        *temperature = (float)raw_temperature / 200.0f;
        return 0;
    }

    fprintf(stderr, "Failed to read SDP31 after %d retries\n", MAX_RETRIES);
    return -1;
}

static int log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    while (!terminate) {
        float pressure, temperature;
        if (read_sdp31(&pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

