    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one raw measurement from the Si7015                             */
/* Returns 0 on success, -1 on error.                                   */
/* ------------------------------------------------------------------ */
static int read_raw_measurement(int handle, uint8_t cmd, int16_t *raw_out)
{
    char buf[2];
    int rc;

    /* Write command to the Si7015 */
    rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "I2C write command 0x%02X failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }

    /* Poll for measurement ready */
    for (int i = 0; i < MEASURE_DELAY_US; i += 10) {
        rc = i2cReadDevice(handle, buf, 2);
        if (rc < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (rc == 2) {
            /* Si7015 returns 2 bytes: MSB first */
            *raw_out = (int16_t)((uint16_t)buf[0] << 8 | (uint8_t)buf[1]);
            return 0;
        }
    }

