#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define CMD_CONT_MEAS  0x362F
#define MEAS_DELAY_MS  45
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_cmd(fd, CMD_CONT_MEAS) < 0) {
        fprintf(stderr, "Failed to trigger continuous measurement\n");
        return -1;
    }
    usleep(MEAS_DELAY_MS * 1000);
    return 0;
}

static int read_sensor(int fd, float *pressure, float *temperature) {
    uint8_t buf[9];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Pressure: 3 bytes, CRC-8, big-endian */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    uint16_t pressure_raw = ((uint16_t)buf[0] << 8) | buf[1];
    *pressure = pressure_raw / (float)SCALE_FACTOR;

    /* Temperature: 3 bytes, CRC-8, big-endian */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    *temperature = temp_raw / 200.0f - 45.0f;

    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log, "# Ventilation system monitoring started\n");
    fflush(g_log);

    while (g_running) {
        float pressure, temperature;
        if (read_sensor(g_fd, &pressure, &temperature) == 0) {
            if (log_data(g_log, pressure, temperature) < 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    fprintf(stderr, "Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

