        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature) {
    uint8_t cmd[2] = { (uint8_t)(CMD_CONT_MEAS >> 8), (uint8_t)(CMD_CONT_MEAS & 0xFF) };
    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t buf[6];
    if (i2c_read_data(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure = (float)raw_pressure / 240.0f;
    *temperature = (float)raw_temperature / 200.0f - 45.0f;
    return 0;
}

static int log_data(float pressure, float temperature, const char *timestamp) {
    if (!log_fp) {
        log_fp = fopen(LOG_FILE, "a");
        if (!log_fp) {
            perror("Failed to open log file");
            return -1;
        }
    }
    if (fprintf(log_fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    uint8_t sensor_id;
    if (i2c_read_data(fd, &sensor_id, 1) < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        close(fd);
        return 1;
    }
    if (sensor_id != 0x00) {
        fprintf(stderr, "Sensor not found (ID 0x%02X)\n", sensor_id);
        close(fd);
        return 1;
    }

    while (running) {
        float pressure, temperature;
        if (read_sdp800(fd, &pressure, &temperature) == 0) {
            if (log_data(pressure, temperature, NULL) < 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }
        sleep(1);
    }

    if (fd >= 0)
        close(fd);
    if (log_fp)
        fclose(log_fp);
    return 0;
}

