#define FAN_GPIO 18
#define TEMP_THRESHOLD 28.0
#define HUM_THRESHOLD 27.0
#define BUFFER_SIZE 60
#define MEASURE_DELAY_US 10000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_si7021(int handle, float *temperature, float *humidity) {
    char cmd[2] = {0xE3, 0xE5};
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, cmd, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, i2cWriteDevice(handle, cmd, 2));
            retries++;
            gpioDelay(MEASURE_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, buf, 2) != 2) {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, i2cReadDevice(handle, buf, 2));
            retries++;
            gpioDelay(MEASURE_DELAY_US);
            continue;
        }

        uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        uint16_t raw_hum = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

        *temperature = 175.72f * (float)raw_temp / 65536.0f - 46.85f;
        *humidity = 125.0f * (float)raw_hum / 65536.0f - 6.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
    return -1;
}

