#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_ADDR          0x62
#define I2C_BUS             1
#define MEASUREMENT_CMD     0x21B1
#define DATA_READY_FLAG     0xE4B8
#define MEASUREMENT_DELAY   1000   /* microseconds */
#define POLL_DELAY_US       100000 /* microseconds */
#define LOG_FILE            "air_quality.log"
#define CO2_THRESHOLD       1000.0f
#define FLUSH_INTERVAL_S    5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ---- CRC-8 (Sensirion: polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- SCD40 command ---- */
static int scd40_send_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (cmd=0x%04X): %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* ---- Read one measurement ---- */
static int scd40_read_measurement(int handle, float *co2, float *temp, float *hum)
{
    uint8_t buf[9];
    int rc = i2cReadDevice(handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 9): %d\n", rc, rc);
        return -1;
    }

    /* Verify data-ready flag */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on data-ready flag (0x%02X)\n", buf[2]);
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] CRC mismatch on CO2 (0x%02X)\n", buf[5]);
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] CRC mismatch on humidity (0x%02X)\n", buf[8]);
        return -1;
    }

    /* CO2: raw value, no CRC */
    uint16_t co2_raw = ((uint16_t)buf[0] << 8) | buf[1];
    *co2 = (float)co2_raw / (2u << 16u);

    /* Temperature: raw value, no CRC */
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    *temp = (float)temp_raw / (2u << 16u);

    /* Humidity: raw value, no CRC */
    uint16_t hum_raw = ((uint16_t)buf[6] << 8) | buf[7];
    *hum = (float)hum_raw / (2u << 16u);

    return 0;
}

/* ---- Flush data immediately ---- */
static void flush_data(float co2, float temp, float hum)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_file, "%s,%.2f,%.2f,%.2f\n", ts, co2, temp, hum);
    fflush(g_log_file);
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd40_send_cmd(g_i2c_handle, MEASUREMENT_CMD);
        gpioDelay(MEASUREMENT_DELAY);
        scd40_send_cmd(g_i2c_handle, 0x3F86);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at SCD40 address */
    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, SCD40_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,CO2_ppm,Temperature_C,Humidity_pct\n");
        fflush(g_log_file);
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Start periodic measurement */
    if (scd40_send_cmd(g_i2c_handle, MEASUREMENT_CMD) != 0) {
        fprintf(stderr, "[FATAL] Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SCD40 monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        /* Wait for data-ready flag */
        int ready = 0;
        while (ready == 0 && g_running) {
            gpioDelay(POLL_DELAY_US);
            if (!g_running) break;
            ready = scd40_read_measurement(g_i2c_handle, &co2, &temp, &hum);
            if (ready < 0) break;
            if (ready == 1) ready = scd40_read_measurement(g_i2c_handle, &co2, &temp, &hum);
        }

        if (!g_running) break;

        /* Flush data immediately */
        flush_data(co2, temp, hum);

        /* Sleep for the next measurement interval */
        gpioDelay(MEASUREMENT_DELAY);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

