#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_ADDR          0x62
#define I2C_BUS             1
#define LED_GPIO            17
#define CO2_THRESHOLD_PPM   1000
#define BUFFER_SIZE         20
#define MEASUREMENT_INTERVAL_S 5

/* SCD40 command/response codes */
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT  0x3F86
#define CMD_GET_DATA_READY_STATUS     0xE4B8
#define CMD_READ_MEASUREMENT          0xEC05

/* CRC-8 polynomial 0x31, init 0xFF (Sensirion default) */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;
static int circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_full = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF)                             */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* SCD40 helpers                                                       */
/* ------------------------------------------------------------------ */
static int scd40_write_cmd(uint8_t cmd)
{
    if (i2cWriteByteData(i2c_handle, 0x00, cmd) < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X)\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_data(uint8_t *buf, int len)
{
    if (i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buf, len) != len) {
        fprintf(stderr, "I2C read failed (got %d bytes, expected %d)\n",
                len, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SCD40 measurement                                                   */
/* ------------------------------------------------------------------ */
static int scd40_read_measurement(uint8_t *buf)
{
    if (scd40_write_cmd(CMD_READ_MEASUREMENT) < 0)
        return -1;

    gpioDelay(10000); /* 10 ms settle */

    if (scd40_read_data(buf, 9) < 0)
        return -1;

    /* Validate data-ready status (bit 0 of status register) */
    if (buf[0] & 0x01) {
        fprintf(stderr, "SCD40 data-ready status 0x%02X not set\n", buf[0]);
        return -1;
    }

    /* Read CO2, temperature, and humidity */
    uint8_t data[3];
    if (scd40_read_data(data, 3) < 0)
        return -1;

    /* CRC-8 checksum on each 2-byte data word */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CO2 CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[1], 2) != data[3]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[4], 2) != data[6]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    /* Validate CRC-8 checksum on each 2-byte data word */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CO2 CRC mismatch (word 0)\n");
        return -1;
    }
    if (crc8(&data[1], 2) != data[3]) {
        fprintf(stderr, "Temperature CRC mismatch (word 1)\n");
        return -1;
    }
    if (crc8(&data[4], 2) != data[6]) {
        fprintf(stderr, "Humidity CRC mismatch (word 2)\n");
        return -1;
    }

    /* Combine data into a single 32-bit value */
    uint32_t raw = ((uint32_t)data[0] << 24) |
                   ((uint32_t)data[1] << 16) |
                   ((uint32_t)data[2] << 8)  |
                   ((uint32_t)data[3]);

    /* Convert to physical units */
    int co2 = (int)(raw / 10);
    int temp = (int)(raw / 100);
    int hum = (int)(raw / 1000);

    /* Sanity checks */
    if (co2 < 0 || co2 > 999 || temp < -40 || temp > 85) {
        fprintf(stderr, "Invalid CO2 or temperature reading: %d, %d\n",
                co2, temp);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
static void add_reading(int co2, int temp, int hum)
{
    circular_buffer[buffer_index] =
        (struct { int co2, temp, hum; })
        { co2, temp, hum };
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_full)
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void)
{
    int idx = (buffer_index + 1) % BUFFER_SIZE;
    printf("CO2: %d ppm, Temp: %d C, Hum: %d %%\n",
           circular_buffer[idx].co2,
           circular_buffer[idx].temp,
           circular_buffer[idx].hum);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        scd40_write_cmd(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, SCD40_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SCD40 CO2 monitor started. Press Ctrl+C to exit.\n");

    /* Main measurement loop */
    while (!terminate) {
        int co2 = -1;
        int temp = -1;
        int hum = -1;

        if (scd40_read_measurement(&co2) < 0) {
            fprintf(stderr, "Measurement failed; continuing\n");
        } else {
            add_reading(co2, temp, hum);
            printf("CO2: %d ppm, Temp: %d C, Hum: %d %%\n",
                   co2, temp, hum);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < MEASUREMENT_INTERVAL_S * 10 && !terminate; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

