static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature from TMP05 using busy-wait polling.
 * Returns 0 on success, -1 on timeout, -2 on sensor-absent/stuck.
 */
static int read_temperature(int gpio_pin)
{
    uint32_t start_tick, end_tick;
    uint32_t high_us, low_us;
    int high_count, low_count;

    /*
     * TMP05 outputs a PWM-style signal where the ratio of high-time to
     * total-cycle-time encodes the temperature. We measure the high
     * pulse width (TH) and total cycle width (TL) directly.
     *
     * The TMP05 datasheet provides a conversion formula:
     *   Temperature = 4215 - (2143 * TH / TL)
     * We use the raw high-count (TH) and total-cycle-count (TL)
     * directly, without dividing by TL.
     */

    /*
     * Wait for a rising edge with a timeout.
     * gpioTick() returns the number of microseconds since the pigpio
     * start, so we subtract the previous tick to get the elapsed time.
     */
    start_tick = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1;  /* Timeout waiting for rising edge */
        }
    }
    high_us = gpioTick() - start_tick;

    /*
     * Wait for a falling edge with a timeout.
     * gpioTick() returns the number of microseconds since the pigpio
     * start, so we subtract the previous tick to get the elapsed time.
     */
    start_tick = gpioTick();
    while (gpioRead(gpio_pin) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1;  /* Timeout waiting for falling edge */
        }
    }
    low_us = gpioTick() - start_tick;

    /*
     * Measure the high-count (TH) and total-cycle-count (TL)
     * directly without dividing by TL.
     */
    high_count = high_us / MIN_TH_US;
    low_count = low_us / MIN_TL_US;

    /*
     * Convert to temperature.
     * TMP05 datasheet:
     *   TH = raw high-count / (1 us / 1 us)
     *   TL = raw total-cycle-count / (1 us / 1 us)
     *   Temperature = 4215 - (2143 * TH / TL)
     */
    float temperature = 4215.0f - (2143.0f * high_count / low_count);

    /*
     * Sanity-check: temperature outside valid range.
     */
    if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
        return -2;
    }

    return 0;
}

static void log_temperature(float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (g_log_file) {
        fprintf(g_log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

int main(void)
{
    int ret;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: Cannot open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install signal handlers.\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP05 temperature logging started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int temperature = read_temperature(GPIO_PIN);

        if (temperature == 0) {
            fprintf(stderr, "Error: Sensor read failed (timeout or sensor absent).\n");
        } else if (temperature == -1) {
            fprintf(stderr, "Error: Sensor read failed (timeout).\n");
        } else if (temperature == -2) {
            fprintf(stderr, "Error: Sensor read failed (sensor stuck).\n");
        } else {
            log_temperature(temperature);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

