#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define SHT35_ADDR 0x44
#define I2C_BUS 1
#define MEASURE_CMD_HIGH 0x24
#define MEASURE_CMD_LOW 0x00
#define MEASURE_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define SAMPLE_INTERVAL_US 5000000
#define SAMPLE_PERIOD_SEC 1
#define SENSITIVITY_FACTOR 2.0
#define SENSITIVITY_OFFSET 2.0
#define HUMIDITY_OFFSET 5.0
#define HUMIDITY_MIN_RH 0.0
#define HUMIDITY_MAX_RH 100.0
#define TEMP_MIN_C -40.0
#define TEMP_MAX_C 85.0
#define HUM_MIN_RH 0.0
#define HUM_MAX_RH 100.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sht35(float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", retries, strerror(errno));
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries, strerror(errno));
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", retries);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", retries);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_hum = (buf[3] << 8) | buf[4];

        *temperature = -45.0 + (175.0 * raw_temp / 65535.0);
        *humidity = 100.0 * raw_hum / 65535.0;

        if (*humidity < HUMIDITY_MIN_RH || *humidity > HUMIDITY_MAX_RH) {
            fprintf(stderr, "Humidity out of range (attempt %d): %.2f%%\n", retries, *humidity);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        return 0;
    }

    fprintf(stderr, "SHT35 read failed after %d retries\n", RETRY_COUNT);
    return -1;
}

static float calculate_sinusoidal_offset(float temperature, float humidity) {
    return SENSITIVITY_FACTOR * (temperature - SENSITIVITY_OFFSET) + SENSITIVITY_OFFSET;
}

static float convert_to_celsius(float temperature) {
    return temperature - 273.15;
}

static float convert_to_humidity(float humidity) {
    return 100.0 - (100.0 * (humidity / 100.0) - HUMIDITY_OFFSET);
}

static int log_data(float temperature, float humidity, float offset, float sinusoidal_offset) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, offset, sinusoidal_offset) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity, offset, sinusoidal_offset;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_sht35(&temperature, &humidity) == 0) {
            consecutive_errors = 0;
            offset = calculate_sinusoidal_offset(temperature, humidity);
            temperature = convert_to_celsius(temperature);
            humidity = convert_to_humidity(humidity);
            log_data(temperature, humidity, offset, sinusoidal_offset);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read failed (attempt %d)\n", consecutive_errors);
            if (consecutive_errors >= RETRY_COUNT) {
                fprintf(stderr, "Max retries reached, aborting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return 0;
}

