}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_sdp810(int fd, float *pressure, float *temperature) {
    uint8_t cmd[2] = { (uint8_t)(CMD_CONT_MEAS >> 8), (uint8_t)(CMD_CONT_MEAS & 0xFF) };
    uint8_t data[9];

    if (i2c_write_cmd(fd, cmd[0]) < 0) return -1;
    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, 9) < 0) return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC error on pressure data\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }
    if (crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC error on scale factor data\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor = (int16_t)((data[6] << 8) | data[7]);

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 10.0f;

    return 0;
}

static int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (csv_fp == NULL) {
        csv_fp = fopen(CSV_FILE, "a");
        if (csv_fp == NULL) {
            perror("Failed to open CSV file");
            return -1;
        }
    }

    if (fprintf(csv_fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        perror("Failed to write to CSV file");
        fclose(csv_fp);
        csv_fp = NULL;
        return -1;
    }

    if (fflush(csv_fp) != 0) {
        perror("Failed to flush CSV file");
        fclose(csv_fp);
        csv_fp = NULL;
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_cmd(i2c_fd, CMD_CONT_MEAS) < 0) {
        close(i2c_fd);
        return 1;
    }

    printf("SDP810 sensor initialized. Logging to %s every 1 second. Press Ctrl+C to stop.\n", CSV_FILE);

    while (running) {
        float pressure, temperature;
        if (read_sdp810(i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    if (csv_fp != NULL) {
        fclose(csv_fp);
        csv_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    return 0;
}

