#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT35_ADDR          0x44
#define MEASURE_CMD_HIGHREP 0x2400
#define MEASURE_CMD_LOWREP  0x2400
#define MEASURE_DELAY_US    20000   /* 20 ms */
#define SAMPLE_INTERVAL_S   5
#define CSV_FILENAME        "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- SHT35 single-shot high-repeatability ---- */
static int sht35_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)(MEASURE_CMD_HIGHREP >> 8),
        (uint8_t)(MEASURE_CMD_HIGHREP & 0xFF)
    };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (cmd 0x%04X)\n", MEASURE_CMD_HIGHREP);
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected 6 bytes)\n");
        return -1;
    }

    /* CRC checks */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_t = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_h = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + (175.0f * (float)raw_t / 65535.0f);
    *humidity   = 100.0f * (float)raw_h / 65535.0f;

    return 0;
}

static void log_data(float temperature, float humidity)
{
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        perror("[ERROR] fopen CSV");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                temperature, humidity);
    } else {
        fprintf(fp, "1970-01-01T00:00:00,%.2f,%.2f\n", temperature, humidity);
    }
    fclose(fp);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (addr 0x%02X)\n", SHT35_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;

        if (sht35_read(g_i2c_handle, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("T=%.2f C  RH=%.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; continuing\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

