#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP 0xED
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_HUM 0xEE
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP 0xEF
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP_HUM 0xF0
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP_TEMP 0xF1
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP_TEMP_HUM 0xF2
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP_TEMP_TEMP_HUM 0xF3
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP_TEMP_TEMP_HUM 0xF4
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP_TEMP_TEMP_HUM 0xF5
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP_TEMP_TEMP_HUM 0xF6
