#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP_TEMP_TEMP_HUM 0xF8
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP_TEMP_TEMP_HUM 0xF9
#define MEASURE_CMD_PAIR_HUM_TEMP_HUM_TEMP_TEMP_TEMP_TEMP_TEMP_TEMP_HUM 0xFA
