#define MEASURE_DELAY_US   100000  /* 100 ms */
#define MEASURE_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d ERROR: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "TIMESTAMP ERROR: %s\n", msg);
    }
    fclose(fp);
}

static int i2c_write_byte(int fd, uint8_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint8_t *data, size_t len)
{
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    if (i2c_read_bytes(fd, data, len) < 0) {
        return -1;
    }
    return 0;
}

static int read_measurement_no_hold(int fd, uint8_t cmd, uint8_t *data, size_t len)
{
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    if (i2c_read_bytes(fd, data, len) < 0) {
        return -1;
    }
    return 0;
}

static int read_measurement_pair(int fd, uint8_t cmd, uint8_t *data, size_t len)
{
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    if (i2c_read_bytes(fd, data, len) < 0) {
