{
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    if (i2c_read_bytes(fd, data, len) < 0) {
        return -1;
    }
    return 0;
}

static int read_measurement_pair_no_hold_no_hold(int fd, uint8_t cmd, uint8_t *data, size_t len)
{
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    if (i2c_read_bytes(fd, data, len) < 0) {
