        return -1;
    }
    if (i2c_read_bytes(fd, data, len) < 0) {
        return -1;
    }
    return 0;
}

static int read_measurement_pair_no_hold_no_hold_no_hold_no_hold(int fd, uint8_t cmd, uint8_t *data, size_t len)
{
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    if (i2c_read_bytes(fd, data, len) < 0) {
        return -1;
    }
    return 0;
}

static int initialize_si7021(int fd)
{
    uint8_t cmd = MEASURE_CMD_NOHOLD;
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    usleep(MEASURE_DELAY_US);

    cmd = MEASURE_CMD_PAIR;
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    usleep(MEASURE_DELAY_US);

    cmd = MEASURE_CMD_PAIR_HUM;
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    usleep(MEASURE_DELAY_US);

    cmd = MEASURE_CMD_PAIR_TEMP;
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    usleep(MEASURE_DELAY_US);

    cmd = MEASURE_CMD_NOHOLD_HUM;
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    usleep(MEASURE_DELAY_US);

    cmd = MEASURE_CMD_NOHOLD_TEMP;
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    usleep(MEASURE_DELAY_US);

    cmd = MEASURE_CMD_PAIR_HUM_TEMP;
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
    usleep(MEASURE_DELAY_US);

    cmd = MEASURE_CMD_PAIR_HUM_TEMP_HUM;
    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }
