#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define CONVERSION_TIME_US 50000
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "airflow.dat"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sensor(int handle, uint16_t *pressure, float *temperature) {
    char cmd[2] = { (char)(CONTINUOUS_MEASUREMENT_CMD >> 8), (char)(CONTINUOUS_MEASUREMENT_CMD & 0xFF) };
    char buf[9];

    if (i2cWriteDevice(handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command\n");
        return -1;
    }

    gpioDelay(CONVERSION_TIME_US);

    if (i2cReadDevice(handle, buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from sensor\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Error: Scale factor CRC mismatch\n");
        return -1;
    }

    uint16_t pressure_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t temperature_raw = (uint16_t)((buf[3] << 8) | buf[4]);

    *pressure = (float)pressure_raw / 100.0f;
    *temperature = (float)temperature_raw / 200.0f - 45.0f;

    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X (handle=%d)\n", SDP810_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        sensor_data_t sensor_data;
        int ret = read_sensor(i2c_handle, &sensor_data.pressure, &sensor_data.temperature);

        if (ret == 0) {
            if (log_data(log_file, sensor_data.pressure, sensor_data.temperature) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Sensor read failed\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

