            fprintf(stderr, "Sensor read failed, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Airflow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

