#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1_REG 0x10
#define PRESS_OUT_XL_REG 0x28
#define PRESS_OUT_L_REG 0x29
#define PRESS_OUT_H_REG 0x2A
#define TEMP_OUT_L_REG 0x2B
#define TEMP_OUT_H_REG 0x2C

#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1_VAL 0xB0
#define OUTPUT_RATE_10HZ 0x00
#define MODE_ACTIVE 0x01

#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error on reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error on reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read error on reg 0x%02X: got %d, expected %u\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int init_lps33hw(int handle) {
    uint8_t who_am_i = 0;
    if (read_register(handle, WHO_AM_I_REG, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (write_register(handle, CTRL_REG1_REG, CTRL_REG1_VAL) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    if (write_register(handle, CTRL_REG1_REG, OUTPUT_RATE_10HZ | MODE_ACTIVE) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

static int read_pressure_temperature(int handle, int32_t *pressure, int16_t *temperature) {
    uint8_t buf[6];
    if (read_register_block(handle, PRESS_OUT_XL_REG, buf, 6) != 0) {
        return -1;
    }

    *pressure = (int32_t)((buf[0] << 16) | (buf[1] << 8) | buf[2]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

static float convert_to_hpa(int32_t pressure, int16_t temperature) {
    return (float)pressure / 4096.0f;
}

static float convert_to_celsius(int16_t temperature) {
    return 42.5f + (float)temperature / 480.0f;
}

static void log_data(FILE *fp, int32_t pressure, int16_t temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime_r(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure / 4096.0f, temperature / 16384.0f);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n",
                LPS33HW_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lps33hw(g_i2c_handle) != 0) {
        fprintf(stderr, "LPS33HW initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LPS33HW logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int32_t pressure, temperature;
        if (read_pressure_temperature(g_i2c_handle, &pressure, &temperature) == 0) {
            float hpa = convert_to_hpa(pressure, temperature);
            float celsius = convert_to_celsius(temperature);
            log_data(g_log_file, pressure, temperature);
            printf("Pressure: %.2f hPa, Temperature: %.2f °C\n", hpa, celsius);
        } else {
            fprintf(stderr, "Sensor read failed; continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

