#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_US      1000000  /* 1 second */

/*
 * STLM75 temperature register map (16-bit two's-complement, 9-bit resolution).
 * The datasheet shows the data word as two bytes in little-endian order.
 * We read the two bytes, swap them, and right-shift by 7 to get the 9-bit
 * value.  Then divide by 2 to get the temperature in degrees Celsius.
 */
#define TEMP_REG_MSB   0x00
#define TEMP_REG_LSB   0x01

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} TemperatureBuffer;

static int i2c_handle = -1;
static TemperatureBuffer temp_buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *out)
{
    char buf[2];
    int rc;

    rc = i2cReadWordData(i2c_handle, TEMP_REG_MSB, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: i2cReadWordData failed (rc=%d)\n", rc);
        return -1;
    }

    /* pigpio returns bytes in little-endian order (MSB first).
     * The STLM75 returns a 16-bit two's-complement word.
     * Swap the two bytes and right-shift by 7 to get the 9-bit value.
     * Then divide by 2 to get the temperature in degrees Celsius. */
    uint16_t raw = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    *out = (float)raw / 2.0f;
    return 0;
}

static void add_to_buffer(float temp)
{
    temp_buffer.buffer[temp_buffer.head] = temp;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) {
        temp_buffer.count++;
    }
}

static float calculate_average(void)
{
    if (temp_buffer.count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < temp_buffer.count; i++) {
        sum += temp_buffer.buffer[i];
    }
    return sum / (float)temp_buffer.count;
}

static void control_led(float avg)
{
    if (avg > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void)
{
    float temperature;
    int rc;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Initialize I2C --- */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Initialize temperature buffer --- */
    temp_buffer.head = 0;
    temp_buffer.count = 0;

    printf("STLM75 temperature monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        rc = read_temperature(&temperature);
        if (rc == 0) {
            add_to_buffer(temperature);
            control_led(calculate_average());
        } else {
            fprintf(stderr, "Warning: temperature read failed; skipping iteration\n");
        }
        usleep(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

