#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_ADDR 0x61
#define I2C_BUS 1
#define MEASURE_INTERVAL_SEC 2
#define LOG_FILE "air_quality.log"

#define CMD_MEASURE_INTERVAL 0x01
#define CMD_START_CONT_MEASURE 0x03
#define CMD_DATA_READY 0x02
#define CMD_READ_MEASUREMENT 0x03

#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

static uint8_t scd30_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int scd30_write_command(uint8_t cmd) {
    uint8_t buf[2] = {cmd >> 8, cmd & 0xFF};
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write failed for command 0x%02X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd30_read_data(uint8_t *data, int len) {
    if (i2cReadDevice(i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error: I2C read failed for %d bytes\n", len);
        return -1;
    }
    return 0;
}

static int scd30_init(void) {
    if (scd30_write_command(CMD_MEASURE_INTERVAL) != 0) return -1;
    gpioDelay(10000);
    if (scd30_write_command(CMD_START_CONT_MEASURE) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int scd30_read_data(sensor_data_t *data) {
    uint8_t cmd = CMD_DATA_READY;
    if (scd30_write_command(cmd) != 0) return -1;
    gpioDelay(10000);

    uint8_t buf[18];
    if (scd30_read_data(buf, 18) != 0) return -1;

    if (scd30_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CO2 CRC mismatch\n");
        return -1;
    }
    if (scd30_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (scd30_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    data->co2 = (float)buf[3] * 0.01f;
    data->temperature = (float)buf[6] * 0.01f;
    data->humidity = (float)buf[9] * 0.01f;
    return 0;
}

static void log_data(float co2, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

static void simulate_ventilation(float co2_level) {
    if (co2_level < 800.0f) {
        printf("CO2 level: %.2f ppm, Ventilation ON\n", co2_level);
    } else if (co2_level < 1200.0f) {
        printf("CO2 level: %.2f ppm, Ventilation LOW\n", co2_level);
    } else {
        printf("CO2 level: %.2f ppm, Ventilation HIGH\n", co2_level);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (bus %d, addr 0x%02X)\n", I2C_BUS, SCD30_ADDR);
        gpioTerminate();
        return 1;
    }

    if (scd30_init() != 0) {
        fprintf(stderr, "Error: SCD30 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD30 CO2 monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        sensor_data_t data;
        if (scd30_read_data(&data) == 0) {
            log_data(data.co2, data.temperature, data.humidity);
            simulate_ventilation(data.co2);
        } else {
            fprintf(stderr, "Error: SCD30 read failed, continuing...\n");
        }
        gpioDelay(MEASURE_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

