 * SDP32 Differential Pressure Sensor Reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Build: gcc -Wall -O2 -o sdp32_reader sdp32_reader.c -lpigpio -lrt
 * Run:   sudo ./sdp32_reader [interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

