#define SDP32_ADDR       0x21
#define DEFAULT_INTERVAL 1000
#define CMD_START        0x36
#define CMD_STOP         0x2F
#define CMD_READ_MEASUREMENT 0x36
#define CMD_READ_CONFIG     0x2F
#define CMD_READ_CONFIG_EX  0x2F
