 * Send a continuous-measurement command to the SDP32.
 * Returns 0 on success, -1 on I2C error.
 */
static int sdp_start_continuous(void) {
    uint8_t cmd[2] = { CMD_START, CMD_READ_MEASUREMENT };
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send continuous measurement command.\n");
        return -1;
    }
    return 0;
}

/*
 * Send a config command to the SDP32.
 * Returns 0 on success, -1 on I2C error.
 */
static int sdp_config_read(void) {
    uint8_t cmd[2] = { CMD_READ_CONFIG, CMD_READ_CONFIG_EX };
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send config command.\n");
        return -1;
    }
    return 0;
}

/*
 * Read 9 bytes of continuous-measurement data from the SDP32.
 * Returns 0 on success, -1 on I2C error.
 */
static int sdp_read_data(uint8_t *data) {
    if (i2cWriteDevice(g_i2c_handle, (char *)&data[0], 9) != 0) {
