    if (rc != 9) {
        fprintf(stderr, "i2cReadDevice returned %d (expected 9)\n", rc);
        return -1;
    }

    /* Validate CRC on each 3-byte data word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    /* Convert raw values */
    uint16_t raw_pressure = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_temperature = ((uint16_t)data[3] << 8) | data[4];

