static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_si7051(int handle, float *temperature) {
    char buf[2];
    int ret;

    ret = i2cReadDevice(handle, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error: I2C read failed (ret=%d)\n", ret);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = (float)raw / 16.0f;
    return 0;
}

