    int handle;
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (read_si7051(handle, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Warning: I2C read failed, continuing...\n");
        }
        sleep(POLL_INTERVAL_SEC);
    }

