#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ICP10101_ADDR  0x63
#define MEASURE_CMD    0x40
#define READ_CMD       0x50
#define READ_LEN       6
#define SAMPLE_INTERVAL_S 5

/* OTP calibration coefficients (datasheet) */
static const uint8_t scale_factor_lut[4] = {0x00, 0x00, 0x00, 0x00};
static const uint8_t scale_factor_h[4]   = {0x00, 0x00, 0x00, 0x00};
static const uint8_t scale_factor_p[4]   = {0x00, 0x00, 0x00, 0x00};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_block(int handle, uint8_t cmd, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read failed: expected %u bytes, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t cmd)
{
    int rc = i2cWriteDevice(handle, (char *)&cmd, 1);
    if (rc != 1) {
        fprintf(stderr, "I2C write failed: cmd 0x%02X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_otp_calibration(int handle, uint8_t *buf, uint32_t len)
{
    if (i2c_write_byte(handle, MEASURE_CMD) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    if (i2c_read_block(handle, READ_CMD, buf, len) != 0)
        return -1;

    return 0;
}

static int read_pressure_temperature(int handle, float *temperature, float *pressure)
{
    uint8_t buf[READ_LEN];

    if (i2c_write_byte(handle, MEASURE_CMD) != 0)
        return -1;
    gpioDelay(10000);

    if (i2c_read_block(handle, READ_CMD, buf, READ_LEN) != 0)
        return -1;

    uint32_t raw_pressure = ((uint32_t)buf[0] << 16) |
                            ((uint32_t)buf[1] << 8)  |
                            (uint32_t)buf[2];
    uint32_t raw_temperature = ((uint32_t)buf[3] << 16) |
                               ((uint32_t)buf[4] << 8)  |
                               (uint32_t)buf[5];

    /* Datasheet compensation formulas (simplified for demonstration) */
    float t_c = (float)raw_temperature / 65536.0f;
    float p_pa = (float)raw_pressure / 65536.0f;

    *temperature = t_c * scale_factor_h[0] + t_c * scale_factor_h[1] +
                    t_c * scale_factor_h[2] + t_c * scale_factor_h[3];
    *pressure  = p_pa * scale_factor_p[0] + p_pa * scale_factor_p[1] +
                   p_pa * scale_factor_p[2] + p_pa * scale_factor_p[3];

    return 0;
}

static void log_reading(float temperature, float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temperature, pressure);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, ICP10101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t cal_buf[4];
    if (read_otp_calibration(g_i2c_handle, cal_buf, sizeof(cal_buf)) != 0) {
        fprintf(stderr, "Sensor absent or I2C read failed — sensor may be disconnected or not responding.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, pressure;
    uint8_t scale_factor_lut_buf[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t scale_factor_h_buf[4]   = {0x00, 0x00, 0x00, 0x00};
    uint8_t scale_factor_p_buf[4]   = {0x00, 0x00, 0x00, 0x00};

    while (g_running) {
        if (read_pressure_temperature(g_i2c_handle, &temperature, &pressure) == 0) {
            log_reading(temperature, pressure);
        } else {
            fprintf(stderr, "Error reading sensor data — sensor absent or I2C bus error.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

