    while (g_running) {
        uint16_t raw;
        if (i2c_read_word(fd, PRESSURE_REG, &raw) == 0) {
            float pressure_kPa = (float)raw * 0.1f;
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("%s - Pressure: %.2f kPa\n", ts, pressure_kPa);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

