#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_DEVID 0x01
#define TMP117_DEVID_VAL 0x0117
#define I2C_BUS 1
#define FILENAME "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, TMP117_REG_TEMP, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static int write_to_file(const char *filename, const float *temps) {
    if (fp == NULL) {
        fp = fopen(filename, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
            return -1;
        }
    }
    size_t written = fwrite(temps, sizeof(float), 4, fp);
    if (written != 4) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        fp = NULL;
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
        fp = NULL;
        return -1;
    }
    fp = NULL;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, TMP117_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    uint8_t devid = 0;
    if (i2cReadByteData(i2c_handle, TMP117_REG_DEVID) < 0) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cReadByteData(i2c_handle, TMP117_REG_DEVID) != TMP117_DEVID_VAL) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n", i2cReadByteData(i2c_handle, TMP117_REG_DEVID), TMP117_DEVID_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("TMP117 detected (device ID: 0x%02X)\n", devid);

    while (running) {
        float temperatures[4];
        if (read_temperature(i2c_handle, &temperatures[0]) != 0 ||
            read_temperature(i2c_handle, &temperatures[1]) != 0 ||
            read_temperature(i2c_handle, &temperatures[2]) != 0 ||
            read_temperature(i2c_handle, &temperatures[3]) != 0) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (write_to_file(FILENAME, temperatures) != 0) {
            fprintf(stderr, "Error writing to file, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, temperatures[0], temperatures[1], temperatures[2], temperatures[3]);
        fflush(fp);
        printf("%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, temperatures[0], temperatures[1], temperatures[2], temperatures[3]);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

