#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SHT40_ADDR 0x44
#define I2C_BUS 1
#define LOG_FILE "environment_data.txt"
#define MEASURE_CMD_HIGH_PRECISION 0xFD
#define MEASURE_CMD_LOW_PRECISION 0xFE
#define MEASURE_DELAY_US 8500
#define SAMPLE_INTERVAL_US 5000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_CMD_HIGH_PRECISION;
    uint8_t buf[6];

    if (i2cWriteDevice(i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read 6 bytes from sensor\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_hum = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
    *humidity = -6.0f + 125.0f * (float)raw_hum / 65535.0f;

    return 0;
}

