#define I2C_BUS 1
#define SHTC3_ADDR 0x70
#define LOG_FILE "shtc3_environment.log"
#define SAMPLE_INTERVAL_SEC 5

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* CRC-8 polynomial 0x31, initial value 0xFF */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_shtc3(float *temperature, float *humidity) {
    uint8_t cmd[2] = {0x78, 0x66};
    uint8_t data[6];
    int rc;

    /* Issue measurement command: clock stretching disabled */
    rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: %d\n", rc);
        return -1;
    }

    /* Wait for conversion (12.4 ms at 1.8 V; datasheet: 12 ms max) */
    gpioDelay(12400);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, H_MSB, H_LSB, H_CRC */
    rc = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C read error: expected 6 bytes, got %d\n", rc);
        return -1;
    }

    /* Validate temperature CRC */
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate humidity CRC */
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_t = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_h = ((uint16_t)data[3] << 8) | data[4];

    *temperature = 175.0f * (float)raw_t / 65535.0f - 45.0f;
    *humidity = 100.0f * (float)raw_h / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

