    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SHTC3 air quality monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature, humidity;

        if (read_shtc3(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

