#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TMP117_ADDR 0x48
#define I2C_BUS 1
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define TEMP_REG 0x00
#define SCALE_FACTOR 0.0078125f  // 7.8125 m°C/LSB

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    // TMP117 returns signed 16-bit two's complement value
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw * SCALE_FACTOR;

    return 0;
}

int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    float temperature;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    while (running) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        gpioDelay(1000000);  // 1 second in microseconds
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

