#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d: %s\n",
                I2C_ADDR, I2C_BUS, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    char buf[4];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(i2c_handle, buf, 4);
        if (bytes_read == 4) {
            uint16_t raw_flow = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            uint16_t raw_temp = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

            if (raw_flow > 0x7FFF || raw_temp > 0x7FFF) {
                fprintf(stderr, "Flow/temperature out of range: raw=%u, raw_temp=%u\n",
                        raw_flow, raw_temp);
                return -1;
            }

            *flow_rate = ((float)raw_flow / 16384.0f) - 0.1f;
            *flow_rate *= 25.0f;
            *flow_rate /= 0.8f;

            if (raw_temp > 0x7FFF) {
                fprintf(stderr, "Temperature out of range: raw=%u\n", raw_temp);
                return -1;
            }

            *flow_rate /= 0.8f;
            *flow_rate -= 40.0f;

            return 0;
        }
        retries++;
        gpioDelay(10000);
    }

    fprintf(stderr, "Failed to read flow data after %d retries\n", MAX_RETRIES);
    return -1;
}

static int read_temperature(float *temperature) {
    char buf[4];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(i2c_handle, buf, 4);
        if (bytes_read == 4) {
            uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            if (raw_temp > 0x7FFF) {
                fprintf(stderr, "Temperature out of range: raw=%u\n", raw_temp);
                return -1;
            }

            *temperature = ((float)raw_temp / 4096.0f) - 0.1f;
            *temperature *= 80.0f;
            *temperature -= 40.0f;

            return 0;
        }
        retries++;
        gpioDelay(10000);
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(float flow_rate, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow_rate, temperature);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float flow_rate, temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Ventilation monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_flow_rate(&flow_rate) == 0 && read_temperature(&temperature) == 0) {
            log_data(flow_rate, temperature);
            printf("Flow Rate: %.2f SLPM, Temperature: %.2f C\n", flow_rate, temperature);
        } else {
            fprintf(stderr, "Failed to read flow or temperature data. Re-initializing I2C...\n");
            if (i2c_handle >= 0) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
            }
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
            if (read_flow_rate(&flow_rate) == 0 && read_temperature(&temperature) == 0) {
                log_data(flow_rate, temperature);
                printf("Flow Rate: %.2f SLPM, Temperature: %.2f C\n", flow_rate, temperature);
            } else {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

