#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SHT31_ADDR 0x44
#define I2C_BUS 1
#define LOG_FILE "sht31d_data.log"
#define MEASURE_CMD_MSB 0x2C
#define MEASURE_CMD_LSB 0x06
#define MEASURE_DELAY_US 15000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht31d(float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d/%d)\n",
                    retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d/%d)\n",
                    retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t raw_hum = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);
        *humidity = 100.0f * (float)raw_hum / 65535.0f;

        return 0;
    }

    fprintf(stderr, "Sensor read failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

static int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f\n", ts, temperature, humidity) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                SHT31_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SHT31-D greenhouse monitor started. Logging to %s\n", LOG_FILE);

    while (running) {
        float temperature, humidity;
        if (read_sht31d(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        gpioDelay(5000000);
    }

    printf("\nShutting down gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

