#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define FAN_GPIO       18
#define TEMP_REG       0x00
#define TEMP_BUF_SIZE  60
#define TEMP_THRESHOLD 28.0f
#define TEMP_THRESHOLD_LOW 26.0f
#define SAMPLE_INTERVAL_US 1000000
#define BUFFER_SIZE     60

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, LM75B_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(g_i2c_handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", TEMP_REG, rc);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    int16_t temp_signed = (int16_t)(raw >> 1);
    *out = (float)temp_signed * 0.5f;
    return 0;
}

static void add_to_buffer(float value) {
    CircularBuffer *c = &buffer[head];
    c->buffer[head] = value;
    c->head = (c->head + 1) % BUFFER_SIZE;
    if (c->count < BUFFER_SIZE) c->count++;
}

static float calculate_average(void) {
    if (c->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < c->count; i++) sum += c->buffer[i];
    return sum / c->count;
}

static void control_fan(float avg) {
    if (avg > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    CircularBuffer buffer[BUFFER_SIZE];
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer[i].head = 0;
        buffer[i].count = 0;
    }

    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            add_to_buffer(temp);
            float avg = calculate_average();
            control_fan(avg);
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);
        } else {
            fprintf(stderr, "Sensor read failed; retrying next cycle\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

