#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define MEAS_DELAY_US 45000
#define LOG_FILE "airflow.log"
#define PRESSURE_THRESHOLD 5.0f
#define SCALE_FACTOR 60
#define TEMP_SCALE 200

static int i2c_handle = -1;
