#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define LED_PIN 17
#define TEMP_THRESHOLD 28.0f
#define TEMP_LOW 27.0f
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, I2C_RETRIES, strerror(errno));
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, I2C_RETRIES, strerror(errno));
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        *out = (uint16_t)((buf[0] << 8) | buf[1]);
        return 0;
    }
    return -1;
}

static float read_temperature(int fd) {
    uint16_t raw;
    if (i2c_read_reg16(fd, 0x00, &raw) != 0) {
        fprintf(stderr, "Failed to read temperature after %d retries\n", I2C_RETRIES);
        return -273.0f;
    }
    return (float)raw / 16.0f;
}

static void set_led(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) != 0) {
        fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "stts2004-led", 0) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    while (running) {
        float temp = read_temperature(fd);
        if (temp < -273.0f) {
            fprintf(stderr, "I2C read error, retrying in 1 s\n");
            sleep(1);
            continue;
        }

        int led_state = (temp > TEMP_THRESHOLD) ? 1 : 0;
        set_led(led_line, led_state);

        printf("Temperature: %.2f C, LED: %s\n", temp, led_state ? "ON" : "OFF");
        fflush(stdout);

        sleep(1);
    }

    set_led(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(fd);
    return 0;
}

