static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_si7021(int handle, float *temperature, float *humidity) {
    char cmd[2] = {MEASURE_RH_NO_HOLD, MEASURE_TEMP_NO_HOLD};
    char data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, cmd, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", retries + 1, pigpio_error(retries));
            retries++;
            gpioDelay(10000);
            continue;
        }
        gpioDelay(MEASURE_RH_NO_HOLD_WAIT_MS * 1000);

        int bytes = i2cReadDevice(handle, data, 3);
        if (bytes != 3) {
            fprintf(stderr, "I2C read failed (attempt %d): got %d bytes, expected 3\n", retries + 1, bytes);
            retries++;
            gpioDelay(10000);
            continue;
        }

        uint16_t raw_rh = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
        uint16_t raw_temp = ((uint16_t)(uint8_t)data[2] << 8) | (uint8_t)data[3];

        if (raw_rh > 65535 || raw_temp > 65535) {
            fprintf(stderr, "Raw values out of range: RH=%u, Temp=%u\n", raw_rh, raw_temp);
            return -1;
