        *humidity = 175.72f * (float)raw_rh / 65536.0f - 46.85f;
        *temperature = 125.0f * (float)raw_temp / 65536.0f - 6.0f;

        if (*humidity < 0.0f || *humidity > 100.0f) {
            fprintf(stderr, "Humidity out of range: %.2f\n", *humidity);
            return -1;
        }

        return 0;
    }

    return -1;
}

