#define CONVERSION_DELAY_US 20000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_config(int handle) {
    char buf[2];
    if (i2cWriteByte(handle, CONFIG_REG) < 0) {
        fprintf(stderr, "Error: Failed to write config register\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read config register\n");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static int read_raw(int handle, int16_t *raw_temp, int16_t *raw_hum) {
    char buf[4];
    if (i2cWriteByte(handle, DATA_REG) < 0) {
        fprintf(stderr, "Error: Failed to write data register\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    if (i2cReadDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error: Failed to read data register\n");
        return -1;
    }
    *raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
    *raw_hum = ((uint16_t)buf[2] << 8) | buf[3];
    return 0;
}

static float convert_temperature(int16_t raw_temp) {
    return ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
}

static float convert_humidity(int16_t raw_hum) {
    return ((float)raw_hum / 65536.0f) * 100.0f;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error: Failed to open log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
