        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", HDC1080_ADDR);
        gpioTerminate();
        return 1;
    }

    if (read_config(i2c_handle) < 0) {
        fprintf(stderr, "Error: HDC1080 not detected or not responding\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        int16_t raw_temp, raw_hum;
        if (read_raw(i2c_handle, &raw_temp, &raw_hum) == 0) {
            float temperature = convert_temperature(raw_temp);
            float humidity = convert_humidity(raw_hum);
            if (log_data(temperature, humidity) != 0) {
