            fprintf(stderr, "Warning: Sensor read failed, skipping log entry\n");
        }
        gpioDelay(5000000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

