#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_CO2_TEMPERATURE_HUMIDITY 0xE000
#define BUFFER_SIZE 100
#define LOG_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} DataPoint;

typedef struct {
    DataPoint data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int scd40_write_command(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_data(int handle, uint8_t *buf, int len) {
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "Error: I2C read failed for %d bytes\n", len);
        return -1;
    }
    return 0;
}

static int scd40_init(int handle) {
    if (scd40_write_command(handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        return -1;
    }
    time_sleep(1.0);
    return 0;
}

static int scd40_read_data_with_crc(int handle, uint8_t *buf, int len) {
    if (scd40_write_command(handle, CMD_READ_CO2_TEMPERATURE_HUMIDITY) != 0) {
        fprintf(stderr, "Error: Failed to send read command\n");
        return -1;
    }
    time_sleep(0.5);
    if (scd40_read_data(handle, buf, len) != 0) {
        fprintf(stderr, "Error: Failed to read data\n");
        return -1;
    }
    for (int i = 0; i < len; i++) {
        if (crc8(&buf[i], 2) != buf[i]) {
            fprintf(stderr, "Error: CRC mismatch on data %d\n", i);
            return -1;
        }
    }
    return 0;
}

static int scd40_convert(const uint8_t *buf, float *co2, float *temp, float *hum) {
    *co2 = (float)buf[0] * 175.0f / 65535.0f;
    *temp = -45.0f + 175.0f * (float)buf[1] / 65535.0f;
    *hum = 100.0f * (float)buf[2] / 65535.0f;
    return 0;
}

static int scd40_write_to_csv(const CircularBuffer *buffer, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open %s for writing\n", filename);
        return -1;
    }
    fprintf(fp, "timestamp,co2,temperature,humidity\n");
    for (int i = 0; i < buffer->count; i++) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, buffer->data[i].co2, buffer->data[i].temperature, buffer->data[i].humidity);
    }
    fclose(fp);
    return 0;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open %s for appending\n", ERROR_LOG_FILE);
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(fp, "%s,ERROR: %s\n", ts, message);
    fclose(fp);
}

static void log_data(const CircularBuffer *buffer, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open %s for appending\n", filename);
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, buffer->data[buffer->head].co2, buffer->data[buffer->head].temperature, buffer->data[buffer->head].humidity);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %d at address 0x%02X\n", I2C_BUS, SCD40_ADDR);
        gpioTerminate();
        return 1;
    }

    if (scd40_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: SCD40 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (scd40_write_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    CircularBuffer data_buffer;
    data_buffer.head = 0;
    data_buffer.count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 data logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint8_t buf[9];
        if (scd40_read_data_with_crc(i2c_handle, buf, 9) != 0) {
            log_error("Failed to read data from SCD40");
            time_sleep(5.0);
            continue;
        }

        float co2, temp, humidity;
        if (scd40_convert(buf, &co2, &temp, &humidity) != 0) {
            log_error("Failed to convert data from SCD40");
            time_sleep(5.0);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

        data_buffer.data[data_buffer.head].timestamp = now;
        data_buffer.data[data_buffer.head].co2 = co2;
        data_buffer.data[data_buffer.head].temperature = temp;
        data_buffer.data[data_buffer.head].humidity = humidity;

        data_buffer.head = (data_buffer.head + 1) % BUFFER_SIZE;
        if (data_buffer.count < BUFFER_SIZE) {
            data_buffer.count++;
        }

        if (scd40_write_to_csv(&data_buffer, LOG_FILE) != 0) {
            log_error("Failed to write to CSV file");
        }

        time_sleep(5.0);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        scd40_write_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Data logging stopped.\n");
    return 0;
}

