#define CMD_CONT_MEAS 0x362F
#define MEAS_DELAY_US 45000
#define LOG_FILE "sdp810_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sdp810(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = {CMD_CONT_MEAS, 0x00};
    uint8_t buf[9];
    int result;

    result = i2cWriteDevice(handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    result = i2cReadDevice(handle, (char *)buf, 9);
    if (result != 9) {
        fprintf(stderr, "I2C read error: expected 9 bytes, got %d\n", result);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure data\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on scale factor data\n");
        return -1;
    }

    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temp = (buf[3] << 8) | buf[4];
    int16_t scale_factor = (buf[6] << 8) | buf[7];

    *pressure = (float)raw_pressure * scale_factor / 1000.0f;
    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;

    return 0;
}

static int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", SDP810_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure, temperature;
    while (running) {
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }
        sleep(1);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

