#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x01
#define CALIB_REG0 0x05
#define CALIB_REG1 0x06
#define CALIB_REG2 0x07
#define CALIB_REG3 0x08

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_calibration_data(int handle, uint16_t *coeff1, uint16_t *coeff2, uint16_t *coeff3) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, CALIB_REG0, buf, 6) != 6) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }
    *coeff1 = (uint16_t)((buf[1] << 8) | buf[0]);
    *coeff2 = (uint16_t)((buf[3] << 8) | buf[2]);
    *coeff3 = (uint16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, float *pressure, float *temperature) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 6) != 6) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }
    uint16_t raw_pressure = ((uint16_t)(buf[0] << 8) | buf[1]);
    uint16_t raw_temperature = ((uint16_t)(buf[2] << 8) | buf[3]);
    *pressure = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temperature / 100.0f;
    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i = 0;
    if (i2cReadByteData(i2c_handle, WHO_AM_I_REG) != WHO_AM_I_VAL) {
        fprintf(stderr, "Sensor not detected (WHO_AM_I mismatch)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("ICP10110 detected (WHO_AM_I=0x%02X)\n", who_am_i);

    if (read_calibration_data(i2c_handle, &who_am_i, &who_am_i, &who_am_i) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        float pressure, temperature;
        if (read_sensor_data(i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(log_file, pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            printf("Pressure: %.2f hPa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read error, skipping sample\n");
        }
        sleep(5);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully\n");
    return 0;
}

