        } else {
            fprintf(stderr, "Sensor read error, skipping sample\n");
        }
        sleep(5);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully\n");
    return 0;
}

