#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x63
#define LED_GPIO_LINE  17
#define PRESSURE_THRESHOLD 95000
#define MEASUREMENT_DELAY_MS 20
#define POLL_INTERVAL_MS 1000

/* OTP calibration coefficients (16 bytes) */
static const uint8_t calib_coeffs[16] = {
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_calibration_coeffs(int fd, uint16_t *coeffs) {
    uint8_t buf[16];
    if (i2c_read_reg16(fd, 0x66, buf) < 0) return -1;
    for (int i = 0; i < 16; i++) {
        coeffs[i] = (uint16_t)buf[i];
    }
    return 0;
}

static int read_pressure_and_temperature(int fd, uint16_t coeffs[16], float *pressure, float *temperature) {
    uint8_t buf[6];
    if (i2c_read_reg16(fd, 0x6F, buf) < 0) return -1;

    uint16_t raw_pressure = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    uint16_t raw_temp     = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);

    /* CRC check for pressure (bytes 0-1) */
    uint8_t crc_pressure = 0;
    for (int i = 0; i < 2; i++) {
        crc_pressure ^= coeffs[i];
        for (int j = 0; j < 2; j++) {
            crc_pressure = (crc_pressure & 0x01) ? (crc_pressure << 1) ^ 0xA1 : crc_pressure >> 1;
        }
    }
    if (crc_pressure != buf[4]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }

    /* CRC check for temperature (bytes 5-6) */
    uint8_t crc_temp = 0;
    for (int i = 0; i < 2; i++) {
        crc_temp ^= coeffs[i + 8];
        for (int j = 0; j < 2; j++) {
            crc_temp = (crc_temp & 0x01) ? (crc_temp << 1) ^ 0xA1 : crc_temp >> 1;
        }
    }
    if (crc_temp != buf[7]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    *pressure = (float)raw_pressure / 10.0f;
    *temperature = (float)raw_temp / 10.0f;
    return 0;
}

static void blink_led(struct gpiod_line *line, int on_ms, int off_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
        return;
    }
    usleep(on_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
    }
    usleep(off_ms * 1000);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint16_t calib_coeffs[16];
    if (read_calibration_coeffs(fd, calib_coeffs) < 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "icp10125-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    printf("ICP-10125 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t coeffs[16];
        float pressure, temperature;

        if (read_pressure_and_temperature(fd, calib_coeffs, &pressure, &temperature) < 0) {
            fprintf(stderr, "Sensor read error; retrying in 1 s...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        if (pressure < PRESSURE_THRESHOLD) {
            printf("Warning: Pressure below %.0f Pa (%.2f C). Blinking LED at 5 Hz.\n", PRESSURE_THRESHOLD, temperature);
            blink_led(led_line, 500, 500);
        } else {
            printf("Normal: Pressure %.2f Pa, Temperature %.2f C\n", pressure, temperature);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Cleanup */
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

