#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define TEMP_REG_AMBIENT 0x06
#define TEMP_REG_OBJECT  0x07
#define FAN_GPIO 18
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 2
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, int reg, float *out) {
    int val;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        val = i2cReadWordData(handle, reg);
        if (val >= 0) {
            *out = (float)val * 0.02f - 273.15f;
            return 0;
        }
        fprintf(stderr, "I2C read failed (reg=0x%02X, attempt %d/%d): %d\n",
                reg, attempt + 1, MAX_RETRIES, val);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static int log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                ambient, object);
    } else {
        fprintf(fp, "Error: time conversion failed\n");
    }
    fclose(fp);
    return 0;
}

static void control_fan(float object_temp) {
    if (object_temp > 30.0f) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, MLX90614_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);

    printf("MLX90614 temperature monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        float ambient, object;

        if (read_temperature(i2c_handle, TEMP_REG_AMBIENT, &ambient) != 0) {
            fprintf(stderr, "Failed to read ambient temperature after %d retries\n",
                    MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }
        if (read_temperature(i2c_handle, TEMP_REG_OBJECT, &object) != 0) {
            fprintf(stderr, "Failed to read object temperature after %d retries\n",
                    MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        if (log_temperature(ambient, object) != 0) {
            fprintf(stderr, "Failed to log temperature data\n");
        }

        control_fan(object);

        printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

