#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define WEB_SERVER_PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MEASURE_CMD_HIGH_REP 0xFD
#define MEASURE_CMD_LOW_REP 0xFE
#define MEASURE_CMD_NO_REP 0xFE
#define SAMPLE_INTERVAL_MS 100
#define SAMPLE_DELAY_MS 50

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int web_server_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int handle, uint8_t cmd) {
    int ret = i2cWriteByteData(handle, 0, cmd);
    if (ret < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int handle, uint8_t *buf, int len) {
    int ret = i2cReadI2CBlockData(handle, 0, (char *)buf, len);
    if (ret != len) {
        fprintf(stderr, "I2C read failed: expected %d, got %d\n", len, ret);
        return -1;
    }
    return 0;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_CMD_HIGH_REP;
    uint8_t buf[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(handle, cmd) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", attempt + 1, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        gpioDelay(SAMPLE_DELAY_MS * 1000);

        if (i2c_read_data(handle, buf, 6) != 0) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", attempt + 1, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        int raw_temp = (buf[0] << 8) | buf[1];
        int raw_rh = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
        *humidity = -6.0f + 125.0f * (float)raw_rh / 65535.0f;

        if (*humidity < 0.0f || *humidity > 100.0f) {
            fprintf(stderr, "Invalid humidity: %.2f\n", *humidity);
            return -1;
        }

        return 0;
    }

    return -1;
}

static int start_web_server(void) {
    struct sockaddr_in address;
    int port = WEB_SERVER_PORT;

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    if (bind(web_server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "bind failed: %s\n", strerror(errno));
        return -1;
    }

    if (listen(web_server_fd, 3) < 0) {
        fprintf(stderr, "listen failed: %s\n", strerror(errno));
        return -1;
    }

    printf("Web server listening on port %d\n", port);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (web_server_fd >= 0) {
        close(web_server_fd);
        web_server_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (start_web_server() != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting SHT40 temperature and humidity monitoring...\n");

    while (running) {
        float temperature, humidity;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_MS * 1000);
            }
        }

        if (retries < MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor after %d retries. Check wiring and sensor presence.\n", MAX_RETRIES);
        } else {
            char html[256];
            snprintf(html, sizeof(html),
                     "<html><head><title>SHT40 Monitor</title></head><body><h1>Temperature: %.2f C, Humidity: %.2f %%\n",
                     temperature, humidity);
            snprintf(html + strlen(html), sizeof(html) - strlen(html), "</h1></body></html>");

            if (send(web_server_fd, html, strlen(html), 0) < 0) {
                fprintf(stderr, "send failed: %s\n", strerror(errno));
            } else {
                printf("Sent: %s\n", html);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

