#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HDC2010_ADDR 0x40
#define I2C_BUS 1
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define MEASUREMENT_CONFIG_VAL 0x01
#define MAX_RETRIES 5
#define MEASUREMENT_CONFIG_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int read_register_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read error (reg 0x%02X, len %u): %d\n", reg, len, rc);
        return -1;
    }
    if (rc != len) {
        fprintf(stderr, "I2C block read short: got %d bytes, expected %u\n", rc, len);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, float *temperature, float *humidity) {
    uint8_t buf[3];
    uint8_t config;

    if (read_register(handle, MEASUREMENT_CONFIG, &config) < 0) {
        return -1;
    }

    if (config & 0x01) {
        /* One-shot measurement: clear bit 0, keep CONFIG unchanged */
        if (write_register(handle, MEASUREMENT_CONFIG, MEASUREMENT_CONFIG_VAL) < 0) {
            return -1;
        }
        gpioDelay(MEASUREMENT_CONFIG_TIMEOUT_US);
    }

    if (read_register_block(handle, CONFIG, buf, 3) < 0) {
        return -1;
    }

    uint16_t raw_temp = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t raw_hum = (uint16_t)((buf[2] << 8) | buf[3]);

    *temperature = (float)raw_temp / 65536.0f * 165.0f - 40.0f;
    *humidity = (float)raw_hum / 65536.0f * 100.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, HDC2010_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float temperature, humidity;

        if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(5000000); /* 5 seconds */
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

