#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "reflow_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_TEMP_C 100.0
#define MIN_TEMP_C -50.0
#define PID_GAIN 1.0
#define PID_DELAY_US 1000
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int read_max6675(int spi_fd, float *temperature) {
    unsigned char tx[4] = {0x00, 0x00, 0x00, 0x00};
    unsigned char rx[4] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    if (rx[0] & 0x08) {
        fprintf(stderr, "MAX6675 sensor absent or open-circuit\n");
        return -1;
    }

    int raw = ((rx[0] & 0x0F) << 8) | rx[1];
    *temperature = (float)raw / 16.0;
    return 0;
}

float pid_control(float current_temp, float target_temp, float *integral, float *last_error) {
    float error = target_temp - current_temp;
    *integral += error * SAMPLE_INTERVAL_SEC;
    float derivative = error - *last_error;
    float output = PID_GAIN * error + PID_DELAY_US * derivative;
    *last_error = error;
    return output;
}

int log_data(float temperature, float target_temp, float integral, float last_error) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, target_temp, integral, last_error);
    fclose(fp);
    return 0;
}

int main() {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay_line = NULL;
    float integral = 0.0, last_error = 0.0;
    float target_temp = 0.0;
    float current_temp = 0.0;
    float temperature = 0.0;
    int ret = 1;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        goto cleanup;
    }
    relay_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(relay_line, "reflow_relay", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    unsigned char spi_mode = SPI_MODE;
    unsigned char spi_bits = SPI_BITS_PER_WORD;
    unsigned char spi_speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Reflow oven started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature = 0.0;
        if (read_max6675(spi_fd, &temperature) < 0) {
            fprintf(stderr, "SPI read error, retrying...\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (temperature < MIN_TEMP_C || temperature > MAX_TEMP_C) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            continue;
        }

        target_temp = MAX_TEMP_C - (temperature - MIN_TEMP_C) * (MAX_TEMP_C - MIN_TEMP_C) / (MAX_TEMP_C - MIN_TEMP_C);

        integral += temperature;
        last_error = temperature;

        float pid_output = pid_control(temperature, target_temp, &integral, &last_error);

        if (pid_output > 1.0) pid_output = 1.0;
        if (pid_output < 0.0) pid_output = 0.0;

        current_temp = pid_output;

        printf("Temperature: %.2f C, Target: %.2f C, PID: %.2f, Relay: %.2f%%\n",
               temperature, target_temp, pid_output, current_temp * 100.0);

        if (log_data(temperature, target_temp, integral, last_error) < 0) {
            fprintf(stderr, "Logging failed\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    ret = 0;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    return ret;
}

