#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define HEATER_GPIO 17
#define PWM_GPIO 18
#define SETPOINT_TEMP 25.0
#define PID_Kp 1.0
#define PID_Ki 0.1
#define PID_Kd 0.01
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL 5
#define W1_SYS_PATH "/sys/bus/w1/devices/"
#define W1_CONTACT_PATH "/w1_slave"
#define W1_CONTACT_FILE "/w1_slave"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *heater_line = NULL;
static struct gpiod_line *pwm_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_w1_sensor(const char *path, char *buf, size_t len) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fgets(buf, len, fp) == NULL) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int verify_crc(const char *path, const char *expected_crc) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    char crc_buf[32];
    if (fread(crc_buf, 1, 32, fp) != 32) {
        fprintf(stderr, "Error reading CRC from %s\n", path);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    char crc_str[16];
    if (strncmp(crc_buf, crc_str, 16) != 0) {
        fprintf(stderr, "CRC mismatch: got %s, expected %s\n", crc_str, expected_crc);
        return -1;
    }
    return 0;
}

static int read_sensor_data(const char *path, char *data, size_t len) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fgets(data, len, fp) == NULL) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int calculate_pid(float setpoint, float current_temp, float *integral, float *last_error, float *last_output) {
    float error = setpoint - current_temp;
    *integral += error;
    float derivative = error - *last_error;
    float output = PID_Kp * error + PID_Ki * (*integral) + PID_Kd * derivative;
    *last_error = error;
    *last_output = output;
    return (int)(output + 0.5);
}

static int control_heater(float setpoint, float current_temp, float *integral, float *last_error, float *last_output) {
    float pid_output = calculate_pid(setpoint, current_temp, integral, last_error, last_output);
    if (pid_output < 0) {
        fprintf(stderr, "PID output out of range\n");
        return -1;
    }
    if (pid_output > 1.0) {
        pid_output = 1.0;
    }
    if (pid_output < -1.0) {
        pid_output = -1.0;
    }
    if (pid_output > 0.0) {
        if (gpiod_line_set_value(heater_line, 1) < 0) {
            fprintf(stderr, "Error enabling heater: %s\n", strerror(errno));
            return -1;
        }
        if (gpiod_line_set_value(pwm_line, pid_output) < 0) {
            fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
            return -1;
        }
    } else {
        if (gpiod_line_set_value(heater_line, 0) < 0) {
            fprintf(stderr, "Error disabling heater: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int log_data(float average_temp, float setpoint, float pid_output, float pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %.2f\n", timestamp, average_temp, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (heater_line) {
        gpiod_line_set_value(heater_line, 0);
        gpiod_line_release(heater_line);
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <setpoint_temp> <pid_k> <pid_i> <pid_d>\n", argv[0]);
        return 1;
    }
    float setpoint = atof(argv[1]);
    float pid_k = atof(argv[2]);
    float pid_i = atof(argv[3]);
    float pid_d = atof(argv[4]);
    if (setpoint < 0.0 || setpoint > 100.0 || pid_k <= 0.0 || pid_i <= 0.0 || pid_d <= 0.0) {
        fprintf(stderr, "Invalid PID gains. Setpoint must be between 0 and 100.\n");
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    heater_line = gpiod_chip_get_line(chip, HEATER_GPIO);
    pwm_line = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!heater_line || !pwm_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(heater_line, "greenhouse-heater", 0) < 0) {
        fprintf(stderr, "Error requesting heater line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(pwm_line, "greenhouse-pwm", 0) < 0) {
        fprintf(stderr, "Error requesting PWM line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (verify_crc(W1_CONTACT_PATH, "CRC") < 0) {
        fprintf(stderr, "CRC verification failed\n");
        cleanup();
        return 1;
    }
    printf("Greenhouse heater control started. Setpoint: %.2f, PID gains: Kp=%.2f, Ki=%.2f, Kd=%.2f\n", setpoint, pid_k, pid_i, pid_d);
    while (running) {
        char data[256];
        if (read_w1_sensor(W1_CONTACT_PATH, data, sizeof(data)) == 0) {
            if (verify_crc(W1_CONTACT_PATH, "CRC") < 0) {
                fprintf(stderr, "CRC verification failed\n");
                break;
            }
            float temp = atof(data);
            float integral = 0.0;
            float last_error = 0.0;
            float last_output = 0.0;
            float pid_output = 0.0;
            float pwm_duty_cycle = 0.0;
            if (temp > 0.0) {
                integral += (temp - last_temp) * 0.1;
                last_temp = temp;
            }
            pid_output = calculate_pid(setpoint, temp, &integral, &last_error, &last_output);
            if (pid_output < 0) {
                fprintf(stderr, "PID output out of range\n");
                break;
            }
            if (pid_output > 1.0) {
                pid_output = 1.0;
            }
            if (pid_output < -1.0) {
                pid_output = -1.0;
            }
            if (pid_output > 0.0) {
                if (gpiod_line_set_value(heater_line, 1) < 0) {
                    fprintf(stderr, "Error enabling heater: %s\n", strerror(errno));
                    break;
                }
                if (gpiod_line_set_value(pwm_line, pid_output) < 0) {
                    fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
                    break;
                }
                pwm_duty_cycle = pid_output;
            } else {
                if (gpiod_line_set_value(heater_line, 0) < 0) {
                    fprintf(stderr, "Error disabling heater: %s\n", strerror(errno));
                    break;
                }
                pwm_duty_cycle = 0.0;
            }
            if (pwm_duty_cycle > 0.0) {
                if (gpiod_line_set_value(pwm_line, pwm_duty_cycle) < 0) {
                    fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
                    break;
                }
            }
            log_data(average_temp, setpoint, pid_output, pwm_duty_cycle);
        }
        sleep(SAMPLE_INTERVAL);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

