#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define RELAY_GPIO     17
#define HUMIDITY_THRESHOLD_HIGH 60.0f
#define HUMIDITY_THRESHOLD_LOW  55.0f
#define POLL_INTERVAL_SEC    5
#define I2C_RETRIES        3
#define I2C_RETRY_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    uint8_t buf[1] = { byte };
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int aht20_init(int fd)
{
    uint8_t cmd[2] = { 0xBE, 0x08 };
    if (i2c_write_byte(fd, cmd[0]) < 0) return -1;
    if (i2c_write_byte(fd, cmd[1]) < 0) return -1;
    usleep(10000);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) < 0) return -1;

    if (data[0] != 0x55) {
        fprintf(stderr, "AHT20 status byte mismatch: 0x%02X\n", data[0]);
        return -1;
    }

    if (data[1] != 0x00) {
        fprintf(stderr, "AHT20 data mismatch: 0x%02X\n", data[1]);
        return -1;
    }

    if (data[2] != 0x00) {
        fprintf(stderr, "AHT20 data mismatch: 0x%02X\n", data[2]);
        return -1;
    }

    if (data[3] != 0x00) {
        fprintf(stderr, "AHT20 data mismatch: 0x%02X\n", data[3]);
        return -1;
    }

    if (data[4] != 0x00) {
        fprintf(stderr, "AHT20 data mismatch: 0x%02X\n", data[4]);
        return -1;
    }

    if (data[5] != 0x00) {
        fprintf(stderr, "AHT20 data mismatch: 0x%02X\n", data[5]);
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *humidity = (float)raw / 10.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (aht20_init(fd) < 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("AHT20 initialized. Starting monitoring...\n");

    while (g_running) {
        float humidity = 0.0f;
        int retries = 0;

        while (retries < I2C_RETRIES && g_running) {
            if (aht20_read_humidity(fd, &humidity) == 0) {
                break;
            }
            retries++;
            if (retries < I2C_RETRIES) {
                fprintf(stderr, "I2C read failed (attempt %d/%d)\n",
                        retries, I2C_RETRIES);
                usleep(I2C_RETRY_DELAY_MS * 1000);
            }
        }

        if (!g_running) break;

        if (humidity > HUMIDITY_THRESHOLD_HIGH && humidity < HUMIDITY_THRESHOLD_LOW) {
            printf("Humidity: %.2f%% (above threshold)\n", humidity);
            if (aht20_read_humidity(fd, &humidity) == 0) {
                if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                    printf("Dehumidifier ON\n");
                    if (ioctl(fd, I2C_SLAVE, AHT20_ADDR) < 0) {
                        perror("ioctl I2C_SLAVE");
                    } else {
                        if (aht20_read_humidity(fd, &humidity) == 0) {
                            if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                                printf("Dehumidifier ON\n");
