#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <time.h>
#include <syslog.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_URL "http://api.example.com/humidity"
#define POLL_INTERVAL_SEC 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (reg select 0x%02X) failed: %s", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        syslog(LOG_ERR, "I2C read (reg 0x%02X) failed: %s", reg, strerror(errno));
        return -1;
    }
    return (int)val;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write (reg 0x%02X, val 0x%02X) failed: %s", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    uint8_t cmd = 0x01;
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, 0x00, cmd) < 0) return -1;
        usleep(10000);

        if (i2c_read_byte(fd, 0x00) < 0) return -1;
        if (i2c_read_byte(fd, 0x01) < 0) return -1;

        buf[0] = i2c_read_byte(fd, 0x00);
        buf[1] = i2c_read_byte(fd, 0x01);

        if (buf[0] == 0x00 && buf[1] == 0x00) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            *humidity = (float)raw / 65536.0f;
            return 0;
        }

        retries++;
        if (retries < MAX_RETRIES) usleep(10000);
    }

    syslog(LOG_ERR, "HTU21D humidity read failed after %d retries", MAX_RETRIES);
    return -1;
}

static int post_humidity(const char *url) {
    int sockfd = -1;
    struct sockaddr_in servaddr;
    int addrlen = sizeof(servaddr);
    char request[256];
    char response[1024];
    int bytes_received;

    syslog(LOG_INFO, "Sending humidity data to %s", url);

    memset(request, 0, sizeof(request));
    snprintf(request, sizeof(request),
             "POST /humidity HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %d\r\n"
             "Connection: close\r\n"
             "\r\n"
             "{\"humidity\": %.2f}", url, (int)strlen(request));

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "socket() failed: %s", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = inet_addr(API_URL);
    servaddr.sin_port = htons(80);

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "connect() failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    bytes_received = send(sockfd, request, strlen(request), 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "send() failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    syslog(LOG_INFO, "Sent humidity data to %s", url);

    memset(response, 0, sizeof(response));
    bytes_received = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "recv() failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    if (bytes_received == 0) {
        syslog(LOG_ERR, "recv() returned 0 bytes");
        close(sockfd);
        return -1;
    }

    syslog(LOG_INFO, "Received %d bytes from %s", bytes_received, url);
    close(sockfd);
    return 0;
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D sensor initialized on 0x%02X", HTU21D_ADDR);

    while (running) {
        float humidity;
        if (read_humidity(i2c_fd, &humidity) == 0) {
            if (post_humidity(API_URL) == 0) {
                syslog(LOG_INFO, "Humidity data sent to %s", API_URL);
            } else {
                syslog(LOG_ERR, "Failed to send humidity data to %s", API_URL);
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity data from %s", API_URL);
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    close(i2c_fd);
    closelog();
    return 0;
}

