#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define MOTOR_RUN_TIME_SEC 5
#define POLL_INTERVAL_SEC 2

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s: %s\n", timestamp, message);
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *enable_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!rain_line || !enable_line || !in1_line || !in2_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("gpiod_line_request_input(rain)");
        goto cleanup;
    }
    if (gpiod_line_request_output(enable_line, "motor_enable", 0) < 0) {
        perror("gpiod_line_request_output(enable)");
        goto cleanup;
    }
    if (gpiod_line_request_input(in1_line, "motor_in1") < 0) {
        perror("gpiod_line_request_input(in1)");
        goto cleanup;
    }
    if (gpiod_line_request_input(in2_line, "motor_in2") < 0) {
        perror("gpiod_line_request_input(in2)");
        goto cleanup;
    }

    log_event("Rain sensor monitoring started.");

    while (program_running) {
        int rain_detected = gpiod_line_get_value(rain_line);
        if (rain_detected < 0) {
            perror("gpiod_line_get_value(rain)");
            log_event("Error reading rain sensor.");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (rain_detected == 0) {
            if (gpiod_line_set_value(enable_line, 1) < 0) {
                perror("gpiod_line_set_value(enable)");
                log_event("Error enabling motor.");
            } else {
                log_event("Rain detected. Motor running.");
                log_event("Motor running for 5 seconds.");
                for (int i = 0; i < MOTOR_RUN_TIME_SEC && program_running; i++) {
                    sleep(1);
                }
                if (gpiod_line_set_value(enable_line, 0) < 0) {
                    perror("gpiod_line_set_value(enable)");
                    log_event("Error stopping motor.");
                } else {
                    log_event("Motor stopped.");
                }
            }
        } else {
            if (gpiod_line_set_value(enable_line, 0) < 0) {
                perror("gpiod_line_set_value(enable)");
                log_event("Error disabling motor.");
            } else {
                log_event("Rain detected. Motor stopped.");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (enable_line) gpiod_line_release(enable_line);
    if (in1_line) gpiod_line_release(in1_line);
    if (in2_line) gpiod_line_release(in2_line);
    if (rain_line) gpiod_line_release(rain_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

