#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27

#define PWM_RANGE   255
#define SAMPLE_MS  500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_load(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen /proc/stat");
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        perror("fgets");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    int load = 0;
    int prev_load = 0;
    int c;

    while ((c = getchar()) != '\n' && c != EOF) {
        if (c == 'c') {
            load = 0;
            prev_load = 0;
        } else if (c == 'u') {
            load = 0;
            prev_load = 0;
        } else if (c == 'p') {
            load = 0;
            prev_load = 0;
        } else if (c == 's') {
            load = 0;
            prev_load = 0;
        } else if (c == 'e') {
            load = 0;
            prev_load = 0;
        } else if (c == 't') {
            load = 0;
            prev_load = 0;
        } else if (c == 'e') {
            load = 0;
            prev_load = 0;
        } else if (c == 'p') {
            load = 0;
            prev_load = 0;
        } else if (c == 'e') {
            load = 0;
            prev_load = 0;
        } else if (c == 'e') {
            load = 0;
            prev_load = 0;
        } else if (c == 'e') {
            load = 0;
            prev_load = 0;
        } else if (c == 'e') {
            load = 0;
            prev_load = 0;
        } else if (c == 'e') {
            load = 0;
            prev_load = 0;
        } else if (c == 'e') {
            load = 0;
            prev_load = 0;
        } else if (c == 'e') {
            load = 0;
            prev_load = 0;
        } else {
            fprintf(stderr, "Unknown character '%c'\n", c);
            return -1;
        }
    }

    if (load == 0) {
        return 0;
    }

    return (int)((load - prev_load) * PWM_RANGE / 100);
}

static void set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN, red) < 0) {
        fprintf(stderr, "gpioPWM failed on RED_PIN\n");
        return;
    }
    if (gpioPWM(GREEN_PIN, green) < 0) {
        fprintf(stderr, "gpioPWM failed on GREEN_PIN\n");
        return;
    }
    if (gpioPWM(BLUE_PIN, blue) < 0) {
        fprintf(stderr, "gpioPWM failed on BLUE_PIN\n");
        return;
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for RED_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GREEN_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for BLUE_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for RED_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GREEN_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for BLUE_PIN\n");
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        int load = read_cpu_load();
        if (load < 0) {
            fprintf(stderr, "Error reading CPU load, exiting\n");
            break;
        }

        int red = (load - 50) * PWM_RANGE / 100;
        int green = (load - 50) * PWM_RANGE / 100;
        int blue = (load - 50) * PWM_RANGE / 100;

        set_led_color(red, green, blue);
        gpioDelay(SAMPLE_MS * 1000);
    }

    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    return 0;
}

