#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 1

typedef struct {
    int16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    int16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int16_t dig_H6;
    uint8_t dig_L1;
    int16_t dig_L2;
    int16_t dig_L3;
} bmp280_calib_data;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int udp_socket = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_calibration_data(int handle, bmp280_calib_data *cal) {
    char buf[24];
    if (i2cReadI2CBlockData(handle, BMP280_REG_CALIB, buf, 24) != 24) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }
    cal->dig_T1 = (buf[1] << 8) | buf[0];
    cal->dig_T2 = (buf[3] << 8) | buf[2];
    cal->dig_T3 = (buf[5] << 8) | buf[4];
    cal->dig_P1 = (buf[7] << 8) | buf[6];
    cal->dig_P2 = (buf[9] << 8) | buf[8];
    cal->dig_P3 = (buf[11] << 8) | buf[10];
    cal->dig_P4 = (buf[13] << 8) | buf[12];
    cal->dig_P5 = (buf[15] << 8) | buf[14];
    cal->dig_P6 = (buf[17] << 8) | buf[16];
    cal->dig_P7 = (buf[19] << 8) | buf[18];
    cal->dig_P8 = (buf[21] << 8) | buf[20];
    cal->dig_P9 = (buf[23] << 8) | buf[22];
    cal->dig_H1 = buf[25];
    cal->dig_H2 = (buf[27] << 8) | buf[26];
    cal->dig_H3 = buf[29];
    cal->dig_H4 = (buf[31] << 8) | buf[30];
    cal->dig_H5 = (buf[33] << 8) | buf[32];
    cal->dig_H6 = (buf[35] << 8) | buf[34];
    cal->dig_L1 = buf[37];
    cal->dig_L2 = (buf[39] << 8) | buf[38];
    cal->dig_L3 = (buf[41] << 8) | buf[40];
    return 0;
}

int read_bmp280_data(int handle, bmp280_calib_data *cal, int32_t *raw_temperature, int32_t *raw_pressure) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }
    *raw_pressure = ((int32_t)(buf[0] << 12) >> 12) | ((int32_t)(buf[1] << 4) >> 4);
    *raw_temperature = ((int32_t)(buf[2] << 12) >> 12) | ((int32_t)(buf[3] << 4) >> 4);
    *raw_temperature = (*raw_temperature - 768) * 0.004875;
    *raw_temperature = (*raw_temperature - (int32_t)cal->dig_T1) * (int32_t)cal->dig_T2 / 1024.0;
    *raw_temperature = (*raw_temperature - (*raw_temperature * cal->dig_T3) / 524288.0) + cal->dig_T4;
    *raw_temperature = (*raw_temperature - (*raw_temperature * cal->dig_T5) / 2.0) * cal->dig_T6 / 524288.0;
