    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, pressure;
    bmp180_data_t data;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", BMP180_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as input\n", GPIO_PIN);
        cleanup();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO%d\n", GPIO_PIN);
        cleanup();
        return 1;
    }

    if (gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, bmp180_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for GPIO%d\n", GPIO_PIN);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler\n");
        cleanup();
        return 1;
    }

    printf("BMP180 logging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_bmp180(i2c_handle, &temperature, &pressure) == 0) {
            data.temperature = temperature;
            data.pressure = pressure;

            if (log_data(temperature, pressure) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Error reading BMP180 data\n");
        }

        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

