#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_CS_PIN 8
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int spi_read_register(unsigned char reg, unsigned char *value) {
    unsigned char tx[2] = {0x00, reg};
    unsigned char rx[2] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to set CS low");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to set CS high");
        return -1;
    }

    *value = rx[1];
    return 0;
}

int read_rtd_temperature(float *temperature) {
    unsigned char status = 0;
    unsigned char data[4];

    if (spi_read_register(0x00, &status) < 0) {
        fprintf(stderr, "Failed to read status register\n");
        return -1;
    }

    if (status & 0x01) {
        fprintf(stderr, "RTD fault detected\n");
        return -1;
    }

    if (spi_read_register(0x01, data) < 0) {
        fprintf(stderr, "Failed to read RTD data\n");
        return -1;
    }

    unsigned int raw_temp = (data[0] << 8) | data[1];
    unsigned int raw_cal = (data[2] << 8) | data[3];

    *temperature = raw_temp / 100.0f;
    return 0;
}

int log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, temperature) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, SPI_CS_PIN);
    if (!cs_line) {
        perror("Failed to get CS line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "rtd_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("RTD Temperature Logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_rtd_temperature(&temperature) == 0) {
            if (log_data(temperature) == 0) {
                printf("Temperature: %.2f C\n", temperature);
            } else {
                fprintf(stderr, "Failed to log temperature\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

