#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_REG_CAL_XLSB 0xBF

#define OVERSAMPLING_0 0x00
#define OVERSAMPLING_1 0x01
#define OVERSAMPLING_2 0x02
#define OVERSAMPLING_3 0x03

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE 0x34

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_calibration_data(int handle) {
    uint8_t buf[24];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_AC1, (char *)buf, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    int16_t ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    int16_t ac4 = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t ac5 = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t ac6 = (int16_t)((buf[10] << 8) | buf[11]);
    int16_t b1 = (int16_t)((buf[12] << 8) | buf[13]);
    int16_t b2 = (int16_t)((buf[14] << 8) | buf[15]);
    int16_t mb = (int16_t)((buf[16] << 8) | buf[17]);
    int16_t mc = (int16_t)((buf[18] << 8) | buf[19]);
    int16_t md = (int16_t)((buf[20] << 8) | buf[21]);
    int16_t xlsb = (int16_t)((buf[22] << 8) | buf[23]);
    return (int)((ac1 * 5 + (ac2 * 10) + (ac3 * 100)) >> 8);
}

int read_raw_temperature(int handle) {
    uint8_t buf[2];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read raw temperature\n");
        return -1;
    }
    int32_t raw_temp = (int32_t)((buf[0] << 8) | buf[1]);
    return (int)(raw_temp >> 4);
}

int read_raw_pressure(int handle) {
    uint8_t buf[3];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return -1;
    }
    int32_t raw_pressure = (int32_t)((buf[0] << 16) | (buf[1] << 8) | buf[2]);
    int32_t b5 = raw_pressure - (int32_t)ac6;
    b5 = (b5 >> 11) - (int32_t)ac5;
    int32_t b6 = (int32_t)((ac2 * b5) >> 11);
    int32_t b7 = ((int32_t)raw_pressure - (int32_t)b6) * (int32_t)oversampling;
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / (int32_t)oversampling;
    } else {
        p = (b7 / (int32_t)oversampling) * 2;
    }
    int32_t p2 = p - (int32_t)ac4;
    p2 = (p2 >> 4) * (p2 >> 4);
    p2 = (p2 + (int32_t)ac3) >> 8;
    p = (p2 * (int32_t)oversampling) >> 4;
    return (int)(p);
}

int bmp180_init(int handle) {
    uint8_t cal_buf[24];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_AC1, (char *)cal_buf, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    int16_t ac1 = (int16_t)((cal_buf[0] << 8) | cal_buf[1]);
    int16_t ac2 = (int16_t)((cal_buf[2] << 8) | cal_buf[3]);
    int16_t ac3 = (int16_t)((cal_buf[4] << 8) | cal_buf[5]);
    int16_t ac4 = (int16_t)((cal_buf[6] << 8) | cal_buf[7]);
    int16_t ac5 = (int16_t)((cal_buf[8] << 8) | cal_buf[9]);
    int16_t ac6 = (int16_t)((cal_buf[10] << 8) | cal_buf[11]);
    int16_t b1 = (int16_t)((cal_buf[12] << 8) | cal_buf[13]);
    int16_t b2 = (int16_t)((cal_buf[14] << 8) | cal_buf[15]);
    int16_t mb = (int16_t)((cal_buf[16] << 8) | cal_buf[17]);
    int16_t mc = (int16_t)((cal_buf[18] << 8) | cal_buf[19]);
    int16_t md = (int16_t)((cal_buf[20] << 8) | cal_buf[21]);
    int16_t xlsb = (int16_t)((cal_buf[22] << 8) | cal_buf[23]);
    if (i2cWriteByteData(handle, BMP180_REG_CAL_AC1, (char)ac1) != 0) {
        fprintf(stderr, "Error: Failed to write AC1\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_AC2, (char)ac2) != 0) {
        fprintf(stderr, "Error: Failed to write AC2\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_AC3, (char)ac3) != 0) {
        fprintf(stderr, "Error: Failed to write AC3\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_AC4, (char)ac4) != 0) {
        fprintf(stderr, "Error: Failed to write AC4\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_AC5, (char)ac5) != 0) {
        fprintf(stderr, "Error: Failed to write AC5\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_AC6, (char)ac6) != 0) {
        fprintf(stderr, "Error: Failed to write AC6\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_B1, (char)b1) != 0) {
        fprintf(stderr, "Error: Failed to write B1\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_B2, (char)b2) != 0) {
        fprintf(stderr, "Error: Failed to write B2\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_MB, (char)mb) != 0) {
        fprintf(stderr, "Error: Failed to write MB\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_MC, (char)mc) != 0) {
        fprintf(stderr, "Error: Failed to write MC\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_MD, (char)md) != 0) {
        fprintf(stderr, "Error: Failed to write MD\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP180_REG_CAL_XLSB, (char)xlsb) != 0) {
        fprintf(stderr, "Error: Failed to write XLSB\n");
        return -1;
    }
    return 0;
}

int bmp180_read_data(int handle, int *temp_c, int *pressure_pa) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read data\n");
        return -1;
    }
    int32_t raw_temp = (int32_t)((data[0] << 8) | data[1]);
    int32_t raw_pressure = (int32_t)((data[2] << 8) | data[3]);
    int32_t b5 = raw_pressure - (int32_t)ac6;
    b5 = (b5 >> 11) - (int32_t)ac5;
    int32_t b6 = (int32_t)((data[4] << 8) | data[5]);
    b6 = (b6 >> 4) * (int32_t)oversampling;
    int32_t p = (b6 * (int32_t)2) / (int32_t)((int32_t)32768 + (int32_t)b5);
    p = (p >> 2) - (int32_t)ac3;
    p = (p * (int32_t)oversampling) / (int32_t)((int32_t)32768 + (int32_t)b5);
    *temp_c = (int)((p / 256) * 100);
    *pressure_pa = (int)(p / 256);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x77\n");
        gpioTerminate();
        return 1;
    }
    if (bmp180_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: BMP180 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
