    int32_t p2 = p - (int32_t)ac4;
    p2 = (p2 >> 4) * (p2 >> 4);
    p2 = (p2 + (int32_t)ac3) >> 8;
    p = (p2 * (int32_t)oversampling) >> 4;
    return (int)(p);
