#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define LOG_FILE "fan_log.txt"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    int temp_raw;
    if (fscanf(fp, "%d", &temp_raw) != 1) {
        fprintf(stderr, "Failed to read temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_raw;
}

static int map_temperature(int temp) {
    if (temp < 40) return 0;
    if (temp > 70) return PWM_RANGE;
    return (int)((temp - 40) * PWM_RANGE / 30);
}

static int set_fan_speed(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static void log_data(int temp, int duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, Temperature: %d, Fan Speed: %d\n", timestamp, temp, duty);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp = read_temperature();
        if (temp < 0) {
            fprintf(stderr, "Temperature read failed, retrying...\n");
            sleep(5);
            continue;
        }

        int duty = map_temperature(temp);
        if (set_fan_speed(duty) != 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }

        log_data(temp, duty);
        printf("Temperature: %d, Fan Speed: %d\n", temp, duty);

        sleep(5);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

