#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

#define BMP280_CHIP_ID 0x58

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "weather_data.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read block from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration(int fd, uint8_t *cal) {
    uint8_t buf[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, buf, sizeof(buf)) < 0) return -1;
    for (int i = 0; i < 24; i++) {
        cal[i] = (uint8_t)buf[i];
    }
    return 0;
}

static int read_raw(int fd, uint16_t *temp, uint16_t *press) {
    uint8_t buf[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, buf, sizeof(buf)) < 0) return -1;
    *press = ((uint16_t)buf[0] << 12) | ((uint16_t)buf[1] << 4) | ((uint16_t)buf[2] >> 4);
    *temp = ((uint16_t)buf[3] << 12) | ((uint16_t)buf[4] << 4) | ((uint16_t)buf[5] >> 4);
    return 0;
}

static int32_t compensate_temp(int32_t raw_t) {
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)cal[3] << 1))) * ((int32_t)cal[4])) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)cal[3] << 1))) * ((raw_t >> 4) - ((int32_t)cal[3] << 1))) >> 12) * ((int32_t)cal[5]) >> 12;
    var1 = (var1 * (unsigned int)cal[6]) >> 0x40;
    var2 = (var2 * (unsigned int)cal[7]) >> 0x40;
    var1 += (var2 >> 4);
    var2 = var1 * ((int32_t)cal[8]) >> 0x0F;
    raw_t = ((var1 + var2) >> 4);
    return (int32_t)(raw_t * 5 + 128) / 100;
}

static int32_t compensate_press(int32_t raw_p) {
    int32_t var1, var2;
    var1 = ((int32_t)raw_p - ((int32_t)cal[3] << 4)) * ((int32_t)cal[4]) >> 11;
    var2 = ((int32_t)raw_p - ((int32_t)cal[3] << 4)) * ((int32_t)cal[5]) >> 12;
    var1 = (var1 * (unsigned int)cal[6]) >> 0x40;
    var2 = (var2 * (unsigned int)cal[7]) >> 0x40;
    var1 = (var1 + (unsigned int)cal[8]) >> 0x0F;
    var2 = (var2 * ((int32_t)cal[9]) >> 0x0F) * ((int32_t)cal[10]) >> 0x0F;
