#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define TEMP_REG       0x00
#define LED_PIN        18
#define TEMP_THRESHOLD 28.0f
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1000000  /* microseconds */
#define LOG_FILE       "temperature.log"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_led_line = NULL;
static struct gpiod_line_event_queue *g_event_queue = NULL;
static struct timespec g_last_sample_time = {0, 0};

/* ---- Prototypes ---- */
static int  init_i2c(void);
static int  init_led(void);
static int  read_temperature(float *temp_out);
static void log_temperature(float temp);
static void trigger_led(float temp);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- I2C init ---- */
static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                LM75_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

/* ---- GPIO init ---- */
static int init_led(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return -1;
    }
    g_led_line = gpiod_chip_get_line(g_chip, LED_PIN);
    if (!g_led_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                LED_PIN, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(g_led_line, "lm75_led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_led_line = NULL;
        return -1;
    }
    return 0;
}

/* ---- Read temperature ---- */
static int read_temperature(float *temp_out)
{
    uint8_t reg = TEMP_REG;
    uint8_t buf[2];
    int rc;

    rc = i2c_smbus_read_i2c_block_data(g_i2c_fd, reg, 2, buf);
    if (rc < 0) {
        fprintf(stderr, "i2c_smbus_read_i2c_block_data: %s\n",
                strerror(errno));
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "i2c_smbus_read_i2c_block_data: expected 2 bytes, got %d\n",
                rc);
        return -1;
    }

    /* LM75 data is two's-complement, MSB first, left-shifted by 5 bits */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    raw >>= 5;
    *temp_out = (float)raw / 256.0f;
    return 0;
}

/* ---- Log temperature ---- */
static void log_temperature(float temp)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp);
    } else {
        fprintf(fp, "unknown, %.2f\n", temp);
    }
    fclose(fp);
}

/* ---- Trigger LED ---- */
static void trigger_led(float temp)
{
    if (gpiod_line_set_value(g_led_line, temp > TEMP_THRESHOLD ? 1 : 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_event_queue) {
        gpiod_line_event_queue_destroy(g_event_queue);
        g_event_queue = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
