#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 1
#define SPI_CE 0

#define RTD_REF_OHM 430.0
#define RTD_RES_OHM 100.0
#define RTD_MAX_CODE 32768.0
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_FAULT_REG 0x07
#define MAX31865_RTD_CODE_MSB 0x01
#define MAX31865_RTD_CODE_LSB 0x02

#define DEFAULT_TARGET_TEMP 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01

#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 1000

#define HEATER_ON 0
#define HEATER_OFF 1

typedef struct {
    double target_temp;
    double kp;
    double ki;
    double kd;
} ConfigParams;

static ConfigParams config = {DEFAULT_TARGET_TEMP, DEFAULT_KP, DEFAULT_KI, DEFAULT_KD};

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)value;
    buf[2] = 0;
    if (spiWrite(spi_handle, buf, 3) != 3) {
        fprintf(stderr, "SPI write failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (char)reg;
    if (spiWrite(spi_handle, buf, 1) != 1) {
        fprintf(stderr, "SPI write failed for reg 0x%02X\n", reg);
        return -1;
    }
    if (spiRead(spi_handle, buf, 1) != 1) {
        fprintf(stderr, "SPI read failed for reg 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

static int spi_read_reg_msb(uint8_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (char)reg;
    if (spiWrite(spi_handle, buf, 1) != 1) {
        fprintf(stderr, "SPI write failed for reg 0x%02X\n", reg);
        return -1;
    }
    if (spiRead(spi_handle, buf, 1) != 1) {
        fprintf(stderr, "SPI read failed for reg 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

static int spi_read_reg_lsb(uint8_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (char)reg;
    if (spiWrite(spi_handle, buf, 1) != 1) {
        fprintf(stderr, "SPI write failed for reg 0x%02X\n", reg);
        return -1;
    }
    if (spiRead(spi_handle, buf, 1) != 1) {
        fprintf(stderr, "SPI read failed for reg 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

static int read_rtd_code(int spi_handle, uint16_t *code) {
    uint8_t msb, lsb;
    if (spi_read_reg_msb(MAX31865_RTD_CODE_MSB, &msb) != 0) return -1;
    if (spi_read_reg_lsb(MAX31865_RTD_CODE_LSB, &lsb) != 0) return -1;
    *code = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int read_fault(int spi_handle) {
    uint8_t status;
    if (spi_read_reg(MAX31865_FAULT_REG, &status) != 0) return -1;
    return (status & 0x01) ? 1 : 0;
}

static double calculate_resistance(uint16_t code) {
    return (code / 32768.0) * RTD_RES_OHM;
}

static double calculate_temperature(double resistance) {
    return (resistance / RTD_RES_OHM) * (RTD_MAX_CODE / RTD_RES_OHM) * (1.0 + config.kp * resistance + config.ki * resistance * resistance);
}

static int set_heater_duty(double temperature) {
    double duty = (temperature - config.target_temp) / config.kd;
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    if (gpioPWM(HEATER_PIN, (int)duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(HEATER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(HEATER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set heater pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);
    gpioPWM(HEATER_PIN, 0);

    if (gpioSetMode(HEATER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set heater pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(HEATER_PIN, heater_alert_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetWarningFuncEx(HEATER_PIN, heater_warning_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set warning function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetFaultFuncEx(HEATER_PIN, heater_fault_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set fault function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetLogFuncEx(HEATER_PIN, heater_log_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set log function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting heater control. Target: %.1f°C, PWM: %d%%\n", config.target_temp, config.kp);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint16_t code = 0;
        if (read_rtd_code(spi_handle, &code) != 0) {
            fprintf(stderr, "Failed to read RTD code\n");
            break;
        }

        if (code == 0) {
            fprintf(stderr, "RTD code is 0, skipping heater control\n");
            gpioDelay(100000);
            continue;
        }

        uint16_t fault = 0;
        if (read_fault(spi_handle) != 0) {
            fprintf(stderr, "Failed to read fault\n");
            gpioDelay(100000);
            continue;
        }

        if (fault & 0x01) {
            fprintf(stderr, "RTD fault detected\n");
            gpioDelay(100000);
            continue;
        }

        double resistance = calculate_resistance(code);
        double temperature = calculate_temperature(resistance);
        double duty = (temperature - config.target_temp) / config.kd;
        if (duty < 0) duty = 0;
        if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

        if (set_heater_duty(temperature) != 0) {
            fprintf(stderr, "Failed to set heater duty\n");
            break;
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

