    uint8_t status;
    if (spi_read_reg(MAX31865_FAULT_REG, &status) != 0) return -1;
    return (status & 0x01) ? 1 : 0;
}

static double calculate_resistance(uint16_t code) {
    return (code / 32768.0) * RTD_RES_OHM;
}

static double calculate_temperature(double resistance) {
    return (resistance / RTD_RES_OHM) * (RTD_MAX_CODE / RTD_RES_OHM) * (1.0 + config.kp * resistance + config.ki * resistance * resistance);
}

static int set_heater_duty(double temperature) {
    double duty = (temperature - config.target_temp) / config.kd;
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    if (gpioPWM(HEATER_PIN, (int)duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(HEATER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(HEATER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set heater pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);
    gpioPWM(HEATER_PIN, 0);

    if (gpioSetMode(HEATER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set heater pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(HEATER_PIN, heater_alert_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetWarningFuncEx(HEATER_PIN, heater_warning_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set warning function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetFaultFuncEx(HEATER_PIN, heater_fault_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set fault function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetLogFuncEx(HEATER_PIN, heater_log_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set log function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting heater control. Target: %.1f°C, PWM: %d%%\n", config.target_temp, config.kp);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint16_t code = 0;
        if (read_rtd_code(spi_handle, &code) != 0) {
            fprintf(stderr, "Failed to read RTD code\n");
            break;
        }

        if (code == 0) {
            fprintf(stderr, "RTD code is 0, skipping heater control\n");
            gpioDelay(100000);
            continue;
        }

        uint16_t fault = 0;
        if (read_fault(spi_handle) != 0) {
            fprintf(stderr, "Failed to read fault\n");
            gpioDelay(100000);
            continue;
        }

        if (fault & 0x01) {
            fprintf(stderr, "RTD fault detected\n");
            gpioDelay(100000);
            continue;
        }

        double resistance = calculate_resistance(code);
        double temperature = calculate_temperature(resistance);
        double duty = (temperature - config.target_temp) / config.kd;
        if (duty < 0) duty = 0;
        if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

        if (set_heater_duty(temperature) != 0) {
            fprintf(stderr, "Failed to set heater duty\n");
            break;
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

