#define BREACH_THRESHOLD 30.0f
#define PRESSURE_BREACH_THRESHOLD 950.0f
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int i2c_read_reg24(int fd, uint8_t reg, uint32_t *val) {
    uint8_t buf[3];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 3) != 3) return -1;
    *val = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    return 0;
}

static int bmp180_init(int fd) {
    uint8_t ver[3];
    if (i2c_read_reg8(fd, 0xAA, ver) < 0) return -1;
    if (ver[0] != 0x55) {
        fprintf(stderr, "BMP180 version mismatch: got 0x%02X, expected 0x55\n", ver[0]);
        return -1;
    }
    if (i2c_read_reg8(fd, 0xF4, &ver[2]) < 0) return -1;
    if (ver[2] != 0x86) {
        fprintf(stderr, "BMP180 version mismatch: got 0x%02X, expected 0x86\n", ver[2]);
        return -1;
    }
    if (i2c_read_reg8(fd, 0xBA, &ver[3]) < 0) return -1;
    if (ver[3] != 0x27) {
        fprintf(stderr, "BMP180 version mismatch: got 0x%02X, expected 0x27\n", ver[3]);
        return -1;
    }
    if (i2c_read_reg8(fd, 0x2E, &ver[4]) < 0) return -1;
    if (ver[4] != 0x75) {
        fprintf(stderr, "BMP180 version mismatch: got 0x%02X, expected 0x75\n", ver[4]);
        return -1;
    }
    return 0;
}

static int bmp180_read_raw(int fd, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t data[6];
    if (i2c_read_reg24(fd, 0x88, data) < 0) return -1;
    *raw_temp = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    *raw_press = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    return 0;
