    var2 = ((int32_t)0 - ((int32_t)raw_temp) * ((int32_t)0x10000)) >> 15;
    return (var1 * (var1 * (int32_t)0x10000 - (int32_t)34125)) >> 15;
}

static float bmp180_calculate_pressure(int32_t raw_press) {
    int32_t var1, var2;
    var1 = ((int32_t)raw_press >> 4) - ((int32_t)32600);
    var2 = ((var1 >> 2) * (var1 >> 2)) >> 11;
    var2 = var2 * ((int32_t)0x000003F8);
    var1 = (((int32_t)raw_press - (var1 >> 2)) * (int32_t)2) >> 13;
    var2 = var2 + var1;
    int32_t p;
    if (var2 == 0) return 0.0f;
    p = (var1 * (int32_t)0x0000078B + (var2 >> 4)) >> 11;
    var1 = ((int32_t)raw_press - p) * (int32_t)0.00001576f;
    var2 = p * (int32_t)0.00002953f;
    p = (int32_t)((var1 + var2) + (int32_t)0.5f);
    return (float)p / (float)10000.0f;
}

static void log_breach(FILE *log_file, float temp, float press) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Temp: %.2fC, Pressure: %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, press);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    if (bmp180_init(fd) < 0) {
        fprintf(stderr, "BMP180 initialization failed\n");
        close(fd);
        return 1;
    }

    FILE *log_file = fopen("breach_log.txt", "a");
    if (!log_file) {
        perror("fopen breach_log.txt");
        close(fd);
        return 1;
    }

    while (running) {
        int32_t raw_temp, raw_press;
        if (bmp180_read_raw(fd, &raw_temp, &raw_press) < 0) {
            fprintf(stderr, "I2C read error, retrying in %d seconds\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float temp = bmp180_calculate_temperature(raw_temp);
        float press = bmp180_calculate_pressure(raw_press);

        if (temp > BREACH_THRESHOLD || press < PRESSURE_BREACH_THRESHOLD) {
            log_breach(log_file, temp, press);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    fclose(log_file);
    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

