#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define BMP180_ADDR 0x77
#define I2C_BUS 1
#define FAN_GPIO 18
#define TEMP_THRESHOLD 30.0f
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 500000
#define BMP180_REG_CALIB_START 0xAA
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_DATA 0xF6

static int i2c_handle = -1;
static FILE *buffer_file = NULL;
static volatile sig_atomic_t running = 1;

typedef struct {
    float temperature;
    float pressure;
} bmp180_data_t;

static bmp180_data_t buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(int handle) {
    char calib[24];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CALIB_START, calib, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    uint16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    ac1 = (uint16_t)((calib[0] << 8) | calib[1]);
    ac2 = (uint16_t)((calib[2] << 8) | calib[3]);
    ac3 = (uint16_t)((calib[4] << 8) | calib[5]);
    b1  = (uint16_t)((calib[6] << 8) | calib[7]);
    b2  = (uint16_t)((calib[8] << 8) | calib[9]);
    mb  = (uint16_t)((calib[10] << 8) | calib[11]);
    mc  = (uint16_t)((calib[12] << 8) | calib[13]);
    md  = (uint16_t)((calib[14] << 8) | calib[15]);
    buffer[0] = ac1; buffer[1] = ac2; buffer[2] = ac3;
    buffer[3] = b1; buffer[4] = b2; buffer[5] = mb;
    buffer[6] = mc; buffer[7] = md;
    return 0;
}

static int read_raw_data(int handle, int32_t *raw_temp, int32_t *raw_press) {
    char data[6];
    if (i2cWriteByte(handle, BMP180_REG_CONTROL) != 0) {
        fprintf(stderr, "Error: Failed to set control register\n");
        return -1;
    }
    gpioDelay(2000);
    if (i2cReadI2CBlockData(handle, BMP180_REG_DATA, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }
    *raw_temp = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    *raw_press = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    return 0;
}

static float compensate_temperature(int32_t raw_temp, const bmp180_data_t *cal) {
    int32_t var1, var2, T;
    var1 = ((((raw_temp >> 3) - ((int32_t)cal->temperature >> 1))) * ((int32_t)cal->temperature >> 1)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)cal->temperature)) * ((raw_temp >> 4) - ((int32_t)cal->temperature))) >> 12) * ((int32_t)cal->temperature >> 1)) >> 15;
    T = var1 + var2;
    return (float)T / 5120.0f;
}

static float compensate_pressure(int32_t raw_press, const bmp180_data_t *cal) {
    int32_t var1, var2, p;
    var1 = ((((raw_press >> 1) - ((int32_t)cal->pressure >> 1))) * ((int32_t)cal->pressure >> 1)) >> 12;
    var2 = (((((raw_press >> 2) - ((int32_t)cal->pressure)) * ((raw_press >> 2) - ((int32_t)cal->pressure))) >> 13) * ((int32_t)cal->pressure >> 1)) >> 14;
    p = 1048576 - raw_press;
    p = (((p << 31) - var1) - ((var2 >> 12) * 31125)) / (var1 * 2);
    var1 = (((int32_t)cal->pressure) - (p / 25600.0f));
    var2 = (((var1 >> 1) * var1) >> 11) * (int32_t)cal->oss;
    if (var2 != 0) {
        p = ((p + (var2 + ((int32_t)cal->oss / 4))) / 2) >> (1 - (int32_t)cal->oss);
    }
    return (float)p / 100.0f;
}

static void add_to_buffer(float temperature, float pressure) {
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (buffer_file) {
        fclose(buffer_file);
        buffer_file = NULL;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data(i2c_handle) != 0) {
        fprintf(stderr, "Error: Failed to read BMP180 calibration data\n");
        cleanup();
        return 1;
    }
    buffer_file = fopen("bmp180_buffer.txt", "a");
    if (!buffer_file) {
        fprintf(stderr, "Error: Failed to open buffer file\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
