#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN      17
#define GREEN_PIN    18
#define BLUE_PIN     27
#define TEMP_FILE    "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE    255
#define PWM_OFF      255
#define PWM_ON       0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_temperature(float *temp_out)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int raw;
    if (fscanf(fp, "%d", &raw) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    int m_deg = raw / 1000;
    *temp_out = m_deg * 0.001f;
    return 0;
}

static void set_rgb_led(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN, PWM_ON) != 0) {
        fprintf(stderr, "Error setting PWM on RED_PIN\n");
        return;
    }
    if (gpioPWM(GREEN_PIN, PWM_ON) != 0) {
        fprintf(stderr, "Error setting PWM on GREEN_PIN\n");
        gpioPWM(RED_PIN, PWM_OFF);
        return;
    }
    if (gpioPWM(BLUE_PIN, PWM_ON) != 0) {
        fprintf(stderr, "Error setting PWM on BLUE_PIN\n");
        gpioPWM(RED_PIN, PWM_OFF);
        return;
    }
    if (red < 0) red = 0;
    if (green < 0) green = 0;
    if (blue < 0) blue = 0;
    if (red > PWM_RANGE) red = PWM_RANGE;
    if (green > PWM_RANGE) green = PWM_RANGE;
    if (blue > PWM_RANGE) blue = PWM_RANGE;
    if (red > PWM_ON) {
        gpioPWM(RED_PIN, PWM_OFF);
        gpioPWM(GREEN_PIN, PWM_OFF);
        gpioPWM(BLUE_PIN, PWM_OFF);
    } else if (green > PWM_ON) {
        gpioPWM(RED_PIN, PWM_OFF);
        gpioPWM(GREEN_PIN, PWM_ON);
        gpioPWM(BLUE_PIN, PWM_OFF);
    } else if (blue > PWM_ON) {
        gpioPWM(RED_PIN, PWM_OFF);
        gpioPWM(GREEN_PIN, PWM_OFF);
        gpioPWM(BLUE_PIN, PWM_ON);
    } else {
        gpioPWM(RED_PIN, PWM_OFF);
        gpioPWM(GREEN_PIN, PWM_OFF);
        gpioPWM(BLUE_PIN, PWM_OFF);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(RED_PIN, PWM_OFF) != 0 ||
        gpioPWM(GREEN_PIN, PWM_OFF) != 0 ||
        gpioPWM(BLUE_PIN, PWM_OFF) != 0) {
        fprintf(stderr, "Failed to initialise PWM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temp_c = 0.0f;
    while (g_running) {
        if (read_temperature(&temp_c) != 0) {
            fprintf(stderr, "Temperature read failed; skipping update cycle\n");
        } else {
            int red = (int)((temp_c * 0.5f) - 50.0f);
            int green = (int)((temp_c * 0.5f) - 50.0f);
            int blue = (int)((temp_c * 0.5f) - 50.0f);

            if (red < 0) red = 0;
            if (green < 0) green = 0;
            if (blue < 0) blue = 0;
            if (red > PWM_ON) {
                gpioPWM(RED_PIN, PWM_OFF);
                gpioPWM(GREEN_PIN, PWM_OFF);
                gpioPWM(BLUE_PIN, PWM_OFF);
            } else if (green > PWM_ON) {
                gpioPWM(RED_PIN, PWM_OFF);
                gpioPWM(GREEN_PIN, PWM_ON);
                gpioPWM(BLUE_PIN, PWM_OFF);
            } else if (blue > PWM_ON) {
                gpioPWM(RED_PIN, PWM_OFF);
                gpioPWM(GREEN_PIN, PWM_OFF);
                gpioPWM(BLUE_PIN, PWM_ON);
            } else {
                gpioPWM(RED_PIN, PWM_OFF);
                gpioPWM(GREEN_PIN, PWM_OFF);
                gpioPWM(BLUE_PIN, PWM_OFF);
            }

            set_rgb_led(red, green, blue);
            printf("Temperature: %.2f m°C, Red: %d, Green: %d, Blue: %d\n",
                   temp_c, red, green, blue);
        }
        sleep(0.5);
    }

    /* Clean shutdown */
    gpioPWM(RED_PIN, PWM_OFF);
    gpioPWM(GREEN_PIN, PWM_OFF);
    gpioPWM(BLUE_PIN, PWM_OFF);
    gpioTerminate();
    return EXIT_SUCCESS;
}

