#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define TIMEOUT_MS 5000

static volatile sig_atomic_t running = 1;
static int curl_handle = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_dht22(int pin) {
    if (gpioWrite(pin, PI_LOW) < 0) return -1;
    gpioDelay(2000);
    if (gpioWrite(pin, PI_HIGH) < 0) return -1;
    gpioDelay(2000);
    if (gpioWrite(pin, PI_LOW) < 0) return -1;
    gpioDelay(2000);

    uint8_t data[5] = {0};
    for (int i = 0; i < 5; i++) {
        if (gpioRead(pin) == PI_HIGH) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22 checksum error: expected %02X, got %02X\n", checksum, data[4]);
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int send_http_post(const char *url, const char *json) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize curl\n");
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, NULL);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, TIMEOUT_MS);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, TIMEOUT_MS);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_cleanup(curl);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(DHT22_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set DHT22 pin mode\n");
        gpioTerminate();
        return 1;
    }

    curl_handle = curl_easy_init();
    if (!curl_handle) {
        fprintf(stderr, "Failed to initialize curl\n");
        gpioTerminate();
        return 1;
    }

    curl_easy_setopt(curl_handle, CURLOPT_TIMEOUT, TIMEOUT_MS);
    curl_easy_setopt(curl_handle, CURLOPT_CONNECTTIMEOUT, TIMEOUT_MS);
    curl_easy_setopt(curl_handle, CURLOPT_NOSIGNAL, 1L);
    curl_easy_setopt(curl_handle, CURLOPT_HTTPHEADER, NULL);
    curl_easy_setopt(curl_handle, CURLOPT_POSTFIELDS, NULL);
    curl_easy_setopt(curl_handle, CURLOPT_POST, 0L);
    curl_easy_setopt(curl_handle, CURLOPT_HTTPGET, 1L);

    printf("DHT22 sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int humidity = read_dht22(DHT22_PIN);
        if (humidity < 0) {
            fprintf(stderr, "Failed to read humidity, retrying...\n");
            sleep(RETRY_DELAY_MS / 1000);
            continue;
