#define DHT22_PIN 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define TIMEOUT_MS 5000

static volatile sig_atomic_t running = 1;
static int curl_handle = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_dht22(int pin) {
    if (gpioWrite(pin, PI_LOW) < 0) return -1;
    gpioDelay(2000);
    if (gpioWrite(pin, PI_HIGH) < 0) return -1;
    gpioDelay(2000);
    if (gpioWrite(pin, PI_LOW) < 0) return -1;
    gpioDelay(2000);

    uint8_t data[5] = {0};
    for (int i = 0; i < 5; i++) {
        if (gpioRead(pin) == PI_HIGH) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22 checksum error: expected %02X, got %02X\n", checksum, data[4]);
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int send_http_post(const char *url, const char *json) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize curl\n");
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, NULL);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, TIMEOUT_MS);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, TIMEOUT_MS);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
