        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    if (read_calibration(i2c_handle) != 0) {
        fprintf(stderr, "Error: calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(GPIO_BUTTON, PI_PUD_UP);
    signal(SIGINT, signal_handler);
    printf("BMP180 logging started. Press Ctrl+C to toggle.\n");
    while (running) {
        int32_t ut = read_raw_temperature(i2c_handle);
        if (ut == -1) {
            fprintf(stderr, "Error: temperature read failed\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        int32_t t_fine = compensate_temperature(ut, 0);
        int32_t p = read_raw_pressure(i2c_handle);
        if (p == -1) {
            fprintf(stderr, "Error: pressure read failed\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        int32_t t = compensate_pressure(ut, t_fine);
        log_pressure(i2c_handle, ut, t, p);
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Logging stopped.\n");
    return 0;
}

