#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

typedef struct {
    int fan_speed;
    int max_speed;
    int current_speed;
} FanControlState;

static FanControlState fan_state = {0, 0, 0};
static volatile sig_atomic_t program_running = 1;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    }
}

static void log_error(const char *message) {
    char buf[256];
    snprintf(buf, sizeof(buf), "ERROR: %s (errno: %d - %s)", message, errno, strerror(errno));
    log_message(buf);
}

static int read_temperature(int *temperature) {
    char temp_path[64];
    snprintf(temp_path, sizeof(temp_path), "%s/temp", TEMP_FILE);
    int fd = open(temp_path, O_RDONLY);
    if (fd < 0) {
        log_error("Failed to open temperature file");
        return -1;
    }
    char buf[16];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    if (n < 0) {
        log_error("Failed to read temperature");
        close(fd);
        return -1;
    }
    buf[n] = '\0';
    close(fd);
    *temperature = (int)strtol(buf, NULL, 10);
    return 0;
}

static int set_fan_speed(int speed) {
    char state_path[64];
    snprintf(state_path, sizeof(state_path), "%s/cur_state", FAN_FILE);
    int fd = open(state_path, O_WRONLY);
    if (fd < 0) {
        log_error("Failed to open cooling device state file");
        return -1;
    }
    char state_str[16];
    snprintf(state_str, sizeof(state_str), "%d", speed);
    if (write(fd, state_str, strlen(state_str)) < 0) {
        log_error("Failed to write cooling device state");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int validate_fan_speed(int speed) {
    if (speed < 0) speed = 0;
    if (speed > fan_state.max_speed) {
        log_error("Fan speed out of bounds");
        return -1;
    }
    return 0;
}

static int set_fan_speed_state(int speed, int max_speed) {
    if (validate_fan_speed(speed) == 0) {
        if (set_fan_speed(speed) == 0) {
            if (speed == max_speed) {
                fan_state.current_speed = speed;
                return 0;
            }
            int new_speed = (speed > max_speed) ? max_speed : speed;
            if (set_fan_speed(new_speed) == 0) {
                fan_state.current_speed = new_speed;
                return 0;
            }
        }
    }
    log_error("Failed to set fan speed");
    return -1;
}

static void cleanup(void) {
    if (fan_state.current_speed > 0) {
        set_fan_speed(0);
    }
    log_message("Fan control system stopped");
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_error("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error("Failed to register SIGTERM handler");
        return 1;
    }

    while (program_running) {
        int temperature = 0;
        if (read_temperature(&temperature) == 0) {
            int fan_speed = temperature;
            int max_speed = fan_state.max_speed;
            int new_speed = (fan_speed > max_speed) ? max_speed : fan_speed;
            if (set_fan_speed_state(fan_speed, max_speed) == 0) {
                fan_state.current_speed = new_speed;
            }
            log_message("Fan speed updated to " + std::to_string(fan_speed) + " (max " + std::to_string(max_speed) + ")");
        } else {
            log_error("Failed to read temperature");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }
    cleanup();
    return 0;
}

