#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 100
#define LOG_FILE "cooling_log.csv"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define TEMP_SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Failed to open temperature file");
        return -1;
    }

    char buf[16];
    if (fgets(buf, sizeof(buf), fp) == NULL) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    int temp_milli = atoi(buf);
    if (temp_milli < 0 || temp_milli > 65535) {
        fprintf(stderr, "Invalid temperature value: %d\n", temp_milli);
        return -1;
    }
    return temp_milli;
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    int pwm_value = (duty_cycle * PWM_RANGE) / 100;
    if (gpioPWM(FAN_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int log_data(int temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("Failed to flush log file");
        return -1;
    }
    return 0;
}

