    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Failed to set PWM range to %d\n", PWM_RANGE);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        int temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Failed to read temperature, retrying in %d seconds...\n", TEMP_SAMPLE_INTERVAL);
            sleep(TEMP_SAMPLE_INTERVAL);
            continue;
        }

        int duty_cycle = (temperature >= 40 && temperature <= 70) ? 0 : 100;
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(TEMP_SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0);
    gpioTerminate();
    if (log_file) fclose(log_file);

    return 0;
}

