#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_1_ADDR 0x08
#define SENSOR_2_ADDR 0x09
#define LOG_FILE "flow_log.txt"
#define RETRY_COUNT 3
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sensor(int handle, uint16_t cmd, uint16_t *value) {
    char buf[3];
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (i2cWriteByte(handle, cmd) < 0) {
            fprintf(stderr, "I2C write failed (handle %d): %d\n", handle, i2cWriteByte(handle, cmd));
            retries--;
            gpioDelay(10000);
            continue;
        }
        if (i2cReadDevice(handle, buf, 3) != 3) {
            fprintf(stderr, "I2C read failed (handle %d): %d\n", handle, i2cReadDevice(handle, buf));
            retries--;
            gpioDelay(10000);
            continue;
        }
        uint8_t crc = crc8(buf, 2);
        if (crc != buf[2]) {
            fprintf(stderr, "CRC mismatch (handle %d): calc=0x%02X recv=0x%02X\n", handle, crc, buf[2]);
            retries--;
            gpioDelay(10000);
            continue;
        }
        *value = ((uint16_t)buf[0] << 8) | buf[1];
        return 0;
    }
    fprintf(stderr, "I2C read failed after %d retries (handle %d)\n", RETRY_COUNT, handle);
    return -1;
}

static int log_data(FILE *fp, float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, flow1, flow2);
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, SENSOR_1_ADDR, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1 (addr 0x%02X): %d\n", SENSOR_1_ADDR, i2c_handle_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, SENSOR_2_ADDR, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2 (addr 0x%02X): %d\n", SENSOR_2_ADDR, i2c_handle_2);
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t flow1 = 0, flow2 = 0;
        int ret1 = read_sensor(i2c_handle_1, 0x3608, &flow1);
        int ret2 = read_sensor(i2c_handle_2, 0x3608, &flow2);

        if (ret1 == 0 && ret2 == 0) {
            float f1 = (float)flow1 * 0.01f;
            float f2 = (float)flow2 * 0.01f;
            if (log_data(fp, f1, f2) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
            printf("Flow1: %.2f ml/min, Flow2: %.2f ml/min\n", f1, f2);
        } else {
            fprintf(stderr, "Sensor read failed (ret1=%d, ret2=%d)\n", ret1, ret2);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (fp) fclose(fp);
    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

