#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define RED_FIFO_REG 0x60
#define IR_FIFO_REG 0x61
#define RED_THRESHOLD 2000
#define LED_GPIO_CHIP "gpiochip0"
#define LED_GPIO_LINE 17
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adpd144ri(int fd, uint16_t *red, uint16_t *ir) {
    uint8_t red_data[2];
    uint8_t ir_data[2];

    if (i2c_write_reg8(fd, RED_FIFO_REG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, IR_FIFO_REG, 0x00) < 0) return -1;

    usleep(10000);

    if (i2c_read_reg8(fd, RED_FIFO_REG, red_data) < 0) return -1;
    if (i2c_read_reg8(fd, IR_FIFO_REG, ir_data) < 0) return -1;

    *red = (uint16_t)((red_data[0] << 8) | red_data[1]);
    *ir = (uint16_t)((ir_data[0] << 8) | ir_data[1]);
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %u, %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(LED_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", LED_GPIO_CHIP, strerror(errno));
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t red, ir;
        if (read_adpd144ri(i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Sensor read error, retrying in %d ms...\n", SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (red > RED_THRESHOLD || ir > 0) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
            } else {
                printf("Red: %u, IR: %u\n", red, ir);
            }
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

