#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_GPIO 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */
#define PULSE_THRESHOLD 10          /* 10 pulses in 1 second = 1 RPM */

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ISR callback for rising edge detection */
static void rpm_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)level;
    (void)tick;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Log RPM with timestamp to file */
static void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s RPM: %.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    } else {
        fflush(log_file);
    }
}

int main(void) {
    int ret;

    /* Initialize pigpio */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure GPIO 18 as input with pull-down */
    ret = gpioSetMode(SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR for rising edge detection */
    ret = gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, rpm_isr, NULL);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to register ISR on GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    /* Main loop */
    while (program_running) {
        /* Wait for 1 second, but interrupt early if signal received */
        for (int i = 0; i < 10 && program_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }

        if (!program_running) {
            break;
        }

        /* Count rising edges only */
        uint32_t last_tick = 0;
        uint32_t current_tick;
        int pulses = 0;

        while (program_running && pulse_count < PULSE_THRESHOLD) {
            current_tick = gpioTick();
            if (current_tick - last_tick >= SAMPLE_INTERVAL_US) {
                pulses++;
                last_tick = current_tick;
            }
            gpioDelay(10000); /* 10 ms */
        }

        if (pulses > 0) {
            double rpm = (double)pulses / (double)SAMPLE_INTERVAL_US * 60.0;
            log_rpm(rpm);
        } else {
            fprintf(stderr, "Warning: No rising edges detected for 1 second. RPM: 0.0\n");
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

