    while (program_running) {
        int level = gpiod_line_get_value(mic_line);
        if (level < 0) {
            fprintf(stderr, "Error reading mic GPIO: %s\n", strerror(errno));
            break;
        }

        if (level == 1) {
            if (log_peak(level) == 0) {
                printf("Peak detected at %s\n", timestamp_string(NULL));
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (mic_line) gpiod_line_release(mic_line);
    if (gain_line) gpiod_line_release(gain_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

/*
 * Returns a string formatted as "YYYY-MM-DD HH:MM:SS" or NULL on error.
 */
static char *timestamp_string(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime_r(&rawtime, NULL);
    if (timeinfo == NULL) {
        return NULL;
    }

    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        return NULL;
    }
    return buf;
}

