#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASURE_CMD 0x3608
#define FLOW_RATE_SCALE 1000.0f
#define LOG_FILE "flow_log.csv"
#define READ_INTERVAL_US 1000000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_slf3s(void) {
    if (i2cWriteByte(i2c_handle, MEASURE_CMD) < 0) {
        fprintf(stderr, "Error: Failed to send measurement command to SLF3S-4000B\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settling time */
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buf[3];
    int retries = 0;
    int bytes_read = 0;

    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)buf, 3);
        if (bytes_read == 3) {
            uint8_t crc = crc8(buf, 2);
            if (crc == buf[2]) {
                uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
                *flow_rate = (float)raw / FLOW_RATE_SCALE;
                return 0;
            }
        }
        fprintf(stderr, "Error: CRC mismatch on SLF3S-4000B (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(10000); /* 10 ms backoff */
    }
    fprintf(stderr, "Error: Failed to read flow rate after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X on bus %d\n", SLF3S_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (init_slf3s() != 0) {
        fprintf(stderr, "Error: SLF3S-4000B initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SLF3S-4000B monitoring started. Logging to '%s'. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        float flow_rate;
        if (read_flow_rate(&flow_rate) == 0) {
            log_data(flow_rate);
            printf("Flow Rate: %.2f uL/min\n", flow_rate);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping this cycle\n");
        }
        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

