#define I2C_BUS 1
#define MICS_VZ_89TE_ADDR 0x70
#define REG_STATE 0x00
#define REG_TVOC_1 0x01
#define REG_TVOC_2 0x02
#define REG_ECO2_1 0x05
#define REG_ECO2_2 0x06
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint8_t *state) {
    if (read_register(handle, REG_STATE, state) != 0) {
        return -1;
    }
