#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/snd_aloop.h>
#include <linux/snd_pcm.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define SAMPLE_RATE 44100
#define BUFFER_SIZE (SAMPLE_RATE * 2)
#define FILE_NAME "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2s_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2S device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2S_PCM_READY, 0) < 0) {
        fprintf(stderr, "Error setting I2S device ready: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int i2s_write(int fd, const uint8_t *data, int len) {
    if (write(fd, data, len) != (ssize_t)len) {
        fprintf(stderr, "Error writing to I2S device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2s_read(int fd, uint8_t *data, int len) {
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
        return -1;
    }
    if (bytes_read != (ssize_t)len) {
        fprintf(stderr, "Short read from I2S device: %zd of %d bytes\n", bytes_read, len);
        return -1;
    }
    return 0;
}

static int16_t extract_16bit_pcm(const uint8_t *data) {
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    return raw;
}

static int log_audio_data(const char *filename, const uint8_t *data, int len) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fwrite(data, 1, len, fp) != len) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    int i2s_fd = i2s_init(I2S_DEVICE);
    if (i2s_fd < 0) {
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2s_fd);
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2s_fd);
        return 1;
    }

    if (gpiod_line_request_output(line, "i2s_audio", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2s_fd);
        return 1;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    while (running) {
        uint8_t data[BUFFER_SIZE];
        int bytes_read = i2s_read(i2s_fd, data, BUFFER_SIZE);
        if (bytes_read < 0) {
            fprintf(stderr, "I2S read error, retrying...\n");
            usleep(100000);
            continue;
        }

        if (bytes_read == 0) {
            usleep(10000);
            continue;
        }

        int16_t raw_16bit = extract_16bit_pcm(data);
        int16_t left_16bit = raw_16bit >> 8;
        int16_t right_16bit = raw_16bit & 0xFF;

        if (log_audio_data(FILE_NAME, &left_16bit, bytes_read) < 0) {
            fprintf(stderr, "Error logging audio data.\n");
        }

        printf("Left: %d, Right: %d\n", left_16bit, right_16bit);
        usleep(10000);
    }

    printf("\nExiting...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2s_fd);
    return 0;
}

