#define PWM_RANGE 100
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 50
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;
static int fan_on = 0;
static int fan_pwm_duty = 0;
static int last_flame_state = 1;
static int last_flame_time_ms = 0;
static int last_flame_duration_ms = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fclose(fp);
}

static void cleanup(void) {
    if (fan_on) {
        gpioPWM(FAN_GPIO, 0);
        fan_on = 0;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

static void set_fan_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

static void control_fan(int on) {
    set_fan_duty(on ? 80 : 0);
}

static void flame_detected(void) {
    if (last_flame_state == 1) {
        last_flame_duration_ms = 0;
        last_flame_state = 0;
    }
    last_flame_time_ms = gpioTick();
    last_flame_duration_ms = last_flame_time_ms - last_flame_time_ms;
    if (last_flame_duration_ms > 0) {
        last_flame_duration_ms = last_flame_duration_ms * 10;
        if (last_flame_duration_ms > 5000) {
            last_flame_duration_ms = 5000;
            last_flame_state = 1;
        }
    } else {
        last_flame_duration_ms = 0;
        last_flame_state = 1;
    }
    if (last_flame_state) {
        if (last_flame_duration_ms > 0) {
            set_fan_duty(1);
            log_event("Flame detected");
        }
    } else {
        set_fan_duty(0);
        log_event("No flame detected");
    }
}

