        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", FLAME_SENSOR_GPIO);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", FAN_GPIO);
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", FAN_GPIO);
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize fan PWM on GPIO %d\n", FAN_GPIO);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    log_event("System started");

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (sensor_value == 0) {
            if (last_flame_state == 1) {
                set_fan_duty(1);
                last_flame_duration_ms = 0;
                last_flame_state = 0;
            }
            flame_detected();
        } else {
            if (last_flame_state == 1) {
                set_fan_duty(0);
                last_flame_duration_ms = 0;
                last_flame_state = 0;
            }
            last_flame_duration_ms = 0;
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    }

    log_event("Shutting down");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

