#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 20
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_flame_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
            break;
        }

        if (value == 1) {
            char timestamp[32];
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Error getting time: %s\n", strerror(errno));
                break;
            }
            if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now)) == 0) {
                fprintf(stderr, "Error formatting timestamp\n");
                break;
            }
            if (log_flame_event(timestamp) != 0) {
                fprintf(stderr, "Failed to log flame event\n");
                break;
            }
            printf("Flame detected at %s\n", timestamp);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Exiting gracefully.\n");
    return ret;
}

