#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define OPT3001_ADDR 0x44
#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define CONVERSION_TIME_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, OPT3001_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_light_data(int handle, uint16_t *lux_out) {
    char buf[2];
    int result;

    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading light data: expected 2 bytes, got %d\n", result);
        return -1;
    }

    *lux_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static void log_data(uint16_t lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, %u\n", timestamp, lux);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Light sensor data logging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t lux;
        if (read_light_data(i2c_handle, &lux) == 0) {
            log_data(lux);
            printf("Lux: %u\n", lux);
        } else {
            fprintf(stderr, "Failed to read light data after retries.\n");
        }

        gpioDelay(CONVERSION_TIME_MS * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Light sensor data logging stopped.\n");
    return 0;
}

