    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Light sensor data logging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t lux;
        if (read_light_data(i2c_handle, &lux) == 0) {
            log_data(lux);
            printf("Lux: %u\n", lux);
        } else {
            fprintf(stderr, "Failed to read light data after retries.\n");
        }

        gpioDelay(CONVERSION_TIME_MS * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Light sensor data logging stopped.\n");
    return 0;
}

