#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define CHIP_NAME "gpiochip0"
#define POLL_INTERVAL_MS 100

static const unsigned int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int log_sensor_state(struct gpiod_line *line, const char *channel_name) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %u: %s\n", channel_name, strerror(errno));
        return -1;
    }
    printf("Channel %s: %s\n", channel_name, value ? "1" : "0");
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", channel_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    ret = gpiod_line_request_input(lines[0], "ttp226-sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %u as input: %s\n", channel_pins[0], strerror(errno));
        for (int i = 0; i < NUM_CHANNELS; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("TTP226 sensor monitoring started on GPIO %u-%u. Press Ctrl+C to exit.\n",
           channel_pins[0], channel_pins[NUM_CHANNELS - 1]);

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (log_sensor_state(lines[i], "Channel " + std::to_string(i)) < 0) {
                break;
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_release(lines[i])) {
            fprintf(stderr, "Failed to release GPIO %u: %s\n", channel_pins[i], strerror(errno));
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

