static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(2 + i, PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for channel %d.\n", i);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(2 + i, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for channel %d.\n", i);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_sensor(int channel)
{
    int val = gpioRead(2 + channel);
    if (val < 0) {
        fprintf(stderr, "Error: gpioRead failed for channel %d.\n", channel);
        return -1;
    }
    return val;
}

static void log_sensor_data(int *data, int num_channels)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
