#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 5
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs with internal pull-up resistors */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with both sensors off */
    if (gpioWrite(SENSOR1_PIN, 0) != 0 || gpioWrite(SENSOR2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize sensor pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Hall-Effect Latch Sensor Monitoring\n");
    printf("Sensor 1: BCM GPIO %d, Sensor 2: BCM GPIO %d\n", SENSOR1_PIN, SENSOR2_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int s1 = gpioRead(SENSOR1_PIN);
        int s2 = gpioRead(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor pin %d\n", SENSOR1_PIN);
            break;
        }

        printf("Sensor 1: %s, Sensor 2: %s\n",
               s1 == 1 ? "HIGH" : "LOW",
               s2 == 1 ? "HIGH" : "LOW");
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioWrite(SENSOR1_PIN, 0);
    gpioWrite(SENSOR2_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

