#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50
#define CHIP_NAME "gpiochip4"

static const unsigned int channel_pins[NUM_CHANNELS] = {
    2, 3, 4, 17, 27, 22, 10, 9
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_gpio(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_request_input_flags(lines[i], "ttp226-touch",
                                              GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("GPIO lines initialized. Polling 8 channels every %d ms.\n",
           POLL_INTERVAL_MS);
    return 0;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return -1;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_get_value(gpiod_line_get_line(lines[i], 0)) == 1) {
            printf("Warning: channel %u still active (input). Cleaning up.\n",
                   channel_pins[i]);
            gpiod_line_release(lines[i]);
        }
    }
    if (gpiod_chip_close(chip)) {
        fprintf(stderr, "Failed to close GPIO chip: %s\n", strerror(errno));
    }
}

static void log_channel_state(int channel_number, int value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "localtime() failed: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    printf("[%s] Channel %d: %d\n", timestamp, channel_number, value);
}

int main(void) {
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Starting TTP226 touch sensor data logging...\n");

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(gpiod_line_get_line(lines[i], 0));
            if (value < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                        channel_pins[i], strerror(errno));
                continue;
            }
            log_channel_state(i, value);
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

