{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TILT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", TILT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n", TILT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           TILT_SENSOR_PIN);
    fflush(stdout);

    int last_state = gpioRead(TILT_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", TILT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int current_state = gpioRead(TILT_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", TILT_SENSOR_PIN);
            break;
        }

        if (current_state != last_state) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            if (localtime_r(&rawtime, &timeinfo) != NULL) {
                if (strftime(timestamp, sizeof(timestamp),
