                    printf("Tilted at %s\n", timestamp);
                    fflush(stdout);
                }
            } else {
                fprintf(stderr, "Error: localtime_r failed.\n");
            }
            fflush(stdout);
            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

