#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_1_ADDR 0x36
#define SENSOR_2_ADDR 0x37
#define ALARM_GPIO_LINE 17
#define FLOW_SCALE_FACTOR 0.036f
#define ALARM_THRESHOLD 0.5f
#define MEASUREMENT_DELAY_MS 100
#define LOOP_DELAY_MS 1000

static volatile sig_atomic_t running = 1;
static int i2c_fd_1 = -1;
static int i2c_fd_2 = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *alarm_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_cmd(fd, 0x3608) < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 0x%02X\n", fd);
        return -1;
    }
    usleep(MEASUREMENT_DELAY_MS * 1000);
    return 0;
}

static int read_flow_rate(int fd, float *flow_rate) {
    uint8_t buf[9];
    if (i2c_read_data(fd, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Failed to read flow data from sensor 0x%02X\n", fd);
        return -1;
    }
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on sensor 0x%02X\n", fd);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw * FLOW_SCALE_FACTOR;
    return 0;
}

static float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0f;
}

static void log_data(float avg_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, %.2f ml/min\n", timestamp, avg_flow);
    fflush(log_file);
}

static void alarm_set(void) {
    if (gpiod_line_set_value(alarm_line, 1) < 0) {
        fprintf(stderr, "Failed to set alarm high: %s\n", strerror(errno));
    }
}

static void alarm_clear(void) {
    if (gpiod_line_set_value(alarm_line, 0) < 0) {
        fprintf(stderr, "Failed to set alarm low: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_release(alarm_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd_1 >= 0) {
        close(i2c_fd_1);
    }
    if (i2c_fd_2 >= 0) {
        close(i2c_fd_2);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO_LINE);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", ALARM_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    i2c_fd_1 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_1 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd_1, I2C_SLAVE, SENSOR_1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SENSOR_1_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    i2c_fd_2 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_2 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd_2, I2C_SLAVE, SENSOR_2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SENSOR_2_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_sensor(i2c_fd_1) < 0 || init_sensor(i2c_fd_2) < 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float avg_flow1 = 0.0f, avg_flow2 = 0.0f;
        int sensor1_ok = 0, sensor2_ok = 0;

        if (read_flow_rate(i2c_fd_1, &avg_flow1) == 0) {
            sensor1_ok = 1;
        }
        if (read_flow_rate(i2c_fd_2, &avg_flow2) == 0) {
            sensor2_ok = 1;
        }

        if (sensor1_ok && sensor2_ok) {
            float avg = calculate_average_flow(avg_flow1, avg_flow2);
            log_data(avg);
            alarm_set();
        } else {
            fprintf(stderr, "Sensor read error. Skipping cycle.\n");
        }

        sleep(LOOP_DELAY_MS / 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

