#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define POLL_INTERVAL_US 50000  /* 50 ms */

typedef struct {
    time_t timestamp;
    int reading;
} ObstacleReading;

static ObstacleReading buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_reading(int reading) {
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].reading = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("Obstacle readings (timestamp, reading):\n");
    for (int i = 0; i < buffer_count; i++) {
        time_t t = buffer[i].timestamp;
        int reading = buffer[i].reading;
        printf("  [%ld] reading=%d\n", t, reading);
    }
    printf("---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler: %s\n", strerror(errno));
    }

    printf("Obstacle avoidance sensor monitoring started on GPIO %d.\n", GPIO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int reading = gpioRead(GPIO_PIN);
        if (reading < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", GPIO_PIN);
            break;
        }

        if (reading == 0) {
            add_reading(reading);
            printf("Obstacle detected on GPIO %d\n", GPIO_PIN);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    print_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

