#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN     25

#define OBSTACLE_THRESHOLD_CM 10.0
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable pull-up so sensors read HIGH when no obstacle is present */
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", SENSOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", SENSOR2_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure LED is off initially */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED state on GPIO %d.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    /* Ensure LED is off before terminating pigpio */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off LED during cleanup.\n");
    }
    gpioTerminate();
}

static int read_sensor(int pin) {
    return gpioRead(pin);
}

static void set_led(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "Error: failed to write to GPIO %d.\n", LED_PIN);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: sensor read failed.\n");
            break;
        }

        if (s1 == 0 && s2 == 0) {
            /* Both sensors read LOW: obstacle detected */
            set_led(1);
            usleep(OBSTACLE_THRESHOLD_CM * 1000000);
            set_led(0);
        } else if (s1 == 0 && s2 != 0) {
            /* Sensor 1 read LOW, sensor 2 HIGH: obstacle detected */
            set_led(1);
            usleep(OBSTACLE_THRESHOLD_CM * 1000000);
            set_led(0);
        } else if (s1 != 0 && s2 == 0) {
            /* Sensor 1 HIGH, sensor 2 LOW: obstacle detected */
            set_led(1);
            usleep(OBSTACLE_THRESHOLD_CM * 1000000);
            set_led(0);
        } else {
            /* No obstacle detected */
            set_led(0);
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Obstacle avoidance system stopped.\n");
    return EXIT_SUCCESS;
}

