#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TMAG5170_ADDR 0x0E
#define I2C_BUS 1
#define LOG_FILE "magnetic_log.csv"
#define SAMPLE_INTERVAL_US 100000

/* TMAG5170 register addresses */
#define TMAG5170_REG_DEVICE_ID 0x00
#define TMAG5170_REG_CONFIG_A 0x01
#define TMAG5170_REG_CONFIG_B 0x02
#define TMAG5170_REG_CONFIG_C 0x03
#define TMAG5170_REG_DATA_A 0x04
#define TMAG5170_REG_DATA_B 0x05
#define TMAG5170_REG_DATA_C 0x06

#define TMAG5170_EXPECTED_DEVICE_ID 0x8D

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_sensor_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    int rc = i2cReadI2CBlockData(handle, TMAG5170_REG_DATA_A, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading 6-byte data block: %d\n", rc);
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static int init_sensor(int handle) {
    uint8_t device_id = 0;

    if (read_reg(handle, TMAG5170_REG_DEVICE_ID, &device_id) < 0) {
        fprintf(stderr, "Failed to read device ID\n");
        return -1;
    }

    if (device_id != TMAG5170_EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n", device_id, TMAG5170_EXPECTED_DEVICE_ID);
        return -1;
    }

    if (write_reg(handle, TMAG5170_REG_CONFIG_A, 0x00) < 0) return -1;
    if (write_reg(handle, TMAG5170_REG_CONFIG_B, 0x00) < 0) return -1;
    if (write_reg(handle, TMAG5170_REG_CONFIG_C, 0x00) < 0) return -1;

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, TMAG5170_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    printf("Logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t x, y, z;

        if (read_sensor_data(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error, continuing\n");
        } else {
            int16_t mT_x = (int16_t)((x & 0x03FF) | ((x >> 12) & 0x03FF));
            int16_t mT_y = (int16_t)((y & 0x03FF) | ((y >> 12) & 0x03FF));
            int16_t mT_z = (int16_t)((z & 0x03FF) | ((z >> 12) & 0x03FF));

            if (log_data(log_file, mT_x, mT_y, mT_z) < 0) {
                fprintf(stderr, "Logging error, continuing\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

