static void rotate_direction_with_mutex_and_sleep_and_poll_and_sleep_and_poll(int new_state) {
    if (new_state == rotation_state) return;
    if (new_state == 1) {
        last_state = 0;
        last_alert_time = gpioTick();
    } else {
        last_state = 1;
        last_alert_time = gpioTick();
    }
    if (new_state == 1) {
        log_rotation_event();
    }
    gpioDelay(POLL_DELAY_US);
    gpioDelay(POLL_DELAY_US);
    gpioDelay(POLL_DELAY_US);
    gpioDelay(POLL_DELAY_US);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_A_GPIO, rotate_direction_with_mutex_and_sleep_and_poll_and_sleep_and_poll) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(SENSOR_B_GPIO, rotate_direction_with_mutex_and_sleep_and_poll_and_sleep_and_poll) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOG_FILE, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LOG_FILE, 0) != 0) {
        fprintf(stderr, "Failed to initialize log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_A_GPIO, rotate_direction_with_mutex_and_sleep_and_poll_and_sleep_and_poll, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFuncEx(SENSOR_B_GPIO, rotate_direction_with_mutex_and_sleep_and_poll_and_sleep_and_poll, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(SENSOR_A_GPIO) == 1) {
            if (rotation_state == 0) {
                rotate_direction(1);
                rotation_state = 1;
                last_alert_time = gpioTick();
            }
        } else if (gpioRead(SENSOR_B_GPIO) == 1) {
            if (rotation_state == 1) {
                rotate_direction(1);
                rotation_state = 0;
                last_alert_time = gpioTick();
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(SENSOR_A_GPIO, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_B_GPIO, NULL, NULL);
    gpioWrite(LOG_FILE, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

