#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_MS 50
#define CONSUMER "touch_sensor_led"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(int priority, const char *message) {
    char timestamp[32];
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        syslog(priority, "Error: localtime failed");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "[%s] %s", timestamp, message);
}

int main(void) {
    openlog(CONSUMER, LOG_PID | LOG_CONS, LOG_USER);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, CONSUMER) < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Touch sensor LED monitoring started on GPIO %d and GPIO %d", TOUCH_SENSOR_PIN, LED_PIN);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Touch sensor LED monitoring started on GPIO %d and GPIO %d", TOUCH_SENSOR_PIN, LED_PIN);

    while (running) {
        int touch_state = gpiod_line_get_value(touch_line);
        if (touch_state < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor: %s", strerror(errno));
            break;
        }

        if (touch_state == 1) {
            log_message(LOG_INFO, "Touch detected!");
            if (gpiod_line_set_value(led_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to turn LED on: %s", strerror(errno));
            }
        } else {
            log_message(LOG_INFO, "Touch not detected.");
            if (gpiod_line_set_value(led_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to turn LED off: %s", strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_message(LOG_INFO, "Shutting down...");
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

