#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define TOUCH_PIN 17
#define LED_PIN 18
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the touch line */
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("gpiod_chip_get_line(touch)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the touch line as input */
    ret = gpiod_line_request_input(touch_line, "touch-sensor");
    if (ret < 0) {
        perror("gpiod_line_request_input(touch)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the LED line as output, initially LOW */
    ret = gpiod_line_request_output(led_line, "led-control", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(led)");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started on GPIO %d. LED on GPIO %d.\n",
           TOUCH_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop: read touch events, toggle LED, sleep 50 ms */
    while (running) {
        int val = gpiod_line_get_value(touch_line);
        if (val < 0) {
            perror("gpiod_line_get_value(touch)");
            break;
        }

        if (val == 1) {
            /* Rising edge: touch detected */
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value(led,1)");
                break;
            }
            printf("Touch detected! LED on.\n");
        } else {
            /* Idle: no touch */
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value(led,0)");
                break;
            }
            printf("No touch.\n");
        }

        usleep(50000); /* 50 ms */
    }

    /* Clean shutdown: turn off LED and release resources */
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

