#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000
#define DEBOUNCE_US 50000

static volatile sig_atomic_t running = 1;
static int buffer_index = 0;
static int buffer_count = 0;
static int buffer_overflow = 0;

typedef struct {
    time_t timestamp;
    int sensor_pin;
    int state;
} Event;

static Event log_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_tail = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int sensor_pin, int state) {
    Event ev;
    ev.timestamp = time(NULL);
    ev.sensor_pin = sensor_pin;
    ev.state = state;
    strftime(ev.state_str, sizeof(ev.state_str), "%Y-%m-%d %H:%M:%S", localtime(&ev.timestamp));
    log_buffer[buffer_head] = ev;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    } else {
        buffer_overflow++;
    }
}

static void cleanup(void) {
    if (gpioWrite(LED_1_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn off LED 1 on cleanup\n");
    }
    if (gpioWrite(LED_2_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn off LED 2 on cleanup\n");
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set SENSOR_1_PIN %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set SENSOR_2_PIN %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED_1_PIN %d as output\n", LED_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED_2_PIN %d as output\n", LED_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_1_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise LED 1 state\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise LED 2 state\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
