#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define DEBOUNCE_US 5000
#define RPM_PER_PULSE 2.0
#define LOG_FILE "shaft_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_hall_effect_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return value;
}

float calculate_rpm(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 1 && sensor2_state == 1) {
        return RPM_PER_PULSE;
    } else if (sensor1_state == 1 && sensor2_state == 0) {
        return RPM_PER_PULSE * 2.0;
    } else if (sensor1_state == 0 && sensor2_state == 1) {
        return RPM_PER_PULSE * 2.0;
    } else if (sensor1_state == 0 && sensor2_state == 0) {
        return RPM_PER_PULSE;
    } else {
        return 0.0;
    }
}

void log_data(float rpm, int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    printf("Monitoring RPM on GPIO %d and %d. Press Ctrl+C to exit.\n", SENSOR1_PIN, SENSOR2_PIN);

    int last_sensor1_state = read_hall_effect_sensor(SENSOR1_PIN);
    int last_sensor2_state = read_hall_effect_sensor(SENSOR2_PIN);

    while (program_running) {
        int sensor1_state = read_hall_effect_sensor(SENSOR1_PIN);
        int sensor2_state = read_hall_effect_sensor(SENSOR2_PIN);

        if (sensor1_state == -1 || sensor2_state == -1) {
            gpioDelay(DEBOUNCE_US);
            continue;
        }

        float rpm = calculate_rpm(sensor1_state, sensor2_state);
        log_data(rpm, sensor1_state, sensor2_state);

        gpioDelay(DEBOUNCE_US);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

