static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_register_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (result != len) {
        fprintf(stderr, "Error reading %u bytes from register 0x%02X: %d\n", len, reg, result);
        return -1;
    }
    return 0;
}

static int init_si1182(int handle) {
    uint8_t part_id = 0;
    if (read_register(handle, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_VAL) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1182_PART_ID_VAL);
        return -1;
    }

    if (write_register(handle, SI1182_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        return -1;
    }

    return 0;
}

static int read_sensor_data(int handle, uint32_t *hr_raw, uint32_t *spo2_raw) {
    uint8_t hr_buf[2];
    uint8_t spo2_buf[2];

    if (read_register_block(handle, SI1182_REG_HR_DATA, hr_buf, 2) < 0) {
        return -1;
    }
    if (read_register_block(handle, SI1182_REG_SPO2_DATA, spo2_buf, 2) < 0) {
        return -1;
    }

    *hr_raw = (uint32_t)((hr_buf[0] << 8) | hr_buf[1]);
    *spo2_raw = (uint32_t)((spo2_buf[0] << 8) | spo2_buf[1]);

    return 0;
}

static int log_data(FILE *fp, uint32_t hr_raw, uint32_t spo2_raw) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s, Heart Rate: %u BPM, SpO2: %u%%\n", timestamp, hr_raw, spo2_raw) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

