    }

    if (init_si1182(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting data logging. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint32_t hr_raw, spo2_raw;

        if (read_sensor_data(i2c_handle, &hr_raw, &spo2_raw) < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            if (log_data(log_file, hr_raw, spo2_raw) < 0) {
                fprintf(stderr, "Logging error, continuing...\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

