#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define ALARM_PIN 27

#define ALARM_ACTIVE 1
#define ALARM_INACTIVE 0

#define TILT_THRESHOLD_HIGH 2.0
#define POLL_INTERVAL_US 100000
#define MAX_HOLD_TIME_S 2

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s - %s\n", timestamp, event_type);
    fflush(log_file);
}

static void activate_alarm(int pin) {
    if (gpioWrite(pin, ALARM_ACTIVE) != 0) {
        fprintf(stderr, "Error: Failed to activate alarm on GPIO %d\n", pin);
        return;
    }
    log_event("ALARM_ACTIVATED");
}

static void deactivate_alarm(int pin) {
    if (gpioWrite(pin, ALARM_INACTIVE) != 0) {
        fprintf(stderr, "Error: Failed to deactivate alarm on GPIO %d\n", pin);
        return;
    }
    log_event("ALARM_DEACTIVATED");
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return value;
}

static void check_tilt(int sensor1, int sensor2) {
    if (read_sensor(SENSOR1_PIN) == ALARM_INACTIVE) {
        if (read_sensor(SENSOR2_PIN) == ALARM_INACTIVE) {
            activate_alarm(ALARM_PIN);
            log_event("TILT_STARTED");
        } else {
            log_event("TILT_STARTED_SENSOR2_HIGH");
        }
    } else {
        log_event("TILT_STARTED_SENSOR1_HIGH");
    }
}

static void cleanup(void) {
    deactivate_alarm(ALARM_PIN);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, PI_LOW);

    log_file = fopen("bridge_integrity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bridge structural integrity monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        check_tilt(read_sensor(SENSOR1_PIN), read_sensor(SENSOR2_PIN));
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

