/*
 * Seismic Event Monitor for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   D7S-A0011 SDA -> GPIO2 (I2C bus 1)
 *   D7S-A0011 SCL -> GPIO3 (I2C bus 1)
 *   D7S-A0011 VDD -> 3.3V
 *   D7S-A0011 GND -> GND
 *   LED anode -> GPIO17 (with 330 ohm resistor to GND)
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x1D
#define LED_GPIO       17
#define VIBRATION_THRESHOLD 500.0f
#define POLL_INTERVAL_US 100000   /* 100 ms */
#define MAX_RETRIES    3
#define LOG_FILE       "seismic_events.log"

/* D7S-A0011 registers */
#define REG_CTRL1       0x1F
#define REG_ACCEL_X_L   0x28
#define REG_ACCEL_X_H   0x29
#define REG_ACCEL_Y_L   0x2A
#define REG_ACCEL_Y_H   0x2B
#define REG_ACCEL_Z_L   0x2C
#define REG_ACCEL_Z_H   0x2D

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, got %d, expected %d): %d\n",
                reg, rc, len, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sensor_init(int handle)
{
    /* Verify sensor presence by reading CTRL1 */
    uint8_t ctrl1_val = 0;
    if (i2c_read_block(handle, REG_CTRL1, &ctrl1_val, 1) != 1) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit (bit 7) */
    if (i2c_write_reg(handle, REG_CTRL1, 0x00) != 0) {
        fprintf(stderr, "Failed to clear power-down bit\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 3-axis acceleration (little-endian, 6 bytes)                    */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int rc;

    rc = i2c_read_block(handle, REG_ACCEL_X_L, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Acceleration read failed (got %d bytes): %d\n", rc, rc);
        return -1;
    }

    int16_t x_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y_raw = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z_raw = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)x_raw / 16384.0f;
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(float peak_vibration)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s, Peak Vibration: %.2f\n", ts, peak_vibration);
        fflush(g_log_file);
    }
    printf("%s, Peak Vibration: %.2f\n", ts, peak_vibration);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the sensor address */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Vibration_Peak_mS\n");
        fflush(g_log_file);
    }

    /* Register signal handler for Ctrl+C and SIGINT */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic event monitor started. Threshold: %.1f m/s^2\n",
           VIBRATION_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            float peak = sqrtf(x * x + y * y + z * z);
            log_event(peak);
            if (peak > VIBRATION_THRESHOLD) {
                printf("Threshold exceeded! Peak: %.2f m/s^2\n", peak);
                gpioWrite(LED_GPIO, 1);
                gpioDelay(1000000);  /* 1 s */
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

