#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define SENSOR_4_PIN 22
#define LED_PIN 18
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor1 = NULL, *sensor2 = NULL, *sensor3 = NULL, *sensor4 = NULL;
    struct gpiod_line *led = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 5) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the four sensor lines */
    sensor1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    sensor2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    sensor3 = gpiod_chip_get_line(chip, SENSOR_3_PIN);
    sensor4 = gpiod_chip_get_line(chip, SENSOR_4_PIN);
    if (!sensor1 || !sensor2 || !sensor3 || !sensor4) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Get the LED line */
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request sensor lines as inputs with pull-down */
    if (gpiod_line_request_input_flags(sensor1, "ky032-sensor1", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags(sensor1)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(sensor2, "ky032-sensor2", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags(sensor2)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(sensor3, "ky032-sensor3", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags(sensor3)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(sensor4, "ky032-sensor4", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags(sensor4)");
        goto cleanup;
    }

    /* Request LED line as output, initially low */
    if (gpiod_line_request_output(led, "ky032-led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("Obstacle detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int val1 = gpiod_line_get_value(sensor1);
        int val2 = gpiod_line_get_value(sensor2);
        int val3 = gpiod_line_get_value(sensor3);
        int val4 = gpiod_line_get_value(sensor4);

        if (val1 < 0 || val2 < 0 || val3 < 0 || val4 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        int led_val = (val1 || val2 || val3 || val4) ? 1 : 0;
        if (gpiod_line_set_value(led, led_val) < 0) {
            perror("gpiod_line_set_value(led)");
            goto cleanup;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off before releasing resources */
    if (led) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (sensor1) gpiod_line_release(sensor1);
    if (sensor2) gpiod_line_release(sensor2);
    if (sensor3) gpiod_line_release(sensor3);
    if (sensor4) gpiod_line_release(sensor4);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

