/*
 * flame_monitor.c — Raspberry Pi 3 Model B+
 *
 * Five KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    ./flame_monitor
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <sys/flock.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define LOG_FILE    "/var/log/flame_events.log"
#define POLL_INTERVAL_SEC 1
#define DEBOUNCE_MS   50
#define CHIP_NAME     "gpiochip0"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/*
 * Append a timestamped event line to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_event(int sensor_id, const char *event_msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        perror("gmtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - %s\n",
                ts, sensor_id, sensor_id, event_msg) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) == EOF) {
        perror("fflush()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) == EOF) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    install_signal_handlers();

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name(" CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    /* Acquire each sensor line */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                    i, strerror(errno));
            goto cleanup;
        }

        /* Request the line as input */
        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            fprintf(stderr, "gpiod_line_request_input(%d) failed: %s\n",
                    i, strerror(errno));
            goto cleanup;
        }
    }

    printf("Flame sensor monitoring started.\n");
    printf("  Sensors: 2, 3, 4, 17, 27\n");
    printf("  Log: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int prev_flame = -1;
        int prev_debounce = -1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(%d) failed: %s\n",
                        i, strerror(errno));
                continue;
            }

            /* KY-026 digital output: LOW = flame detected, HIGH = no flame */
            if (val == 0) {
                if (prev_flame == 1) {
                    if (gpiod_line_request_rising_edge_events(lines[i],
                                                              "flame_monitor") < 0) {
                        fprintf(stderr, "gpiod_request_rising_edge_events(%d) failed: %s\n",
                                i, strerror(errno));
                        continue;
                    }
                    prev_debounce = val;
                } else {
                    prev_debounce = -1;
                }
            } else {
                prev_debounce = -1;
            }

            if (prev_debounce != -1) {
                /* Debounce: wait for 50 ms after a rising edge */
                struct timespec ts = {
                    .tv_sec  = 0,
                    .tv_nsec = DEBOUNCE_MS * 1000000L
                };
                nanosleep(&ts, NULL);

                int new_val = gpiod_line_get_value(lines[i]);
                if (new_val < 0) {
                    fprintf(stderr, "gpiod_line_get_value(%d) failed: %s\n",
                            i, strerror(errno));
                    continue;
                }

                if (new_val == 1) {
                    if (prev_flame == 1) {
                        if (log_event(i, "Flame detected") < 0) {
                            fprintf(stderr, "Failed to log event for sensor %d\n", i);
                        }
                    }
                    prev_flame = new_val;
                }
            }
        }

        /* Sleep POLL_INTERVAL_SEC seconds */
        struct timespec ts = {
            .tv_sec  = POLL_INTERVAL_SEC,
            .tv_nsec = 0
        };
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release all requested lines */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    printf("\nExiting cleanly.\n");
    return ret;
}

