#include <gpiod.h>

#define NUM_PINS 8
#define POLL_INTERVAL_MS 50

static const unsigned int pins[NUM_PINS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int log_touch_event(int pin, const char *sensor_name) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    printf("[%s] Touch detected on GPIO %u (sensor: %s)\n",
           timestamp, pin, sensor_name);
    fflush(stdout);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_request_config config;
    struct gpiod_line_request *request = NULL;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    lines.bulk = NULL;
    ret = gpiod_line_bulk_new(&lines);
    if (ret < 0) {
        fprintf(stderr, "Failed to create line bulk: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_bulk_add_lines(lines.bulk, pins, NUM_PINS);
    if (ret < 0) {
        fprintf(stderr, "Failed to add lines to line bulk: %s\n", strerror(errno));
        gpiod_line_bulk_free(&lines);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    config.consumer = "ttp226-touch-sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    request = gpiod_chip_request_lines(chip, &config, NULL);
    if (request == NULL) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        gpiod_line_bulk_free(&lines);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started on GPIO pins %u-%u. Press Ctrl+C to exit.\n",
           pins[0], pins[NUM_PINS - 1]);
    fflush(stdout);

    while (program_running) {
        ret = gpiod_line_request_get_values(request, NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        for (int i = 0; i < NUM_PINS; i++) {
            if (ret[i] < 0) {
                fprintf(stderr, "Failed to read GPIO %u: %s\n",
                        pins[i], strerror(errno));
                break;
            }
            if (ret[i] == 1) {
                if (log_touch_event(pins[i], "ttp226") < 0) {
                    fprintf(stderr, "Failed to log touch event on GPIO %u\n", pins[i]);
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

