#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LUX_THRESHOLDS 100 500 1000
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)(reg & 0x7F), (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int veml7700_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C write (reg select) failed\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int veml7700_init(void) {
    uint8_t config = 0x00;
    if (veml7700_write_reg(0x00, config) != 0) return -1;
    gpioDelay(100000);
    return 0;
}

static int read_lux(uint16_t *lux_out) {
    uint8_t reg = 0x04;
    uint8_t value = 0;
    if (veml7700_read_reg(reg, &value) != 0) return -1;
    *lux_out = (uint16_t)value;
    return 0;
}

static int control_led(int brightness) {
    if (gpioPWM(PWM_PIN, brightness) != 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static void log_data(int lux, int brightness) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s, Lux: %d, Brightness: %d\n", ts, lux, brightness);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (bus %d, addr 0x%02X)\n", I2C_BUS, VEML7700_ADDR);
        gpioTerminate();
        return 1;
    }

    if (veml7700_init() != 0) {
        fprintf(stderr, "Error: VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for PWM\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: fopen log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Grow light system started. Logging to %s\n", LOG_FILE);

    while (running) {
        uint16_t lux = 0;
        int ret = read_lux(&lux);
        if (ret != 0) {
            fprintf(stderr, "Error: VEML7700 read failed (code %d)\n", ret);
            gpioDelay(1000000);
            continue;
        }

        int brightness = 0;
        if (lux < 100) brightness = 100;
        else if (lux < 500) brightness = 75;
        else if (lux < 1000) brightness = 50;
        else brightness = 25;

        if (control_led(brightness) != 0) {
            fprintf(stderr, "Error: LED control failed\n");
        }

        log_data(lux, brightness);
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

