    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: fopen log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Grow light system started. Logging to %s\n", LOG_FILE);

    while (running) {
        uint16_t lux = 0;
        int ret = read_lux(&lux);
        if (ret != 0) {
            fprintf(stderr, "Error: VEML7700 read failed (code %d)\n", ret);
            gpioDelay(1000000);
            continue;
        }

        int brightness = 0;
        if (lux < 100) brightness = 100;
        else if (lux < 500) brightness = 75;
        else if (lux < 1000) brightness = 50;
        else brightness = 25;

        if (control_led(brightness) != 0) {
            fprintf(stderr, "Error: LED control failed\n");
        }

        log_data(lux, brightness);
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

