#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000  /* 50 ms */
#define DEBOUNCE_DELAY_US 10000  /* 10 ms */
#define LED_GPIO 17
#define LOG_FILE "touch_log.txt"

/* TTP226 digital output channels (BCM numbering) */
static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Channel %d Touched\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, channel);
    } else {
        fprintf(fp, "Timestamp error - Channel %d Touched\n", channel);
    }
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure touch pins as inputs with pull-down */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED pin as output and ensure it starts off */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED state on GPIO %d\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security keypad started. Press Ctrl+C to exit.\n");

    while (running) {
        int touched = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpioRead(touch_pins[i]);
            if (val < 0) {
                fprintf(stderr, "gpioRead failed on GPIO %d\n", touch_pins[i]);
                running = 0;
                break;
            }
            if (val == 1) {
                touched = 1;
                break;
            }
        }

        if (touched) {
            if (log_touch_event(i) != 0) {
                fprintf(stderr, "Failed to log touch event\n");
            }
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to turn LED on\n");
            }
        } else {
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to turn LED off\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

