#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR          0x44
#define CONFIG_REG            0x01
#define RESULT_REG            0x00
#define CONFIG_WORD           0xC810  /* continuous, FS, 100 ms, AFS, 0x0C10 */
#define CONVERSION_DELAY_US   100000 /* 100 ms */
#define LOG_FILE              "light_data.txt"
#define SAMPLE_INTERVAL_US    1000000 /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit little-endian word to the OPT3001's configuration register.
 * pigpio's i2cWriteWordData uses little-endian; the OPT3001 expects big-endian.
 * The 16-bit value is swapped before writing. */
static int opt3001_write_config(int handle, uint16_t value)
{
    uint16_t swapped = (value >> 8) | (value << 8);
    if (i2cWriteWordData(handle, CONFIG_REG, (char *)&swapped, 2) != 0) {
        fprintf(stderr, "Error writing configuration register 0x%02X\n", CONFIG_REG);
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian word from the OPT3001's result register.
 * pigpio's i2cReadWordData uses little-endian; the OPT3001 reports big-endian.
 * The 16-bit value is swapped after reading. */
static int opt3001_read_result(int handle, uint16_t *value)
{
    char buf[2];
    if (i2cReadWordData(handle, RESULT_REG, buf) != 2) {
        fprintf(stderr, "Error reading result register 0x%02X\n", RESULT_REG);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *value = raw;
    return 0;
}

static int opt3001_init(int handle)
{
    /* Configure continuous conversion mode, FS, 100 ms, AFS, 0x0C10 */
    if (opt3001_write_config(handle, CONFIG_WORD) != 0)
        return -1;

    /* Wait for first conversion to complete */
    gpioDelay(CONVERSION_DELAY_US);
    return 0;
}

static int read_lux(int handle, uint16_t *lux_out)
{
    uint16_t raw;
    if (opt3001_read_result(handle, &raw) != 0)
        return -1;

    /* OPT3001 reports big-endian: exponent bits 15-12, mantissa bits 11-0 */
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;

    /* Convert to lux: mantissa * 0.01 * (2^exponent) */
    *lux_out = (uint16_t)((float)mantissa * 0.01f * (float)powf(2.0f, (float)exponent));
    return 0;
}

static void log_data(FILE *fp, uint16_t lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux);
    fflush(fp);
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at OPT3001 address 0x44 */
    g_i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize OPT3001 */
    if (opt3001_init(g_i2c_handle) != 0) {
        fprintf(stderr, "OPT3001 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file for appending */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': ", LOG_FILE);
        perror("");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(fp);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart greenhouse monitoring started. Logging to '%s' every 1 s.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t lux;
        if (read_lux(g_i2c_handle, &lux) != 0) {
            fprintf(stderr, "Skipping sample due to I2C error\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        printf("Lux: %u\n", lux);
        log_data(fp, lux);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (fp != NULL) {
        fclose(fp);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

