#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 4
#define ALERT_GPIO 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000
#define ALERT_DURATION_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static int read_flame_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        log_event("Error: Failed to read GPIO %d.", gpio);
        return -1;
    }
    return value;
}

static void trigger_alert(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        log_event("Error: Failed to set GPIO %d HIGH."), fprintf(stderr, "Error: Failed to set alert GPIO %d HIGH.\n", gpio);
        return;
    }
    log_event("Alert triggered: Flame detected on GPIO %d.", gpio);
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(gpio, 0) != 0) {
        log_event("Error: Failed to set alert GPIO %d LOW."), fprintf(stderr, "Error: Failed to set alert GPIO %d LOW.\n", gpio);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize alert GPIO %d LOW.\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioWrite(ALERT_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioWrite(ALERT_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

