#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define FLOW_RATE_MIN 0.0f
#define FLOW_RATE_MAX 100.0f
#define SAMPLE_INTERVAL_US 1000000
#define READ_DELAY_US 2000
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float flow_rate;
    int status;
} SensorData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d: %d\n",
                SLF3S_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[3];
    int ret;

    ret = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (ret < 0) {
        fprintf(stderr, "I2C write failed: %d\n", ret);
        return -1;
    }

    gpioDelay(READ_DELAY_US);

    ret = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (ret != 3) {
        fprintf(stderr, "I2C read failed: expected 3 bytes, got %d\n", ret);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow rate data\n");
        return -1;
    }

    int16_t raw = (buf[0] << 8) | buf[1];
    *flow_rate = (float)raw / 90.0f;
    return 0;
}

static void log_data(float flow_rate, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s,%.2f,%d\n", ts, flow_rate, status);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("cooling_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    fflush(log_file);

    while (!terminate) {
        float flow_rate;
        int status;

        if (read_flow_rate(&flow_rate) == 0) {
            status = 0;
            if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
                status = 1;
                fprintf(stderr, "Flow rate out of range: %.2f ml/min\n", flow_rate);
            }
        } else {
            status = 1;
            fprintf(stderr, "Failed to read flow rate\n");
        }

        log_data(flow_rate, status);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

