        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, SENSOR_1_PIN);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line %d: %s\n", SENSOR_1_PIN, strerror(errno));
            goto cleanup;
        }

        lines[i] = gpiod_chip_get_line(chip, SENSOR_2_PIN);
        if (lines[i] == NULL) {
