#define LOG_FILE "flame_events.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

static void log_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%s - Flame detected\n", timestamp);
    fclose(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request falling edge events on line %d: %s\n", FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", FLAME_SENSOR_PIN);

    while (running) {
        int ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
