#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_touch_event(int led_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Touch detected: %s\n", timestamp, led_state ? "LED ON" : "LED OFF") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch sensor line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223-touch") < 0) {
        fprintf(stderr, "Failed to request touch events: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ttp223-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", TOUCH_SENSOR_PIN);

    while (program_running) {
        int val = gpiod_line_get_value(touch_line);
        if (val < 0) {
            fprintf(stderr, "Error reading touch sensor: %s\n", strerror(errno));
            break;
        }

        if (val == 1) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Error toggling LED: %s\n", strerror(errno));
                break;
            }
            log_touch_event(1);
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Error toggling LED: %s\n", strerror(errno));
                break;
            }
            log_touch_event(0);
        }

        usleep(POLL_TIMEOUT_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

