 *
 * Flame-detection safety system using libgpiod.
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 * Run:    ./flame_alert
 */

#include <stdio.h>
#include <stdlib.h>
