/*
 * TMAG5110A1 Hall-effect magnetic sensor latch reader for Raspberry Pi 4.
 *
 * Wiring:
 *   Sensor OUT -> GPIO4 (BCM), pull-up enabled (internal)
 *   Sensor OUT -> GPIO17 (BCM), pull-up enabled (internal)
 *   Sensor OUT -> GPIO27 (BCM), pull-up enabled (internal)
 *
 * Behavior:
 *   The TMAG5110A1 latch outputs a logic low when a south pole is
 *   present (magnetic field detected) and a logic high when the field
 *   is removed (no magnet).  The internal pull-up ensures the output
 *   stays stable when the sensor is not actively driving it.
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnet_reader magnet_reader.c -lpigpio -lrt
 * Run:    sudo ./magnet_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_GPIO  4
#define SENSOR2_GPIO  17
#define SENSOR3_GPIO  27

#define LOG_FILE      "magnet_log.txt"
#define POLL_DELAY_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISO-8601 timestamp string                                           */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Log a magnet state change with timestamp                             */
/* ------------------------------------------------------------------ */
static void log_magnet_state(int sensor_id, int state)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return;
    }

    fprintf(g_log_fp, "%s,Sensor%d,State=%d\n", ts, sensor_id, state);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Read a TMAG5110A1 latch with error logging                         */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d).\n",
                gpio_pin, level);
        return -1;
    }

    /*
     * The TMAG5110A1 latch output is open-drain:
     *   logic low = magnet present
     *   logic high = magnet removed
     * The internal pull-up ensures the output stays stable when the
     * sensor is not actively driving it.
     */
    return level;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor GPIOs as inputs with pull-up --- */
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n",
                SENSOR1_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n",
                SENSOR1_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n",
                SENSOR2_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n",
                SENSOR2_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n",
                SENSOR3_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n",
                SENSOR3_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMAG5110A1 magnetic sensor reader started.\n");
    printf("  Sensor 1: GPIO%d  Sensor 2: GPIO%d  Sensor 3: GPIO%d\n",
           SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO);
    printf("  Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_GPIO);
        int s2 = read_sensor(SENSOR2_GPIO);
        int s3 = read_sensor(SENSOR3_GPIO);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Warning: sensor read error — continuing.\n");
        } else {
            log_magnet_state(1, s1);
            log_magnet_state(2, s2);
            log_magnet_state(3, s3);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

