    fprintf(g_log_fp, "%s,Sensor%d,State=%d\n", ts, sensor_id, state);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Read a TMAG5110A1 latch with error logging                         */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d).\n",
                gpio_pin, level);
        return -1;
    }

    /*
     * The TMAG5110A1 latch output is open-drain:
     *   logic low = magnet present
     *   logic high = magnet removed
     * The internal pull-up ensures the output stays stable when the
     * sensor is not actively driving it.
     */
    return level;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor GPIOs as inputs with pull-up --- */
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n",
                SENSOR1_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n",
                SENSOR1_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n",
                SENSOR2_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n",
                SENSOR2_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n",
                SENSOR3_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n",
                SENSOR3_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMAG5110A1 magnetic sensor reader started.\n");
    printf("  Sensor 1: GPIO%d  Sensor 2: GPIO%d  Sensor 3: GPIO%d\n",
           SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO);
    printf("  Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_GPIO);
        int s2 = read_sensor(SENSOR2_GPIO);
        int s3 = read_sensor(SENSOR3_GPIO);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Warning: sensor read error — continuing.\n");
        } else {
            log_magnet_state(1, s1);
            log_magnet_state(2, s2);
            log_magnet_state(3, s3);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

