#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1182_ADDR 0x4A
#define I2C_BUS 1
#define LOG_FILE "heart_rate.csv"
#define BPM_MIN 30.0
#define BPM_MAX 220.0
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, SI1182_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    uint8_t part_id = 0;
    if (i2cReadByteData(i2c_handle, 0x00) < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    uint8_t hw_rev = 0;
    if (i2cReadByteData(i2c_handle, 0x01) < 0) {
        fprintf(stderr, "Error reading HW_REV: %s\n", strerror(errno));
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x01)\n", hw_rev);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x3F, 0x00) < 0) {
        fprintf(stderr, "Error writing LED_CURRENT register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x04, 0x00) < 0) {
        fprintf(stderr, "Error writing Averaging register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x01, 0x01) < 0) {
        fprintf(stderr, "Error writing Enable register\n");
        return -1;
    }

    return 0;
}

static int read_heart_rate(int *heart_rate) {
    uint8_t data[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(i2c_handle, 0x2A);
        if (result < 0) {
            fprintf(stderr, "Error reading heart rate: %s\n", strerror(errno));
            retries++;
            gpioDelay(100000);
            continue;
        }
        data[0] = (uint8_t)result;
        data[1] = 0;
        break;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to read heart rate after %d retries\n", MAX_RETRIES);
        return -1;
    }

    *heart_rate = (data[0] << 8) | data[1];
    return 0;
}

static double calculate_bpm(int heart_rate) {
    return (double)heart_rate * 0.5;
}

static int log_data(double bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int heart_rate;
        if (read_heart_rate(&heart_rate) == 0) {
            double bpm = calculate_bpm(heart_rate);
            if (log_data(bpm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading heart rate, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

