/*
 * 8-channel TTP226 capacitive touch sensor counter on Raspberry Pi Zero W.
 *
 * Wiring:
 *   TTP226 OUT1 -> GPIO 5 (BCM 5)
 *   TTP226 OUT2 -> GPIO 6 (BCM 6)
 *   TTP226 OUT3 -> GPIO 7 (BCM 7)
 *   TTP226 OUT4 -> GPIO 8 (BCM 8)
 *   TTP226 OUT5 -> GPIO 9 (BCM 9)
 *   TTP226 OUT6 -> GPIO 10 (BCM 10)
 *   TTP226 OUT7 -> GPIO 11 (BCM 11)
 *   TTP226 OUT8 -> GPIO 12 (BCM 12)
 *   TTP226 VDD -> 3.3 V (Pin 1)
 *   TTP226 GND -> GND  (Pin 9)
 *
 * Build: gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define GPIO_CHIP_NAME "gpiochip0"
#define LOG_FILE "touch_log.txt"
#define POLL_INTERVAL_MS 10
#define STABILIZATION_DELAY_MS 200

