#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define LOG_FILE "tracking_log.csv"
#define POLL_INTERVAL_MS 100

static const unsigned int sensor_pins[NUM_SENSORS] = {17, 18, 27, 22};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_sensor_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(lines[i], "ky033-tracker") < 0) {
            fprintf(stderr, "gpiod_line_request_input(%u) failed: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    if (fseek(fp, 0, SEEK_END) == 0) {
        long file_size = ftell(fp);
        if (file_size == 0) {
            if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
                fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
                goto cleanup;
            }
            if (fflush(fp) != 0) {
                fprintf(stderr, "fflush failed: %s\n", strerror(errno));
                goto cleanup;
            }
        }
    }

    printf("Monitoring KY-033 sensors... Press Ctrl+C to exit.\n");

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(%u) failed: %s\n", sensor_pins[i], strerror(errno));
                continue;
            }

            if (val == 0) {
                if (log_sensor_data(fp, sensor1, sensor2, sensor3, sensor4) != 0) {
                    fprintf(stderr, "Failed to log sensor data.\n");
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

