#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125
#define LED_ON_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    printf("[%s] ", timestamp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_PIN %d as input\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED_PIN %d to LOW\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Monitoring MIC on GPIO%d. Press Ctrl+C to exit.\n", MIC_PIN);

    while (running) {
        int mic_val = gpioRead(MIC_PIN);
        if (mic_val < 0) {
            fprintf(stderr, "Error: gpioRead failed on MIC_PIN %d\n", MIC_PIN);
            break;
        }

        if (mic_val == 1) {
            print_timestamp();
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_MS * 1000);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

