/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+
 * Uses libgpiod v1.x API (no wiringPi).
 *
 * Wiring:
 *   TTP226 VCC -> 3V3 (Pin 1)
 *   TTP226 GND -> GND (Pin 9)
 *   TTP226 OUT -> BCM GPIO 5, 6, 13, 19, 26, 12, 16, 20 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int gpio_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int read_channel(struct gpiod_line *line, int channel)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %u: %s\n",
                channel, strerror(errno));
        return -1;
    }
    return value;
}

static void log_sensor_data(int *data, int num_data)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("[%s] CH%d=%d\n", timestamp, channel + 1, data[channel]);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int pins[NUM_CHANNELS];
    int i;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226_reader") < 0) {
            fprintf(stderr, "Failed to request GPIO %u as input: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 8-channel capacitive touch sensor reader started.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int value = read_channel(lines[i], i);
            if (value < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                continue;
            }
            log_sensor_data(&value, 1);
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");

cleanup:
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

