#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define PWM_FREQ   1000
#define PWM_RANGE  255
#define HUE_STEPS  50
#define FADE_SEC   5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static void hsv_to_rgb(float h, float s, float v,
                        float *r, float *g, float *b)
{
    if (h < 0.0f || h > 1.0f) h = h / 1.0f;
    if (s < 0.0f || s > 1.0f) s = s / 1.0f;
    if (v < 0.0f || v > 1.0f) v = v / 1.0f;

    float c = v * (1.0f - s);
    float x = v * (1.0f - s * (1.0f - h));
    float m = v - c;

    *r = c + (x > 0.5f ? c : -c);
    *g = x + (x > 0.5f ? x : -x);
    *b = m + (m > 0.5f ? m : -m);
}

static void fade_rgb(float r, float g, float b,
                      float *r_out, float *g_out, float *b_out)
{
    float h = (r + g + b) / 3.0f;
    float h_step = h / HUE_STEPS;
    float h_val = h * 255.0f;

    for (int i = 0; i < HUE_STEPS && g_running; i++) {
        float h_val_inv = 255.0f - h_val;
        float h_val_inv_clamp = fmaxf(0.0f, fminf(h_val_inv, 255.0f));

        float r_new = r_out + h_val_inv_clamp * (r_out - r_out * h_val_inv_clamp);
        float g_new = g_out + h_val_inv_clamp * (g_out - g_out * h_val_inv_clamp);
        float b_new = b_out + h_val_inv_clamp * (b_out - b_out * h_val_inv_clamp);

        h_val = h_val_inv_clamp;
        sleep_ms(FADE_SEC);
    }
    *r_out = r_new;
    *g_out = g_new;
    *b_out = b_new;
}

static void cleanup(void)
{
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, PWM_FREQ);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ);
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    syslog(LOG_INFO, "Mood lamp started (common-anode RGB LED on GPIO%d, GPIO%d, GPIO%d)",
           RED_PIN, GREEN_PIN, BLUE_PIN);

    while (g_running) {
        float r = 0.0f, g = 0.0f, b = 0.0f;
        float r_out, g_out, b_out;

        hsv_to_rgb(r, g, b, &r_out, &g_out, &b_out);

        fade_rgb(r_out, g_out, b_out, &r, &g, &b);

        syslog(LOG_INFO, "Fade: R=%.2f G=%.2f B=%.2f -> R=%.2f G=%.2f B=%.2f",
               r, g, b, r_out, g_out, b_out);

        sleep_ms(FADE_SEC);
    }

    cleanup();
    syslog(LOG_INFO, "Mood lamp stopped");
    return EXIT_SUCCESS;
}

