static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
            reg, val, strerror(errno));
    return -1;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out) {
    if (i2c_write_byte(fd, reg, 0x00) < 0) return -1;
    uint8_t buf[2];
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (read(fd, buf, 2) == 2) {
            *out = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
        usleep(I2C_RETRY_DELAY_MS * 1000);
