#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VEML7700_ADDR 0x10
#define VEML7700_REG_CONFIG 0x00
#define VEML7700_REG_ALS 0x04
#define I2C_DEV "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 18
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 100
#define LUX_THRESHOLD 0
#define LUX_MAX 120000.0
#define LUX_SCALE 0.036
#define INTEGRATION_TIME_MS 100
#define BRIGHTNESS_SCALE 0.0288
#define BRIGHTNESS_MAX 255
#define LOOP_DELAY_MS 200

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_init(int fd) {
    if (i2c_write_reg(fd, VEML7700_REG_CONFIG, 0x0000) < 0) return -1;
    usleep(INTEGRATION_TIME_MS * 1000);
    if (i2c_write_reg(fd, VEML7700_REG_CONFIG, 0x0000) < 0) return -1;
    return 0;
}

static int veml7700_read_als(int fd, uint16_t *als) {
    uint8_t buf[2];
    if (i2c_read_reg(fd, VEML7700_REG_ALS, buf) < 0) return -1;
    *als = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float lux_to_brightness(float lux) {
    return (float)LUX_SCALE * (LUX_MAX / LUX_MAX) * (1.0f / (1.0f / BRIGHTNESS_SCALE));
}

static int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) return 0;
    return (int)((lux / LUX_MAX) * BRIGHTNESS_MAX);
}

static int bit_bang_led(struct gpiod_line *line, int brightness) {
    if (brightness > BRIGHTNESS_MAX) brightness = BRIGHTNESS_MAX;
    if (brightness < 0) brightness = 0;
    int duty_cycle = (int)((brightness * 255.0f) / BRIGHTNESS_MAX);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(duty_cycle * 100000);
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(duty_cycle * 100000);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (veml7700_init(i2c_fd) < 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(line, "veml7700_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int retries = I2C_RETRIES;
    while (running) {
        uint16_t als;
        if (veml7700_read_als(i2c_fd, &als) < 0) {
            fprintf(stderr, "Failed to read ALS data, retrying (%d/%d)\n", retries, I2C_RETRIES);
            retries++;
            if (retries > I2C_RETRIES) {
                fprintf(stderr, "I2C bus error, exiting\n");
                break;
            }
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        retries = I2C_RETRIES;
        float lux = (float)als / LUX_MAX * LUX_MAX;
        int brightness = map_lux_to_brightness(lux);
        if (bit_bang_led(line, brightness) < 0) {
            fprintf(stderr, "LED bit-banging failed\n");
            break;
        }
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        usleep(LOOP_DELAY_MS * 1000);
    }

    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

