#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_HRES 0x10
#define GPIO_CHIP      "/sys/class/gpio"
#define GPIO_PIN       17
#define BUFFER_SIZE    60
#define LUX_THRESHOLD  1000.0f
#define BLINK_RATE_MIN 0.5f
#define BLINK_RATE_MAX 5.0f
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_lux(int fd, float *lux_out) {
    uint8_t cmd = BH1750_CMD_HRES;
    if (i2c_write_byte(fd, cmd) < 0) return -1;
    usleep(10000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;

    int raw = (buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static float calculate_average_lux(const float *buffer, size_t size) {
    float sum = 0.0f;
    for (size_t i = 0; i < size; i++) sum += buffer[i];
    return sum / (float)size;
}

static void control_led(int gpio, int on_off) {
    if (gpio_on_off(gpio, on_off) < 0) {
        fprintf(stderr, "GPIO write failed: %s\n", strerror(errno));
    }
}

static int gpio_on_off(int gpio, int on_off) {
    char path[64];
    snprintf(path, sizeof(path), "%s/gpio%d/export", GPIO_CHIP, GPIO_PIN);
    if (write(i2c_fd, path, strlen(path)) < 0) {
        fprintf(stderr, "GPIO export failed: %s\n", strerror(errno));
        return -1;
    }
    char path_gpio[64];
    snprintf(path_gpio, sizeof(path_gpio), "%s/gpio%d/gpio%d/level", GPIO_CHIP, GPIO_PIN, gpio);
    if (on_off) {
        snprintf(path_gpio, sizeof(path_gpio), "%s/gpio%d/high", path_gpio, gpio);
    } else {
        snprintf(path_gpio, sizeof(path_gpio), "%s/gpio%d/low", path_gpio, gpio);
    }
    if (write(i2c_fd, path_gpio, strlen(path_gpio)) < 0) {
        fprintf(stderr, "GPIO write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (gpio_on_off(GPIO_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d\n", GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    float buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int last_lux = 0.0f;

    while (running) {
        float lux = 0.0f;
        if (read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Skipping sample due to I2C read error\n");
            usleep(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        float avg = calculate_average_lux(buffer, BUFFER_SIZE);
        float rate = (avg > LUX_THRESHOLD) ? BLINK_RATE_MAX : BLINK_RATE_MIN;
        control_led(GPIO_PIN, (rate > 0.0f) ? 1.0f : 0.0f);

        buffer[buffer_index] = lux;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        if (buffer_index == 0) {
            last_lux = lux;
        }

        usleep(SAMPLE_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    gpio_on_off(GPIO_PIN, 0);
    close(i2c_fd);
    return 0;
}

