#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEGMENT_A 0
#define SEGMENT_B 1
#define SEGMENT_C 2
#define SEGMENT_D 3
#define SEGMENT_E 4
#define SEGMENT_F 5
#define SEGMENT_G 6
#define SEGMENT_DP 7

#define NUM_SEGMENTS 8

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (data_line) {
        gpiod_line_set_value(data_line, 0);
        gpiod_line_release(data_line);
    }
    if (clock_line) {
        gpiod_line_set_value(clock_line, 0);
        gpiod_line_release(clock_line);
    }
    if (latch_line) {
        gpiod_line_set_value(latch_line, 0);
        gpiod_line_release(latch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

void blink_digit(int digit) {
    if (digit == 5) {
        gpiod_line_set_value(data_line, 1);
        gpiod_line_set_value(clock_line, 1);
        usleep(500000);
        gpiod_line_set_value(clock_line, 0);
        usleep(500000);
        gpiod_line_set_value(data_line, 0);
        gpiod_line_set_value(clock_line, 0);
        usleep(500000);
    } else {
        gpiod_line_set_value(data_line, 0);
        gpiod_line_set_value(clock_line, 1);
        usleep(500000);
        gpiod_line_set_value(clock_line, 0);
        usleep(500000);
    }
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(data_line, "seven_segment", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seven_segment", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seven_segment", 0) < 0) {
        perror("Failed to request GPIO lines as outputs");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize 74HC595
