#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define CONSUMER "blink_button"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        cleanup_and_exit(0);
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        cleanup_and_exit(0);
    }

    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        cleanup_and_exit(0);
    }

    if (gpiod_line_request_input_flags(button_line, CONSUMER, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags (button)");
        cleanup_and_exit(0);
    }

    printf("Blinking LED on BCM GPIO%d, monitoring button on BCM GPIO%d. Press Ctrl+C to exit.\n",
           LED_PIN, BUTTON_PIN);

    while (keep_running) {
        struct timespec ts = {1, 0};
        int ret = gpiod_line_event_wait(button_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(button_line, &event) < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            printf("Button pressed!\n");
            gpiod_line_set_value(led_line, 0);
            usleep(1000);
            gpiod_line_set_value(led_line, 1);
            usleep(1000);
            printf("LED turned off.\n");
            break;
        }
    }

    cleanup_and_exit(0);
    return EXIT_SUCCESS;
}

