#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

#define PWM_PERIOD_NS 1000000  // 1 ms
#define PWM_DUTY_RANGE 100
#define PWM_PERIOD_US 1000    // 1 ms

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL;
    struct gpiod_line *green_line = NULL;
    struct gpiod_line *blue_line = NULL;
    int ret;

    // Set up signal handler for clean exit
    signal(SIGINT, signal_handler);

    // Open GPIO chip 0 (Raspberry Pi 5 default)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip 0");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO lines");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as outputs
    ret = gpiod_line_request_output(red_line, "rgb_led", 0);
    if (ret < 0) {
        perror("Failed to request red line as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

