#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define ADPD188BI_ADDR 0x39
#define I2C_BUS 1
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOG_FILE "color_log.csv"
#define SAMPLE_INTERVAL_US 500000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_adpd188bi(int handle) {
    if (i2cWriteByteData(handle, 0x0D, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write mode register (0x0D).\n");
        return -1;
    }
    return 0;
}

static int read_adpd188bi(int handle, uint16_t *als, uint16_t *r, uint16_t *g, uint16_t *b) {
    char buf[6];
    int bytes_read = i2cReadDevice(handle, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: Failed to read ALS data (read %d bytes).\n", bytes_read);
        return -1;
    }
    *als = (uint16_t)((buf[0] << 8) | buf[1]);
    *r = (uint16_t)((buf[2] << 8) | buf[3]);
    *g = (uint16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int read_color_data(int handle, uint16_t *r, uint16_t *g, uint16_t *b) {
    char buf[6];
    int bytes_read = i2cReadDevice(handle, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: Failed to read color data (read %d bytes).\n", bytes_read);
        return -1;
    }
    *r = (uint16_t)((buf[0] << 8) | buf[1]);
    *g = (uint16_t)((buf[2] << 8) | buf[3]);
    *b = (uint16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t r, uint16_t g, uint16_t b) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            als, r, g, b);
    fflush(fp);
}

static void control_led(int gpio, uint16_t als, uint16_t r, uint16_t g, uint16_t b) {
    uint16_t als_value = (uint16_t)((als * 65535) / 65536);
    uint16_t r_value = (uint16_t)((r * 65535) / 65536);
    uint16_t g_value = (uint16_t)((g * 65535) / 65536);
    uint16_t b_value = (uint16_t)((b * 65535) / 65536);

    if (als_value > 0) {
        gpioPWM(gpio, PWM_RANGE);
        gpioPWM(gpio, PWM_RANGE);
        gpioPWM(gpio, PWM_RANGE);
        gpioPWM(gpio, PWM_RANGE);
    } else {
        gpioPWM(gpio, 0);
    }

    uint16_t duty_cycle = (uint16_t)((als_value * PWM_FREQUENCY) / 65536);
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (duty_cycle < 0) duty_cycle = 0;

    gpioPWM(gpio, duty_cycle);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X.\n", ADPD188BI_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_adpd188bi(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADPD188BI initialization failed.\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als, r, g, b;
    while (!terminate) {
        if (read_adpd188bi(i2c_handle, &als, &r, &g, &b) == 0) {
            log_data(log_file, als, r, g, b);
            control_led(LED_GPIO, als, r, g, b);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying in 100ms...\n");
            gpioDelay(100000);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

