    terminate = 1;
}

/* ---- Initialize the FXOS8700 ---- */
static int init_fxos8700(void)
{
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (pigpio error %d).\n",
                who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby: clear CTRL_REG1 bit 0 (standby) */
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_REG, CTRL_REG1_VAL) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1.\n");
        return -1;
    }

    /* Configure XYZ_DATA_CFG: ±2g mode */
    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG_REG, XYZ_DATA_CFG_2G_MODE) < 0) {
        fprintf(stderr, "Error: failed to write XYZ_DATA_CFG.\n");
        return -1;
    }

    /* Activate: clear CTRL_REG1 bit 0 (active mode) */
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_REG, CTRL_REG1_VAL) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1.\n");
        return -1;
    }

    return 0;
}

/* ---- Read 6 bytes of acceleration (14-bit left-justified) ---- */
static int read_accel_raw(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int  rc;

    rc = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: I2C block read returned %d (expected 6).\n", rc);
        return -1;
    }

    /* 14-bit left-justified: shift right by 2 */
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* ---- Calculate magnitude (m/s^2) from 14-bit left-justified ---- */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    return (float)x * 0.00390625f +
           (float)y * 0.00390625f +
           (float)z * 0.00390625f;
}

/* ---- Log impact to file ---- */
static void log_impact(float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        perror("Error opening impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", ts, x, y, z, magnitude);
    fclose(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700 address 0x1F */
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_fxos8700() != 0) {
        fprintf(stderr, "Error: FXOS8700 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t x, y, z;

        if (read_accel_raw(&x, &y, &z) != 0) {
            fprintf(stderr, "Warning: I2C read error; continuing.\n");
        } else {
            float magnitude = calculate_magnitude(x, y, z);
            log_impact(magnitude);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

