/*
 * GY-50 L3G4200D gyroscope reader for Raspberry Pi Zero W
 * Uses i2c-dev character device (/dev/i2c-1) at address 0x69.
 *
 * Build: gcc -O2 -Wall -o gyro_reader gyro_reader.c
 * Run:   sudo ./gyro_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define GYRO_ADDR          0x69
#define GYRO_WHO_AM_I      0x0F
#define GYRO_WHO_AM_I_VAL  0xD3
#define GYRO_CTRL_REG1     0x20
#define GYRO_CTRL_REG4     0x23
#define GYRO_OUT_X_L       0x28
#define GYRO_OUT_X_H       0x29
#define GYRO_OUT_Y_L       0x2A
#define GYRO_OUT_Y_H       0x2B
#define GYRO_OUT_Z_L       0x2C
#define GYRO_OUT_Z_H       0x2D

#define SENSITIVITY        0.00875f   /* dps/LSB */
#define MAX_DPS           50.0f
#define CALIBRATION_SAMPLES 100
#define LOG_INTERVAL_US   50000      /* 50 ms */
#define I2C_BUS            "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu: %s\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gyroscope calibration                                               */
/* ------------------------------------------------------------------ */
static int calibrate_gyro(int fd, float *x_offset, float *y_offset,
                          float *z_offset)
{
    uint8_t who_am_i;
    if (i2c_read_block(fd, GYRO_WHO_AM_I, &who_am_i, 1) != 0)
        return -1;
    if (who_am_i != GYRO_WHO_AM_I_VAL) {
        fprintf(stderr, "GY-50 WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, GYRO_WHO_AM_I_VAL);
        return -1;
    }

    uint8_t raw[6];
    if (i2c_read_block(fd, GYRO_OUT_X_L, raw, 6) != 0)
        return -1;

    int16_t x = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t y = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t z = (int16_t)((raw[4] << 8) | raw[5]);

    *x_offset = (float)x / SENSITIVITY;
    *y_offset = (float)y / SENSITIVITY;
    *z_offset = (float)z / SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                GYRO_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify sensor presence via WHO_AM_I */
    uint8_t who_am_i;
    if (i2c_read_block(g_i2c_fd, GYRO_WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "GY-50 not detected at 0x%02X\n", GYRO_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (who_am_i != GYRO_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, GYRO_WHO_AM_I_VAL);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* CTRL_REG1: normal mode, all axes enabled, 100 Hz ODR */
    if (i2c_write_reg8(g_i2c_fd, GYRO_CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* CTRL_REG4: 250 dps full-scale, continuous update */
    if (i2c_write_reg8(g_i2c_fd, GYRO_CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("gyro_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open gyro_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (calibrate_gyro(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Calibration failed; skipping sample.\n");
        } else {
            log_data(g_log_fp, x, y, z);
            printf("X: %.3f, Y: %.3f, Z: %.3f\n", x, y, z);
        }
        usleep(LOG_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

