#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define MAG_ADDR   0x1E
#define ACCEL_REG_X_L_A 0x28
#define ACCEL_REG_X_H_A 0x29
#define MAG_REG_M_X_H_M 0x03
#define CTRL_REG1_A 0x20
#define MR_REG_M   0x02

static int accel_handle = -1;
static int mag_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1_A\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing MR_REG_M\n");
        return -1;
    }
    return 0;
}

static int read_sensor(int handle, int reg, int16_t *data) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading sensor data from 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y, int16_t z) {
    float heading = atan2f((float)y, (float)z) * 180.0f / M_PI;
    if (heading < 0.0f) heading += 360.0f;
    return heading;
}

static void log_data(float heading, int16_t ax, int16_t ay, int16_t az, int16_t mx, int16_t my, int16_t mz) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    FILE *fp = fopen("compass_log.txt", "a");
    if (fp) {
        fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, heading, ax, ay, az, mx, my, mz);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening log file\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

