#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VL6180X_ADDR 0x29
#define VL6180X_REG_STATUS 0x04d
#define VL6180X_REG_RANGE_STATUS 0x0207
#define VL6180X_REG_CONFIG 0x000
#define VL6180X_REG_DATA 0x00d
#define VL6180X_INIT_SEQ 0x01
#define VL6180X_INIT_SEQ_LEN 3
#define VL6180X_INIT_SEQ_VAL 0x01
#define VL6180X_RANGE_ERR 0x01
#define VL6180X_RANGE_OK 0x00
#define VL6180X_RANGE_MIN 100
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl6180x_init(void) {
    uint8_t init_seq[VL6180X_INIT_SEQ_LEN];
    init_seq[0] = VL6180X_REG_CONFIG;
    init_seq[1] = VL6180X_INIT_SEQ_VAL;
    init_seq[2] = 0x00;
    if (i2cWriteDevice(i2c_handle, (char *)init_seq, 3) != 0) {
        fprintf(stderr, "Error: Failed to write VL6180X init sequence\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int vl6180x_read_range(int *range_out) {
    uint8_t reg = VL6180X_REG_DATA;
    uint8_t data[2];
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set register address for VL6180X\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from VL6180X\n");
        return -1;
    }
    *range_out = (data[0] << 8) | data[1];
    return 0;
}

static int vl6180x_read_status(int *status_out) {
    uint8_t reg = VL6180X_REG_STATUS;
    uint8_t data[1];
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set register address for VL6180X\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)data, 1) != 1) {
        fprintf(stderr, "Error: Failed to read 1 byte from VL6180X\n");
        return -1;
    }
    *status_out = data[0];
    return 0;
}

static int vl6180x_read_range_status(int *range_out) {
    int status;
    if (vl6180x_read_status(&status) != 0) {
        return -1;
    }
    if (status & VL6180X_RANGE_ERR) {
        fprintf(stderr, "Error: VL6180X range error (0x%02X)\n", status);
        return -1;
    }
    if (status & VL6180X_RANGE_OK) {
        *range_out = status;
    }
    return 0;
}

static void log_reading(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X\n", VL6180X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (vl6180x_init() != 0) {
        fprintf(stderr, "Error: VL6180X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL6180X proximity door opener started. Press Ctrl+C to exit.\n");

    while (running) {
        int range;
        if (vl6180x_read_range_status(&range) != 0) {
            fprintf(stderr, "Error: Failed to read VL6180X status\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int status = range & 0x0F;
        if (status == VL6180X_RANGE_ERR) {
            fprintf(stderr, "Warning: VL6180X range error (0x%02X)\n", status);
        }

        if (range < VL6180X_RANGE_MIN) {
            log_reading(range);
            printf("DOOR_OPEN\n");
        } else {
            log_reading(range);
            printf("DOOR_CLOSED\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

