#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

static int read_register(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, i2cReadByte(handle));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, i2cReadByte(handle));
        return -1;
    }
    *value = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, i2cReadByte(handle));
        return -1;
    }
    return 0;
}

static int read_audio_sample(int handle, int16_t *sample) {
    uint16_t raw;
    if (read_register(handle, 0x01, &raw) < 0) {
        return -1;
    }
    *sample = (int16_t)raw;
    return 0;
}

static int log_data(FILE *fp, int16_t sensor1, int16_t sensor2, int16_t tdoa) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, tdoa);
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Audio logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t sample1, sample2;
        int16_t tdoa;

        if (read_audio_sample(i2c_handle1, &sample1) < 0) {
            fprintf(stderr, "Sensor 1 read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (read_audio_sample(i2c_handle2, &sample2) < 0) {
            fprintf(stderr, "Sensor 2 read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (read_audio_sample(i2c_handle2, &tdoa) < 0) {
            fprintf(stderr, "Sensor 2 read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_data(log_file, sample1, sample2, tdoa) < 0) {
            fprintf(stderr, "Logging error, skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

