/*
 * ADIS16488A IMU reader for Raspberry Pi 4 Model B
 * SPI: CE0 (GPIO8), 1 MHz, mode 3, 16-bit words
 * Logs gyro X,Y,Z and accel X,Y,Z every 100 ms to imu_data.csv
 * Build: gcc -O2 -Wall -o imu_reader imu_reader.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL        0          /* CE0 on GPIO8 */
#define SPI_SPEED          1000000     /* 1 MHz */
#define SPI_FLAGS          0b11000000000 /* mode 3, CPHA=1, CPHA=1, CPOL=0, CPOL=0 */
#define GYRO_REG_X_GYRO   0x04
#define ACCEL_REG_X_ACCEL 0x0A
#define GYRO_SENSITIVITY  0.005f      /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f    /* g/LSB */
#define SAMPLE_PERIOD_US  100000      /* 100 ms */
#define STALL_US           40          /* ADIS16488A: 40 us between read and data */
#define MAX_RETRIES        3

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_csv_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_csv_fp) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit word from a 16-bit register address.                */
/* Returns 0 on success, -1 on SPI transfer error.                  */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg_addr, uint16_t *out)
{
    char tx[2] = { (char)(reg_addr & 0xFF), (char)((reg_addr >> 8) & 0xFF) };
    char rx[2] = { 0, 0 };

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer error (reg 0x%02X): %s\n",
                reg_addr, pigpio_error(spiXfer(handle, tx, rx, 2)));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read gyroscope X,Y,Z and accelerometer X,Y,Z.                        */
/* Returns 0 on success, -1 on SPI transfer error.                      */
/* ------------------------------------------------------------------ */
static int read_imu_data(int handle, float *gyro_x, float *gyro_y,
                         float *gyro_z, float *accel_x, float *accel_y,
                         float *accel_z)
{
    uint16_t gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw;

    if (read_register(handle, GYRO_REG_X_GYRO, &gyro_x_raw) != 0)
        return -1;
    if (read_register(handle, GYRO_REG_X_GYRO + 1, &gyro_y_raw) != 0)
        return -1;
    if (read_register(handle, GYRO_REG_X_GYRO + 2, &gyro_z_raw) != 0)
        return -1;
    if (read_register(handle, ACCEL_REG_X_ACCEL, &accel_x_raw) != 0)
        return -1;
    if (read_register(handle, ACCEL_REG_X_ACCEL + 1, &accel_y_raw) != 0)
        return -1;
    if (read_register(handle, ACCEL_REG_X_ACCEL + 2, &accel_z_raw) != 0)
        return -1;

    *gyro_x = (float)gyro_x_raw * GYRO_SENSITIVITY;
    *gyro_y = (float)gyro_y_raw * GYRO_SENSITIVITY;
    *gyro_z = (float)gyro_z_raw * GYRO_SENSITIVITY;
    *accel_x = (float)accel_x_raw * ACCEL_SENSITIVITY;
    *accel_y = (float)accel_y_raw * ACCEL_SENSITIVITY;
    *accel_z = (float)accel_z_raw * ACCEL_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV.                                              */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z,
                     float accel_x, float accel_y, float accel_z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            ts, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- CSV open --- */
    g_csv_fp = fopen("imu_data.csv", "a");
    if (!g_csv_fp) {
        fprintf(stderr, "Cannot open imu_data.csv\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_csv_fp, 0, SEEK_END);
    if (ftell(g_csv_fp) == 0) {
        fprintf(g_csv_fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
        fflush(g_csv_fp);
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop --- */
    while (g_running) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_imu_data(g_spi_handle, &gyro_x, &gyro_y, &gyro_z,
                          &accel_x, &accel_y, &accel_z) == 0) {
            log_data(g_csv_fp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read IMU data after %d retries\n",
                    MAX_RETRIES);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_US / 1000 && g_running; i++)
            gpioDelay(1000);
    }

    /* --- cleanup --- */
    cleanup();
    return EXIT_SUCCESS;
}

