#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define CS_PIN 8
#define LOG_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
