static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t tx_byte, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_byte,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};

    if (spi_transfer(tx[0], rx[0], 2) < 0) return -1;
    if (spi_transfer(rx[1], rx[1], 2) < 0) return -1;

    *value = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int read_register_16(uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};

    if (spi_transfer(tx[0], rx[0], 2) < 0) return -1;
    if (spi_transfer(rx[1], rx[1], 2) < 0) return -1;

    *value = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int read_gyro_x(float *gyro_x) {
    uint16_t val;
    if (read_register_16(XGYRO_OUT, &val) < 0) return -1;
    *gyro_x = (float)val * 0.02f;
    return 0;
}

static int read_gyro_y(float *gyro_y) {
    uint16_t val;
    if (read_register_16(YGYRO_OUT, &val) < 0) return -1;
    *gyro_y = (float)val * 0.02f;
    return 0;
}

static int read_gyro_z(float *gyro_z) {
    uint16_t val;
    if (read_register_16(ZGYRO_OUT, &val) < 0) return -1;
    *gyro_z = (float)val * 0.02f;
    return 0;
}

static int read_accel_x(float *accel_x) {
    uint16_t val;
    if (read_register_16(XACCL_OUT, &val) < 0) return -1;
    *accel_x = (float)val * 0.00025f;
    return 0;
}

static int read_accel_y(float *accel_y) {
    uint16_t val;
    if (read_register_16(YACCL_OUT, &val) < 0) return -1;
    *accel_y = (float)val * 0.00025f;
    return 0;
}

static int read_accel_z(float *accel_z) {
    uint16_t val;
    if (read_register_16(ZACCL_OUT, &val) < 0) return -1;
    *accel_z = (float)val * 0.00025f;
    return 0;
}

static void cleanup(void) {
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "adis16448_cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", CS_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    printf("ADIS16448 IMU initialized. Logging every %d ms. Press Ctrl+C to exit.\n", LOG_INTERVAL_MS);

    while (running) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_gyro_x(&gyro_x) < 0 || read_gyro_y(&gyro_y) < 0 || read_gyro_z(&gyro_z) < 0 ||
            read_accel_x(&accel_x) < 0 || read_accel_y(&accel_y) < 0 || read_accel_z(&accel_z) < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            usleep(LOG_INTERVAL_MS * 1000);
            continue;
        }

        printf("Gyro X: %.2f, Gyro Y: %.2f, Gyro Z: %.2f\n", gyro_x, gyro_y, gyro_z);
        printf("Accel X: %.2f, Accel Y: %.2f, Accel Z: %.2f\n", accel_x, accel_y, accel_z);

        usleep(LOG_INTERVAL_MS * 1000);
    }

    printf("\nExiting cleanly.\n");
    cleanup();
    return 0;
}

