#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define GYRO_REG 0x04
#define ACCEL_REG 0x06
#define GYRO_SCALE 0.05f
#define ACCEL_SCALE 0.00025f

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, int len) {
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed: returned %d, expected %d\n", ret, len);
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(tx, rx, 2) != 0) return -1;
    *value = ((uint16_t)rx[1] << 8) | rx[0];
    return 0;
}

static int read_gyro_data(float *gyro_x, float *gyro_y, float *gyro_z) {
    uint16_t raw;
    if (read_register(GYRO_REG, &raw) != 0) return -1;
    *gyro_x = (float)raw * GYRO_SCALE;
    *gyro_y = (float)raw * GYRO_SCALE;
    *gyro_z = (float)raw * GYRO_SCALE;
    return 0;
}

static int read_accel_data(float *accel_x, float *accel_y, float *accel_z) {
    uint16_t raw;
    if (read_register(ACCEL_REG, &raw) != 0) return -1;
    *accel_x = (float)raw * ACCEL_SCALE;
    *accel_y = (float)raw * ACCEL_SCALE;
    *accel_z = (float)raw * ACCEL_SCALE;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) != 0) {
            fprintf(stderr, "Gyro read failed\n");
            gpioDelay(100000);
            continue;
        }
        if (read_accel_data(&accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "Accel read failed\n");
            gpioDelay(100000);
            continue;
        }

        printf("Gyro: X=%.3f, Y=%.3f, Z=%.3f\n", gyro_x, gyro_y, gyro_z);
        printf("Accel: X=%.3f, Y=%.3f, Z=%.3f\n", accel_x, accel_y, accel_z);
        gpioDelay(100000);
    }

    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("\nClean exit\n");
    return EXIT_SUCCESS;
}

