#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ICM20602_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define WHO_AM_I_VAL 0x12
#define ACCEL_CONFIG 0x00
#define GYRO_CONFIG 0x00
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define CSV_FILE "imu_log.csv"

static int i2c_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteI2CBlockData(handle, reg, buf, 2) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X)\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int handle, uint8_t reg, char *buf, uint32_t len) {
    if (i2cWriteI2CBlockData(handle, reg, buf, len) < 0) {
        fprintf(stderr, "I2C burst write failed (reg 0x%02X)\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, char *buf, uint32_t len) {
    if (i2cWriteI2CBlockData(handle, reg, buf, len) < 0) {
        fprintf(stderr, "I2C block write failed (reg 0x%02X)\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *val) {
    char buf[2];
    if (i2c_read_burst(handle, reg, buf, 2) < 0) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    char buf[1];
    if (i2c_read_burst(handle, reg, buf, 1) < 0) return -1;
    *val = buf[0];
    return 0;
}

static int init_icm20602(int handle) {
    if (i2c_write_reg(handle, WHO_AM_I_REG, WHO_AM_I_VAL) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg(handle, ACCEL_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(handle, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_imu_data(int handle, float *ax, float *ay, float *az, float *gx, float *gy, float *gz) {
    char buf[6];
    if (i2c_read_block(handle, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *ax = (float)buf[0] | ((float)buf[1] << 8) | ((float)buf[2] << 16);
    *ay = (float)buf[3] | ((float)buf[4] << 8) | ((float)buf[5] << 16);
    *az = (float)buf[6] | ((float)buf[7] << 8) | ((float)buf[8] << 16);
    if (i2c_read_block(handle, GYRO_XOUT_H, buf, 6) < 0) return -1;
    *gx = (float)buf[0] | ((float)buf[1] << 8) | ((float)buf[2] << 16);
    *gy = (float)buf[3] | ((float)buf[4] << 8) | ((float)buf[5] << 16);
    *gz = (float)buf[6] | ((float)buf[7] << 8) | ((float)buf[8] << 16);
    return 0;
}

static int log_data(FILE *fp, float ax, float ay, float az, float gx, float gy, float gz) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            ax, ay, az, gx, gy, gz);
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, ICM20602_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_icm20602(i2c_handle) < 0) {
        fprintf(stderr, "IMU initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file %s\n", CSV_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(csv_file, "timestamp,ax,ay,az,gx,gy,gz\n");
    fflush(csv_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float ax, ay, az, gx, gy, gz;
    while (running) {
        if (read_imu_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            if (log_data(csv_file, ax, ay, az, gx, gy, gz) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "IMU read failed\n");
        }
        gpioDelay(100000);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (csv_file) fclose(csv_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

