/*
 * GY-45 MMA8451Q Accelerometer reader with LED impact indicator.
 * Board:  Raspberry Pi 3 Model B+
 * I2C:    /dev/i2c-1  (BCM 17, GPIO2 = SDA, GPIO3 = SCL)
 * LED:    GPIO17 (BCM 17, GPIO numbering)
 *
 * Build:  gcc -O2 -Wall -o accel_impact accel_impact.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define GY_ACCEL_ADDR        0x1D
#define GY_ACCEL_WHO_AM_I    0x0D
#define GY_ACCEL_WHO_AM_I_VAL 0x1A
#define GY_ACCEL_WHO_AM_I_VAL_VAL 0x1A
#define GY_ACCEL_WHO_AM_I_VAL_VAL_VAL 0x1A
