    running = 0;
}

static int spi_transfer(uint8_t tx_byte, uint8_t *rx_byte) {
    int result = spiXfer(spi_handle, (char *)&tx_byte, (char *)rx_byte, 1);
    if (result != 1) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg_addr, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg_addr | 0x80), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(tx, rx) != 0) {
        return -1;
    }
