#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GYRO_ADDR 0x69
#define GYRO_REG_WHO_AM_I 0x0F
#define GYRO_REG_CTRL_REG1 0x20
#define GYRO_REG_CTRL_REG4 0x23
#define GYRO_REG_OUT_X_L 0x28
#define GYRO_WHO_AM_I_VAL 0xD3
#define GYRO_FS_250DPS 0x00
#define SENSITIVITY 8.75f
#define SAMPLE_INTERVAL_US 10000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_gyro(void) {
    int who_am_i = i2cReadByteData(i2c_handle, GYRO_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != GYRO_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, GYRO_WHO_AM_I_VAL);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, GYRO_REG_CTRL_REG1, GYRO_FS_250DPS) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, GYRO_REG_CTRL_REG4, GYRO_FS_250DPS) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int retries = 0;
    int bytes_read = 0;

    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, GYRO_REG_OUT_X_L, buf, 6);
        if (bytes_read == 6) {
            break;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                retries + 1, MAX_RETRIES, strerror(errno));
        retries++;
        gpioDelay(10000); /* 10 ms backoff */
    }

    if (bytes_read != 6) {
        fprintf(stderr, "I2C read failed after %d retries: got %d bytes\n",
                MAX_RETRIES, bytes_read);
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

