static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_flame_sensor(int gpio)
{
    int value = gpioRead(gpio);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", gpio,
                (value == PI_BAD_GPIO) ? "pigpio returned PI_BAD_GPIO"
                : "sensor read error");
        return -1;
    }
    return value;
}

