    while (g_running) {
        int flame_detected = read_flame_sensor(FLAME_SENSOR_GPIO);
        if (flame_detected < 0) {
            /* Sensor read error — continue polling */
            gpioDelay(POLL_INTERVAL_US);
            continue;
