        fprintf(g_csv_fp, "Timestamp,X,Y,Z\n");
        fflush(g_csv_fp);
    }

    printf("Vibration sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x, y, z;

        if (read_sensor_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        } else {
            if (log_data(g_csv_fp, x, y, z) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_MS && g_running; i++)
            usleep(100000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_csv_fp != NULL) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
