#define CONVEYOR_SENSOR_1_PIN 17
#define CONVEYOR_SENSOR_2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_sensor_state(int sensor_pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm *timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor %d: %s\n", timestamp, sensor_pin, state ? "triggered" : "not triggered") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[2] = {NULL, NULL};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 2; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, CONVEYOR_SENSOR_1_PIN);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", CONVEYOR_SENSOR_1_PIN, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input_flags(sensor_lines[i], "conveyor_sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", CONVEYOR_SENSOR_1_PIN, strerror(errno));
            goto cleanup;
        }
    }

    printf("Conveyor belt safety system started. Monitoring GPIO%d and GPIO%d.\n", CONVEYOR_SENSOR_1_PIN, CONVEYOR_SENSOR_2_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_1_val = gpiod_line_get_value(sensor_lines[0]);
        int sensor_2_val = gpiod_line_get_value(sensor_lines[1]);

        if (sensor_1_val < 0 || sensor_2_val < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        if (sensor_1_val == 1 && sensor_2_val == 1) {
            printf("Conveyor stopped due to sensor 1 and sensor 2 triggering.\n");
            log_sensor_state(CONVEYOR_SENSOR_1_PIN, 1);
            log_sensor_state(CONVEYOR_SENSOR_2_PIN, 1);
        }

