#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LIS3MDL_ADDR 0x1E
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0x3D
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG3 0x24
#define WHO_AM_I_VAL_VAL 0x3D
#define WHO_AM_I_VAL_EXPECTED 0x3D
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3
#define SENSITIVITY 0.146f  /* mG/LSB for 0.146 mG/Gauss */
#define METAL_THRESHOLD 800.0f
#define LOG_FILE_SIZE 4096

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_lis3mdl(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I_REG, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x70) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG3, 0x00) < 0) return -1;
    return 0;
}

static int read_magnetometer_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_reg16(fd, 0x28, buf) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x * SENSITIVITY;
    *y = (float)raw_y * SENSITIVITY;
    *z = (float)raw_z * SENSITIVITY;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

static void check_metal_threshold(float x, float y, float z) {
    if (x + y + z > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Total field magnitude: %.2f mG\n", x + y + z);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (init_lis3mdl(i2c_fd) < 0) {
        fprintf(stderr, "LIS3MDL initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    while (running) {
        float x, y, z;
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        log_data(log_file, x, y, z);
        check_metal_threshold(x, y, z);
        usleep(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

