#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define CHIP_NAME      "gpiochip0"
#define SENSOR_1_PIN   17
#define SENSOR_2_PIN   27
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_obstacle_detected(int sensor_pin)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Obstacle detected on GPIO%d\n", timestamp, sensor_pin);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    if (!line1) {
        fprintf(stderr, "Failed to get GPIO%d: %s\n", SENSOR_1_PIN, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO%d: %s\n", SENSOR_2_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "ky032_sensor1") < 0) {
        fprintf(stderr, "Failed to request GPIO%d as input: %s\n", SENSOR_1_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "ky032_sensor2") < 0) {
        fprintf(stderr, "Failed to request GPIO%d as input: %s\n", SENSOR_2_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Collision avoidance system started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO%d or GPIO%d: %s\n",
                    SENSOR_1_PIN, SENSOR_2_PIN, strerror(errno));
            break;
        }

        if (val1 == 0 && val2 == 0) {
            log_obstacle_detected(SENSOR_1_PIN);
            log_obstacle_detected(SENSOR_2_PIN);
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

