#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define LSM6DSR_ADDR 0x6B
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0x6B
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define CTRL1_G_FS 0x12
#define CTRL2_G_FS 0x13
#define CTRL1_XL_FS 0x14
#define CTRL2_XL_FS 0x15
#define CTRL1_G_ODR 0x16
#define CTRL2_G_ODR 0x17
#define CTRL1_XL_ODR 0x18
#define CTRL2_XL_ODR 0x19
#define OUTX_L_G_DATA 0x22

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C read burst failed (reg 0x%02X, got %d, expected %u): %d\n",
                reg, rc, len, rc);
    }
    return rc;
}

static int lsm6dsr_init(int handle) {
    uint8_t who = 0;
    if (i2c_read_burst(handle, WHO_AM_I_REG, &who, 1) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg(handle, CTRL1_XL_FS, 0x42) != 0) return -1;
    if (i2c_write_reg(handle, CTRL2_G_FS, 0x42) != 0) return -1;

    return 0;
}

static int lsm6dsr_read(int handle, float *x, float *y, float *z, float *gx, float *gy, float *gz) {
    uint8_t buf[12];
    if (i2c_read_burst(handle, OUTX_L_G_DATA, buf, 12) != 0) return -1;

    int16_t gx_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t gy_raw = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t gz_raw = (int16_t)((buf[4] << 8) | buf[5]);
    int16_t ax_raw = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t ay_raw = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t az_raw = (int16_t)((buf[10] << 8) | buf[11]);

    *gx = (float)gx_raw / 8.75f;
    *gy = (float)gy_raw / 8.75f;
    *gz = (float)gz_raw / 8.75f;
    *ax = (float)ax_raw / 0.061f;
    *ay = (float)ay_raw / 0.061f;
    *az = (float)az_raw / 0.061f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", LSM6DSR_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lsm6dsr_init(i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z, gx, gy, gz;
    while (!terminate) {
        if (lsm6dsr_read(i2c_handle, &x, &y, &z, &gx, &gy, &gz) == 0) {
            printf("X: %.3f g, Y: %.3f g, Z: %.3f g, GX: %.3f g/s, GY: %.3f g/s, GZ: %.3f g/s\n",
                   x, y, z, gx, gy, gz);
        } else {
            fprintf(stderr, "Read error, retrying...\n");
        }
        gpioDelay(100000);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

