#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define FXOS8700_ADDR 0x1D
#define I2C_BUS 1
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VAL 0xC7
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error on reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error on reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_fxos8700(int handle) {
    uint8_t who_am_i = 0;
    if (read_register(handle, WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (write_register(handle, CTRL_REG1, 0x00) != 0) return -1;
    if (write_register(handle, CTRL_REG2, 0x00) != 0) return -1;

    if (write_register(handle, M_CTRL_REG1, 0x00) != 0) return -1;
    if (write_register(handle, M_CTRL_REG2, 0x00) != 0) return -1;

    return 0;
}

static int read_accel_mag(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                          int16_t *mx, int16_t *my, int16_t *mz) {
    uint8_t buf[12];
    int rc = i2cReadI2CBlockData(handle, OUT_X_MSB, (char *)buf, 12);
    if (rc != 12) {
        fprintf(stderr, "I2C block read error: got %d bytes, expected 12\n", rc);
        return -1;
    }

    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *mx = (int16_t)((buf[6] << 8) | buf[7]);
    *my = (int16_t)((buf[8] << 8) | buf[9]);
    *mz = (int16_t)((buf[10] << 8) | buf[11]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
