#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDR 0x53
#define REG_XOUT_H 0x32
#define REG_XOUT_L 0x33
#define REG_YOUT_H 0x34
#define REG_YOUT_L 0x35
#define REG_ZOUT_H 0x36
#define REG_ZOUT_L 0x37

#define TILT_THRESHOLD 30.0
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "/var/log/tilt_events.log"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int read_accel_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_reg(fd, REG_XOUT_H, buf) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_reg(fd, REG_YOUT_H, buf) < 0) return -1;
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    if (i2c_read_reg(fd, REG_ZOUT_H, buf) < 0) return -1;
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

float calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    float x_angle = atan2f(y, sqrtf(x * x + z * z));
    float y_angle = atan2f(z, sqrtf(x * x + y * y));
    return (float)atan2f(y_angle, x_angle) * 180.0f / M_PI;
}

void log_tilt_event(float tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s Tilt Angle: %.2f degrees\n", timestamp, tilt_angle);
    fclose(fp);
}

