        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t reg_xout_h = REG_XOUT_H;
    uint8_t reg_xout_l = REG_XOUT_L;
    uint8_t reg_yout_h = REG_YOUT_H;
    uint8_t reg_yout_l = REG_YOUT_L;
    uint8_t reg_zout_h = REG_ZOUT_H;
    uint8_t reg_zout_l = REG_ZOUT_L;

    if (i2c_write_reg(i2c_fd, reg_xout_h, 0x00) < 0) {
        fprintf(stderr, "Failed to write XOUT_H\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, reg_xout_l, 0x00) < 0) {
        fprintf(stderr, "Failed to write XOUT_L\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, reg_yout_h, 0x00) < 0) {
        fprintf(stderr, "Failed to write YOUT_H\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, reg_yout_l, 0x00) < 0) {
        fprintf(stderr, "Failed to write YOUT_L\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, reg_zout_h, 0x00) < 0) {
        fprintf(stderr, "Failed to write ZOUT_H\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, reg_zout_l, 0x00) < 0) {
        fprintf(stderr, "Failed to write ZOUT_L\n");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int16_t x, y, z;
        if (read_accel_data(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            usleep(100000);
            continue;
        }

        float tilt_angle = calculate_tilt_angle(x, y, z);
        log_tilt_event(tilt_angle);

        usleep(100000);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

