    if (strtol(argv[1], NULL, 10) <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer\n");
        return EXIT_FAILURE;
    }
    if (strchr(argv[1], '.') != NULL) {
        fprintf(stderr, "Error: threshold must not contain a decimal point\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    int threshold = strtol(argv[1], NULL, 10);
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring sound sensor on GPIO%d for %d seconds. Threshold: %d\n",
           SOUND_SENSOR_PIN, WINDOW_DURATION_SEC, threshold);
    fflush(stdout);

    int window_count = 0;
    int window_start_tick = gpioTick();

    while (running) {
        int count = read_sound_level(SOUND_SENSOR_PIN);
        if (count < 0) {
            gpioDelay(1000000);
            continue;
        }

        if (count > 0) {
            window_count++;
            if (window_count >= threshold) {
                print_timestamped_alert(count);
            }
        }

        gpioDelay(WINDOW_DURATION_SEC * 1000000);
        if (running) {
            window_start_tick = gpioTick();
        }
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

