#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN    17
#define DOOR_B_PIN    27
#define CHIP_NAME     "gpiochip4"   /* BCM GPIO chip on Pi 4 */
#define LOG_FILE      "access_log.txt"
#define UNLOCK_DURATION_SEC 5
#define CODE_MIN       100000
#define CODE_MAX       999999
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_random_code(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[16];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(buf, sizeof(buf), "%d%d%d%d%d%d",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    return (int)strtol(buf, NULL, 10);
}

static int unlock_door(struct gpiod_line *door_line, int pin)
{
    if (gpiod_line_set_value(door_line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH: %s\n", pin, strerror(errno));
        return -1;
    }
    usleep(UNLOCK_DURATION_SEC * 1000);
    if (gpiod_line_set_value(door_line, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_access(int door_a_locked)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", buf, door_a_locked) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *door_a_line = NULL;
    struct gpiod_line *door_b_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(door_a_line, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(door_b_line, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Door access control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        printf("Enter 6-digit code (000000-999999): ");
        fflush(stdout);

        char buf[64];
        if (fgets(buf, sizeof(buf), stdin) == NULL) {
            if (feof(stdin))
                break;
            fprintf(stderr, "Input error: %s\n", strerror(errno));
            continue;
        }

        buf[strcspn(buf, "\n")] = '\0';

        if (buf[0] == '\0' || buf[0] == '\n') {
            fprintf(stderr, "Empty or blank input. Exiting.\n");
            break;
        }

        if (generate_random_code() != 0) {
            fprintf(stderr, "Invalid code. Exiting.\n");
            continue;
        }

        printf("Code entered: %d\n", (int)strtol(buf, NULL, 10));

        if (strcmp(buf, "000000") == 0) {
            if (unlock_door(door_a_line, DOOR_A_PIN) == 0) {
                printf("Door A unlocked.\n");
                if (log_access(1) != 0)
                    fprintf(stderr, "Failed to log access.\n");
            } else {
                fprintf(stderr, "Failed to unlock door A.\n");
            }
        } else if (strcmp(buf, "999999") == 0) {
            if (unlock_door(door_a_line, DOOR_A_PIN) == 0) {
                printf("Door A locked.\n");
                if (log_access(0) != 0)
                    fprintf(stderr, "Failed to log access.\n");
            } else {
                fprintf(stderr, "Failed to lock door A.\n");
            }
        } else {
            fprintf(stderr, "Invalid code. Exiting.\n");
            continue;
        }

        if (unlock_door(door_a_line, DOOR_A_PIN) != 0)
            fprintf(stderr, "Failed to unlock door A.\n");

        if (log_access(0) != 0)
            fprintf(stderr, "Failed to log access.\n");

        if (unlock_door(door_a_line, DOOR_A_PIN) != 0)
            fprintf(stderr, "Failed to lock door A.\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (door_a_line)
        gpiod_line_release(door_a_line);
    if (door_b_line)
        gpiod_line_release(door_b_line);
    if (chip)
        gpiod_chip_close(chip);

    printf("Access control stopped.\n");
    return ret;
}

