#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CMD_OT_HRES_MODE2 0x21
#define BH1750_CONV_TIME_MS 180
#define LOG_FILE "light_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing command 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading %zu bytes from I2C device: %s\n", len, strerror(errno));
        return -1;
    }
    if (bytes_read != (ssize_t)len) {
        fprintf(stderr, "Short read: got %zd of %zu bytes\n", bytes_read, len);
        return -1;
    }
    return 0;
}

int read_bh1750(int fd, float *lux) {
    uint8_t buf[2];
    if (i2c_write_cmd(fd, BH1750_CMD_OT_HRES_MODE2) < 0) {
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);

    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw * 5.0f / 6.0f;
    return 0;
}

int log_data(const char *timestamp, float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("BH1750 light sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) == 0) {
            time_t now = time(NULL);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            if (log_data(timestamp, lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
            printf("%s, Lux: %.2f\n", timestamp, lux);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

