#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PORT 12345
#define LOG_FILE "frequency_log.txt"
#define MAX_TOUCH_VAL 255
#define PWM_FREQ_MIN 220
#define PWM_FREQ_MAX 880
#define PWM_DURATION_MS 5000
#define SAMPLE_INTERVAL_MS 20
#define MAX_TOUCH_SAMPLES 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n", I2C_BUS, MPR121_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_pwm(void) {
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting PWM GPIO %d as output\n", PWM_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ_MIN) != 0) {
        fprintf(stderr, "Error setting PWM frequency %d Hz\n", PWM_FREQ_MIN);
        return -1;
    }
    if (gpioSetPWMrange(PWM_GPIO, 1000) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        return -1;
    }
    return 0;
}

static int initialize_mpr121(void) {
    /* Soft reset */
    if (i2cWriteByteData(i2c_handle, 0x01, 0x00) != 0) {
        fprintf(stderr, "Error writing soft reset to MPR121\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Electrode configuration: 1-16 electrodes, default config */
    if (i2cWriteByteData(i2c_handle, 0x00, 0x0F) != 0) {
        fprintf(stderr, "Error writing electrode config to MPR121\n");
        return -1;
    }

    /* Start continuous measurement */
    if (i2cWriteByteData(i2c_handle, 0x01, 0x01) != 0) {
        fprintf(stderr, "Error starting continuous measurement\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */
    return 0;
}

static int read_mpr121_touch_data(int *touch_data) {
    char buf[2];
    int ret;

    ret = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading touch data from MPR121: %s\n", strerror(errno));
        return -1;
    }

    *touch_data = (buf[0] << 8) | buf[1];
    return 0;
}

static int map_to_frequency(int touch_data) {
    if (touch_data < 0) return 0;
    if (touch_data > MAX_TOUCH_VAL) return 0;
    return (int)((float)MAX_TOUCH_VAL - (float)touch_data) * (PWM_FREQ_MAX - PWM_FREQ_MIN) / (MAX_TOUCH_VAL - 0);
}

static void play_tone(int frequency) {
    if (gpioPWM(PWM_GPIO, frequency) != 0) {
        fprintf(stderr, "Error setting PWM frequency %d Hz\n", frequency);
    }
}

static void log_frequency(int frequency) {
    if (!log_file) return;
    fprintf(log_file, "%d\n", frequency);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (initialize_pwm() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Error setting SO_REUSEADDR: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Error binding socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Error listening: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (running) {
        int client_socket = accept(server_fd, NULL, NULL);
        if (client_socket < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error accepting connection: %s\n", strerror(errno));
            break;
        }

        printf("Connection accepted from %s\n", inet_ntoa(address.sin_addr));

        char buffer[1024];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading from client: %s\n", strerror(errno));
            close(client_socket);
            continue;
        }
        if (bytes_received == 0) {
            fprintf(stderr, "Client disconnected\n");
            close(client_socket);
            continue;
        }

        buffer[bytes_received] = '\0';
        printf("Received message: %s\n", buffer);

        char *endptr;
        long int value = strtol(buffer, &endptr, 10);
        if (endptr == buffer || *endptr != '\0') {
            fprintf(stderr, "Invalid data format\n");
            close(client_socket);
            continue;
        }

        int touch_data = read_mpr121_touch_data(&value);
        if (touch_data < 0) {
            fprintf(stderr, "Error reading touch data\n");
            close(client_socket);
            continue;
        }

        int frequency = map_to_frequency(touch_data);
        if (frequency < 0) {
            fprintf(stderr, "Error mapping touch data to frequency\n");
            close(client_socket);
            continue;
        }

        play_tone(frequency);
        log_frequency(frequency);

        printf("Frequency: %d Hz\n", frequency);

        if (running) {
            gpioDelay(PWM_DURATION_MS * 1000);
        }
    }

    printf("Shutting down...\n");
    cleanup();
    return 0;
}

