/*
 * LSM303D accelerometer/magnetometer monitor for Raspberry Pi Zero W
 * Uses Linux i2c-dev (no wiringPi) and libgpiod for GPIO interrupt.
 *
 * Wiring:
 *   LSM303D SDA -> GPIO2 (pin 3)
 *   LSM303D SCL -> GPIO3 (pin 5)
 *   LSM303D VDD -> 3.3 V
 *   LSM303D GND -> GND
 *   INT1 -> GPIO23 (pin 16)
 *
 * Build: gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D register addresses ---- */
#define LSM303D_ADDR            0x1D
#define WHO_AM_I               0x0F
#define WHO_AM_I_VAL           0x49
#define CTRL_REG1              0x20
#define CTRL_REG4              0x23
#define OUT_X_L_A              0x28
#define INT1_CFG               0x2A
#define INT1_TH_A              0x2B
#define INT1_TH_HIGH_A         0x2C
#define INT1_TH_DUR_A          0x2D
#define INT1_CFG_VAL           0x7D
#define INT1_TH_HIGH_VAL       0x7D
#define INT1_TH_DUR_VAL        0x00
#define CTRL_REG1_VAL          0x57
#define ACCEL_XOUT_H_L         0x28

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x, y, z;
    int16_t x_old, y_old, z_old;
    int16_t x_buf[64], y_buf[64], z_buf[64];
    int head, tail;
    int count;
} buffer_t;

static buffer_t g_buf;

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D init ---- */
static int lsm303d_init(int fd)
{
    uint8_t who;
    if (i2c_read_burst(fd, WHO_AM_I, &who, 1) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }

    /* 50 Hz ODR, full-scale +/-2g, auto-increment */
    if (i2c_write_reg(fd, CTRL_REG1, CTRL_REG1_VAL) < 0)
        return -1;
    /* 50 Hz, full scale, no filtering */
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) < 0)
        return -1;

    /* Sensitivity +/-2g -> 0.061 mg/LSB */
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) < 0)
        return -1;

    /* Threshold interrupt on any axis */
    if (i2c_write_reg(fd, INT1_CFG, INT1_CFG_VAL) < 0)
        return -1;

    /* Threshold on any axis, immediate */
    if (i2c_write_reg(fd, INT1_TH_A, INT1_TH_HIGH_VAL) < 0)
        return -1;
    if (i2c_write_reg(fd, INT1_TH_DUR_A, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Read acceleration (X, Y, Z) ---- */
static int lsm303d_read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L_A, buf, 6) < 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(buffer_t *b)
{
    b->head = 0;
    b->tail = 0;
    b->count = 0;
}

static void buffer_add(buffer_t *b, int16_t x, int16_t y, int16_t z)
{
    b->x_buf[b->head] = x;
    b->y_buf[b->head] = y;
    b->z_buf[b->head] = z;
    b->head = (b->head + 1) % 64;
    if (b->count < 64) b->count++;
}

static void buffer_dump(const buffer_t *b)
{
    printf("--- Last %d samples ---\n", b->count);
    for (int i = 0; i < b->count; i++) {
        int idx = (b->head - b->tail + 64) % 64;
        int16_t x = b->x_buf[idx];
        int16_t y = b->y_buf[idx];
        int16_t z = b->z_buf[idx];
        printf("  X: %d, Y: %d, Z: %d\n", x, y, z);
    }
}

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_line) {
        gpiod_line_set_value(g_line, 0);
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize LSM303D */
    if (lsm303d_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request line 23 */
    g_chip = gpiod_chip_open_by_number(0);
    if (!g_chip) {
