#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27
#define CONSUMER_NAME "reciprocating_actuator"
#define DELAY_MS 500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *solenoid1 = NULL;
    struct gpiod_line *solenoid2 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines for the solenoids */
    solenoid1 = gpiod_chip_get_line(chip, SOLENOID1_PIN);
    if (!solenoid1) {
        perror("gpiod_chip_get_line(SOLENOID1)");
        goto cleanup;
    }
    solenoid2 = gpiod_chip_get_line(chip, SOLENOID2_PIN);
    if (!solenoid2) {
        perror("gpiod_chip_get_line(SOLENOID2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially LOW */
    ret = gpiod_line_request_output(solenoid1, CONSUMER_NAME, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(SOLENOID1)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(solenoid2, CONSUMER_NAME, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(SOLENOID2)");
        goto cleanup;
    }

    printf("Reciprocating actuator started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Energize solenoid 1 for 500 ms */
        ret = gpiod_line_set_value(solenoid1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(SOLENOID1)");
            goto cleanup;
        }
        usleep(DELAY_MS * 1000);

        /* De-energize solenoid 1 */
        ret = gpiod_line_set_value(solenoid1, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(SOLENOID1)");
            goto cleanup;
        }
        usleep(DELAY_MS * 1000);

        /* Energize solenoid 2 for 500 ms */
        ret = gpiod_line_set_value(solenoid2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(SOLENOID2)");
            goto cleanup;
        }
        usleep(DELAY_MS * 1000);

        /* De-energize solenoid 2 */
        ret = gpiod_line_set_value(solenoid2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(SOLENOID2)");
            goto cleanup;
        }
        usleep(DELAY_MS * 1000);
    }

cleanup:
    /* Ensure both lines are LOW before exiting */
    gpiod_line_set_value(solenoid1, 0);
    gpiod_line_set_value(solenoid2, 0);
    gpiod_line_release(solenoid1);
    gpiod_line_release(solenoid2);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

