#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define UART1_PORT "/dev/serial0"
#define UART2_PORT "/dev/serial1"
#define BAUD_RATE 9600
#define TIMEOUT_US 5000000
#define UNLOCK_DURATION_US 2000000
#define CODE_LENGTH 6
#define MAX_RETRIES 3
#define MAX_RETRIES_PER_PORT 5

static volatile sig_atomic_t running = 1;
static int uart1_fd = -1;
static int uart2_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    return 0;
}

static int set_lock_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to %d\n", pin, state);
        return -1;
    }
    return 0;
}

static int unlock_locks(void) {
    if (set_lock_state(LOCK1_PIN, 1) != 0 ||
        set_lock_state(LOCK2_PIN, 1) != 0) {
        fprintf(stderr, "Failed to unlock locks\n");
        return -1;
    }
    return 0;
}

static int read_code(const char *port, int timeout_us) {
    int code[CODE_LENGTH];
    int retries = 0;
    int timeout_count = 0;

    while (retries < MAX_RETRIES) {
        char buf[CODE_LENGTH];
        int bytes_read = gpioRead(UART1_PORT, buf, sizeof(buf));
        if (bytes_read > 0) {
            for (int i = 0; i < bytes_read; i++) {
                if (buf[i] == '\0') {
                    timeout_count++;
                    if (timeout_count >= timeout_us) {
                        fprintf(stderr, "Timeout waiting for code\n");
                        return -1;
                    }
                    continue;
                }
            }
            for (int i = 0; i < bytes_read; i++) {
                code[i] = buf[i];
            }
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(10000);
        }
    }
    return -1;
}

static int match_code(const char *code1, const char *code2) {
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (code1[i] != code2[i]) {
            return 0;
        }
    }
    return 1;
}

static int unlock_locks_with_match(const char *code1, const char *code2) {
    if (match_code(code1, code2)) {
        if (unlock_locks() != 0) {
            fprintf(stderr, "Failed to unlock locks\n");
            return -1;
        }
        printf("Code matched! Unlocking doors.\n");
        return 0;
    }
    fprintf(stderr, "Code mismatch. Re-locking doors.\n");
    return -1;
}

static void cleanup(void) {
    if (uart1_fd >= 0) {
        gpioWrite(LOCK1_PIN, 0);
        gpioWrite(LOCK2_PIN, 0);
        gpioClose(uart1_fd);
        uart1_fd = -1;
    }
    if (uart2_fd >= 0) {
        gpioWrite(LOCK1_PIN, 0);
        gpioWrite(LOCK2_PIN, 0);
        gpioClose(uart2_fd);
        uart2_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    uart1_fd = gpioOpen(UART1_PORT, BAUD_RATE, 0);
    if (uart1_fd < 0) {
        fprintf(stderr, "Failed to open UART1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    uart2_fd = gpioOpen(UART2_PORT, BAUD_RATE, 0);
    if (uart2_fd < 0) {
        fprintf(stderr, "Failed to open UART2: %s\n", strerror(errno));
        gpioClose(uart1_fd);
        gpioTerminate();
        return 1;
    }

    if (unlock_locks_with_match("123456", "123456") != 0) {
        cleanup();
        return 1;
    }

    printf("Dual-factor authentication started. Press Ctrl+C to exit.\n");

    while (running) {
        char code1[CODE_LENGTH];
        char code2[CODE_LENGTH];
        int timeout_count = 0;

        if (read_code(UART1_PORT, TIMEOUT_US) != 0) {
            gpioDelay(100000);
            continue;
        }
        timeout_count++;
        if (timeout_count >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for UART1\n");
            gpioDelay(100000);
            continue;
        }

        if (read_code(UART2_PORT, TIMEOUT_US) != 0) {
            gpioDelay(100000);
            continue;
        }
        timeout_count++;
        if (timeout_count >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for UART2\n");
            gpioDelay(100000);
            continue;
        }

        if (read_code(UART1_PORT, TIMEOUT_US) != 0) {
            gpioDelay(100000);
            continue;
        }
        timeout_count++;
        if (timeout_count >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for UART1\n");
            gpioDelay(100000);
            continue;
        }

        if (read_code(UART2_PORT, TIMEOUT_US) != 0) {
            gpioDelay(100000);
            continue;
        }
        timeout_count++;
        if (timeout_count >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for UART2\n");
            gpioDelay(100000);
            continue;
        }

        if (read_code(UART1_PORT, TIMEOUT_US) != 0) {
            gpioDelay(100000);
            continue;
