#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define STRIKE_DURATION_MS 1000
#define POLL_INTERVAL_MS 50
#define FAILSAFE_THRESHOLD_SEC 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(int priority, const char *message) {
    openlog("motion_strike", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

static int gpio_init(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open gpiochip0");
        return -1;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_message(LOG_ERR, "Failed to get relay line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "motion_strike") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "motion_strike", 0) < 0) {
        log_message(LOG_ERR, "Failed to request relay line as output");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void gpio_cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void motion_detected(void) {
    if (gpiod_line_get_value(pir_line) == 1) {
        log_message(LOG_INFO, "Motion detected! Activating strike.");
        if (gpiod_line_set_value(relay_line, 1) < 0) {
            log_message(LOG_ERR, "Failed to energize relay");
        }
        usleep(STRICK_DURATION_MS * 1000);
        if (gpiod_line_set_value(relay_line, 0) < 0) {
            log_message(LOG_ERR, "Failed to de-energize relay");
        }
        log_message(LOG_INFO, "Strike complete.");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_message(LOG_ERR, "Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        log_message(LOG_ERR, "GPIO initialization failed");
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Motion detection system started.");

    while (program_running) {
        motion_detected();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_message(LOG_INFO, "Shutting down gracefully.");
    gpio_cleanup();
    return EXIT_SUCCESS;
}

