#define ACCEL_XOUT_H 0x3B
#define ACCEL_CONFIG 0x00
#define PWR_MGMT_1 0x6B
#define ACCEL_RANGE_2G 0x00
#define ACCEL_XOUT_H_LEN 6
#define BUFFER_SIZE 1024
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *sysfs_fp = NULL;
static FILE *log_fp = NULL;
static int buffer_index = 0;
static struct timespec last_sample_time = {0, 0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) return -1;
