#include <unistd.h>
#include <gpiod.h>

#define RELAY_PIN_1 18
#define RELAY_PIN_2 23
#define RELAY_PIN_3 24
#define RELAY_PIN_4 25

static volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay_lines[4] = {NULL, NULL, NULL, NULL};
    struct timespec last_toggle[4] = {0, 0, 0, 0};
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip 0 (Raspberry Pi 3 Model B+)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip 0");
        return EXIT_FAILURE;
    }

    // Get relay lines
    relay_lines[0] = gpiod_chip_get_line(chip, RELAY_PIN_1);
    relay_lines[1] = gpiod_chip_get_line(chip, RELAY_PIN_2);
    relay_lines[2] = gpiod_chip_get_line(chip, RELAY_PIN_3);
    relay_lines[3] = gpiod_chip_get_line(chip, RELAY_PIN_4);

    if (!relay_lines[0] || !relay_lines[1] || !relay_lines[2] || !relay_lines[3]) {
        perror("Failed to get relay lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request relay lines as outputs, initially LOW
    ret = gpiod_line_request_output(relay_lines[0], "smart_lighting", 0);
    if (ret < 0) {
        perror("Failed to request relay line 0 as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(relay_lines[1], "smart_lighting", 0);
    if (ret < 0) {
        perror("Failed to request relay line 1 as output");
        gpiod_line_release(relay_lines[0]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(relay_lines[2], "smart_lighting", 0);
    if (ret < 0) {
        perror("Failed to request relay line 2 as output");
        gpiod_line_release(relay_lines[0]);
        gpiod_line_release(relay_lines[1]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(relay_lines[3], "smart_lighting", 0);
    if (ret < 0) {
        perror("Failed to request relay line 3 as output");
        gpiod_line_release(relay_lines[0]);
        gpiod_line_release(relay_lines[1]);
        gpiod_line_release(relay_lines[2]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        // Generate prime numbers for each relay
        int prime_numbers[4] = {2, 3, 5, 7};
        int num_primes = 4;
        int current_prime = prime_numbers[0];
        int last_toggle_time[4] = {0, 0, 0, 0};

        // Generate prime numbers
        for (int i = 1; i < num_primes; i++) {
            int next_prime = (current_prime + 1) % 8;
            if (next_prime == 0) next_prime = 2;
            if (next_prime == 1) next_prime = 3;
            if (next_prime == 2) next_prime = 5;
            if (next_prime == 3) next_prime = 7;
            if (next_prime == 4) next_prime = 11;
            if (next_prime == 5) next_prime = 13;
            if (next_prime == 6) next_prime = 17;
            if (next_prime == 7) next_prime = 19;
            current_prime = next_prime;
        }

        // Generate intervals for each relay
        for (int i = 0; i < num_primes; i++) {
            int interval = last_toggle_time[i] + (current_prime - last_toggle_time[i]) * (1000000000 / num_primes);
            clock_gettime(CLOCK_MONOTONIC, &last_toggle_time[i]);

            // Turn on relay
            ret = gpiod_line_set_value(relay_lines[i], 1);
            if (ret < 0) {
                perror("Failed to turn on relay");
                break;
            }

            // Wait for the interval
            struct timespec sleep_time;
            sleep_time.tv_sec = interval / 1000000000;
            sleep_time.tv_nsec = (interval % 1000000000) * 1000000;
            nanosleep(&sleep_time, NULL);

            // Turn off relay
            ret = gpiod_line_set_value(relay_lines[i], 0);
            if (ret < 0) {
                perror("Failed to turn off relay");
                break;
            }
        }

        // Wait for remaining time (non-rolling-over)
        struct timespec remaining;
        remaining.tv_sec = (last_toggle_time[i] + interval) % 1000000000;
        remaining.tv_nsec = (last_toggle_time[i] % 1000000000) * 1000000;
        nanosleep(&remaining, NULL);
    }

    // Turn off all relays
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(relay_lines[i], 0);
    }

    // Cleanup
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(relay_lines[i]);
    }
    gpiod_chip_close(chip);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

