// MPU-6050 Register Addresses
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_GYRO_XOUT_H 0x43

// Gyroscope Sensitivity (default +-250 dps)
#define GYRO_SENSITIVITY 131.0f

// I2C Device Path
#define I2C_DEVICE "/dev/i2c-1"

// Circular Buffer Structure
typedef struct {
    float x;
    float y;
    float z;
    float magnitude;
} AngularVelocityData;

// Circular Buffer Structure
typedef struct {
    AngularVelocityData buffer[100];
    int head;
    int count;
} CircularBuffer;

// Global Variables
static int i2c_fd = -1;
static CircularBuffer gyro_buffer;
static volatile sig_atomic_t running = 1;

// Function Prototypes
int i2c_init(void);
int i2c_read_reg(uint8_t reg, uint8_t *value);
int i2c_write_reg(uint8_t reg, uint8_t value);
int i2c_read_reg_block(uint8_t reg, uint8_t *buf, int len);
int read_gyro_data(float *x, float *y, float *z);
void buffer_add(float x, float y, float z);
void buffer_check_threshold(float magnitude);
void signal_handler(int sig);

// Initialize I2C Communication
int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit in PWR_MGMT_1)
    if (i2c_write_reg(MPU6050_PWR_MGMT_1, 0x00) < 0) {
        perror("Failed to wake up MPU-6050");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Verify device identity
    uint8_t who_am_i = 0;
    if (i2c_read_reg_block(MPU6050_WHO_AM_I, &who_am_i, 1) < 0) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x68)\n", who_am_i);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read a single byte from a register
int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("Failed to read register data");
        return -1;
    }
    return 0;
}

// Write a single byte to a register
int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write register data");
        return -1;
    }
    return 0;
}

// Read a block of bytes from a register
int i2c_read_reg_block(uint8_t reg, uint8_t *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("Failed to read register data");
        return -1;
    }
    return 0;
}

// Read Gyroscope Data
int read_gyro_data(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_reg_block(MPU6050_GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }

    // Combine bytes into a single 32-bit value
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add a new data point to the circular buffer
void buffer_add(float x, float y, float z) {
    gyro_buffer.buffer[gyro_buffer.head] = (AngularVelocityData){x, y, z, sqrtf(x * x + y * y + z * z)};
    gyro_buffer.head = (gyro_buffer.head + 1) % gyro_buffer.count;
}

// Check if the magnitude of the absolute velocity exceeds the threshold
void buffer_check_threshold(float magnitude) {
    if (magnitude > 50.0f) {
        printf("Threshold Exceeded! Magnitude: %.2f\n", magnitude);
    }
}

// Signal Handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    // Initialize I2C
    if (i2c_init() < 0) {
        return 1;
    }

    // Initialize Circular Buffer
    gyro_buffer.count = 0;
    gyro_buffer.head = 0;

    // Register Signal Handler
    signal(SIGINT, signal_handler);

    printf("Gyroscope Data Acquisition Program started. Press Ctrl+C to exit.\n");

    // Main Loop
    while (running) {
        float x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            buffer_add(x, y, z);
            buffer_check_threshold(sqrtf(x * x + y * y + z * z));
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }
        usleep(100000); // 100ms delay
    }

    // Cleanup
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("Program terminated.\n");
    return 0;
}

