#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_PORT        "/dev/serial0"
#define BAUD_RATE        9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define READ_TIMEOUT_MS  1000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

/* MH-Z19B 9-byte read command */
static const uint8_t cmd_buf[9] = {
    0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79
};

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (g_err_fp) {
        fprintf(g_err_fp, "[%s] ERROR: %s\n", ts, msg);
        fflush(g_err_fp);
    }
}

static void log_co2(float ppm, int error)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(g_log_fp, "[%s] CO2: %.2f ppm, Error: %s\n", ts, ppm,
            error ? "true" : "false");
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Read one byte from the serial port                                  */
/* Returns 0 on success, -1 on timeout/error                          */
/* ------------------------------------------------------------------ */
static int read_byte(int handle, uint8_t *out)
{
    int v = serRead(handle, (char *)out, 1);
    if (v < 0) {
        log_error("serRead failed");
        return -1;
    }
    if (v != 1) {
        log_error("serRead returned unexpected length");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly 9 bytes from the serial port                            */
/* Returns 0 on success, -1 on timeout/error                          */
/* ------------------------------------------------------------------ */
static int read_data(int handle, uint8_t *buf, size_t len)
{
    int v = serRead(handle, (char *)buf, len);
    if (v < 0) {
        log_error("serRead failed");
        return -1;
    }
    if (v != len) {
        log_error("serRead returned partial read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse 9-byte response                                               */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int parse_response(const uint8_t *buf, size_t len,
                           float *co2_ppm)
{
    if (len != 9) {
        log_error("parse_response: expected 9 bytes, got %zu", len);
        return -1;
    }

    /* Checksum: sum of bytes 1-7, incremented by 1 */
    uint8_t sum = 0;
    for (int i = 0; i < 7; i++)
        sum += buf[i];
    sum += buf[7];

    if (sum != buf[8]) {
        log_error("parse_response: checksum mismatch");
        return -1;
    }

    uint16_t co2_raw = ((uint16_t)buf[1] << 8) | buf[2];
    *co2_ppm = (float)co2_raw / 10.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- UART open --- */
    int handle = serOpen(UART_PORT, BAUD_RATE, 0);
    if (handle < 0) {
        fprintf(stderr, "serOpen(%s) failed: %d\n", UART_PORT, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log files --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }
    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen(" ERROR_LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO2 monitor started. Logging to %s, errors to %s\n",
           LOG_FILE, ERROR_LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint8_t buf[9];
        int rc = 0;

        for (int attempt = 0; attempt < 10 && g_running; attempt++) {
            if (read_byte(handle, &buf[0]) != 0) {
                log_error("read_byte failed");
                gpioDelay(100000);
                continue;
            }
            if (read_data(handle, buf, sizeof(buf)) != 0) {
                log_error("read_data failed");
                gpioDelay(100000);
                continue;
            }
            if (parse_response(buf, sizeof(buf), &co2_ppm) != 0) {
                log_error("parse_response failed");
                gpioDelay(100000);
                continue;
            }
            rc = 0;
            break;
        }

        if (rc == 0) {
            log_co2(co2_ppm, 0);
        } else {
            log_error("co2_read failed after multiple retries");
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

