#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LOG_FILE "lighting_log.txt"
#define CONVERSION_DELAY_MS 120
#define POLL_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, 0x01) < 0) return -1;
    usleep(1000);
    if (i2c_write_byte(fd, 0x00) < 0) return -1;
    usleep(1000);
    if (i2c_write_byte(fd, 0x10) < 0) return -1;
    usleep(CONVERSION_DELAY_MS * 1000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    unsigned char buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    int raw = (buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(float lux, int red, int green, int blue) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n", ts, lux, red, green, blue);
    fflush(log_fp);
}

static void cleanup(void) {
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fp) fclose(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

