static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, 0x01) < 0) return -1;
    usleep(1000);
    if (i2c_write_byte(fd, 0x00) < 0) return -1;
    usleep(1000);
    if (i2c_write_byte(fd, 0x10) < 0) return -1;
    usleep(CONVERSION_DELAY_MS * 1000);
    return 0;
