#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_PIN1 17
#define MOTOR_PIN2 18
#define MOTOR_PIN3 27
#define MOTOR_PIN4 22

#define BUTTON_PIN1 24
#define BUTTON_PIN2 23

#define STEP_DELAY_US 2000
#define STEP_DELAY_US_PER_STEP 2

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void motor_step(int pin1, int pin2, int pin3, int pin4) {
    gpioWrite(pin1, 1);
    gpioWrite(pin2, 0);
    gpioWrite(pin3, 1);
    gpioWrite(pin4, 0);
}

static void motor_stop(void) {
    gpioWrite(MOTOR_PIN1, 1);
    gpioWrite(MOTOR_PIN2, 1);
    gpioWrite(MOTOR_PIN3, 1);
    gpioWrite(MOTOR_PIN4, 1);
}

static void motor_forward(int steps) {
    for (int i = 0; i < steps && running; i++) {
        motor_step(MOTOR_PIN1, MOTOR_PIN2, MOTOR_PIN3, MOTOR_PIN4);
    }
}

static void motor_backward(int steps) {
    for (int i = 0; i < steps && running; i++) {
        motor_step(MOTOR_PIN1, MOTOR_PIN2, MOTOR_PIN3, MOTOR_PIN4);
    }
}

static void motor_clockwise(int steps) {
    motor_forward(steps);
}

static void motor_counterclockwise(int steps) {
    motor_backward(steps);
}

static void lock_door(void) {
    motor_clockwise(512);
    printf("Door locked.\n");
}

static void unlock_door(void) {
    motor_counterclockwise(512);
    printf("Door unlocked.\n");
}

static void cleanup(void) {
    motor_stop();
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_PIN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PIN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PIN3, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PIN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN1, PI_INPUT) != 0 ||
        gpioSetMode(BUTTON_PIN2, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN1, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(BUTTON_PIN2, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on button pins\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(BUTTON_PIN1, signal_handler) != 0 ||
        gpioSetAlertFunc(BUTTON_PIN2, signal_handler) != 0) {
        fprintf(stderr, "Failed to set alert functions\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(BUTTON_PIN1, signal_handler, NULL) != 0 ||
        gpioSetAlertFuncEx(BUTTON_PIN2, signal_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set alert functions with flags\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(BUTTON_PIN1, NULL, NULL) != 0 ||
        gpioSetAlertFuncEx(BUTTON_PIN2, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set alert functions with NULL\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(BUTTON_PIN1, NULL, NULL) != 0 ||
        gpioSetAlertFuncEx(BUTTON_PIN2, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set alert functions with NULL\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Automatic door lock program started. Press button on GPIO24 to lock, GPIO23 to unlock.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(BUTTON_PIN1) == 0) {
            if (gpioRead(BUTTON_PIN2) == 0) {
                lock_door();
                motor_forward(512);
            }
        } else {
            unlock_door();
            motor_backward(512);
        }
        gpioDelay(STEP_DELAY_US);
    }

    printf("\nShutting down...\n");
    motor_stop();
    cleanup();
    return EXIT_SUCCESS;
}

