        cleanup();
        return EXIT_FAILURE;
    }

    printf("Automatic door lock program started. Press button on GPIO24 to lock, GPIO23 to unlock.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(BUTTON_PIN1) == 0) {
            if (gpioRead(BUTTON_PIN2) == 0) {
                lock_door();
                motor_forward(512);
            }
        } else {
            unlock_door();
            motor_backward(512);
        }
        gpioDelay(STEP_DELAY_US);
    }

    printf("\nShutting down...\n");
    motor_stop();
    cleanup();
    return EXIT_SUCCESS;
