#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 30.0
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define TRIGGER_PULSE_US 10
#define MEASUREMENT_GAP_US 60000  /* 60 ms gap between measurements */
#define LOOP_DELAY_US 50000      /* 50 Hz loop rate */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns the distance in cm, or -1.0 on timeout or error.
 */
static double measure_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout = 0;

    /* Wait for echo start (rising edge) with timeout */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > 1000) {
            return -1.0;  /* timeout */
        }
    }
    timeout++;

    /* Wait for echo end (falling edge) with timeout */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > 1000) {
            return -1.0;  /* timeout */
        }
        timeout++;
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us == 0) {
        return -1.0;  /* timeout */
    }

    return (double)pulse_us / 1000000.0;
}

/*
 * Map distance to frequency.
 * Returns the frequency in Hz, or -1.0 on error.
 */
static double distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    double ratio = (distance - MIN_DISTANCE_CM) /
                    (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    double freq = MIN_FREQUENCY_HZ +
                  (ratio * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ)) +
                  MIN_FREQUENCY_HZ;

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;

    return freq;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100);  /* 100 us settling time */

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Trigger the sensor */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set trigger high.\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set trigger low.\n");
            break;
        }

        /* Measure distance */
        double distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Error: distance measurement failed.\n");
            break;
        }

        /* Map distance to frequency */
        double freq = distance_to_frequency(distance);

        /* Set buzzer frequency */
        if (freq > 0.0) {
            if (gpioSetPWMfrequency(BUZZER_PIN, freq) != 0) {
                fprintf(stderr, "Error: failed to set PWM frequency on pin %d.\n", BUZZER_PIN);
                break;
            }
            if (gpioPWM(BUZZER_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn buzzer off.\n");
                break;
            }
        }

        /* Sleep for the measurement gap */
        gpioDelay(MEASUREMENT_GAP_US);
    }

    /* Cleanup */
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting.\n");
    return EXIT_SUCCESS;
}

