#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27
#define PWM_FREQUENCY 1000
#define PWM_RANGE   255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

static void set_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

static void simulate_proximity(float value) {
    // Simulate a sine wave over time
    int period = 100;
    int phase = 0;
    for (int i = 0; i < period && running; i++) {
        int red = (int)(value * period * 0.5 + phase * PWM_RANGE);
        int green = (int)(value * period * 0.5 + (phase + 1) * PWM_RANGE);
        int blue = (int)(value * period * 0.5 + (phase + 2) * PWM_RANGE);
        set_color(red, green, blue);
        phase += 0.01;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    set_color(0, 0, 0);

    while (running) {
        simulate_proximity(0.5);
        gpioDelay(100000); // 100 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

