    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "MPU-6050 init failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized on %s at 0x%02X. Logging to %s every %d ms.\n",
           I2C_BUS, MPU6050_ADDR, LOG_FILE, SAMPLE_MS);

    while (g_running) {
        int16_t x, y, z;
        if (read_gyro_data(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "read_gyro_data failed; continuing\n");
            usleep(SAMPLE_MS * 1000);
