#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define POLL_TIMEOUT_MS 1000
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_event(FILE *fp, int value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s: %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        return -1;
    }
    return value;
}

static void print_earthquake_alert(FILE *fp) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "EARTHQUAKE ALERT: %s\n", timestamp);
    fflush(fp);
}

int main(int argc, char *argv[]) {
    int pin = GPIO_PIN;
    int polling_ms = POLL_TIMEOUT_MS;
    int window_size = WINDOW_SIZE;
    int threshold = EARTHQUAKE_THRESHOLD;

    if (argc > 1) {
        polling_ms = atoi(argv[1]);
        if (polling_ms <= 0) {
            fprintf(stderr, "Invalid polling interval. Using default %d ms.\n", POLL_TIMEOUT_MS);
            polling_ms = POLL_TIMEOUT_MS;
        }
    }

    if (argc > 2) {
        threshold = atoi(argv[2]);
        if (threshold < 0 || threshold > 1) {
            fprintf(stderr, "Invalid threshold. Using default %d.\n", EARTHQUAKE_THRESHOLD);
            threshold = EARTHQUAKE_THRESHOLD;
        }
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "vibration_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        fclose(g_log_fp);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        fclose(g_log_fp);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Monitoring vibration sensor on GPIO%d. Polling %d ms. Press Ctrl+C to exit.\n", GPIO_PIN, polling_ms);

    while (g_running) {
        int value = read_sensor(line);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor value. Retrying in %d ms.\n", polling_ms);
            usleep(polling_ms * 1000);
            continue;
        }

        if (value == 1) {
            if (log_event(g_log_fp, value) < 0) {
                fprintf(stderr, "Error logging event.\n");
            }
        }

        if (value == 0 && window_size > 1) {
            int prev_value = read_sensor(line);
            if (prev_value == 1) {
                window_size--;
            }
            if (window_size < 1) {
                window_size = WINDOW_SIZE;
            }
        }

        if (window_size >= threshold) {
            print_earthquake_alert(g_log_fp);
            window_size = 0;
        }

        usleep(polling_ms * 1000);
    }

    printf("\nShutting down gracefully...\n");
    fclose(g_log_fp);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

