#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 10
#define RELAY_ACTIVE_DURATION_SEC 5
#define RELAY_INACTIVE_DURATION_SEC 1

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int relay_number, int moisture_level) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Relay %d: Moisture level %d\n",
                timestamp, relay_number, moisture_level);
        fflush(log_file);
    }
    printf("%s - Relay %d: Moisture level %d\n",
           timestamp, relay_number, moisture_level);
}

static void activate_relay(int relay_number) {
    if (gpiod_line_set_value(relay_lines[relay_number], 0) < 0) {
        fprintf(stderr, "Failed to set relay %d to OFF: %s\n",
                relay_number, strerror(errno));
        return;
    }
    log_event(relay_number, 0);
    printf("Relay %d activated\n", relay_number);
}

static void deactivate_relay(int relay_number) {
    if (gpiod_line_set_value(relay_lines[relay_number], 1) < 0) {
        fprintf(stderr, "Failed to set relay %d to ON: %s\n",
                relay_number, strerror(errno));
        return;
    }
    log_event(relay_number, 1);
    printf("Relay %d deactivated\n", relay_number);
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i] != NULL) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, i);
        if (relay_lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                    i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(relay_lines[i], "irrigation-relay", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                    i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart irrigation system started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = rand() % 100;
        if (moisture_level < 0 || moisture_level > 100) {
            moisture_level = 0;
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (moisture_level < MOISTURE_THRESHOLD) {
                activate_relay(i);
                for (int j = 0; j < RELAY_ACTIVE_DURATION_SEC && running; j++) {
                    sleep(1);
                }
                deactivate_relay(i);
            }
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set relay %d to ON: %s\n",
                        i, strerror(errno));
            }
        }
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set relay %d to OFF: %s\n",
                        i, strerror(errno));
            }
        }
        for (int i = 0; i < RELAY_INACTIVE_DURATION_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

