/*
 * Watering system for Raspberry Pi Zero W using pigpio.
 *
 * Servo valves: water_valve_servo (GPIO17, physical pin 11)
 *                     servo_valve_angle = 0  -> closed
 *                     servo_valve_angle = 90 -> open
 *
 * Servo nozzles: no_nozzle_servo (GPIO18, physical pin 12)
 *                     servo_nozzle_angle = 0  -> no water
 *                     servo_nozzle_angle = 45 -> water
 *                     servo_nozzle_angle = 90 -> water
 *                     servo_nozzle_angle = 135 -> water
 *                     servo_nozzle_angle = 180 -> water
 *
 * Soil moisture threshold: 50
 *
 * Build: gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define WATER_VALVE_PIN 17
#define NOZZLE_PIN       18

#define MOISTURE_THRESHOLD 50
#define MOISTURE_CYCLE_DELAY_US 1000000   /* 1 second */
#define SERVO_PULSE_MIN_US   500          /* 0 degrees */
#define SERVO_PULSE_MAX_US   2500         /* 180 degrees */
#define SERVO_PULSE_STEP_US  (SERVO_PULSE_MAX_US - SERVO_PULSE_MIN_US)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Set servo angle (0-180 degrees) using gpioServo().
 * Returns 0 on success, -1 on gpioServo() failure.
 */
static int set_servo_angle(int pin, int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: servo angle %d out of range (0-180)\n", angle);
        return -1;
    }

    int pulse_us = SERVO_PULSE_MIN_US +
                   (int)((angle * SERVO_PULSE_STEP_US) / 180);

    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

/*
 * Sweep servo from angle0 to angle180.
 * Returns 0 on success, -1 on gpioServo() failure.
 */
static int servo_sweep(int pin, int angle0, int angle180)
{
    if (angle0 < 0 || angle0 > 180) {
        fprintf(stderr, "Error: servo angle0 %d out of range (0-180)\n", angle0);
        return -1;
    }
    if (angle180 < 0 || angle180 > 180) {
        fprintf(stderr, "Error: servo angle180 %d out of range (0-180)\n", angle180);
        return -1;
    }

    for (int i = 0; i <= 180 && g_running; i += 10) {
        if (set_servo_angle(pin, angle0 + (i * 10)) < 0)
            return -1;
        gpioDelay(10000); /* 10 ms */
    }

    for (int i = 180; i >= 0 && g_running; i -= 10) {
        if (set_servo_angle(pin, angle0 + (i * 10)) < 0)
            return -1;
        gpioDelay(10000);
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure servo pins as outputs */
    if (gpioSetMode(WATER_VALVE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", WATER_VALVE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(NOZZLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", NOZZLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure valves start closed */
    if (set_servo_angle(WATER_VALVE_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set initial water valve angle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_servo_angle(NOZZLE_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set initial nozzle angle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = 20; /* Cycle through 20, 40, 60, 80, 100 */

        printf("Moisture: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold. Watering...\n");

            if (set_servo_angle(WATER_VALVE_PIN, 90) < 0) {
                fprintf(stderr, "Warning: failed to set water valve angle\n");
            }

            if (servo_sweep(WATER_VALVE_PIN, 0, 90) < 0) {
                fprintf(stderr, "Warning: failed to sweep water valve\n");
            }

            if (set_servo_angle(NOZZLE_PIN, 0) < 0) {
                fprintf(stderr, "Warning: failed to set nozzle angle\n");
            }

            if (servo_sweep(NOZZLE_PIN, 0, 135) < 0) {
                fprintf(stderr, "Warning: failed to sweep nozzle\n");
            }

            if (set_servo_angle(NOZZLE_PIN, 0) < 0) {
                fprintf(stderr, "Warning: failed to set nozzle angle\n");
            }

            if (servo_sweep(NOZZLE_PIN, 0, 180) < 0) {
                fprintf(stderr, "Warning: failed to sweep nozzle\n");
            }

            if (set_servo_angle(WATER_VALVE_PIN, 0) < 0) {
                fprintf(stderr, "Warning: failed to set water valve angle\n");
            }

            if (servo_sweep(WATER_VALVE_PIN, 0, 90) < 0) {
                fprintf(stderr, "Warning: failed to sweep water valve\n");
            }

            if (set_servo_angle(NOZZLE_PIN, 0) < 0) {
                fprintf(stderr, "Warning: failed to set nozzle angle\n");
            }

            if (servo_sweep(NOZZLE_PIN, 0, 135) < 0) {
                fprintf(stderr, "Warning: failed to sweep nozzle\n");
            }

            if (set_servo_angle(NOZZLE_PIN, 0) < 0) {
                fprintf(stderr, "Warning: failed to set nozzle angle\n");
            }

            if (servo_sweep(NOZZLE_PIN, 0, 180) < 0) {
                fprintf(stderr, "Warning: failed to sweep nozzle\n");
            }

            if (set_servo_angle(WATER_VALVE_PIN, 0) < 0) {
                fprintf(stderr, "Warning: failed to set water valve angle\n");
            }
        }

        /* Sleep for MOISTURE_CYCLE_DELAY_US, checking g_running every 100 ms */
        for (int i = 0; i < 100 && g_running; i++)
            gpioDelay(100000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (set_servo_angle(WATER_VALVE_PIN, 0) < 0)
        fprintf(stderr, "Warning: failed to set water valve angle to 0\n");
    if (set_servo_angle(NOZZLE_PIN, 0) < 0)
        fprintf(stderr, "Warning: failed to set nozzle angle to 0\n");
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

