#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_PIN      24
#define UNLOCK_PIN    23
#define MOTOR_PINS    {4, 17, 27, 22}
#define DEBOUNCE_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Drive the motor: step clockwise (512 steps).
 * Returns 0 on success, -1 on error.
 */
static int motor_clockwise(void)
{
    for (int i = 0; i < 512; i++) {
        if (gpioWrite(MOTOR_PINS[0], 1) != 0)
            return -1;
        if (gpioWrite(MOTOR_PINS[1], 1) != 0)
            return -1;
        if (gpioWrite(MOTOR_PINS[2], 1) != 0)
            return -1;
        if (gpioWrite(MOTOR_PINS[3], 1) != 0)
            return -1;

        gpioDelay(3);  /* 3 ms per step */
    }
    return 0;
}

/*
 * Drive the motor: step counter-clockwise (512 steps).
 * Returns 0 on success, -1 on error.
 */
static int motor_counterclockwise(void)
{
    for (int i = 0; i < 512; i++) {
        if (gpioWrite(MOTOR_PINS[0], 1) != 0)
            return -1;
        if (gpioWrite(MOTOR_PINS[1], 1) != 0)
            return -1;
        if (gpioWrite(MOTOR_PINS[2], 1) != 0)
            return -1;
        if (gpioWrite(MOTOR_PINS[3], 1) != 0)
            return -1;

        gpioDelay(3);  /* 3 ms per step */
    }
    return 0;
}

static void deenergize_all(void)
{
    for (int i = 0; i < 4; i++)
        gpioWrite(MOTOR_PINS[i], 0);
}

int main(void)
{
    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure motor pins as outputs --- */
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(MOTOR_PINS[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_PINS[i]);
            deenergize_all();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Configure lock and unlock pins as inputs with pull-ups --- */
    if (gpioSetMode(LOCK_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LOCK_PIN);
        deenergize_all();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", UNLOCK_PIN);
        deenergize_all();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", LOCK_PIN);
        deenergize_all();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", UNLOCK_PIN);
        deenergize_all();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automatic door lock system started. Press LOCK (BCM %d) or UNLOCK (BCM %d) to rotate.\n",
           LOCK_PIN, UNLOCK_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_lock_state = 0;  /* 0 = unlocked, 1 = locked */

    while (running) {
        int lock_state = gpioRead(LOCK_PIN);
        if (lock_state < 0) {
            fprintf(stderr, "Error reading LOCK GPIO %d\n", LOCK_PIN);
            break;
        }

        if (lock_state == 1) {
            if (motor_clockwise() != 0)
                break;
            last_lock_state = 1;
            printf("Lock rotation complete.\n");
        } else if (lock_state == 0) {
            if (motor_counterclockwise() != 0)
                break;
            last_lock_state = 0;
            printf("Unlock rotation complete.\n");
        } else {
            /* LOCK and UNLOCK are active-low; check state only. */
            if (lock_state == 0)
                last_lock_state = 1;
            else
                last_lock_state = 0;
            printf("Invalid lock/unlock state.\n");
        }

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    printf("\nShutting down...\n");
    deenergize_all();
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

