#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_LINE_OFFSET 17
#define ECHO_LINE_OFFSET 18
#define LOG_FILE "distance_log.txt"
#define MIN_GAP_US 60000
#define MAX_GAP_US 60000
#define SOUND_SPEED_CM_PER_US 0.01715
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 50000
#define ECHO_TIMEOUT_US_HIGH 50
#define ECHO_TIMEOUT_US_LOW 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int gpio_init(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_LINE_OFFSET);
    echo = gpiod_chip_get_line(chip, ECHO_LINE_OFFSET);
    if (!trigger || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(trigger, "hc-sr04-trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(echo, "hc-sr04-echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static int gpio_release(void) {
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return 0;
}

static int measure_distance(void) {
    struct timespec start, end;
    int ret;

    ret = gpiod_line_set_value(trigger, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    ret = gpiod_line_set_value(trigger, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }

    ret = gpiod_line_request_timed_read(echo, NULL, ECHO_TIMEOUT_US_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Failed to read echo line: %s\n", strerror(errno));
        return -1;
    }

    ret = gpiod_line_request_timed_read(echo, NULL, ECHO_TIMEOUT_US_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to read echo line: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 0) {
        fprintf(stderr, "Timeout waiting for echo pulse: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 0) {
        fprintf(stderr, "Echo pulse too short: %s\n", strerror(errno));
        return -1;
    }

    long pulse_us = ret;
    if (pulse_us < 0) {
        fprintf(stderr, "Error reading pulse width: %s\n", strerror(errno));
        return -1;
    }

    long duration_us = pulse_us;
    if (duration_us < 0) {
        fprintf(stderr, "Error calculating duration: %s\n", strerror(errno));
        return -1;
    }

    return (int)duration_us * SOUND_SPEED_CM_PER_US;
}

static int log_distance(int distance_cm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d\n", timestamp, distance_cm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_init() < 0) {
        return 1;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");

    while (program_running) {
        int distance_cm = measure_distance();
        if (distance_cm < 0) {
            fprintf(stderr, "Measurement failed, skipping.\n");
        } else {
            if (log_distance(distance_cm) < 0) {
                fprintf(stderr, "Logging failed, continuing.\n");
            }
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpio_release();
    return 0;
}

