        fprintf(stderr, "Error reading pulse width: %s\n", strerror(errno));
        return -1;
    }

    long duration_us = pulse_us;
    if (duration_us < 0) {
        fprintf(stderr, "Error calculating duration: %s\n", strerror(errno));
        return -1;
    }

    return (int)duration_us * SOUND_SPEED_CM_PER_US;
}

static int log_distance(int distance_cm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d\n", timestamp, distance_cm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_init() < 0) {
        return 1;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");

    while (program_running) {
        int distance_cm = measure_distance();
        if (distance_cm < 0) {
            fprintf(stderr, "Measurement failed, skipping.\n");
        } else {
            if (log_distance(distance_cm) < 0) {
                fprintf(stderr, "Logging failed, continuing.\n");
            }
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpio_release();
    return 0;
}

