#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

/* VL53L1X I2C address (default on Pi 4B) */
#define VL53L1X_ADDR 0x29

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_RANGING_MODE 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0046
#define VL53L1X_REG_RESULT_DISTANCE_MSB 0x0096
#define VL53L1X_REG_RESULT_DISTANCE_LSB 0x0097

/* GPIO pin for the relay */
#define RELAY_GPIO 18

/* Distance threshold for opening the door */
#define DISTANCE_THRESHOLD 50.0f

/* I2C bus on Raspberry Pi 4B */
#define I2C_BUS 1

/* Global I2C handle for cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    exit(0);
}

/* Initialize the VL53L1X sensor */
static int init_vl53l1x(void) {
    /* Software reset */
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Set ranging mode to continuous (0x01) */
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set ranging mode\n");
        return -1;
    }

    /* Start continuous ranging */
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

/* Read the 16-bit distance value from the VL53L1X */
static int read_distance(void) {
    uint16_t distance_msb = 0, distance_lsb = 0;

    /* Read 16-bit result from registers 0x0096 (MSB) and 0x0097 (LSB) */
    if (i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_DISTANCE_MSB, &distance_msb) < 0) {
        fprintf(stderr, "Error: Failed to read distance register\n");
        return -1;
    }
    if (i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_DISTANCE_LSB, &distance_lsb) < 0) {
        fprintf(stderr, "Error: Failed to read distance register\n");
        return -1;
    }

    return (int)distance_msb | ((int)distance_lsb << 8);
}

/* Check if the sensor data is ready (data ready bit set) */
static int is_data_ready(void) {
    return (i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS) & 0x01) != 0;
}

/* Log the current distance to stdout */
static void log_distance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to the VL53L1X */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n",
                VL53L1X_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the VL53L1X sensor */
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO for relay control */
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    /* Set up signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (1) {
        /* Check if data is ready */
        if (is_data_ready()) {
            /* Read distance */
            int distance = read_distance();
            if (distance < 0) {
                fprintf(stderr, "Error: Failed to read distance\n");
            } else {
                /* Log the distance */
                log_distance(distance);

                /* Check if the distance is within the threshold */
                if (distance <= DISTANCE_THRESHOLD) {
                    gpioWrite(RELAY_GPIO, 1); /* HIGH = open door */
                } else {
                    gpioWrite(RELAY_GPIO, 0); /* LOW = close door */
                }
            }
        }

        /* Wait 100 ms (pigpio delay returns in microseconds) */
        gpioDelay(100000);
    }

    /* Unreachable, but kept for completeness */
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

