#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"

#define GYRO_CONFIG 0x1B
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) error: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) error: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error (reg 0x%02X, len %d): %s\n", reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, GYRO_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6050 initialized. Reading gyroscope data...\n");

    while (running) {
        float x, y, z;
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            printf("X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }
        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

