#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_1_PIN 17
#define RELAY_2_PIN 18
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOG_FILE "smart_lighting.log"
#define SUNRISE_DURATION 30
#define STEP_SIZE 1

static volatile sig_atomic_t running = 1;
static int relay_pins[4] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
static int current_relay_pin = -1;
static int current_relay_duty = 0;
static int current_relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

static int set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        log_event("Error writing to GPIO pin");
        return -1;
    }
    return 0;
}

static int set_relay_duty(int pin, int duty) {
    if (duty < 0 || duty > PWM_RANGE) {
        log_event("Error: Duty cycle out of range");
        return -1;
    }
    if (gpioPWM(pin, duty) != 0) {
        log_event("Error: PWM write failed");
        return -1;
    }
    return 0;
}

static int set_relay_pwm(int pin, int duty) {
    if (set_relay_state(pin, 1) != 0) return -1;
    if (set_relay_duty(pin, duty) != 0) return -1;
    if (set_relay_state(pin, 0) != 0) return -1;
    return 0;
}

static int sunrise_simulation(int num_relays) {
    for (int i = 0; i < SUNRISE_DURATION && running; i++) {
        for (int j = 0; j < num_relays; j++) {
            if (set_relay_pwm(relay_pins[j], current_relay_duty) != 0) {
                log_event("Error: Failed to set relay PWM");
                return -1;
            }
            if (set_relay_state(relay_pins[j], 1) != 0) {
                log_event("Error: Failed to set relay HIGH");
                return -1;
            }
            if (set_relay_state(relay_pins[j], 0) != 0) {
                log_event("Error: Failed to set relay LOW");
                return -1;
            }
            if (i % STEP_SIZE == 0) {
                if (set_relay_duty(relay_pins[j], current_relay_duty + 1) != 0) {
                    log_event("Error: Failed to increment relay duty cycle");
                    return -1;
                }
            }
        }
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    for (int i = 0; i < 4; i++) {
        if (set_relay_pwm(relay_pins[i], 0) != 0) {
            log_event("Error: Failed to initialize relay state");
            gpioTerminate();
            return 1;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Smart lighting simulation started");

    if (sunrise_simulation(4) != 0) {
        log_event("Smart lighting simulation failed");
        gpioTerminate();
        return 1;
    }

    log_event("Smart lighting simulation completed");
    gpioTerminate();
    return 0;
}

