        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (pigpio error %d)\n",
                I2C_BUS, MPU6050_ADDR, handle);
        return -1;
    }

    /* Wake up the MPU-6050: write 0x00 to PWR_MGMT_1 (register 0x6B) */
    if (i2cWriteByteData(handle, 0x6B, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake MPU-6050\n");
        i2cClose(handle);
        return -1;
    }

    /* Set sample rate: SMPLRT_DIV = 0x07 (1 kHz) */
    if (i2cWriteByteData(handle, 0x19, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to set sample rate\n");
        i2cClose(handle);
        return -1;
    }

    /* Set gyro range: GYRO_CONFIG = 0x00 (±250 deg/s) */
    if (i2cWriteByteData(handle, 0x1B, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set gyro range\n");
        i2cClose(handle);
        return -1;
    }

    /* Verify sensor identity: WHO_AM_I = 0x68 */
    int who_am_i = i2cReadByteData(handle, 0x75);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        i2cClose(handle);
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I mismatch: got 0x%02X, expected 0x68\n", who_am_i);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

static int read_gyro_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z) {
    char buf[6];
    int bytes_read = i2cReadI2CBlockData(handle, 0x43, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: Failed to read 6 bytes from gyroscope (read %d)\n", bytes_read);
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *gyro_x = (float)raw_x / GYRO_SENSITIVITY_LSB_PER_DEG_S;
    *gyro_y = (float)raw_y / GYRO_SENSITIVITY_LSB_PER_DEG_S;
    *gyro_z = (float)raw_z / GYRO_SENSITIVITY_LSB_PER_DEG_S;
    return 0;
}

static void add_to_buffer(float gyro_x, float gyro_y, float gyro_z) {
    gyro_buffer[buffer_index] = gyro_x;
    gyro_buffer[buffer_index + 1] = gyro_y;
    gyro_buffer[buffer_index + 2] = gyro_z;
    buffer_index = (buffer_index + 3) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void check_threshold(float gyro_x, float gyro_y, float gyro_z) {
    if (fabsf(gyro_x) > GYRO_THRESHOLD_DEG_S ||
        fabsf(gyro_y) > GYRO_THRESHOLD_DEG_S ||
        fabsf(gyro_z) > GYRO_THRESHOLD_DEG_S) {
        gpioWrite(LED_PIN, 1);
        printf("Threshold exceeded! Gyro: X=%.2f, Y=%.2f, Z=%.2f\n", gyro_x, gyro_y, gyro_z);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    if (gpioSetMode(LED_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = init_mpu6050();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float gyro_x, gyro_y, gyro_z;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_gyro_data(i2c_handle, &gyro_x, &gyro_y, &gyro_z) == 0) {
            add_to_buffer(gyro_x, gyro_y, gyro_z);
            check_threshold(gyro_x, gyro_y, gyro_z);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading gyro data (attempt %d)\n", consecutive_errors);
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Error: Too many consecutive I2C read failures. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_RATE_HZ * 1000);
    }

    cleanup();
    return 0;
}

