#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 3900000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define LED_PIN 17
#define BUFFER_SIZE 64
#define THRESHOLD_X 200.0f
#define THRESHOLD_Y 200.0f
#define BLINK_DURATION_MS 500
#define SAMPLE_INTERVAL_US 100000

#define MPU6050_REG_XOUT_H 0x43
#define MPU6050_REG_XOUT_L 0x45
#define MPU6050_REG_YOUT_H 0x47
#define MPU6050_REG_YOUT_L 0x45
#define MPU6050_REG_ZOUT_H 0x47
#define MPU6050_REG_ZOUT_L 0x45

typedef struct {
    float x;
    float y;
    float z;
    time_t timestamp;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *buf, int len) {
    if (len > 1) {
        return -1;
    }
    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = buf,
        .len = 1,
        .speed_hz = SPI_SPEED_HZ,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    uint8_t buf[6];
    if (spi_read_reg(MPU6050_REG_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)raw_x / 131.0f;
    data->y = (float)raw_y / 131.0f;
    data->z = (float)raw_z / 131.0f;
    return 0;
}

static void add_to_buffer(circular_buffer_t *buf, gyro_data_t data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) {
        buf->count++;
    }
}

static void print_buffer(const circular_buffer_t *buf) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buf->count; i++) {
        time_t t = buf->data[i].timestamp;
        struct tm tm;
        localtime_r(&t, &tm);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        printf("%s,%.2f,%.2f,%.2f\n", ts, buf->data[i].x, buf->data[i].y, buf->data[i].z);
    }
}

static void control_led(int on) {
    if (led_line) {
        gpiod_line_set_value(led_line, on ? 1 : 0);
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "gyro_monitor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    circular_buffer_t buffer;
    memset(&buffer, 0, sizeof(buffer));

    while (running) {
        gyro_data_t data;
        if (read_gyro_data(&data) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            control_led(0);
            usleep(BLINK_DURATION_MS * 1000);
            continue;
        }

        time_t now = time(NULL);
        add_to_buffer(&buffer, data);
        print_buffer(&buffer);

        control_led(data.x > THRESHOLD_X || data.y > THRESHOLD_Y);

        usleep(SAMPLE_INTERVAL_US);
    }

    control_led(0);
    cleanup();
    return EXIT_SUCCESS;
}

