#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define LED_PIN 21
#define ACCEL_SCALE_2G 1.0f
#define ACCEL_CONFIG_REG 0x1C
#define ACCEL_XOUT_H 0x3B
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define LOG_FILE "tilt_log.txt"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_mpu6050(void) {
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake MPU-6050\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set accelerometer config\n");
        return -1;
    }
    return 0;
}

static int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static float calculate_roll(int16_t x, int16_t y, int16_t z) {
    return atan2f(y, sqrtf(x * x + z * z)) * 180.0f / (float)M_PI;
}

static float calculate_pitch(int16_t x, int16_t y, int16_t z) {
    return atan2f(-x, sqrtf(y * y + z * z)) * 180.0f / (float)M_PI;
}

static void log_data(float roll, float pitch) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error: Failed to open log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    fclose(fp);
}

static void control_led(float roll, float pitch) {
    int led_state = (fabsf(roll) > 45.0f) ? 1 : 0;
    gpioWrite(LED_PIN, led_state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", MPU6050_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Tilt monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t x, y, z;
        if (read_accel_data(&x, &y, &z) == 0) {
            float roll = calculate_roll(x, y, z);
            float pitch = calculate_pitch(x, y, z);
            log_data(roll, pitch);
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Tilt monitoring stopped.\n");
    return 0;
}

