#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define GPIO_CHIP "gpiochip0"
#define GPIO_LED 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, value, 1) == 1) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_sensor_data(int fd, uint16_t *ambient, uint16_t *proximity) {
    uint8_t buf[2];
    if (i2c_write_reg8(fd, 0x20, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x22, 0x00) < 0) return -1;
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    *ambient = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *proximity = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,AmbientLight:0x%04X,Proximity:0x%04X\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LED, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "si1145_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LED, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Si1145 biometric sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ambient, proximity;
        if (read_sensor_data(i2c_fd, &ambient, &proximity) < 0) {
            fprintf(stderr, "Sensor read failed, retrying...\n");
            usleep(100000);
            continue;
        }

        if (proximity > PROXIMITY_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            printf("Proximity threshold exceeded! LED ON.\n");
        } else {
            gpiod_line_set_value(led_line, 0);
            printf("Proximity threshold not exceeded. LED OFF.\n");
        }

        log_data(log_fp, ambient, proximity);
        usleep(100000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

