#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define LED_GPIO 17
#define THRESHOLD_DEG_PER_SEC 20.0
#define BUFFER_SIZE 100
#define REG_RATE_XL 0x02
#define REG_RATE_XH 0x03
#define REG_ADDR_MSB 0x80
#define REG_ADDR_LSB 0x00
#define SAMPLE_PERIOD_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int spi_ready = 0;
static int led_on = 0;
static struct timespec last_warning_time = {0, 0};
static struct timespec last_reading_time = {0, 0};
static struct timespec buffer_start_time = {0, 0};
static struct timespec buffer_end_time = {0, 0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (spi_ready) {
        spiClose(spi_handle);
        spi_ready = 0;
    }
    if (led_on) {
        gpioWrite(LED_GPIO, 0);
        led_on = 0;
    }
    gpioTerminate();
}

static void read_gyro_data(float *x, float *y, float *z) {
    uint8_t addr = REG_ADDR_MSB | REG_ADDR_LSB;
    uint8_t tx[2] = {REG_ADDR_MSB, 0x00};
    uint8_t rx[2] = {0, 0};

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed\n");
        return;
    }

    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    *x = (float)raw * 200.0f / 0xFFFF;
    *y = (float)raw * 200.0f / 0xFFFF;
    *z = (float)raw * 200.0f / 0xFFFF;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(buf + strlen(buf), len - strlen(buf), ".%03ld", ts.tv_nsec / 1000000);
}

static void log_reading(float x, float y, float z) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    printf("[%s] X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", ts, x, y, z);
}

static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > THRESHOLD_DEG_PER_SEC ||
        fabsf(y) > THRESHOLD_DEG_PER_SEC ||
        fabsf(z) > THRESHOLD_DEG_PER_SEC) {
        if (led_on) {
            gpioWrite(LED_GPIO, 1);
            last_warning_time = buffer_end_time;
        } else {
            led_on = 1;
            gpioWrite(LED_GPIO, 1);
        }
    } else {
        if (!led_on) {
            led_on = 0;
            gpioWrite(LED_GPIO, 0);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        cleanup();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    buffer_start_time = buffer_end_time = {0, 0};

    while (running) {
        float x, y, z;
        read_gyro_data(&x, &y, &z);
        get_timestamp(buffer_start_time.tv_sec, buffer_start_time.tv_nsec);

        if (buffer_start_time.tv_sec == buffer_end_time.tv_sec &&
            buffer_start_time.tv_nsec == buffer_end_time.tv_nsec) {
            buffer_end_time = buffer_start_time;
            buffer_start_time = {0, 0};
        }

        log_reading(x, y, z);
        check_threshold(x, y, z);

        if (buffer_end_time.tv_sec != buffer_start_time.tv_sec ||
            buffer_end_time.tv_nsec != buffer_start_time.tv_nsec) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("Buffer reset, %s\n", ts);
            buffer_start_time = buffer_end_time;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

