#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP_1_PIN 17
#define LAMP_2_PIN 18
#define LAMP_3_PIN 27
#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define DIM_PERIOD_US 1000
#define DIM_STEP_US 100
#define DIM_MAX_US 3600
#define MAX_DIM_US DIM_MAX_US

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioPWM(LAMP_1_PIN, 0);
    gpioPWM(LAMP_2_PIN, 0);
    gpioPWM(LAMP_3_PIN, 0);
    gpioTerminate();
}

static void dim_lamp(int pin, int duration_s) {
    if (duration_s <= 0) {
        fprintf(stderr, "Error: duration must be positive\n");
        return;
    }

    int step = (int)(duration_s * PWM_RANGE / DIM_MAX_US);
    int remaining = duration_s;

    while (remaining > 0 && running) {
        int duty = (remaining > PWM_RANGE) ? PWM_RANGE : remaining;
        gpioPWM(pin, duty);
        remaining -= DIM_STEP_US;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: duration must be between 1 and 3600 seconds\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(LAMP_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LAMP_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LAMP_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LAMP_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LAMP_3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LAMP_3_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LAMP_1_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", LAMP_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LAMP_2_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", LAMP_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LAMP_3_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", LAMP_3_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LAMP_1_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", LAMP_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LAMP_2_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", LAMP_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LAMP_3_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", LAMP_3_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fading lamps: GPIO%d, GPIO%d, GPIO%d\n",
           LAMP_1_PIN, LAMP_2_PIN, LAMP_3_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        dim_lamp(LAMP_1_PIN, duration);
        dim_lamp(LAMP_2_PIN, duration);
        dim_lamp(LAMP_3_PIN, duration);

        if (running) {
            usleep(DIM_PERIOD_US);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

