#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define BLUE_PIN 24

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *yellow_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !yellow_line || !green_line || !blue_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(0);
    }

    if (gpiod_line_request_output(red_line, "traffic_light", 0) < 0) {
        perror("gpiod_line_request_output(red)");
        cleanup_and_exit(0);
    }
    if (gpiod_line_request_output(yellow_line, "traffic_light", 0) < 0) {
        perror("gpiod_line_request_output(yellow)");
        cleanup_and_exit(0);
    }
    if (gpiod_line_request_output(green_line, "traffic_light", 0) < 0) {
        perror("gpiod_line_request_output(green)");
        cleanup_and_exit(0);
    }
    if (gpiod_line_request_output(blue_line, "traffic_light", 0) < 0) {
        perror("gpiod_line_request_output(blue)");
        cleanup_and_exit(0);
    }

    printf("Traffic light simulator started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        if (gpiod_line_set_value(red_line, 0) < 0) {
            perror("gpiod_line_set_value(red)");
            cleanup_and_exit(0);
        }
        if (gpiod_line_set_value(yellow_line, 0) < 0) {
            perror("gpiod_line_set_value(yellow)");
            cleanup_and_exit(0);
        }
        if (gpiod_line_set_value(green_line, 0) < 0) {
            perror("gpiod_line_set_value(green)");
            cleanup_and_exit(0);
        }
        if (gpiod_line_set_value(blue_line, 0) < 0) {
            perror("gpiod_line_set_value(blue)");
            cleanup_and_exit(0);
        }

        usleep(1000000);
        if (gpiod_line_set_value(red_line, 1) < 0) {
            perror("gpiod_line_set_value(red)");
            cleanup_and_exit(0);
        }
        if (gpiod_line_set_value(yellow_line, 1) < 0) {
            perror("gpiod_line_set_value(yellow)");
            cleanup_and_exit(0);
        }
        if (gpiod_line_set_value(green_line, 1) < 0) {
            perror("gpiod_line_set_value(green)");
            cleanup_and_exit(0);
        }
        if (gpiod_line_set_value(blue_line, 1) < 0) {
            perror("gpiod_line_set_value(blue)");
            cleanup_and_exit(0);
        }
    }

    cleanup_and_exit(0);
    return EXIT_SUCCESS;
}

