#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "UNKNOWN TIME: %s\n", message);
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!sensor_line || !buzzer_line || !led_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Fire alarm started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value: %s\n", strerror(errno));
            break;
        }

        if (sensor_value == 0) {
            printf("Flame Detected!\n");
            log_event("Flame Detected");
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Failed to activate buzzer: %s\n", strerror(errno));
            }
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to activate LED: %s\n", strerror(errno));
            }
            usleep(DEBOUNCE_MS * 1000);
            int debounced = gpiod_line_get_value(sensor_line);
            if (debounced == 0) {
                printf("Flame Cleared.\n");
                log_event("Flame Cleared");
                if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                    fprintf(stderr, "Failed to deactivate buzzer: %s\n", strerror(errno));
                }
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "Failed to deactivate LED: %s\n", strerror(errno));
                }
            }
        } else {
            usleep(POLL_INTERVAL_MS * 1000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (sensor_line) gpiod_line_release(sensor_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

