#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set touch pin %d as input\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on touch pin %d\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart light switch started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int touch_state = gpioRead(TOUCH_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read touch pin %d\n", TOUCH_PIN);
            break;
        }

        if (touch_state == 1) {
            if (gpioWrite(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to energize relay on GPIO %d\n", RELAY_PIN);
                break;
            }
            printf("Relay ON\n");
            gpioDelay(DEBOUNCE_MS * 1000);
            if (gpioWrite(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to de-energize relay on GPIO %d\n", RELAY_PIN);
                break;
            }
            printf("Relay OFF\n");
        } else {
            if (gpioWrite(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to de-energize relay on GPIO %d\n", RELAY_PIN);
                break;
            }
            printf("Relay OFF\n");
        }
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

