/*
 * Mood light with ALSA audio capture on Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - Common-cathode RGB LED on GPIO17 (red), GPIO18 (green), GPIO27 (blue)
 *   - Current-limiting resistors (e.g., 220 ohm)
 *   - pigpio software PWM on GPIO17, GPIO18, GPIO27
 *
 * Build:
 *   gcc -O2 -Wall -o mood_light mood_light.c -lpigpio -lrt
 *
 * Run:
 *   ./mood_light [optional: sensitivity scaling]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN      17
#define GREEN_PIN    18
#define BLUE_PIN     27

#define ALSA_DEVICE  "/dev/snd/pcm0p"
#define ALSA_PERIOD  1024
#define ALSA_CHAN     1
#define ALSA_SAMPLE_RATE 8000
#define ALSA_PERIOD_SIZE (ALSA_SAMPLE_RATE * ALSA_PERIOD)

#define SAMPLE_PERIOD_US 10000   /* 10 ms */
#define SAMPLE_PERIOD_US_ALSA (SAMPLE_PERIOD_US * 1000)

#define SENSITIVITY_SCALE 1.0

#define ALSA_AVAILABLE 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single frame from ALSA.
 * Returns 0 on success, -1 on error.
 */
static int alsa_read_frame(int *data, int *frame_size)
{
    int ret;

    /*
     * ALSA_AVAILABLE:
     *   - If ALSA is not available, pigpio will fall back to a
     *     simulated sine-wave amplitude.  This is a graceful
     *     fallback for users who do not have ALSA installed.
     */
    if (!ALSA_AVAILABLE) {
        /*
         * pigpio software PWM is not available on the Raspberry Pi.
         * We simulate the audio input with a sine-wave amplitude.
         */
        int sine_val = (int)((ALSA_PERIOD_SIZE * ALSA_PERIOD) / 2.0);
        *data = sine_val;
        *frame_size = ALSA_PERIOD_SIZE;
        return 0;
    }

    /*
     * Suspend ALSA:
     *   - ALSA_SUSPEND: suspend the ALSA driver
     *   - ALSA_RESUME: resume the ALSA driver
     */
    ret = snd_pcm_prepare(alsa_handle);
    if (ret < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", strerror(errno));
        return -1;
    }

    /*
     * Resume ALSA:
     *   - ALSA_SUSPEND: suspend the ALSA driver
     *   - ALSA_RESUME: resume the ALSA driver
     */
    ret = snd_pcm_resume(alsa_handle);
    if (ret < 0) {
        fprintf(stderr, "snd_pcm_resume failed: %s\n", strerror(errno));
        snd_pcm_prepare(alsa_handle);
        return -1;
    }

    /*
     * Read the frame.
     * ALSA_PERIOD_SIZE is the number of frames in the period.
     * We read ALSA_PERIOD_SIZE samples.
     */
    int frame_size_actual = ALSA_PERIOD_SIZE;
    if (ret < 0) {
        fprintf(stderr, "snd_pcm_readi failed: %s\n", strerror(errno));
        return -1;
    }

    *data = (int)ret;
    *frame_size = frame_size_actual;
    return 0;
}

/*
 * Compute the RMS amplitude of the audio samples.
 * Returns the RMS value (0.0 to 1.0) or -1.0 on error.
 */
static double calculate_rms(int *data, int frame_size)
{
    if (frame_size == 0) {
        return -1.0;
    }

    double sum = 0.0;
    for (int i = 0; i < frame_size; i++) {
        sum += (double)data[i] * (double)data[i];
    }

    return sqrt(sum / frame_size);
}

/*
 * Map the RMS amplitude to RGB PWM values.
 * Returns the RGB PWM values (0-255) or -1.0 on error.
 */
static double map_rms_to_pwm(double rms)
{
    if (rms < 0.0) {
        return -1.0;
    }

    /*
     * Cool colors for low amplitude (0.0-0.5).
     * Warm colors for high amplitude (0.5-1.0).
     */
    if (rms < 0.5) {
        return (double)rms;
    }

    return (double)rms * 0.5 + 0.5;
}

/*
 * Set the RGB PWM values for the given amplitude.
 * Returns 0 on success, -1.0 on error.
 */
static int set_rgb_pwm(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN, red) < 0) {
        fprintf(stderr, "gpioPWM(RED_PIN, %d) failed\n", red);
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green) < 0) {
        fprintf(stderr, "gpioPWM(GREEN_PIN, %d) failed\n", green);
        return -1;
    }
    if (gpioPWM(BLUE_PIN, blue) < 0) {
        fprintf(stderr, "gpioPWM(BLUE_PIN, %d) failed\n", blue);
        return -1;
    }
    return 0;
}

/*
 * Set the RGB PWM values for the given amplitude.
 * Returns 0 on success, -1.0 on error.
 */
static int set_rgb_pwm_with_sensitivity(double amplitude, double sensitivity)
{
    if (amplitude < 0.0) {
        return -1.0;
    }

    double rms = calculate_rms(data, frame_size);
    if (rms < 0.0) {
        return -1.0;
    }

    double pwm = map_rms_to_pwm(rms);
    if (pwm < 0.0) {
        return -1.0;
    }

    if (amplitude < sensitivity) {
        return (int)(pwm * sensitivity);
    }

    return (int)(pwm * (1.0 - sensitivity));
}

int main(int argc, char *argv[])
{
    int opt;
    int opt_arg;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                opt_arg = atoi(optarg);
                if (opt_arg <= 0) {
                    fprintf(stderr, "Invalid sensitivity scale (must be positive)\n");
                    return EXIT_FAILURE;
                }
                SENSITIVITY_SCALE = (double)opt_arg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RED_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(GREEN_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BLUE_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off */
    if (gpioWrite(RED_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(RED_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GREEN_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(GREEN_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BLUE_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(BLUE_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Set the initial PWM values to 0.
     * This ensures the LEDs are off at startup.
     */
    if (set_rgb_pwm(0, 0, 0) < 0) {
        fprintf(stderr, "Failed to set initial PWM values\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Mood light started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int data[ALSA_PERIOD_SIZE];
        int frame_size;

        if (alsa_read_frame(data, &frame_size) != 0) {
            fprintf(stderr, "Failed to read ALSA frame\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double amplitude = calculate_rms(data, frame_size);
        double pwm = map_rms_to_pwm(amplitude);

        if (set_rgb_pwm_with_sensitivity(pwm, SENSITIVITY_SCALE) < 0) {
            fprintf(stderr, "Failed to set RGB PWM\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    set_rgb_pwm(0, 0, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

