#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define TCS34725_ADDR 0x29
#define TCS34725_REG_POWER_ON 0x80
#define TCS34725_REG_ENABLE_RGCB 0x81
#define TCS34725_REG_DATA_START 0x14
#define TCS34725_REG_DATA_END 0x1A
#define TCS34725_DATA_CLEAR 0x14
#define TCS34725_DATA_RED 0x15
#define TCS34725_DATA_GREEN 0x16
#define TCS34725_DATA_BLUE 0x17
#define TCS34725_DATA_CLEAR_VALUE 0x00
#define TCS34725_DATA_RED_VALUE 0x01
#define TCS34725_DATA_GREEN_VALUE 0x02
#define TCS34725_DATA_BLUE_VALUE 0x03
#define TCS34725_DATA_CLEAR_TIME_MS 154
#define SAMPLE_INTERVAL_MS 500

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, pigpio_error(rc));
    }
    return rc;
}

static int read_register(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_data(uint8_t start_reg, uint8_t *data) {
    int rc = i2cReadI2CBlockData(i2c_handle, start_reg, (char *)data, TCS34725_DATA_END - TCS34725_DATA_START + 1);
    if (rc < 0) {
        fprintf(stderr, "Error reading data block: %s\n", pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    if (write_register(TCS34725_REG_POWER_ON, 0x03) < 0) return -1;
    gpioDelay(2000);
    if (write_register(TCS34725_REG_ENABLE_RGCB, 0x03) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int read_sensor_data(uint8_t *clear, uint8_t *red, uint8_t *green, uint8_t *blue) {
    uint8_t data[4];
    if (read_data(TCS34725_DATA_CLEAR, data) < 0) return -1;
    *clear = data[0];
    if (read_data(TCS34725_DATA_RED, data) < 0) return -1;
    *red = data[1];
