#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME "gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = {11, 13, 15, 17};

static const int brightness_steps[NUM_RELAYS] = {0, 64, 128, 192};
static const int brightness_step_increment[NUM_RELAYS] = {1, 1, 1, 1};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", relay_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "sunrise-relay", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", relay_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void set_relay(int pin, int value) {
    if (gpiod_line_set_value(lines[pin], value) < 0) {
        fprintf(stderr, "Failed to set GPIO line %u to %d\n", pin, value);
    }
}

static void cycle_phase(int phase) {
    int brightness = brightness_steps[phase];
    int step_increment = brightness_step_increment[phase];

    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
        usleep(100000);
        set_relay(relay_pins[i], 1);
        usleep(100000);
    }
}

static void cycle_phase_sunrise(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 1);
        usleep(100000);
    }
}

static void cycle_phase_daytime(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 1);
        usleep(100000);
    }
}

static void cycle_phase_sunset(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
        usleep(100000);
    }
}

static void cycle_phase_nighttime(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
        usleep(100000);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", CHIP_NAME);
        return EXIT_FAILURE;
    }

    if (init_relays() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sunrise/Sunset lighting simulator started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        cycle_phase_sunrise();
        cycle_phase_daytime();
        cycle_phase_sunset();
        cycle_phase_nighttime();
        usleep(1000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

