#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define IR_SENSOR_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_SEC 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *filename) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("fopen log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s - Motion detected at %s\n", timestamp, filename) < 0) {
        perror("fprintf log file");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush log file");
        return -1;
    }

    return 0;
}

static int record_video(const char *filename) {
    char command[256];
    int ret;

    snprintf(command, sizeof(command), "raspivid -o %s --timestamps -n %d -b %d -fps 25",
             filename, VIDEO_DURATION_SEC, VIDEO_DURATION_SEC);

    ret = system(command);
    if (ret == -1) {
        perror("system() failed");
        return -1;
    }

    if (WIFEXITED(ret) && WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(ret));
        return -1;
    }

    return 0;
}

int main(void) {
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(IR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(IR_SENSOR_PIN, PI_PUD_DOWN);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int level = gpioRead(IR_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", IR_SENSOR_PIN);
            break;
        }

        if (level == 0) {
            if (log_event(filename) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
            if (record_video(filename) != 0) {
                fprintf(stderr, "Failed to record video\n");
            }
        }

        gpioDelay(DEBOUNCE_MS * 1000);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Motion detection stopped.\n");
    return EXIT_SUCCESS;
}

