}

static int log_reading(int zone, int reading, int relay_pin) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Zone: %d, Reading: %d, Relay: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                zone, reading, relay_pin);
    } else {
        fprintf(fp, "Error: time() failed\n");
    }
    fclose(fp);
    return 0;
}

