#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define GPIO_ALARM 27
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_SEC 0.5
#define ALARM_DURATION_SEC 5
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_adxl345(int handle) {
    if (i2cWriteByteData(handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to enable measurement mode\n");
        return -1;
    }
    if (i2cWriteByteData(handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to configure data format\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, DATAX0, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }

    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;
    return 0;
}

static float calculate_g_force(float x, float y, float z) {
    return (x * x) + (y * y) + (z * z);
}

static int check_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD ||
            fabsf(y) < FREEFALL_THRESHOLD ||
            fabsf(z) < FREEFALL_THRESHOLD);
}

static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        perror("Error: Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

static void alarm_simulation(float x, float y, float z) {
    if (gpioWrite(GPIO_ALARM, 1) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO high\n");
        return;
    }
    gpioDelay(ALARM_DURATION_SEC * 1000000);
    if (gpioWrite(GPIO_ALARM, 0) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO low\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", ADXL345_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_adxl345(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_ALARM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_ALARM, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;
    int freefall_count = 0;
    int consecutive_freefall = 0;

    while (!terminate) {
        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            consecutive_freefall++;
            if (consecutive_freefall >= FREEFALL_DURATION_SEC) {
                consecutive_freefall = 0;
                if (check_freefall(x, y, z)) {
                    log_freefall(x, y, z);
                    alarm_simulation(x, y, z);
                    freefall_count++;
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_ALARM, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

