#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <stdbool.h>

#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define FALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 1.5f
#define SENSITIVITY 16384.0f
#define MAX_RETRIES 3
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_acceleration(int handle, float *x, float *y, float *z) {
    char buf[6];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(handle, OUT_X_L) < 0) {
            fprintf(stderr, "I2C write error (retry %d): %d\n", retries + 1, retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }
        if (i2cReadDevice(handle, buf, 6) != 6) {
            fprintf(stderr, "I2C read error (retry %d): %d\n", retries + 1, retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }
        int16_t raw = (int16_t)((buf[0] << 8) | (buf[1] & 0xFF));
        *x = (float)raw / SENSITIVITY;
        *y = (float)raw / SENSITIVITY;
        *z = (float)raw / SENSITIVITY;
        return 0;
    }
    return -1;
}

float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

void buzzer_on(void) {
    gpioWrite(BUZZER_GPIO, 1);
}

void buzzer_off(void) {
    gpioWrite(BUZZER_GPIO, 0);
}

void cleanup(void) {
    buzzer_off();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        float fall_threshold = atof(argv[1]);
        if (fall_threshold <= 0.0f) {
            fprintf(stderr, "Fall threshold must be positive.\n");
            return 1;
        }
        if (argc > 2) {
            float impact_threshold = atof(argv[2]);
            if (impact_threshold <= 0.0f) {
                fprintf(stderr, "Impact threshold must be positive.\n");
                return 1;
            }
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer GPIO mode\n");
        cleanup();
        return 1;
    }

    if (gpioWrite(BUZZER_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise buzzer GPIO state\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);
            if (magnitude < FALL_THRESHOLD) {
                buzzer_on();
                printf("FALL DETECTED (magnitude: %.2f g)\n", magnitude);
            } else if (magnitude > IMPACT_THRESHOLD) {
                buzzer_on();
                printf("IMPACT DETECTED (magnitude: %.2f g)\n", magnitude);
            }
            gpioDelay(POLL_DELAY_US);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
    }

    cleanup();
    return 0;
}

