#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define CTRL_REG1_VAL 0x57
#define CTRL_REG4_VAL 0x88
#define THRESHOLD_G 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define I2C_BUS 1

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading acceleration data: expected 6 bytes, got %d\n", bytes_read);
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static float calculate_g(int16_t raw) {
    return (float)raw / 2048.0f;
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.4f, Y: %.4f, Z: %.4f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fclose(fp);
}

static void trigger_shutdown(void) {
    printf("High acceleration detected! Shutting down...\n");
    system("sudo shutdown -h now");
}

static int init_lis3dh(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG1, CTRL_REG1_VAL) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(handle, CTRL_REG4, CTRL_REG4_VAL) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4\n");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int i2c_address = LIS3DH_ADDR;
    if (argc > 1) {
        i2c_address = (int)strtol(argv[1], NULL, 0);
        if (i2c_address < 0x08 || i2c_address > 0x77) {
            fprintf(stderr, "Invalid I2C address: 0x%02x\n", i2c_address);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "LIS3DH initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LIS3DH initialized at 0x%02x. Threshold: %.2f g\n", i2c_address, THRESHOLD_G);

    while (running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            float x = calculate_g(raw_x);
            float y = calculate_g(raw_y);
            float z = calculate_g(raw_z);
            if (x > THRESHOLD_G || y > THRESHOLD_G || z > THRESHOLD_G) {
                log_event(x, y, z);
                trigger_shutdown();
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

