#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define RELAY_GPIO 18
#define LOG_FILE "relay_log.txt"
#define BUFFER_SIZE 256

static int server_socket = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    if (!log_file) return -1;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
    return 0;
}

static int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s: %s (errno: %s)\n", timestamp, message, strerror(errno));
    return -1;
}

static int read_command(char *command, size_t max_len) {
    char *ptr = command;
    while (*ptr && *ptr != '\n' && *ptr != '\r') {
        ptr++;
    }
    if (*ptr == '\0') {
        return -1;
    }
    *ptr = '\0';
    char *endptr = NULL;
    errno = 0;
    long val = strtol(command, &endptr, 10);
    if (errno != 0 || endptr == command || *endptr != '\0') {
        return -1;
    }
    if (val < 0 || val > 255) {
        return -1;
    }
    return 0;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        return -1;
    }
    char message[BUFFER_SIZE];
    snprintf(message, sizeof(message), "Relay state changed to %d", state);
    log_event(message);
    return 0;
}

static int handle_client(int client_socket) {
    char command[BUFFER_SIZE];
    char response[BUFFER_SIZE];
    int retries = 0;
    int bytes_read;

    while (running) {
        bytes_read = recv(client_socket, command, sizeof(command) - 1, 0);
        if (bytes_read < 0) {
            if (errno == EINTR) continue;
            log_error("recv failed");
