#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Sensirion SLF3S-1300F I2C addresses ---- */
#define SENSOR1_ADDR  0x08
#define SENSOR2_ADDR  0x09

/* ---- Scaling factors (ml/min per sensor) ---- */
#define SCALE_FACTOR  1.0f
#define MIN_FLOW_RATE 5.0f
#define MAX_FLOW_RATE 100.0f

/* ---- GPIO pin for relay control ---- */
#define RELAY_PIN    18

/* ---- I2C bus ---- */
#define I2C_BUS      1

/* ---- Timing ---- */
#define POLL_DELAY_US 100000  /* 100 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c1 = -1;
static int g_i2c2 = -1;

/* ---- Function prototypes ---- */
static int  init_i2c(void);
static int  read_flow_rate(int handle, float *flow_rate);
static void control_relay(int handle, float flow_rate);
static void log_flow_rate(float flow_rate);
static void cleanup(void);
static void signal_handler(int sig);

/*
 * Initialize I2C communication on the first handle.
 * Returns 0 on success, -1 on failure.
 */
static int init_i2c(void)
{
    if (g_i2c1 >= 0) {
        i2cClose(g_i2c1);
        g_i2c1 = -1;
    }
    if (g_i2c2 >= 0) {
        i2cClose(g_i2c2);
        g_i2c2 = -1;
    }

    g_i2c1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c1 < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SENSOR1_ADDR, g_i2c1);
        return -1;
    }

    g_i2c2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c2 < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SENSOR2_ADDR, g_i2c2);
        i2cClose(g_i2c1);
        g_i2c1 = -1;
        return -1;
    }

    return 0;
}

/*
 * Read flow rate from a single sensor.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_flow_rate(int handle, float *flow_rate)
{
    char buf[3];
    int  rc;

    /* Send start-measurement command (bytes 0x36, 0x08) */
    rc = i2cWriteByte(handle, 0x36);
    if (rc < 0) {
        fprintf(stderr, "Error writing start-measurement command to handle %d: %d\n",
                handle, rc);
        return -1;
    }
    gpioDelay(2000);  /* 2 ms settle time */

    /* Read 3 bytes: 2 data + 1 CRC */
    rc = i2cReadDevice(handle, buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Error reading from handle %d: expected 3 bytes, got %d\n",
                handle, rc);
        return -1;
    }

    /* Validate CRC-8 (polynomial 0x31, init 0xFF, no final XOR) */
    uint8_t crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= buf[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    if (crc != buf[2]) {
        fprintf(stderr, "CRC mismatch on handle %d: calc=0x%02X, recv=0x%02X\n",
                handle, crc, buf[2]);
        return -2;
    }

    /* Convert big-endian 16-bit value to ml/min */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw * SCALE_FACTOR;

    return 0;
}

/*
 * Control the relay pin based on the flow rate.
 * Returns 0 on success, -1 on I2C error, -2 on relay control error.
 */
static void control_relay(int handle, float flow_rate)
{
    if (flow_rate < MIN_FLOW_RATE) {
        gpioWrite(RELAY_PIN, 0);
    } else if (flow_rate > MAX_FLOW_RATE) {
        gpioWrite(RELAY_PIN, 1);
    } else {
        gpioWrite(RELAY_PIN, 0);
    }
}

/*
 * Log a successful flow rate cycle to flow_log.txt.
 * Returns 0 on success, -1 on I2C error.
 */
static int log_flow_rate(float flow_rate)
{
    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening flow_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Flow Rate: %.2f ml/min\n", timestamp, flow_rate);
    fclose(fp);
    return 0;
}

/*
 * Cleanup all resources.
 * De-energizes the relay pin.
 */
static void cleanup(void)
{
    if (g_i2c1 >= 0) {
        i2cClose(g_i2c1);
        g_i2c1 = -1;
    }
    if (g_i2c2 >= 0) {
        i2cClose(g_i2c2);
        g_i2c2 = -1;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);  /* relay de-energized initially */

    /* Initialize I2C */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        float flow_rate1 = 0.0f;
        float flow_rate2 = 0.0f;

        if (read_flow_rate(g_i2c1, &flow_rate1) == 0) {
            log_flow_rate(flow_rate1);
            control_relay(g_i2c1, flow_rate1);
        } else {
            fprintf(stderr, "Warning: read failed for sensor 1; skipping cycle\n");
        }

        if (read_flow_rate(g_i2c2, &flow_rate2) == 0) {
            log_flow_rate(flow_rate2);
            control_relay(g_i2c2, flow_rate2);
        } else {
            fprintf(stderr, "Warning: read failed for sensor 2; skipping cycle\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

