#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24
#define MOTOR_ENA_PIN   22

#define POLL_INTERVAL_US 200000   /* 200 ms */
#define MOTOR_RUN_US     5000000 /* 5 s  */
#define DRY_THRESHOLD_US 600000 /* 600 ms */
#define SENSOR_POLLS      3       /* 3 consecutive dry readings */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single byte to a pigpio GPIO pin.
 * Returns 0 on success, -1 on failure.
 */
static int gpio_write(int pin, int value)
{
    if (gpioWrite(pin, value) < 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", pin, value);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a pigpio GPIO pin.
 * Returns 0 on success, -1 on failure.
 */
static int gpio_read(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        syslog(LOG_ERR, "gpioRead(%d) failed", pin);
        return -1;
    }
    return v;
}

/*
 * Trigger the window-closing sequence.
 * Returns 0 on success, -1 on failure.
 */
static int trigger_close_sequence(void)
{
    if (gpio_write(MOTOR_ENA_PIN, 1) < 0)
        return -1;
    if (gpio_write(MOTOR_IN1_PIN, 1) < 0)
        return -1;
    if (gpio_write(MOTOR_IN2_PIN, 0) < 0)
        return -1;
    syslog(LOG_INFO, "Rain detected. Closing window...");

    /* Motor run */
    if (gpio_write(MOTOR_ENA_PIN, 1) < 0)
        return -1;
    if (gpio_write(MOTOR_IN1_PIN, 1) < 0)
        return -1;
    if (gpio_write(MOTOR_IN2_PIN, 0) < 0)
        return -1;
    gpioDelay(MOTOR_RUN_US);

    /* Motor stop */
    if (gpio_write(MOTOR_ENA_PIN, 0) < 0)
        return -1;
    if (gpio_write(MOTOR_IN1_PIN, 0) < 0)
        return -1;
    if (gpio_write(MOTOR_IN2_PIN, 0) < 0)
        return -1;

    syslog(LOG_INFO, "Rain-activated window closed.");
    return 0;
}

/*
 * Verify that the sensor reads dry for DRY_THRESHOLD_US consecutive polls.
 * Returns 0 on success, -1 on failure.
 */
static int verify_dry(void)
{
    int dry_count = 0;
    int last_poll = 0;

    for (int i = 0; i < SENSOR_POLLS; i++) {
        int v = gpio_read(RAIN_SENSOR_PIN);
        if (v < 0) {
            syslog(LOG_ERR, "gpio_read(rain) failed");
            return -1;
        }
        if (v == 0) {
