            if (dry_count >= DRY_THRESHOLD_US) {
                syslog(LOG_INFO, "Rain-activated window verified dry.");
                return 0;
            }
        } else {
            dry_count = 0;
        }
        usleep(POLL_INTERVAL_US);
    }
    syslog(LOG_ERR, "Rain-activated window not verified dry after %d polls.",
           SENSOR_POLLS);
    return -1;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* --- motor pins --- */
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* --- sensor pin --- */
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* --- motor pins --- */
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain-activated window controller started.");

    /* --- main loop --- */
    while (g_running) {
        int rain_detected = 0;

        /* Read sensor */
        int v = gpio_read(RAIN_SENSOR_PIN);
        if (v < 0) {
            syslog(LOG_ERR, "gpio_read(rain) failed");
            break;
        }

        if (v == 0) {
            rain_detected = 1;
        }

        /* Poll motor-close sequence */
        if (rain_detected) {
            if (trigger_close_sequence() < 0) {
                syslog(LOG_ERR, "Trigger failed; continuing.");
            }
        }

        /* Verify dry */
        if (verify_dry() < 0) {
            syslog(LOG_ERR, "Verification failed; continuing.");
        }

        /* Sleep 200 ms */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- graceful shutdown --- */
    syslog(LOG_INFO, "Shutting down...");
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

