        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_PIN_1, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO %d\n", BUTTON_PIN_1);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_PIN_2, PI_PUD_UP) != 0) {
