            // Button 1 pressed, button 2 released
            if (unlock_servo() != 0) {
                fprintf(stderr, "Error: failed to unlock servo\n");
                break;
            }
            printf("Unlocked\n");
        } else if (button_state1 == 0 && button_state2 == 1) {
