#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTION_SENSOR_PIN 4
#define LED_PIN 17
#define LED_ON_DURATION_SEC 60
#define POLL_INTERVAL_US 100000
#define LOG_FILE "security_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event_type) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s - %s\n", ts, event_type);
    } else {
        fprintf(fp, "ERROR - %s\n", event_type);
    }
    fclose(fp);
    return 0;
}

static int activate_floodlight(void) {
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set LED pin high\n");
        return -1;
    }
    printf("Floodlight activated for %d seconds\n", LED_ON_DURATION_SEC);
    return 0;
