#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define LOG_FILE "security.log"
#define PIR_THRESHOLD 0
#define PIR_ACTIVATION_THRESHOLD 1
#define PWM_FREQ 50
#define PWM_DUTY_WIDTH_MIN 0
#define PWM_DUTY_WIDTH_MAX 180
#define SERVO_PULSE_WIDTH_MIN 0
#define SERVO_PULSE_WIDTH_MAX 180

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_message("Failed to open gpiochip4");
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        log_message("Failed to get GPIO17 line");
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        log_message("Failed to get GPIO4 line");
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message("Failed to request GPIO17 as output");
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message("Failed to request GPIO4 as input");
        return -1;
    }
    return 0;
}

int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message("Invalid servo angle");
        return -1;
    }
    int duty_width = (angle * PWM_DUTY_WIDTH_MAX) / 180;
    if (gpiod_line_set_value(servo_line, duty_width) < 0) {
        log_message("Failed to set servo value");
        return -1;
    }
    return 0;
}

int read_pir(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        log_message("Failed to read PIR sensor");
        return -1;
    }
    return val;
}

int control_servo(int angle) {
    if (set_servo_angle(angle) < 0) return -1;
    if (read_pir() == PIR_ACTIVATION_THRESHOLD) {
        log_message("PIR sensor activated");
        return 1;
    }
    return 0;
}

int log_message(const char *message) {
    if (!log_file) return -1;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
    return 0;
}

int main(void) {
    openlog("servo_monitor", LOG_PID | LOG_NDELAY, LOG_USER);
    log_message("Servo monitor started");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() < 0) {
        log_message("GPIO initialization failed");
        closelog();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Failed to create socket");
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_message("Failed to bind socket");
        close(server_fd);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_message("Failed to listen on socket");
        close(server_fd);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    log_message("Servo monitor listening on port 5000");

    while (running) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            log_message("Accept failed");
            break;
        }

        char buffer[1024];
        ssize_t bytes_read = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_read < 0) {
            if (errno == EINTR) continue;
            log_message("Recv failed");
            close(client_fd);
            continue;
        }
        if (bytes_read == 0) {
            log_message("Client disconnected");
            close(client_fd);
            continue;
        }
        buffer[bytes_read] = '\0';

        char *token = strtok(buffer, " \n\r");
        while (token != NULL) {
            if (strcmp(token, "SERVO") == 0) {
                int angle;
                if (sscanf(token, "SERVO %d", &angle) == 1) {
                    if (control_servo(angle) == 0) {
                        log_message("Servo angle set to " + std::to_string(angle));
                    } else {
                        log_message("Failed to set servo angle");
                    }
                } else {
                    log_message("Invalid servo angle");
                }
            }
            token = strtok(NULL, " \n\r");
        }
        close(client_fd);
    }

    log_message("Shutting down");
    if (server_fd >= 0) close(server_fd);
    if (servo_line) gpiod_line_release(servo_line);
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    closelog();
    return 0;
}

