#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 25

#define WEIGHT_THRESHOLD 1000
#define WEIGHT_AVG_COUNT 5
#define TARE_COUNT 10
#define POLL_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int hx711_read(struct gpiod_line *dout, struct gpiod_line *sck,
                      struct gpiod_line *solenoid,
                      int *raw_out) {
    int retries = 0;
    int dout_val = 0;
    int sck_val = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = gpiod_line_set_value(sck, 0);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to set SCK low: %s", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        usleep(10000);

        ret = gpiod_line_set_value(dout, 1);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to set DOUT high: %s", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        ret = gpiod_line_set_value(sck, 1);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to set SCK high: %s", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        usleep(10000);

        ret = gpiod_line_set_value(dout, 0);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to set DOUT low: %s", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        ret = gpiod_line_get_value(sck);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read SCK: %s", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (ret == 0) {
            dout_val = gpiod_line_get_value(dout);
            if (dout_val < 0) {
                syslog(LOG_ERR, "Failed to read DOUT: %s", strerror(errno));
                retries++;
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            *raw_out = dout_val;
            return 0;
        }

        usleep(RETRY_DELAY_MS * 1000);
    }

    syslog(LOG_ERR, "HX711 read failed after %d retries", MAX_RETRIES);
    return -1;
}

static int hx711_tare(struct gpiod_line *dout, struct gpiod_line *sck,
                      struct gpiod_line *solenoid,
                      int *raw_out) {
    int retries = 0;
    int tare_val = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = gpiod_line_set_value(sck, 0);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to set SCK low: %s", strerror(errno));
            retries++;
