}

static int hx711_read_weight(struct gpiod_line *dout, struct gpiod_line *sck,
                            struct gpiod_line *solenoid,
                            int *raw_out) {
    int retries = 0;
    int weight = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = hx711_read(dout, sck, solenoid, raw_out);
        if (ret < 0) {
            syslog(LOG_ERR, "HX711 read failed after %d retries", MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        usleep(POLL_INTERVAL_MS * 1000);

        ret = hx711_tare(dout, sck, solenoid, raw_out);
        if (ret < 0) {
            syslog(LOG_ERR, "HX711 tare failed after %d retries", MAX_RETRIES);
            retries++;
            continue;
        }

        ret = hx711_read(dout, sck, solenoid, raw_out);
        if (ret < 0) {
            syslog(LOG_ERR, "HX711 read failed after %d retries", MAX_RETRIES);
            retries++;
            continue;
        }

        weight = (int)((double)(*raw_out) - (double)WEIGHT_AVG_COUNT * WEIGHT_AVG_COUNT / 2.0);
        return 0;
    }

    syslog(LOG_ERR, "HX711 read failed after %d retries", MAX_RETRIES);
    return -1;
}

int main(int argc, char *argv[]) {
    int threshold = WEIGHT_THRESHOLD;
    int scale = 1;
    int duration = POLL_INTERVAL_MS;

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold < 0 || threshold > 1000) {
            fprintf(stderr, "Threshold must be between 0 and 1000 grams.\n");
            return EXIT_FAILURE;
        }
    }

    if (argc > 2) {
        scale = atoi(argv[2]);
        if (scale <= 0) {
            fprintf(stderr, "Scale must be a positive integer.\n");
            return EXIT_FAILURE;
        }
    }

    if (argc > 3) {
        duration = atoi(argv[3]);
        if (duration <= 0) {
            fprintf(stderr, "Duration must be a positive integer.\n");
            return EXIT_FAILURE;
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting weight monitor (threshold=%d, scale=%d, duration=%d ms)",
           threshold, scale, duration);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    struct gpiod_line *solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(solenoid, "hx711_solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_line_release(solenoid);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring weight every %d ms", duration);

    while (program_running) {
        int weight = 0;
        int ret = hx711_read_weight(dout, sck, solenoid, &weight);

        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read weight after %d retries", MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (weight >= threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold: %d g", weight);
            if (gpiod_line_set_value(solenoid, 1) < 0) {
                syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
            }
            usleep(duration * 1000);
            if (gpiod_line_set_value(solenoid, 0) < 0) {
                syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    gpiod_line_set_value(solenoid, 0);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(solenoid);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

