    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    struct gpiod_line *solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(solenoid, "hx711_solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_line_release(solenoid);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring weight every %d ms", duration);

    while (program_running) {
        int weight = 0;
        int ret = hx711_read_weight(dout, sck, solenoid, &weight);

        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read weight after %d retries", MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (weight >= threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold: %d g", weight);
            if (gpiod_line_set_value(solenoid, 1) < 0) {
                syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
            }
            usleep(duration * 1000);
            if (gpiod_line_set_value(solenoid, 0) < 0) {
                syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    gpiod_line_set_value(solenoid, 0);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(solenoid);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

