            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioPWM(SERVO_2_PIN, SERVO_PULSE_US_MIN) != 0) {
            fprintf(stderr, "Error: failed to start PWM on GPIO %d\n", SERVO_2_PIN);
