#define STALL_THRESHOLD_SEC 2.0
#define TICKS_PER_REV 64
#define COUNT_PER_RISE 1
#define STALL_COUNT_THRESHOLD (TICKS_PER_REV * COUNT_PER_RISE)

static volatile int motor_a_count = 0;
static volatile int motor_b_count = 0;
static volatile int encoder_a_count = 0;
static volatile int encoder_b_count = 0;
static volatile int motor_a_pwm_high = 0;
