static volatile int motor_a_pwm_ticks_count_low_low = 0;
static volatile int motor_b_pwm_ticks_count_low_low = 0;

static void motor_a_pwm_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    if (level == 1) {
        motor_a_pwm_ticks++;
        if (motor_a_pwm_ticks >= motor_a_pwm_period) {
            motor_a_pwm_ticks = 0;
            motor_a_pwm_ticks_count++;
            if (motor_a_pwm_ticks_count > motor_a_pwm_ticks_count_high) {
                motor_a_pwm_ticks_count_high = motor_a_pwm_ticks_count;
                motor_a_pwm_ticks_count_low = 0;
            }
            if (motor_a_pwm_ticks_count_high > 0) {
                motor_a_pwm_ticks_count_high--;
                motor_a_pwm_ticks_count_low = motor_a_pwm_ticks_count_high;
                motor_a_pwm_ticks_count_high = 0;
            }
        }
    } else if (level == 0) {
        motor_a_pwm_ticks_count--;
        if (motor_a_pwm_ticks_count < 0) {
            motor_a_pwm_ticks_count = 0;
            motor_a_pwm_ticks_count_count = 0;
        }
    }
}

