#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_HIGH 200.0
#define POLL_INTERVAL_SEC 5
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_lux(int handle, float *lux_out) {
    char cmd[2] = {0x21, 0x00};
    char buf[2];
    int ret;

    ret = i2cWriteDevice(handle, cmd, 2);
    if (ret != 0) {
        fprintf(stderr, "Error writing One-Time High-Resolution Mode 2 command: %d\n", ret);
        return -1;
    }

    gpioDelay(180000); // 180 ms for high-res mode

    ret = i2cReadDevice(handle, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading 2 bytes of lux data: %d\n", ret);
        return -1;
    }

    int raw_lux = ((buf[0] << 8) | buf[1]) >> 8;
    *lux_out = (float)raw_lux / 1.2f;
    return 0;
}

static int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];

    if (tstruct == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    if (fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", buf, lux, relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

int main(void) {
    float lux = 0.0f;
    int relay_state = 0;
    int ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart chicken coop control started. Press Ctrl+C to exit.\n");

    while (running) {
        ret = read_lux(i2c_handle, &lux);
        if (ret != 0) {
            fprintf(stderr, "Error reading lux sensor. Relay off.\n");
            control_relay(RELAY_GPIO, 0);
            gpioDelay(POLL_INTERVAL_SEC * 1000000);
            continue;
        }

        if (lux < LUX_THRESHOLD_LOW) {
            printf("Lux below %.2f. Activating relay.\n", LUX_THRESHOLD_LOW);
            control_relay(RELAY_GPIO, 1);
            gpioDelay(POLL_INTERVAL_SEC * 1000000);
        } else if (lux > LUX_THRESHOLD_HIGH) {
            printf("Lux above %.2f. Deactivating relay.\n", LUX_THRESHOLD_HIGH);
            control_relay(RELAY_GPIO, 0);
            gpioDelay(POLL_INTERVAL_SEC * 1000000);
        }

        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    // Cleanup
    printf("\nShutting down...\n");
    control_relay(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

