            control_relay(RELAY_GPIO, 0);
            gpioDelay(POLL_INTERVAL_SEC * 1000000);
        }

        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    // Cleanup
    printf("\nShutting down...\n");
    control_relay(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

