#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define LPM_THRESHOLD 5.0
#define LPM_HYSTERESIS 0.5
#define LOG_FILE "water_flow.log"
#define SAMPLE_INTERVAL_US 1000000

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[64];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void flow_sensor_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_lpm(int pulses) {
    if (pulses <= 0) return 0.0;
    return (double)pulses / 450.0 * 60.0;
}

static void solenoid_control(int state) {
    if (gpioWrite(SOLENOID_PIN, state) != 0) {
        log_event("Error: Failed to write solenoid pin state.");
    }
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", SOLENOID_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to initialize solenoid to open.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioWrite(SOLENOID_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR for GPIO %d.\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = calculate_lpm(pulses);
        char message[128];
        snprintf(message, sizeof(message), "LPM: %.2f", lpm);
        log_event(message);

        if (lpm > LPM_THRESHOLD) {
            solenoid_control(1);
        } else if (lpm < LPM_HYSTERESIS) {
            solenoid_control(0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

