code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000  /* 50 ms */
#define DEBOUNCE_DELAY_US 50000 /* 50 ms */
#define DEBOUNCE_COUNT 3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int debounce_touch(int pin, int debounce_us) {
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", pin);
        return -1;
    }
    if (level == 0) {
        /* TTP223 idles LOW; rising edge to HIGH indicates touch */
        if (gpioWrite(pin, 1) != 0) {
            fprintf(stderr, "gpioWrite HIGH failed on pin %d\n", pin);
            return -1;
        }
        return 1;
    }
    /* TTP223 idles HIGH; falling edge to LOW indicates release */
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "gpioWrite LOW failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int toggle_relay(int pin) {
    int relay_state = gpioRead(pin);
    if (relay_state < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", pin);
        return -1;
    }
    if (relay_state == 0) {
        if (gpioWrite(pin, 1) != 0) {
            fprintf(stderr, "gpioWrite HIGH failed on pin %d\n", pin);
            return -1;
        }
        printf("Relay: ON\n");
    } else {
        if (gpioWrite(pin, 0) != 0) {
            fprintf(stderr, "gpioWrite LOW failed on pin %d\n", pin);
            return -1;
        }
        printf("Relay: OFF\n");
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int debounce_us = DEBOUNCE_DELAY_US;
    if (argc > 1) {
        if (sscanf(argv[1], "%d", &debounce_us) != 1) {
            fprintf(stderr, "Invalid debounce delay: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite initial relay state failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-controlled desk lamp control started. Touch sensor on GPIO %d, relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_touch_state = 0;
    int debounce_count = 0;

    while (g_running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "gpioRead failed on touch sensor pin %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_state == 0) {
            if (debounce_touch(TOUCH_SENSOR_PIN, debounce_us) == 0) {
                if (debounce_count < DEBOUNCE_COUNT) {
                    debounce_count++;
                    if (debounce_count > DEBOUNCE_COUNT) {
                        debounce_count = DEBOUNCE_COUNT;
                    }
                    if (gpioWrite(RELAY_PIN, 1) != 0) {
                        fprintf(stderr, "gpioWrite HIGH failed on relay pin %d\n", RELAY_PIN);
                        break;
                    }
                    printf("Touch detected. Toggling relay ON.\n");
                    last_touch_state = 1;
                }
            }
        } else {
            if (last_touch_state == 1) {
                if (debounce_touch(TOUCH_SENSOR_PIN, debounce_us) == 0) {
                    if (gpioWrite(RELAY_PIN, 0) != 0) {
                        fprintf(stderr, "gpioWrite LOW failed on relay pin %d\n", RELAY_PIN);
                        break;
                    }
                    printf("Touch released. Toggling relay OFF.\n");
                    last_touch_state = 0;
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

