#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define PWM_PERIOD_US 20000
#define PULSE_WIDTH_STEP 50

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    int pulse_width = (int)((float)MIN_ANGLE + (float)angle / 180.0f * (float)(MAX_ANGLE - MIN_ANGLE));
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1;
    }

    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

int main(void) {
    struct termios tty;
    int rc;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open terminal device */
    if (tcgetattr(STDIN_FILENO, &tty) != 0) {
        perror("tcgetattr");
        return EXIT_FAILURE;
    }

    /* Save terminal settings */
    if (tcgetattr(STDIN_FILENO, &tty) != 0) {
        perror("tcgetattr");
        return EXIT_FAILURE;
    }

    /* Set 8-bit parity, 1 stop bit, no flow control */
    if (cfsetispeed(&tty, B9600) != 0 || cfsetospeed(&tty, B9600) != 0) {
        perror("cfsetispeed");
        return EXIT_FAILURE;
    }

    /* Set software flow control (CTS/RTS) */
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return EXIT_FAILURE;
    }

    /* Set hardware PWM on GPIO18 */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SERVO_PIN);
        return EXIT_FAILURE;
    }

    /* Start with PWM off */
    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return EXIT_FAILURE;
    }

    printf("Servo control started. Press '+' to increase, '-' to decrease, 'q' to quit.\n");
    printf("Servo pin: GPIO%d, PWM period: %d us, pulse width: %d-500 us\n",
           SERVO_PIN, PWM_PERIOD_US, MIN_PULSE_WIDTH);

    while (running) {
        char c;
        int k;

        if (getchar() == '\n') {
            continue;
        }

        if (c == '+') {
            if (set_servo_angle(MIN_ANGLE + PULSE_WIDTH_STEP) != 0) {
                fprintf(stderr, "Error: failed to set angle\n");
                break;
            }
            printf("Angle: %d°\n", MIN_ANGLE + PULSE_WIDTH_STEP);
        } else if (c == '-') {
            if (set_servo_angle(MIN_ANGLE - PULSE_WIDTH_STEP) != 0) {
                fprintf(stderr, "Error: failed to set angle\n");
                break;
            }
            printf("Angle: %d°\n", MIN_ANGLE - PULSE_WIDTH_STEP);
        } else if (c == 'q' || c == 'Q') {
            running = 0;
            printf("Exiting.\n");
            break;
        } else {
            fprintf(stderr, "Error: invalid input '%c'\n", c);
            break;
        }

        usleep(10000); /* 10 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    tcsetattr(STDIN_FILENO, TCSANOW, &tty);
    return EXIT_SUCCESS;
}

