#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define TOUCH_HIGH_TIMEOUT_SEC 10.0
#define POLL_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int safe_write(int gpio, int value)
{
    if (gpioWrite(gpio, value) < 0) {
        fprintf(stderr, "gpioWrite failed on GPIO %d: %s\n",
                gpio, pigpio_error(gpioWrite(gpio, value)));
        return -1;
    }
    return 0;
}

static int safe_read(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n",
                gpio, pigpio_error(v));
        return -1;
    }
    return v;
}

static int safe_set_mode(int gpio, int mode)
{
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "gpioSetMode failed on GPIO %d: %s\n",
                gpio, pigpio_error(gpioSetMode(gpio, mode)));
        return -1;
    }
    return 0;
}

static int safe_write_relay(int gpio, int state)
{
    if (safe_write(gpio, state) < 0)
        return -1;
    if (state)
        safe_write(RELAY_PIN, 1);
    else
        safe_write(RELAY_PIN, 0);
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (safe_set_mode(RELAY_PIN, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* TTP223: 3.3V logic HIGH when touched, LOW otherwise. */
    if (safe_write_relay(TOUCH_SENSOR_PIN, 1) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", pigpio_error(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_touch_state = safe_read(TOUCH_SENSOR_PIN);
    if (last_touch_state < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_touch_state = safe_read(TOUCH_SENSOR_PIN);
        if (current_touch_state < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            if (safe_write_relay(RELAY_PIN, 1) < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
            last_touch_state = 1;
            printf("Touch detected. Relay toggled ON.\n");
        } else if (current_touch_state == 0 && last_touch_state == 1) {
            if (safe_write_relay(RELAY_PIN, 0) < 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
            last_touch_state = 0;
            printf("Touch released. Relay toggled OFF.\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    safe_write_relay(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

