#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 24
#define PWM_PIN 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 100000
#define Kp 1.0
#define TARGET_FLOW_RATE 5.0

static volatile int running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM pin to LOW.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level != RISING_EDGE) return;

    int pulses = gpioRead(FLOW_SENSOR_PIN);
    if (pulses < 0) return;

    uint32_t elapsed = tick - gpioTick();
    if (elapsed > 0) {
        uint32_t dt_us = (uint32_t)(elapsed * 1000);
        float flow_rate = (float)pulses / (float)dt_us * 450.0f;
        if (flow_rate < 0.0f) flow_rate = 0.0f;
        if (flow_rate > TARGET_FLOW_RATE) flow_rate = TARGET_FLOW_RATE;
        float target_duty = (flow_rate - TARGET_FLOW_RATE) * Kp;
        if (target_duty < 0.0f) target_duty = 0.0f;
        if (target_duty > 255.0f) target_duty = 255.0f;
        if (gpioPWM(PWM_PIN, (int)target_duty) != 0) {
            fprintf(stderr, "Warning: failed to set PWM duty cycle.\n");
        }
    }
}

static void log_data(float flow_rate, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2d\n", timestamp, flow_rate, valve_position);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: log file is not open.\n");
    }
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(PWM_PIN, 0);
    gpioWrite(PWM_PIN, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <target_flow_rate_lpm>\n", argv[0]);
        return 1;
    }

    float target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0.0f) {
        fprintf(stderr, "Error: invalid target flow rate.\n");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow control system. Target: %.2f LPM. Press Ctrl+C to exit.\n", target_flow_rate);

    while (running) {
        int pulses = gpioRead(FLOW_SENSOR_PIN);
        if (pulses < 0) {
            fprintf(stderr, "Error: failed to read flow sensor.\n");
            break;
        }

        uint32_t elapsed = gpioTick() - tick_start;
        if (elapsed > 0) {
            float flow_rate = (float)pulses / (float)elapsed * 450.0f;
            if (flow_rate < 0.0f) flow_rate = 0.0f;
            if (flow_rate > TARGET_FLOW_RATE) flow_rate = TARGET_FLOW_RATE;
            float target_duty = (flow_rate - TARGET_FLOW_RATE) * Kp;
            if (target_duty < 0.0f) target_duty = 0.0f;
            if (target_duty > 255.0f) target_duty = 255.0f;
            if (gpioPWM(PWM_PIN, (int)target_duty) != 0) {
                fprintf(stderr, "Warning: failed to set PWM duty cycle.\n");
            }
        }

        log_data(flow_rate, (int)valve_position);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

