#define LOG_FILE "/var/log/door_access.log"
#define GPIO_LOCK1 17
#define GPIO_LOCK2 27
#define BUTTON_GPIO 22
#define DEBOUNCE_DELAY_MS 50
#define LOCK_DURATION_MS 5000
#define SPI_READ_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    if (!log_file) return -1;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file);
        return 0;
    }
    return -1;
}

static int read_rfid_tag(int spi_handle) {
    char buffer[10];
    int bytes_read = spiXfer(spi_handle, buffer, buffer, 10);
    if (bytes_read != 10) {
        fprintf(stderr, "SPI read failed: expected 10 bytes, got %d\n", bytes_read);
        return -1;
    }
    if (memcmp(buffer, "\x01\x02\x03\x04\x05\x06\x07\x08\x09", 10) != 0) {
        fprintf(stderr, "Invalid tag: expected 0x01, got 0x%02X\n", buffer[10]);
        return -1;
    }
    return 0;
}

static int check_button_press(int gpio_pin) {
    int level = gpioRead(gpio_pin);
    if (level < 0) return -1;
    if (level != 0) return -1;
    return 0;
}

static int control_locks(int lock1, int lock2) {
    if (gpioWrite(lock1, 0) < 0) return -1;
    if (gpioWrite(lock2, 0) < 0) return -1;
    gpioDelay(LOCK_DURATION_MS * 1000);
    if (gpioWrite(lock1, 1) < 0) return -1;
    if (gpioWrite(lock2, 1) < 0) return -1;
    return 0;
}

