#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"
#define POLL_INTERVAL_US 50000  // 50 ms
#define MAX_CONSECUTIVE_ERRORS 10

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x2E
#define MPR121_SOFT_RESET 0x80

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_mpr121_touch_status(int i2c_handle);
void control_relay(int gpio_pin, int state);
void log_relay_state(int gpio_pin, int state);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

// Initialize MPR121 sensor
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset byte.\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay for reset

    // Configure electrode configuration: 12 electrodes, touch and release thresholds
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to write electrode config.\n");
        return -1;
    }

    // Enable touch and release detection for all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to enable touch and release.\n");
        return -1;
    }

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHSTATUS_L + (i * 2), 0x00) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHSTATUS_H + (i * 2), 0x00) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    return 0;
}

// Read MPR121 touch status
int read_mpr121_touch_status(int i2c_handle) {
    char buf[2];

    // Read touch status register 0x00
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }

    // Combine low and high bytes
    int touch_status = (buf[1] << 8) | buf[0];

    // Clear any pending interrupts
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to clear interrupts.\n");
        return -1;
    }

    return touch_status;
}

// Control relay based on MPR121 touch status
void control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d.\n", gpio_pin);
    }
}

// Log relay state to file
void log_relay_state(int gpio_pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - GPIO %d: %s\n", timestamp, gpio_pin, state ? "ACTIVATED" : "DEACTIVATED");
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, MPR121_ADDR);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPR121 initialization failed.\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("MPR121 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_status = read_mpr121_touch_status(i2c_handle);

        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read MPR121 touch status.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        // Check for any touched electrodes
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                control_relay(RELAY_GPIO, 1);
                log_relay_state(RELAY_GPIO, 1);
            } else {
                control_relay(RELAY_GPIO, 0);
                log_relay_state(RELAY_GPIO, 0);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

