#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define RELAY_ON_TIME_MS 500
#define PAUSE_DURATION_S 5
#define PAUSE_DURATION_S 10
#define WATER_DISTRIBUTION_INTERVAL_S 5
#define WATER_DISTRIBUTION_LOG_FILE "valve_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event_type) {
    FILE *fp = fopen(WATER_DISTRIBUTION_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s - %s\n", timestamp, event_type);
    fclose(fp);
}

static void activate_valve(struct gpiod_line *valve_line, int duration_ms) {
    if (gpiod_line_set_value(valve_line, 1) < 0) {
        fprintf(stderr, "Error setting valve HIGH: %s\n", strerror(errno));
        return;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(valve_line, 0) < 0) {
        fprintf(stderr, "Error setting valve LOW: %s\n", strerror(errno));
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *valve1_line = NULL;
    struct gpiod_line *valve2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", VALVE1_GPIO, strerror(errno));
        goto cleanup;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", VALVE2_GPIO, strerror(errno));
        goto cleanup;
