#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

#define MPR121_TOUCH_STATUS_REG 0x00
#define MPR121_ELECTRODE_STATUS_REG 0x01
#define MPR121_ELECTRODE_DATA_REG 0x02
#define MPR121_FILTER_CHARGE_REG 0x20
#define MPR121_FILTER_CHARGE_TIME_REG 0x21
#define MPR121_ELECTRODE_CURRENT_REG 0x01
#define MPR121_ELECTRODE_CURRENT_THRESHOLD_REG 0x0A
#define MPR121_TOUCH_THRESHOLD_REG 0x10
#define MPR121_SOFT_RESET_REG 0x27
#define MPR121_SOFT_RESET_VAL 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {reg, value};
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to MPR121 register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int mpr121_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error setting MPR121 register pointer 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading MPR121 register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int mpr121_init(int handle) {
    if (mpr121_write_reg(handle, MPR121_SOFT_RESET_REG, MPR121_SOFT_RESET_VAL) != 0) return -1;
    gpioDelay(10000);
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CURRENT_THRESHOLD_REG, 0x0A) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CURRENT_REG, 0x00) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FILTER_CHARGE_REG, 0x00) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FILTER_CHARGE_TIME_REG, 0x00) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_FILTER_REG, 0x00) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CURRENT_THRESHOLD_REG, 0x0A) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_THRESHOLD_REG, 0x0A) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_FILTER_REG, 0x00) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CURRENT_REG, 0x00) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_FILTER_REG, 0x00) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_ELECTRODE_THRESHOLD_REG, 0x0A) != 0) return -1;
    if (mpr121_write_reg(handle, MPR121_SOFT_RESET_REG, MPR121_SOFT_RESET_VAL) != 0) return -1;
    return 0;
}

int mpr121_read_touch_status(int handle) {
    uint8_t status[12];
    if (mpr121_read_reg(handle, MPR121_ELECTRODE_STATUS_REG, status) != 0) return -1;
    return status[0];
}

int mpr121_read_electrode_data(int handle, int electrode_num) {
    uint8_t data;
    if (mpr121_read_reg(handle, MPR121_ELECTRODE_DATA_REG, &data) != 0) return -1;
    return data;
}

int mpr121_toggle_relay(int handle) {
    int relay_state = gpioRead(RELAY_PIN);
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error writing to relay pin\n");
        return -1;
    }
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X\n", I2C_BUS, MPR121_ADDR);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting relay pin mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 touch sensor running. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status\n");
            gpioDelay(100000);
            continue;
        }

        for (int i = 0; i < 12; i++) {
            int electrode_num = i;
            int touch_status = mpr121_read_electrode_data(i2c_handle, electrode_num);
            if (touch_status < 0) {
                fprintf(stderr, "Error reading electrode %d\n", electrode_num);
                gpioDelay(100000);
                continue;
            }

            if (touch_status > 0) {
                if (mpr121_toggle_relay(i2c_handle) != 0) {
                    fprintf(stderr, "Error toggling relay for electrode %d\n", electrode_num);
                }
                printf("Touch detected on electrode %d (status: %d)\n", electrode_num, touch_status);
            }
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

