#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define UNLOCK_DURATION_MS 500
#define LOG_FILE "door_events.log"
#define POLL_INTERVAL_MS 50
#define RATE_LIMIT_MS 2000
#define MAX_CONSECUTIVE_UNLOCKS 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    if (!log_file) return -1;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
    return 0;
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to set relay HIGH\n");
        return;
    }
    log_event("Door unlocked");
    printf("Door unlocked\n");
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set relay LOW\n");
    }
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error registering SIGINT handler");
        cleanup();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Error reading PIR sensor\n");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_value == 1) {
            if (log_event("Motion detected") != 0) {
                fprintf(stderr, "Error logging motion event\n");
            }

            if (gpioWrite(RELAY_PIN, 1) < 0) {
                fprintf(stderr, "Error: Failed to activate relay\n");
            } else {
                unlock_door();
            }

            if (log_event("Door unlocked") != 0) {
                fprintf(stderr, "Error logging unlock event\n");
            }

            if (log_event("Rate limit exceeded") != 0) {
                fprintf(stderr, "Error logging rate limit event\n");
            }

            gpioDelay(RATE_LIMIT_MS * 1000);
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

