#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_LOCK_PIN 27
#define THRESHOLD 10.0
#define LOG_FILE "weight_log.txt"
#define CALIBRATION_FILE "calibration.txt"
#define READ_INTERVAL_US 500000
#define HX711_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;
static FILE *calibration_file = NULL;
static FILE *log_file = NULL;

typedef struct {
    float scale_factor;
    float offset;
} CalibrationData;

static CalibrationData calibration_data = {1.0, 0.0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (!calibration_file) {
        fprintf(stderr, "Error opening calibration file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), calibration_file)) {
        fprintf(stderr, "Error reading calibration file: %s\n", strerror(errno));
        fclose(calibration_file);
        calibration_file = NULL;
        return -1;
    }

    calibration_data.scale_factor = atof(line);
    calibration_data.offset = atof(line);
    if (calibration_data.scale_factor <= 0.0 || calibration_data.offset <= 0.0) {
        fprintf(stderr, "Invalid calibration data: scale=%f, offset=%f\n", calibration_data.scale_factor, calibration_data.offset);
        fclose(calibration_file);
        calibration_file = NULL;
        return -1;
    }

    fclose(calibration_file);
    calibration_file = NULL;
    return 0;
}

static int load_calibration(void) {
    if (read_calibration() != 0) {
        fprintf(stderr, "Failed to read calibration data. Using defaults.\n");
        calibration_data.scale_factor = 1.0;
        calibration_data.offset = 0.0;
    } else {
        printf("Calibration data loaded: scale=%.2f, offset=%.2f\n", calibration_data.scale_factor, calibration_data.offset);
    }
    return 0;
}

static int hx711_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set HX711 data pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set HX711 clock pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(HX711_CLOCK_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize HX711 clock pin low\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(HX711_CLOCK_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on HX711 clock pin\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(HX711_DATA_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on HX711 data pin\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(HX711_CLOCK_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize HX711 clock pin low\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int hx711_read(float *raw_value) {
    uint32_t start_tick = gpioTick();
    uint32_t timeout = 0;

    while (gpioTick() - start_tick < HX711_TIMEOUT_US) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set HX711 clock high\n");
            return -1;
        }
        gpioDelay(1);
        if (gpioWrite(HX711_CLOCK_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set HX711 clock low\n");
            return -1;
        }
        timeout++;
        if (timeout >= HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout\n");
            return -1;
        }
    }

    uint32_t tick = gpioTick();
    uint32_t duration = tick - start_tick;
    uint32_t raw_duration = duration;

    if (duration >= HX711_TIMEOUT_US) {
        fprintf(stderr, "HX711 timeout\n");
        return -1;
    }

    uint32_t high_tick = tick;
    uint32_t low_tick = tick;

    uint32_t high_tick_diff = high_tick - low_tick;
    uint32_t low_tick_diff = tick - high_tick;

    if (high_tick_diff > HX711_TIMEOUT_US) {
        fprintf(stderr, "High tick out of range\n");
        return -1;
    }

    if (low_tick_diff > HX711_TIMEOUT_US) {
        fprintf(stderr, "Low tick out of range\n");
        return -1;
    }

    uint32_t high_tick_diff_ms = high_tick_diff / 1000;
    uint32_t low_tick_diff_ms = low_tick_diff / 1000;

    if (high_tick_diff_ms > HX711_TIMEOUT_US) {
        fprintf(stderr, "High tick out of range\n");
        return -1;
    }

    if (low_tick_diff_ms > HX711_TIMEOUT_US) {
        fprintf(stderr, "Low tick out of range\n");
        return -1;
    }

    uint32_t high_tick_diff_us = high_tick_diff_ms * 1000;
    uint32_t low_tick_diff_us = low_tick_diff_ms * 1000;

    uint32_t high_tick_us = high_tick - start_tick;
    uint32_t low_tick_us = low_tick - start_tick;

    if (high_tick_us > HX711_TIMEOUT_US) {
        fprintf(stderr, "High tick out of range\n");
        return -1;
    }

    if (low_tick_us > HX711_TIMEOUT_US) {
        fprintf(stderr, "Low tick out of range\n");
        return -1;
    }

    uint32_t high_tick_us_diff = high_tick_us - high_tick_diff;
    uint32_t low_tick_us_diff = low_tick_us - low_tick_diff;

    if (high_tick_us_diff > HX711_TIMEOUT_US) {
        fprintf(stderr, "High tick out of range\n");
        return -1;
    }

    if (low_tick_us_diff > HX711_TIMEOUT_US) {
        fprintf(stderr, "Low tick out of range\n");
        return -1;
    }

    uint32_t high_tick_us_diff_ms = high_tick_us_diff / 1000;
    uint32_t low_tick_us_diff_ms = low_tick_us_diff / 1000;

    uint32_t high_tick_ms = high_tick_us / 1000;
    uint32_t low_tick_ms = low_tick_us / 1000;

    *raw_value = (float)high_tick_ms * calibration_data.scale_factor +
                 (float)low_tick_ms * calibration_data.offset;
    return 0;
}

static void log_reading(float weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, weight);
    fflush(log_file);
}

static void control_solenoid(float weight) {
    if (weight > THRESHOLD) {
        gpioWrite(SOLENOID_LOCK_PIN, 1);
        printf("Weight threshold exceeded. Lock engaged.\n");
    } else {
        gpioWrite(SOLENOID_LOCK_PIN, 0);
        printf("Weight below threshold. Lock released.\n");
    }
}

int main(void) {
    float weight;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (load_calibration() != 0) {
        fprintf(stderr, "Failed to load calibration data. Using defaults.\n");
        calibration_data.scale_factor = 1.0;
        calibration_data.offset = 0.0;
    }

    if (gpioSetPullUpDown(HX711_CLOCK_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on HX711 clock pin\n");
        return 1;
    }

    if (gpioSetPullUpDown(HX711_DATA_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on HX711 data pin\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_LOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode for solenoid lock\n");
        return 1;
    }

    if (gpioWrite(SOLENOID_LOCK_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize solenoid lock\n");
        return 1;
    }

    if (gpioSetPullUpDown(HX711_DATA_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on HX711 data pin\n");
        return 1;
    }

    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode for HX711 clock pin\n");
        return 1;
    }

    if (gpioWrite(HX711_CLOCK_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize HX711 clock pin low\n");
        return 1;
    }

    printf("HX711 initialized. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        ret = hx711_read(&weight);
        if (ret != 0) {
            fprintf(stderr, "Error reading HX711 sensor\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        log_reading(weight);
        control_solenoid(weight);

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_LOCK_PIN, 0);
    gpioTerminate();
    if (calibration_file) {
        fclose(calibration_file);
    }
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}

