#define MOTOR_IN2 18
#define MOTOR_PWM 27
#define MOTOR_DURATION 5
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_INTERVAL_MS 50
#define LOG_FILE "/var/log/window_control.log"
#define MOTOR_DUTY_CYCLE 150

static volatile sig_atomic_t running = 1;
static int motor_running = 0;
static int motor_pwm_enabled = 0;
static int motor_pwm_frequency = 1000;
static int motor_pwm_duty_cycle = 0;
static int rain_detected = 0;
static int rain_count = 0;
static int last_rain_state = 1;
static int last_rain_reading = 0;
static int last_rain_reading_time = 0;
