                rain_state = 0;
                rain_reading = 0;
                rain_reading_time = 0;
                log_event("Rain detected, rain stopped");
            }
        }

        gpioDelay(DEBOUNCE_INTERVAL_MS * 1000);
    }

    log_event("Window control stopped");
    cleanup();
    return EXIT_SUCCESS;
}

