#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define STOCK_THRESHOLD 100
#define SOLENOID_DURATION 5
#define LOG_FILE "stock_events.txt"
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int dt_pin, int sck_pin, int *weight) {
    int timeout = 100;
    int count = 0;
    int val = 0;
    int ret;

    while (count < timeout) {
        val = gpioRead(sck_pin);
        if (val < 0) {
            fprintf(stderr, "Error reading SCK pin\n");
            return -1;
        }
        if (val == 1) {
            count++;
            if (count >= timeout) {
                fprintf(stderr, "Timeout waiting for HX711 data\n");
                return -1;
            }
        }
        gpioDelay(1);
    }

    if (count < timeout) {
        fprintf(stderr, "HX711 timeout: data not stable\n");
        return -1;
    }

    *weight = (val - 1) / 8;
    return 0;
}

static int control_solenoid(int pin, int duration_us) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error setting solenoid high\n");
        return -1;
    }
    gpioDelay(duration_us);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error setting solenoid low\n");
        return -1;
    }
    return 0;
}

static int log_event(int solenoid_pin) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Solenoid lock activated\n", timestamp);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DT_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioSetPullUpDown(HX711_DT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SOLENOID_PIN, PI_PUD_UP);

    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error initialising solenoid\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring stock level. Press Ctrl+C to exit.\n");

    while (running) {
        int weight = 0;
        int ret = read_hx711(HX711_DT_PIN, HX711_SCK_PIN, &weight);

        if (ret != 0) {
            fprintf(stderr, "Error reading HX711, ret=%d\n", ret);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (weight < STOCK_THRESHOLD) {
            if (control_solenoid(SOLENOID_PIN, SOLENOID_DURATION) < 0) {
                fprintf(stderr, "Error controlling solenoid\n");
            }
            if (log_event(SOLENOID_PIN) < 0) {
                fprintf(stderr, "Error logging event\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

