#define HX711_DATA_TIMEOUT_US 100

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

typedef struct {
    float calibration_factor;
    float calibration_offset;
} CalibrationData;

static CalibrationData calibration_data = {0.0, 0.0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, int *raw_value) {
    uint32_t start_tick, end_tick;
    uint32_t high_tick, low_tick;
    int timeout_count = 0;

    while (gpioRead(clock_pin) == 0) {
        gpioDelay(1);
        timeout_count++;
        if (timeout_count > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 clock timeout\n");
            return -1;
        }
    }

    start_tick = gpioTick();

    while (gpioRead(data_pin) == 1) {
        gpioDelay(1);
        timeout_count++;
        if (timeout_count > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 data timeout\n");
            return -1;
        }
    }

    end_tick = gpioTick();

    high_tick = end_tick - start_tick;
    low_tick = end_tick - end_tick;

    *raw_value = (int)((high_tick << 16) | (low_tick << 8) | high_tick);
    return 0;
}

static float calculate_calibration_factor(int raw_value) {
    return (float)raw_value / (float)calibration_data.calibration_offset;
}

