#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define WATERING_DURATION_FILE "watering.conf"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_duration(const char *filename, int *duration_out) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strncmp(line, "duration=", 7) != 0) {
        fprintf(stderr, "Error: invalid format in %s\n", filename);
        return -1;
    }

    char *endptr = NULL;
    long val = strtol(line + 7, &endptr, 10);
    if (endptr == line + 7 || *endptr != '\0') {
        fprintf(stderr, "Error: invalid duration value in %s\n", filename);
        return -1;
    }

    if (val < 1 || val > 3600) {
        fprintf(stderr, "Error: duration must be between 1 and 3600 seconds\n");
        return -1;
    }

    *duration_out = (int)val;
    return 0;
}

static int activate_valve(struct gpiod_line *line, int duration_sec) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: failed to set GPIO line high: %s\n", strerror(errno));
        return -1;
    }
    usleep(duration_sec * 1000000);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: failed to set GPIO line low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration = 0;
    int val = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error: failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Error: failed to request GPIO line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (read_duration(WATERING_DURATION_FILE, &duration) < 0) {
        goto cleanup;
    }

    printf("Watering system started. Valve on for %d seconds.\n", duration);
    fflush(stdout);

    while (g_running) {
        if (gpiod_line_set_value(line, val) < 0) {
            fprintf(stderr, "Error: failed to set GPIO line value: %s\n", strerror(errno));
            break;
        }
        val = !val;
        printf("Valve %s\n", val ? "ON" : "OFF");
        fflush(stdout);

        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error: failed to set GPIO line low: %s\n", strerror(errno));
            break;
        }
        usleep(1000000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

