#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define MOTOR1_PIN 22
#define MOTOR2_PIN 23
#define MOTOR3_PIN 24
#define MOTOR4_PIN 25

#define SPEED_BASE 150
#define SPEED_LEFT_HALF 75
#define SPEED_RIGHT_HALF 75
#define SPEED_STOP 0

#define LOG_FILE "trace_log.txt"
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_sensor_states(int sensor1, int sensor2, int sensor3, int left_speed, int right_speed) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,Sensor1=%d,Sensor2=%d,Sensor3=%d,Left=%d,Right=%d\n",
                timestamp, sensor1, sensor2, sensor3, left_speed, right_speed) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void stop_motors(void) {
    gpioWrite(MOTOR1_PIN, MOTOR1_PIN);
    gpioWrite(MOTOR2_PIN, MOTOR2_PIN);
    gpioWrite(MOTOR3_PIN, MOTOR3_PIN);
    gpioWrite(MOTOR4_PIN, MOTOR4_PIN);
}

static void stop_motors_and_log(void) {
    gpioWrite(MOTOR1_PIN, MOTOR1_PIN);
    gpioWrite(MOTOR2_PIN, MOTOR2_PIN);
    gpioWrite(MOTOR3_PIN, MOTOR3_PIN);
    gpioWrite(MOTOR4_PIN, MOTOR4_PIN);
    log_sensor_states(0, 0, 0, 0, 0);
}

static void set_motor_speed(int motor_pin, int speed) {
    gpioWrite(motor_pin, speed);
}

static void set_motor_direction(int motor_pin, int direction) {
    gpioSetMode(motor_pin, PI_OUTPUT);
    gpioWrite(motor_pin, 0);
}

static void set_motor_speed_range(int motor_pin, int speed, int min_speed, int max_speed) {
    if (speed < min_speed) speed = min_speed;
    if (speed > max_speed) speed = max_speed;
    set_motor_speed(motor_pin, speed);
}

static void control_line_following(int sensor1, int sensor2, int sensor3, int left_speed, int right_speed) {
    int middle_speed = (sensor1 + sensor2 + sensor3) / 3;
    int left_speed_out = left_speed;
    int right_speed_out = right_speed;

    if (sensor1 == 0 && sensor2 == 0 && sensor3 == 0) {
        left_speed_out = SPEED_STOP;
        right_speed_out = SPEED_STOP;
    } else if (sensor1 == 0 && sensor2 == 0 && sensor3 != 0) {
        left_speed_out = SPEED_STOP;
        right_speed_out = SPEED_STOP;
    } else if (sensor1 != 0 && sensor2 == 0 && sensor3 == 0) {
        left_speed_out = SPEED_STOP;
        right_speed_out = SPEED_STOP;
    } else if (sensor1 != 0 && sensor2 != 0 && sensor3 == 0) {
        left_speed_out = SPEED_STOP;
        right_speed_out = SPEED_STOP;
    } else {
        left_speed_out = SPEED_STOP;
        right_speed_out = SPEED_STOP;
    }

    set_motor_speed_range(MOTOR1_PIN, left_speed_out, 0, SPEED_BASE);
    set_motor_speed_range(MOTOR2_PIN, left_speed_out, 0, SPEED_BASE);
    set_motor_speed_range(MOTOR3_PIN, left_speed_out, 0, SPEED_BASE);
    set_motor_speed_range(MOTOR4_PIN, left_speed_out, 0, SPEED_BASE);

    set_motor_direction(MOTOR1_PIN, left_speed_out > 0 ? 1 : 0);
    set_motor_direction(MOTOR2_PIN, left_speed_out > 0 ? 1 : 0);
    set_motor_direction(MOTOR3_PIN, left_speed_out > 0 ? 1 : 0);
    set_motor_direction(MOTOR4_PIN, left_speed_out > 0 ? 1 : 0);

    set_motor_speed_range(MOTOR1_PIN, right_speed_out, 0, SPEED_BASE);
    set_motor_speed_range(MOTOR2_PIN, right_speed_out, 0, SPEED_BASE);
    set_motor_speed_range(MOTOR3_PIN, right_speed_out, 0, SPEED_BASE);
