        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        int relay_state;

        if (read_bh1750(i2c_handle, &lux) == 0) {
            relay_state = (lux < LUX_THRESHOLD) ? 1 : 0;
            if (control_relay(RELAY_GPIO, relay_state) != 0) {
                fprintf(stderr, "Warning: Failed to control relay GPIO %d.\n", RELAY_GPIO);
            }
            if (log_data(lux, relay_state) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read light sensor data.\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        gpioWrite(RELAY_GPIO, 0);
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

