#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_PIN      21
#define UNLOCK_PIN    22
#define SERVO_PIN     18
#define SERVO_PULSE_US 1000
#define DEBOUNCE_US   100000
#define DEBOUNCE_MS   100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(LOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LOCK_PIN %d as output.\n", LOCK_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(UNLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set UNLOCK_PIN %d as output.\n", UNLOCK_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output.\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(LOCK_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on LOCK_PIN.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(UNLOCK_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on UNLOCK_PIN.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(SERVO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on SERVO_PIN.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_servo_position(int pin, int pulse_us) {
    if (pulse_us < 500 || pulse_us > 2500) {
        fprintf(stderr, "Error: pulse width %d us out of safe range (500-2500 us).\n", pulse_us);
        return;
    }
    if (gpioServo(pin, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d.\n", pin);
    }
}

static void lock_servo(void) {
    set_servo_position(LOCK_PIN, SERVO_PULSE_US);
}

static void unlock_servo(void) {
    set_servo_position(UNLOCK_PIN, SERVO_PULSE_US);
}

static void cleanup(void) {
    unlock_servo();
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        int lock_pressed = gpioRead(LOCK_PIN);
        int unlock_pressed = gpioRead(UNLOCK_PIN);

        if (lock_pressed == 0) {
            lock_servo();
            printf("Locked\n");
        } else if (unlock_pressed == 0) {
            unlock_servo();
            printf("Unlocked\n");
        } else {
            printf("Warning: button press detected, ignoring.\n");
        }

        gpioDelay(DEBOUNCE_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

