#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PULSE_DURATION_MS 200
#define PULSE_DURATION_MS_2 300
#define CONSUMER "haptic_feedback"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *motor1_line = NULL;
    struct gpiod_line *motor2_line = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines for motor 1 and motor 2 */
    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("gpiod_chip_get_line(MOTOR1)");
        goto cleanup;
    }
    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("gpiod_chip_get_line(MOTOR2)");
        goto cleanup;
    }

    /* Request motor 1 as output, initially low */
    if (gpiod_line_request_output(motor1_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(MOTOR1)");
        goto cleanup;
    }

    /* Request motor 2 as output, initially low */
    if (gpiod_line_request_output(motor2_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(MOTOR2)");
        goto cleanup;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Motor 1 pulse */
        if (gpiod_line_set_value(motor1_line, 1) < 0) {
            perror("gpiod_line_set_value(MOTOR1, 1)");
            goto cleanup;
        }
        usleep(PULSE_DURATION_MS * 1000);
        if (gpiod_line_set_value(motor1_line, 0) < 0) {
            perror("gpiod_line_set_value(MOTOR1, 0)");
            goto cleanup;
        }
        usleep(PULSE_DURATION_MS_2 * 1000);

        /* Motor 2 pulse */
        if (gpiod_line_set_value(motor2_line, 1) < 0) {
            perror("gpiod_line_set_value(MOTOR2, 1)");
            goto cleanup;
        }
        usleep(PULSE_DURATION_MS * 1000);
        if (gpiod_line_set_value(motor2_line, 0) < 0) {
            perror("gpiod_line_set_value(MOTOR2, 0)");
            goto cleanup;
        }
        usleep(PULSE_DURATION_MS_2 * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure motors are off before releasing lines */
    if (motor1_line) {
        gpiod_line_set_value(motor1_line, 0);
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_set_value(motor2_line, 0);
        gpiod_line_release(motor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

