#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_BUS        "/dev/i2c-1"
#define NUM_SENSORS    4
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define CONV_MS        180
#define LOOP_MS        1000
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_write_cmd: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "i2c_read_data: %s\n", strerror(errno));
        return -1;
    }
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_data: short read (%zd of %zu)\n", n, len);
        return -1;
    }
    return 0;
}

static float lux_from_raw(uint8_t raw)
{
    return ((float)raw / 1.2f) - 1.0f;
}

static int read_sensor(int fd, uint8_t addr, float *lux)
{
    if (i2c_write_cmd(fd, 0x20) < 0)
        return -1;
    usleep(CONV_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_data(fd, buf, sizeof(buf)) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = lux_from_raw(raw);
    return 0;
}

static int send_udp(int sock, const char *msg)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) <= 0) {
        fprintf(stderr, "inet_pton: %s\n", strerror(errno));
        return -1;
    }
    if (sendto(sock, msg, strlen(msg), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        int fd = i2c_open(I2C_BUS, 0x23 + i);
        if (fd < 0)
            continue;
        if (i2c_write_cmd(fd, 0x20) < 0) {
            close(fd);
            continue;
        }
        if (read_sensor(fd, 0x23 + i, &lux_from_raw(0)) < 0) {
            close(fd);
            continue;
        }
        close(fd);
    }

    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) <= 0) {
        fprintf(stderr, "inet_pton: %s\n", strerror(errno));
        close(sock);
        return 1;
    }

    while (g_running) {
        char msg[256];
        snprintf(msg, sizeof(msg), "1,%.2f;2,%.2f;3,%.2f;4,%.2f",
                 lux_from_raw(0), lux_from_raw(1),
                 lux_from_raw(2), lux_from_raw(3));
        if (send_udp(sock, msg) < 0)
