 * Sensor: 7-bit I2C address 0x37, default acceleration range ±8 g.
 *
 * Logs:   seismic_data.csv (timestamp,X_g,Y_g,Z_g)
 * Error:  seismic_error.log (timestamp,error_type)
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x37
#define D7S_REG_X_L    0x28
#define D7S_REG_X_H    0x29
#define D7S_REG_Y_L    0x2A
#define D7S_REG_Y_H    0x2B
#define D7S_REG_Z_L    0x2C
#define D7S_REG_Z_H    0x2D
#define D7S_REG_G_L    0x2E
#define D7S_REG_G_H    0x2F

#define D7S_MAX_G      8.0f
#define D7S_MAX_COUNT  32767.0f
#define D7S_MAX_COUNT_G 8.0f

#define CSV_FILENAME    "seismic_data.csv"
#define ERROR_FILENAME  "seismic_error.log"
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  10
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a D7S register; returns 0 on success, -1 on error. */
static int d7s_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read one byte from a D7S register; returns 0 on success, -1 on error. */
static int d7s_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* Read 6 bytes of acceleration data starting at D7S_REG_X_L.
 * Returns 0 on success, -1 on error. */
static int d7s_read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

    if (d7s_read_reg(fd, D7S_REG_X_L, &x_l) < 0) return -1;
    if (d7s_read_reg(fd, D7S_REG_X_H, &x_h) < 0) return -1;
    if (d7s_read_reg(fd, D7S_REG_Y_L, &y_l) < 0) return -1;
    if (d7s_read_reg(fd, D7S_REG_Y_H, &y_h) < 0) return -1;
    if (d7s_read_reg(fd, D7S_REG_Z_L, &z_l) < 0) return -1;
    if (d7s_read_reg(fd, D7S_REG_Z_H, &z_h) < 0) return -1;

    int16_t raw_x = (int16_t)((x_h << 8) | x_l);
    int16_t raw_y = (int16_t)((y_h << 8) | y_l);
    int16_t raw_z = (int16_t)((z_h << 8) | z_l);

    *x = (float)raw_x * D7S_MAX_G / D7S_MAX_COUNT_G;
    *y = (float)raw_y * D7S_MAX_G / D7S_MAX_COUNT_G;
    *z = (float)raw_z * D7S_MAX_G / D7S_MAX_COUNT_G;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,ERROR,%s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(fp);
}

int main(int argc, char *argv[])
{
    int opt;
    int i2c_fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Parse command-line options */
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                D7S_ADDR = (uint8_t)strtol(optarg, NULL, 0);
                break;
            case 'i':
                sample_interval_s = (int)strtol(optarg, NULL, 0);
                break;
            case 'f':
                CSV_FILENAME = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a 0x37] [-i <seconds>] [-f <filename>]\n",
                        argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                D7S_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open CSV file for appending */
    fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,X_g,Y_g,Z_g\n");
        fflush(fp);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("D7S seismic sensor reader started. Sampling every %d s. "
           "I2C address 0x%02X, interval %d s.\n",
           SAMPLE_INTERVAL_S, D7S_ADDR, sample_interval_s);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (d7s_read_accel(i2c_fd, &x, &y, &z) < 0) {
            log_error(fp, "Sensor read failed");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        log_data(fp, x, y, z);
        usleep(SAMPLE_INTERVAL_S * 1000);
    }

    printf("\nShutting down...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return rc;
}

