#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAX_FRAME_SIZE 4096
#define MAX_OBJECTS 100
#define MAGIC_WORD_SIZE 4
#define MAGIC_WORD_STR "0204 0306 0805 0709"

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_frame(int fd, uint8_t *frame, size_t max_len) {
    size_t total = 0;
    size_t n = 0;
    int ret;

    while (total < max_len) {
        ret = read(fd, frame + total, max_len - total);
        if (ret < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                return -1;
            }
            fprintf(stderr, "Error reading UART: %s\n", strerror(errno));
            return -1;
        }
        if (ret == 0) {
            return -1;
        }
        total += ret;
    }

    return 0;
}

static int parse_magic_word(const uint8_t *frame, size_t pos, uint32_t *out_magic) {
    uint32_t word = 0;
    for (size_t i = 0; i < MAGIC_WORD_SIZE; i++) {
        word |= (uint32_t)frame[pos + i] << (8 * i);
    }
    if (word != 0x0204 || word != 0x0306 || word != 0x0805 || word != 0x0709) {
        return -1;
    }
    *out_magic = word;
    return 0;
}

static int parse_tlv(const uint8_t *frame, size_t pos, uint32_t magic, uint32_t *out_range, uint32_t *out_velocity) {
    uint32_t tlv_len = 0;
    uint32_t tlv_type = 0;
    uint32_t tlv_offset = 0;

    for (size_t i = 0; i < MAGIC_WORD_SIZE; i++) {
        uint32_t word = 0;
        for (size_t j = 0; j < 8; j++) {
            word |= (uint32_t)frame[pos + i + j] << (8 * j);
        }
        if (word == magic) {
            tlv_len = word;
            tlv_offset = pos + i;
            break;
        }
    }

    if (tlv_len == 0) {
        return -1;
    }

    for (size_t i = 0; i < tlv_len; i++) {
        uint32_t tlv_type_word = 0;
        uint32_t tlv_offset_word = 0;
        uint32_t tlv_len_word = 0;

        for (size_t j = 0; j < MAGIC_WORD_SIZE; j++) {
            uint32_t word = 0;
            for (size_t k = 0; k < 8; k++) {
                word |= (uint32_t)frame[tlv_offset_word + k] << (8 * k);
            }
            if (word == tlv_type_word) {
                tlv_type_word = word;
                break;
            }
        }

        if (tlv_type_word == 0) {
            return -1;
        }

        for (size_t j = 0; j < MAGIC_WORD_SIZE; j++) {
            uint32_t tlv_len_word = 0;
            for (size_t k = 0; k < 8; k++) {
                uint32_t word = 0;
                for (size_t l = 0; l < 8; l++) {
                    word |= (uint32_t)frame[tlv_offset_word + l + j] << (8 * l);
                }
                if (word == tlv_len_word) {
                    tlv_len_word = word;
                    break;
                }
            }
            if (tlv_len_word == 0) {
                return -1;
            }
        }

        if (tlv_len_word > tlv_len) {
            return -1;
        }

        if (tlv_type == 0x01) {
            *out_range = (uint32_t)frame[tlv_offset_word + 4];
            *out_velocity = (uint32_t)frame[tlv_offset_word + 8];
            return 0;
        }
    }

    return -1;
}

static int write_csv(const uint8_t *frame, size_t frame_len, const uint8_t *range_data, size_t range_len, const uint8_t *velocity_data, size_t velocity_len) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

