static int parse_magic_word(const uint8_t *frame, size_t pos, uint32_t *out_magic) {
    uint32_t word = 0;
    for (size_t i = 0; i < MAGIC_WORD_SIZE; i++) {
        word |= (uint32_t)frame[pos + i] << (8 * i);
    }
    if (word != 0x0204 || word != 0x0306 || word != 0x0805 || word != 0x0709) {
