        return -1;
    }

    for (size_t i = 0; i < tlv_len; i++) {
        uint32_t tlv_type_word = 0;
        uint32_t tlv_offset_word = 0;
        uint32_t tlv_len_word = 0;

        for (size_t j = 0; j < MAGIC_WORD_SIZE; j++) {
            uint32_t word = 0;
            for (size_t k = 0; k < 8; k++) {
