#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/select.h>
#include <termios.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define READ_TIMEOUT_SEC 2
#define LINE_BUFFER_SIZE 256
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart(int fd, float *range_meters) {
    char buffer[LINE_BUFFER_SIZE];
    int bytes_read = 0;
    int timeout_ms = READ_TIMEOUT_SEC * 1000;

    while (bytes_read < LINE_BUFFER_SIZE && g_running) {
        fd_set readfds;
        struct timeval tv;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        tv.tv_sec = timeout_ms / 1000;
        tv.tv_usec = (timeout_ms % 1000) * 1000;

        if (select(fd + 1, &readfds, NULL, NULL, &tv) == -1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error during select: %s\n", strerror(errno));
            return -1;
        }

        if (FD_ISSET(fd, &readfds)) {
            ssize_t n = read(fd, buffer + bytes_read, LINE_BUFFER_SIZE - bytes_read);
            if (n > 0) {
                bytes_read += n;
            } else if (n < 0) {
                fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
                return -1;
            }
        }
    }

    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    }

    if (bytes_read == 0) {
        fprintf(stderr, "No data available from UART after %d ms.\n", timeout_ms);
        return -1;
    }

    char *line = strtok(buffer, "\n");
    if (line == NULL) {
        fprintf(stderr, "Invalid line format in UART data.\n");
        return -1;
    }

    if (sscanf(line, "%d.%03d", &range_meters, &range_meters) != 2) {
        fprintf(stderr, "Invalid range format in UART data.\n");
        return -1;
    }

    return 0;
}

static void log_data(float range_meters) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range_meters);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        return 1;
    }

    printf("UART initialized on %s at %d baud. Press Ctrl+C to exit.\n", UART_DEVICE, BAUD_RATE);

    while (g_running) {
        float range_meters;
        if (read_uart(uart_fd, &range_meters) == 0) {
            log_data(range_meters);
        } else {
            fprintf(stderr, "Failed to read from UART after %d retries.\n", MAX_RETRIES);
        }
        usleep(100000);
    }

    printf("\nShutting down...\n");
    close(uart_fd);
    return 0;
}

