#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN  4
#define SENSOR_2_PIN  17
#define SENSOR_3_PIN  27
#define SERIAL_PORT   "/dev/ttyAMA0"
#define BAUD_RATE     115200
#define LOG_INTERVAL  100  /* microseconds */
#define SAMPLE_PERIOD  (1000000 / (LOG_INTERVAL / 1000))

static volatile sig_atomic_t g_running = 1;
static FILE *g_serial = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_serial) {
        fclose(g_serial);
        g_serial = NULL;
    }
    gpioTerminate();
}

static void log_sensor_state(int sensor_pin, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }
    printf("[%s] Sensor %d: %s\n", ts, sensor_pin, state ? "Obstacle" : "Clear");
    fflush(stdout);
}

int main(void)
{
    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins --- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_3_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable pull-up resistors on each input pin */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_3_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_3_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open serial port --- */
    g_serial = fopen(SERIAL_PORT, "rb");
    if (g_serial == NULL) {
        perror("fopen(" SERIAL_PORT ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);
        int s3 = gpioRead(SENSOR_3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "gpioRead failed; continuing\n");
        } else {
            log_sensor_state(SENSOR_1_PIN, s1);
            log_sensor_state(SENSOR_2_PIN, s2);
            log_sensor_state(SENSOR_3_PIN, s3);
        }

        /* 10 Hz sampling; 100 ms period */
        gpioDelay(LOG_INTERVAL);
    }

    /* --- Graceful shutdown --- */
    cleanup();
    return EXIT_SUCCESS;
}

